INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无所谓", "is_correct": true, "explanation": "正确：“无所谓”表示不在乎，与“对我来说”的说话语境一致。"}, {"text": "无所事事", "is_correct": false, "explanation": "语义：“无所事事”指没有事做，不能用来评价选哪种交通工具。"}, {"text": "无所不能", "is_correct": false, "explanation": "语义：“无所不能”指什么都能做，与选择交通工具无关。"}, {"text": "打招呼", "is_correct": false, "explanation": "语义：“打招呼”是一个动作，不能用来评价选择。"}], "explanations": {"无所谓": "正确：“无所谓”表示不在乎，与“对我来说”的说话语境一致。", "无所事事": "语义：“无所事事”指没有事做，不能用来评价选哪种交通工具。", "无所不能": "语义：“无所不能”指什么都能做，与选择交通工具无关。", "打招呼": "语义：“打招呼”是一个动作，不能用来评价选择。"}, "sentence_index": 6, "correct_answer": "无所谓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师无所谓，什么问题都能解答。", "explanation": "这里应该用〈无所不能〉。“无所谓”表示不在乎，不能用来说本领很强。"}, {"text": "这位爷爷无所谓，什么事情都知道。", "explanation": "这里应该用〈无所不知〉。“无所谓”表示不在乎，不表示什么都知道。"}, {"text": "这部百科全书无所谓，各种知识都收录了。", "explanation": "这里应该用〈无所不包〉。“无所谓”表示不在乎，不表示包括一切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我这件事无所谓，你定吧。", "corrected_sentence": "我对这件事无所谓，你定吧。", "error_description": "错误：漏了介词“对”。“我这件事无所谓”不通；可说“我对这件事无所谓”，或把“这件事”提前作话题，说“这件事我无所谓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他无所谓得笑了笑，继续吃饭。", "corrected_sentence": "他无所谓地笑了笑，继续吃饭。", "error_description": "错误：“无所谓”作状语后应接“地”，不接“得”。“得”用于补语，此处应为“他无所谓地笑了笑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
