INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98036, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "如同；好像。", "primary_collocate": null, "pronunciation": "yóu rú", "ipa": "joʊ˧˥ ʐu˧˥", "syllable_count": 2, "sentences": [{"text": "夜晚的星星犹如一颗颗宝石。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的笑容犹如春天的阳光。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小城犹如一幅美丽的画。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得很快，犹如一阵风。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们犹如小鸟一样飞出了教室。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月光洒在湖面上，犹如一层银纱。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的冬天犹如一座冰城。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话犹如一盏灯，照亮了我的路。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沉默了很久，犹如一尊雕像。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着我，犹如看着一个陌生人。", "target_word": "犹如", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "犹如：书面语，用于比喻，表示如同、好像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98036, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "犹如", "is_correct": true, "explanation": "正确：犹如 yóu rú，意思是如同、好像。"}, {"text": "又如", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，「又如」表示举例，意思不是比喻。"}, {"text": "游人", "is_correct": false, "explanation": "rén（en 韵）与 rú（u 韵）韵母不同，「游人」指游览的人。"}, {"text": "油炉", "is_correct": false, "explanation": "lú 与 rú 声母不同（l 与 r），「油炉」指用油加热的炉子。"}], "explanations": {"犹如": "正确：犹如 yóu rú，意思是如同、好像。", "又如": "yòu（第四声）与 yóu（第二声）声调不同，「又如」表示举例，意思不是比喻。", "游人": "rén（en 韵）与 rú（u 韵）韵母不同，「游人」指游览的人。", "油炉": "lú 与 rú 声母不同（l 与 r），「油炉」指用油加热的炉子。"}, "sentence_index": null, "correct_answer": "犹如"}, "level_3": {"options": [{"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”要求有生命或有权属的主语，星星不能拥有宝石。"}, {"text": "犹如", "is_correct": true, "explanation": "正确：“犹如”表示如同，把星星比作宝石，与句中比喻一致。"}, {"text": "等于", "is_correct": false, "explanation": "语义：“等于”表示数量或价值相等，星星与宝石并不相等。"}, {"text": "属于", "is_correct": false, "explanation": "语义：“属于”表示归属，星星不属于宝石，与比喻的意思不合。"}], "explanations": {"拥有": "配价：“拥有”要求有生命或有权属的主语，星星不能拥有宝石。", "犹如": "正确：“犹如”表示如同，把星星比作宝石，与句中比喻一致。", "等于": "语义：“等于”表示数量或价值相等，星星与宝石并不相等。", "属于": "语义：“属于”表示归属，星星不属于宝石，与比喻的意思不合。"}, "sentence_index": 0, "correct_answer": "犹如"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢运动，犹如打篮球。", "explanation": "这里应该用〈比如〉。比如用于举例说明，犹如只表示比方，不能用来列举例子。"}, {"text": "他犹如去了北京，我也不太清楚。", "explanation": "这里应该用〈好像〉。好像可以表示不确定的推测，犹如只用于比喻，不能表示推测。"}, {"text": "这件衣服犹如很贵，我不敢买。", "explanation": "这里应该用〈好像〉。表示估计、猜测要用好像，犹如只用于打比方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位于", "is_correct": false, "explanation": "语义：“位于”表示处在某个地点，冬天是时段，不能位于某地。"}, {"text": "犹如", "is_correct": true, "explanation": "正确：“犹如”表示如同，把冬天的景象比作一座冰城，与句意一致。"}, {"text": "盖", "is_correct": false, "explanation": "配价：“盖”的施事须是人，冬天无法建造城市。"}, {"text": "参观", "is_correct": false, "explanation": "配价：“参观”的主语须是人，冬天不能去参观。"}], "explanations": {"位于": "语义：“位于”表示处在某个地点，冬天是时段，不能位于某地。", "犹如": "正确：“犹如”表示如同，把冬天的景象比作一座冰城，与句意一致。", "盖": "配价：“盖”的施事须是人，冬天无法建造城市。", "参观": "配价：“参观”的主语须是人，冬天不能去参观。"}, "sentence_index": 6, "correct_answer": "犹如"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两加三犹如五。", "explanation": "这里应该用〈等于〉。等于表示数量完全相等，犹如只表示相似，不能用于算术上的相等。"}, {"text": "天太晚了，我们犹如明天再去吧。", "explanation": "这里应该用〈不如〉。不如用于提出更好的建议，犹如只表示比喻。"}, {"text": "一斤犹如五百克。", "explanation": "这里应该用〈相当于〉。相当于用于数量的等量换算，犹如只表示相似，不能用于换算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的声音犹如了清泉，很好听。", "corrected_sentence": "她的声音犹如清泉，很好听。", "error_description": "错误：“犹如”后多加了“了”。正确：“犹如”后直接接比喻对象，不加“了”，应为“她的声音犹如清泉，很好听。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的脚步是犹如猫一样轻。", "corrected_sentence": "他的脚步犹如猫一样轻。", "error_description": "错误：“犹如”前多加了判断词“是”。正确：“犹如”本身已表示比喻，前面不需要“是”，应为“他的脚步犹如猫一样轻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
