INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "珍珠、宝石、玉器等贵重饰品的统称。", "primary_collocate": null, "pronunciation": "zhū bǎo", "ipa": "ʈʂu˥ pɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "珠宝是珍珠、宝石和玉器的统称。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "展览会上有很多贵重的珠宝。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位设计师专门做珠宝。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "珠宝要放在安全的地方。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他花了很多钱买珠宝。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把珠宝都放进了保险柜。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的皇后有很多珠宝。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别弄坏了这些珠宝。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些珠宝里，玉器最有名。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想学怎么看珠宝的好坏。", "target_word": "珠宝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一套珠宝", "label": "量词"}, {"form": "一件珠宝", "label": "量词"}], "register": "中性", "sense_fingerprint": "珍珠、宝石、玉器等贵重饰品的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '244a8996-a574-446d-85a5-426380410052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "珠宝", "is_correct": true, "explanation": "珠宝指珍珠、宝石、玉器等贵重饰品的统称，句中“是……的统称”正是这个意思。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是珍珠、宝石、玉器的统称，类别不相容。"}, {"text": "昆虫", "is_correct": false, "explanation": "语义：昆虫是动物的一类，不包括珍珠和宝石，句子不成立。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”指地点的高度，不能作为一类物品的统称。"}], "explanations": {"珠宝": "珠宝指珍珠、宝石、玉器等贵重饰品的统称，句中“是……的统称”正是这个意思。", "水果": "语义：水果不是珍珠、宝石、玉器的统称，类别不相容。", "昆虫": "语义：昆虫是动物的一类，不包括珍珠和宝石，句子不成立。", "海拔": "搭配：“海拔”指地点的高度，不能作为一类物品的统称。"}, "sentence_index": 0, "correct_answer": "珠宝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天家里很冷，我们买了很多珠宝取暖。", "explanation": "这里应该用〈煤炭〉。珠宝是贵重饰品，不能用来取暖。"}, {"text": "工人用珠宝盖房子，房子很快就建好了。", "explanation": "这里应该用〈砖头〉。珠宝不能用来砌墙盖房，此处应用建筑材料。"}, {"text": "妈妈用珠宝给我们做了一锅汤。", "explanation": "这里应该用〈蔬菜〉。珠宝是贵重饰品，不能用来做汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "珠宝", "is_correct": true, "explanation": "珠宝是古代贵族拥有的贵重饰品，“古代的皇后有很多珠宝”符合句意。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是现代器物，古代不存在，与句中语境矛盾。"}, {"text": "高铁", "is_correct": false, "explanation": "语义：高铁是现代交通工具，古代没有，与句中语境不符。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“很多”不能用于体温，体温是单一的生理数值。"}], "explanations": {"珠宝": "珠宝是古代贵族拥有的贵重饰品，“古代的皇后有很多珠宝”符合句意。", "电脑": "语义：电脑是现代器物，古代不存在，与句中语境矛盾。", "高铁": "语义：高铁是现代交通工具，古代没有，与句中语境不符。", "体温": "搭配：“很多”不能用于体温，体温是单一的生理数值。"}, "sentence_index": 6, "correct_answer": "珠宝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中药店里摆满了各种珠宝。", "explanation": "这里应该用〈药材〉。中药店卖的是药材，珠宝不会作为货物摆在中药店里。"}, {"text": "他每天早上都吃珠宝当早饭。", "explanation": "这里应该用〈面包〉。珠宝是贵重饰品，不能吃，早饭应当吃食物。"}, {"text": "院子里的珠宝开花了，很香。", "explanation": "这里应该用〈果树〉。珠宝是贵重饰品，不会生长、开花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一张很贵的珠宝，平时不戴。", "corrected_sentence": "她有一套很贵的珠宝，平时不戴。", "error_description": "错误：用了“张”。“张”用于平面的东西，如纸、桌子，珠宝应用“套”或“件”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一朵珠宝送给妈妈。", "corrected_sentence": "我想买一件珠宝送给妈妈。", "error_description": "错误：用了“朵”。“朵”用于花、云等，珠宝应用“件”或“套”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
