INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98043, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "研讨会是很多人坐在一起，一边说一边听，一起想一个问题的会。", "primary_collocate": null, "pronunciation": "yán tǎo huì", "ipa": "jɛn˧˥ tʰɑʊ̯˨˩˦ xweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "明天下午我们有一个研讨会。", "target_word": "研讨会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个研讨会有二十多个人参加。", "target_word": "研讨会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我昨天去参加了一个研讨会。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研讨会上，大家一边听一边说。", "target_word": "研讨会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师请学生们在研讨会上说说想法。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的研讨会从两点开始。", "target_word": "研讨会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的研讨会在三楼的大房间里开。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场研讨会很有意思，大家都说了很多。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想参加周五的研讨会吗？", "target_word": "研讨会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研讨会结束以后，我们一起去吃饭。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "国际研讨会", "label": "复合"}, {"form": "研討會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家一起交流想法的讨论会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研讨会", "is_correct": true, "explanation": "研讨会：正确。指大家一起交流讨论的一次会议，可以说“有一个研讨会”。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是场所，不是“明天下午”可以举行的活动。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不可数，不能用“一个”计数。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是人身上的数值，不是下午要发生的事，不能说“有一个体重”。"}], "explanations": {"研讨会": "研讨会：正确。指大家一起交流讨论的一次会议，可以说“有一个研讨会”。", "食堂": "语义：食堂是场所，不是“明天下午”可以举行的活动。", "空气": "搭配：“空气”不可数，不能用“一个”计数。", "体重": "语义：体重是人身上的数值，不是下午要发生的事，不能说“有一个体重”。"}, "sentence_index": 0, "correct_answer": "研讨会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把研讨会借给了朋友。", "explanation": "这里应该用〈会议室〉。会议室是场地，可以借给别人；研讨会是活动，不能借出。"}, {"text": "研讨会上，选手们一个接一个地上台表演，评委打分。", "explanation": "这里应该用〈比赛〉。比赛有选手和评委打分；研讨会是大家平等地交流讨论，不评分。"}, {"text": "我们把研讨会挂在墙上。", "explanation": "这里应该用〈画〉。画可以挂在墙上；研讨会是活动，不能挂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研讨会", "is_correct": true, "explanation": "研讨会：正确。会议可以在房间里举行，与“开”搭配。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震不是可以安排在房间里“开”的活动。"}, {"text": "考卷", "is_correct": false, "explanation": "搭配：“考卷”不能与“开”搭配，不能说在房间里开考卷。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会在房间里举行，也不能说“开”。"}], "explanations": {"研讨会": "研讨会：正确。会议可以在房间里举行，与“开”搭配。", "地震": "语义：地震不是可以安排在房间里“开”的活动。", "考卷": "搭配：“考卷”不能与“开”搭配，不能说在房间里开考卷。", "天气": "语义：天气不会在房间里举行，也不能说“开”。"}, "sentence_index": 6, "correct_answer": "研讨会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研讨会上，大家唱歌跳舞，很热闹。", "explanation": "这里应该用〈联欢会〉。联欢会是文娱聚会；研讨会围绕专题交流，不会唱歌跳舞。"}, {"text": "研讨会上，医生给我抽了一管血。", "explanation": "这里应该用〈体检〉。体检时才抽血；研讨会是学术交流，不会有这种场面。"}, {"text": "研讨会上，学员动手操作，不用说话。", "explanation": "这里应该用〈培训班〉。培训班重在动手练习；研讨会靠大家交流讨论，不能不说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们下周五开一只研讨会。", "corrected_sentence": "我们下周五开一场研讨会。", "error_description": "错误在量词：研讨会是一场活动，应用〈场〉，不能用〈只〉（〈只〉多用于动物或单件物品）。正确说法是“一场研讨会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们上个月参加了一个很有意思研讨会。", "corrected_sentence": "我们上个月参加了一个很有意思的研讨会。", "error_description": "错误在定语的“的”：“很有意思”修饰名词时要用“的”，应说“很有意思的研讨会”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
