INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "围绕某一专题，由专业人员集中交流、讨论的会议。", "primary_collocate": null, "pronunciation": "yán tǎo huì", "ipa": "jɛn˧˥ tʰɑʊ̯˨˩˦ xweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "这个研讨会的专题是人工智能。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几十位专家来参加这场研讨会。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学院下个月要开一场国际研讨会。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研讨会围绕环境保护进行讨论。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在研讨会上发表了一篇论文。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研讨会的主题是教育改革。", "target_word": "研讨会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多医生参加了这次医学研讨会。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加过好几次学术研讨会。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研讨会结束后，材料会发给大家。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把研讨会的时间改到了周四。", "target_word": "研讨会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "学术研讨会", "label": "复合"}, {"form": "研討會", "label": "繁体"}], "register": "书面", "sense_fingerprint": "围绕专题的专业学术会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "研讨会", "is_correct": true, "explanation": "研讨会：正确。围绕某一专题的会议，可以有“专题”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食品，没有专题可言。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“专题”一般配会议、课程、节目，不配手机。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车是交通工具，不是围绕专题的活动。"}], "explanations": {"研讨会": "研讨会：正确。围绕某一专题的会议，可以有“专题”。", "面包": "语义：面包是食品，没有专题可言。", "手机": "搭配：“专题”一般配会议、课程、节目，不配手机。", "公交车": "语义：公交车是交通工具，不是围绕专题的活动。"}, "sentence_index": 0, "correct_answer": "研讨会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员把研讨会端上了桌。", "explanation": "这里应该用〈菜〉。菜可以端上桌；研讨会是会议，不能端。"}, {"text": "研讨会上，大家跳起舞来，气氛很热烈。", "explanation": "这里应该用〈舞会〉。舞会是跳舞的聚会；研讨会围绕专题讨论，不会跳舞。"}, {"text": "他在桌上摊开了研讨会。", "explanation": "这里应该用〈地图〉。地图可以摊开查看；研讨会是会议，不能摊开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "研讨会", "is_correct": true, "explanation": "研讨会：正确。医生可以参加的专业交流会议。"}, {"text": "病房", "is_correct": false, "explanation": "语义：病房是住院的地方，不是可以“参加”的活动。"}, {"text": "药膏", "is_correct": false, "explanation": "语义：药膏是药物，不能被“参加”。"}, {"text": "盒饭", "is_correct": false, "explanation": "搭配：“参加”配活动、会议，不配食物。"}], "explanations": {"研讨会": "研讨会：正确。医生可以参加的专业交流会议。", "病房": "语义：病房是住院的地方，不是可以“参加”的活动。", "药膏": "语义：药膏是药物，不能被“参加”。", "盒饭": "搭配：“参加”配活动、会议，不配食物。"}, "sentence_index": 6, "correct_answer": "研讨会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "研讨会上，亲属们低声哭泣。", "explanation": "这里应该用〈葬礼〉。葬礼上亲属会哭泣；研讨会是学术交流，不会有这种场面。"}, {"text": "研讨会上，买家竞相举牌，价格不断上涨。", "explanation": "这里应该用〈拍卖会〉。拍卖会是买家竞价；研讨会是学术交流，没有竞价。"}, {"text": "研讨会上，学员只按老师的步骤做练习，不用说话。", "explanation": "这里应该用〈培训班〉。培训班重在练习；研讨会靠大家交流讨论，不能不说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月我们将开一只学术研讨会。", "corrected_sentence": "这个月我们将开一场学术研讨会。", "error_description": "错误在量词：研讨会是一场活动，应用〈场〉，不能用〈只〉（〈只〉多用于动物或单件物品）。正确说法是“一场学术研讨会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她去年参加了一个很有收获研讨会。", "corrected_sentence": "她去年参加了一个很有收获的研讨会。", "error_description": "错误在定语的“的”：“很有收获”修饰名词时要用“的”，应说“很有收获的研讨会”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
