INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98047, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "科技人员是用科学和新办法做研究、做新东西的人。", "primary_collocate": null, "pronunciation": "kē jì rén yuán", "ipa": "kʰɤ˥ tɕi˥˩ ɻən˧˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "这家公司有很多科技人员。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科技人员正在实验室里做研究。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他父亲是一位科技人员。", "target_word": "科技人员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科技人员用新办法做出了一个小机器。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想长大以后做科技人员。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些科技人员每天都工作到很晚。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校请了几位科技人员来给学生上课。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科技人员把新做的机器带到了会议室。", "target_word": "科技人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多科技人员都住在这个城市的东边。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科技人员为了做出好东西，常常试很多次。", "target_word": "科技人员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "科技人員", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用科学和新办法做研究、做新东西的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98047, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科技人员", "is_correct": true, "explanation": "正确：科技人员指做科学研究和新东西的人，可以在公司里“有很多”，与句子搭配。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“有很多”和“空气”不搭，空气是不可计数的物质，公司不会“有很多空气”。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象是动物，公司不会“有很多大象”，句子说的是公司的人员。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是自然现象，不是公司可以拥有的东西，与“有很多”不合。"}], "explanations": {"科技人员": "正确：科技人员指做科学研究和新东西的人，可以在公司里“有很多”，与句子搭配。", "空气": "搭配：“有很多”和“空气”不搭，空气是不可计数的物质，公司不会“有很多空气”。", "大象": "语义：大象是动物，公司不会“有很多大象”，句子说的是公司的人员。", "闪电": "语义：闪电是自然现象，不是公司可以拥有的东西，与“有很多”不合。"}, "sentence_index": 0, "correct_answer": "科技人员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科技人员负责给空调换滤网，每周都要去各个房间检查。", "explanation": "这里应该用〈维修工〉。科技人员指做科学研究、做新东西的人；日常维修、换滤网的工作要说维修工。"}, {"text": "科技人员在商场里卖衣服，帮顾客试穿。", "explanation": "这里应该用〈售货员〉。科技人员做研究和开发，不在商场卖衣服；卖衣服、招呼顾客要说售货员。"}, {"text": "科技人员在车间里一天装配几百个零件，按时下班。", "explanation": "这里应该用〈工人〉。科技人员侧重研究和开发新东西，不做重复的流水线装配；车间里做重复生产的要说工人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98047, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科技人员", "is_correct": true, "explanation": "正确：科技人员是做研究的人，“请了几位”指人，“来给学生上课”也说得通。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会讲课，不能给学生上课。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷不能给学生上课，学校不会请他来讲课。"}, {"text": "机器", "is_correct": false, "explanation": "搭配：“几位”只用于人，“机器”应说“几台”，且机器不能给学生上课。"}], "explanations": {"科技人员": "正确：科技人员是做研究的人，“请了几位”指人，“来给学生上课”也说得通。", "婴儿": "语义：婴儿不会讲课，不能给学生上课。", "小偷": "语义：小偷不能给学生上课，学校不会请他来讲课。", "机器": "搭配：“几位”只用于人，“机器”应说“几台”，且机器不能给学生上课。"}, "sentence_index": 6, "correct_answer": "科技人员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科技人员在医院里给病人看病，开药方。", "explanation": "这里应该用〈医生〉。科技人员做研究和开发，不给病人看病、开药方；看病开药要说医生。"}, {"text": "科技人员每天开车接送客人，还负责加油。", "explanation": "这里应该用〈司机〉。科技人员做研究和开发，不负责开车接送客人；开车接送、加油要说司机。"}, {"text": "科技人员在饭店后厨炒菜，给客人做饭。", "explanation": "这里应该用〈厨师〉。科技人员做研究和开发，不在饭店后厨做菜；做菜、炒菜要说厨师。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98047, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司今年招了几只科技人员。", "corrected_sentence": "我们公司今年招了几位科技人员。", "error_description": "“科技人员”指人，量词应用“位”（或“名”），不能用“只”（“只”多用于动物）。正确说法：我们公司今年招了几位科技人员。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98047, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究所请了几科技人员来参加会议。", "corrected_sentence": "研究所请了几位科技人员来参加会议。", "error_description": "“几”和名词之间漏了量词。“科技人员”是指人的名词，数词“几”后面要加量词“位”，应说“几位科技人员”，漏掉“位”就不成话。正确说法：研究所请了几位科技人员来参加会议。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
