INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98048, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "从事科学研究和技术开发工作的专业人员。", "primary_collocate": null, "pronunciation": "kē jì rén yuán", "ipa": "kʰɤ˥ tɕi˥˩ ɻən˧˥ ɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "他是一名从事研究工作的科技人员。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家需要更多年轻的科技人员。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科技人员的工资比去年高了。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科技人员在大学学过十年物理。", "target_word": "科技人员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院请科技人员帮忙检查新机器。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和丈夫都是科技人员。", "target_word": "科技人员", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科技人员开会讨论了新方法。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给科技人员买了新电脑。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的科技人员越来越多。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科技人员中有一半是女的。", "target_word": "科技人员", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "科技人員", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从事科学研究和技术开发的专业人员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科技人员", "is_correct": true, "explanation": "正确：科技人员指从事科学研究的专业人员，与“从事研究工作的”搭配。"}, {"text": "工人", "is_correct": false, "explanation": "语义：工人从事生产劳动，不是从事研究工作的人，与后面的修饰语不合。"}, {"text": "司机", "is_correct": false, "explanation": "语义：司机的工作是开车，与“从事研究工作”完全不合。"}, {"text": "仪器", "is_correct": false, "explanation": "搭配：“一名”只用于人，仪器应说“一台”，而且仪器不能“从事”研究工作。"}], "explanations": {"科技人员": "正确：科技人员指从事科学研究的专业人员，与“从事研究工作的”搭配。", "工人": "语义：工人从事生产劳动，不是从事研究工作的人，与后面的修饰语不合。", "司机": "语义：司机的工作是开车，与“从事研究工作”完全不合。", "仪器": "搭配：“一名”只用于人，仪器应说“一台”，而且仪器不能“从事”研究工作。"}, "sentence_index": 0, "correct_answer": "科技人员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位科技人员在饭店后厨切菜，每天要做几百份饭。", "explanation": "这里应该用〈厨师〉。科技人员做研究和开发，不在饭店后厨做饭；做饭、切菜要说厨师。"}, {"text": "这位科技人员负责公司的财务和报销，每月算工资。", "explanation": "这里应该用〈会计〉。科技人员做研究和开发，不负责公司财务；记账、报销、算工资要说会计。"}, {"text": "这位科技人员在餐厅里端菜，给客人倒茶。", "explanation": "这里应该用〈服务员〉。科技人员做研究和开发，不在餐厅端菜倒茶；端菜、倒茶要说服务员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科技人员", "is_correct": true, "explanation": "正确：科技人员是做研究、开发的人，能够“开会讨论新方法”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有思考和发言的能力，不能“开会讨论新方法”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“开会讨论”的主语要能发言，桌子不能与“开会讨论”搭配。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不能开会，也不能讨论方法，与句子的意思不合。"}], "explanations": {"科技人员": "正确：科技人员是做研究、开发的人，能够“开会讨论新方法”。", "石头": "语义：石头没有思考和发言的能力，不能“开会讨论新方法”。", "桌子": "搭配：“开会讨论”的主语要能发言，桌子不能与“开会讨论”搭配。", "树": "语义：树不能开会，也不能讨论方法，与句子的意思不合。"}, "sentence_index": 6, "correct_answer": "科技人员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "科技人员每天在工厂门口站岗，检查来往的车辆。", "explanation": "这里应该用〈保安〉。科技人员做研究和开发，不负责门口站岗、查验车辆；站岗、查车要说保安。"}, {"text": "科技人员在医院里给病人打针。", "explanation": "这里应该用〈护士〉。科技人员做研究和开发，不负责给病人打针。"}, {"text": "科技人员每天开车接送客人。", "explanation": "这里应该用〈司机〉。科技人员做研究和开发，开车接送客人要说司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家研究所今年招了两只科技人员。", "corrected_sentence": "这家研究所今年招了两位科技人员。", "error_description": "“科技人员”指人，量词应用“位”（或“名”），不能用“只”（“只”多用于动物）。正确说法：这家研究所今年招了两位科技人员。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司为了新项目招了三位科技人员们。", "corrected_sentence": "这家公司为了新项目招了三位科技人员。", "error_description": "“三位”已经表示数量，数量词修饰的名词后面不能再加“们”。正确说法：这家公司为了新项目招了三位科技人员。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
