INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98049, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "等式是用等号连起来的算式，等号两边一样大。", "primary_collocate": null, "pronunciation": "děng shì", "ipa": "təŋ˨˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "老师在黑板上写了一个等式。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个等式两边的数一样大。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能把这个等式算一遍吗？", "target_word": "等式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等式中间要写等号。", "target_word": "等式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很快就算出了等式的答案。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题要先列一个等式。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明看着黑板上的等式，想了很久。", "target_word": "等式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等式的左边是三加五。", "target_word": "等式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个等式错了，两边不一样大。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们今天学习了怎么列等式。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "恒等式", "label": "复合"}], "register": "中性", "sense_fingerprint": "用等号连接、两边一样大的算式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98049, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苹果", "is_correct": false, "explanation": "语义：苹果是实物，不能写在黑板上，“写了一个苹果”句意不通。"}, {"text": "等式", "is_correct": true, "explanation": "正确：等式是用等号连起来的算式，可以写在黑板上，与“写”和“黑板”相合。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“写”的宾语应是文字或符号，不说“写一个桌子”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不是用来在黑板上书写的东西，句意不通。"}], "explanations": {"苹果": "语义：苹果是实物，不能写在黑板上，“写了一个苹果”句意不通。", "等式": "正确：等式是用等号连起来的算式，可以写在黑板上，与“写”和“黑板”相合。", "桌子": "搭配：“写”的宾语应是文字或符号，不说“写一个桌子”。", "手机": "语义：手机不是用来在黑板上书写的东西，句意不通。"}, "sentence_index": 0, "correct_answer": "等式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两边不一样大的式子叫等式。", "explanation": "这里应该用〈不等式〉。等式两边必须相等，两边不相等的式子叫不等式。"}, {"text": "这个式子里没有等号，它也是等式。", "explanation": "这里应该用〈算式〉。没有等号的式子是算式，等式必须用等号连接。"}, {"text": "老师在黑板上写了一个等式，表示三大于五。", "explanation": "这里应该用〈不等式〉。等式表示两边相等，表示大小关系的应是不等式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98049, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：心情是内心的感受，看不见，不能出现在黑板上让人看着想。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“看着”后的对象要是看得见的具体事物，“黑板上的早饭”不说。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，也不能写在黑板上，句意不通。"}, {"text": "等式", "is_correct": true, "explanation": "正确：等式可以写在黑板上，小明看着它想问题，与句意相合。"}], "explanations": {"心情": "语义：心情是内心的感受，看不见，不能出现在黑板上让人看着想。", "早饭": "搭配：“看着”后的对象要是看得见的具体事物，“黑板上的早饭”不说。", "空气": "语义：空气看不见，也不能写在黑板上，句意不通。", "等式": "正确：等式可以写在黑板上，小明看着它想问题，与句意相合。"}, "sentence_index": 6, "correct_answer": "等式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这节课我们学会了一只等式。", "explanation": "这里应该用〈个〉或〈道〉。〈只〉用于动物，不能用来数等式。"}, {"text": "等式表示两边不相等，要记住它。", "explanation": "这里应该用〈不等号〉。等式表示两边相等，两边不相等要用不等号。"}, {"text": "老师让我们抄下一把等式。", "explanation": "这里应该用〈个〉或〈道〉。〈把〉用于有柄的器具，不用来数等式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98049, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在黑板上列了一只等式。", "corrected_sentence": "老师在黑板上列了一个等式。", "error_description": "“等式”是抽象的算式，量词用“个”，不能用“只”（“只”多用于动物）。错误：列一只等式；正确：列一个等式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98049, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我做了三等式。", "corrected_sentence": "我做了三个等式。", "error_description": "数词“三”后面数等式要加量词“个”，不能直接说“三等式”。错误：三等式；正确：三个等式。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
