INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98050, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用等号表示两个数或式子相等的式子。", "primary_collocate": null, "pronunciation": "děng shì", "ipa": "təŋ˨˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "书上有很多等式，我都做过了。", "target_word": "等式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等号把两个数连成了一个等式。", "target_word": "等式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二加三等于五是一个等式。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个等式成立吗？", "target_word": "等式", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用等式表示两个数相等。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这个等式写在本子上。", "target_word": "等式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等式两边同时加三，结果不变。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个等式不对，左右两边不相等。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们检查一下这个等式。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学会解等式，数学就不难了。", "target_word": "等式", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "恒等式", "label": "复合"}], "register": "中性", "sense_fingerprint": "数学中表示两个数或式子相等的式子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，书上不会有很多雨，也不能“做过”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，书上不会有很多空气。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“做过”的对象是题目或任务，不说“做过树”。"}, {"text": "等式", "is_correct": true, "explanation": "正确：书上的等式是可以做的题目，“做过”与之搭配。"}], "explanations": {"雨": "语义：雨是天气现象，书上不会有很多雨，也不能“做过”。", "空气": "语义：空气看不见，书上不会有很多空气。", "树": "搭配：“做过”的对象是题目或任务，不说“做过树”。", "等式": "正确：书上的等式是可以做的题目，“做过”与之搭配。"}, "sentence_index": 0, "correct_answer": "等式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两边不相等的式子也叫等式。", "explanation": "这里应该用〈不等式〉。等式表示两边相等，两边不相等的式子叫不等式。"}, {"text": "这个式子没有等号，也是等式。", "explanation": "这里应该用〈算式〉。没有等号的式子是算式，等式必须有等号。"}, {"text": "老师让我们检查一个等式，它表示三大于五。", "explanation": "这里应该用〈不等式〉。等式表示两边相等，表示大小关系的是〈不等式〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98050, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "语义：房子不能两边同时加三，句意不通。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天不是数或式子，不能“两边同时加三”。"}, {"text": "小孩", "is_correct": false, "explanation": "搭配：“加三”的对象是数或式子，不说“小孩两边同时加三”。"}, {"text": "等式", "is_correct": true, "explanation": "正确：等式两边可以同时加三，结果不变，与句意相合。"}], "explanations": {"房子": "语义：房子不能两边同时加三，句意不通。", "春天": "语义：春天不是数或式子，不能“两边同时加三”。", "小孩": "搭配：“加三”的对象是数或式子，不说“小孩两边同时加三”。", "等式": "正确：等式两边可以同时加三，结果不变，与句意相合。"}, "sentence_index": 6, "correct_answer": "等式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "等式的意思是两边不相等。", "explanation": "这里应该用〈不等号〉。等式表示两边相等，两边不相等要用不等号。"}, {"text": "我们今天学会了解一只等式。", "explanation": "这里应该用〈个〉或〈道〉。〈只〉用于动物，不能用来数等式。"}, {"text": "等式写在两个数中间，它表示相等。", "explanation": "这里应该用〈等号〉。等式是整个算式，写在两个数中间、表示相等的是〈等号〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98050, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我做完了书上的两只等式。", "corrected_sentence": "我做完了书上的两个等式。", "error_description": "量词错误：“等式”的量词用“个”，不用“只”（“只”多用于动物或成对的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98050, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天解完了一等式。", "corrected_sentence": "我昨天解完了一个等式。", "error_description": "数词“一”后面必须加量词，应说“一个等式”，不能直接说“一等式”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
