INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98054, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机构、酒店等设置的负责接待、咨询或转接电话的总服务台。", "primary_collocate": null, "pronunciation": "zǒng tái", "ipa": "tsʊŋ˨˩˦ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "请问，总台的电话是多少？", "target_word": "总台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒店总台二十四小时都有人。", "target_word": "总台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打电话给总台，他们会帮你转分机。", "target_word": "总台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司总台负责接待客人。", "target_word": "总台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我给总台打了电话，问明天的天气。", "target_word": "总台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "总台的电话一直在响。", "target_word": "总台", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你在总台留下名字和电话。", "target_word": "总台", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把行李放在总台，下午再来拿。", "target_word": "总台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总台说经理现在不在，请您晚点再打。", "target_word": "总台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大楼的总台工作，每天要接很多电话。", "target_word": "总台", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "總台", "label": "繁体"}], "register": "中性", "sense_fingerprint": "机构、酒店负责接待、咨询和转接电话的总服务台", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a956c441-19d3-4000-954b-c5a96b39ceec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98054, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总台", "is_correct": true, "explanation": "总台是酒店或机构的服务台，可以向它询问电话，符合句意。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图没有电话，问地图的电话于理不通。"}, {"text": "猫", "is_correct": false, "explanation": "配价：「电话」的所有者需要是能拥有电话的机构或人，猫不能拥有，句子不成立。"}, {"text": "寒舍", "is_correct": false, "explanation": "语域：寒舍是自谦说法，询问别人的电话时不用这样说。"}], "explanations": {"总台": "总台是酒店或机构的服务台，可以向它询问电话，符合句意。", "地图": "语义：地图没有电话，问地图的电话于理不通。", "猫": "配价：「电话」的所有者需要是能拥有电话的机构或人，猫不能拥有，句子不成立。", "寒舍": "语域：寒舍是自谦说法，询问别人的电话时不用这样说。"}, "sentence_index": 0, "correct_answer": "总台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "酒店大厅里有一间总台，服务很好。", "explanation": "这里应该用〈个〉。「间」用于房间，总台的量词是「个」。"}, {"text": "他站在总台上做演讲。", "explanation": "这里应该用〈讲台〉。做演讲要站在讲台上，总台是接待、咨询的服务台，不能用来做演讲。"}, {"text": "客人们在总台吃了一顿晚饭。", "explanation": "这里应该用〈餐厅〉。吃饭要去餐厅，总台负责接待、咨询和转接电话，不是吃饭的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98054, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总台", "is_correct": true, "explanation": "总台是服务台，可以在那里留下名字和电话，符合句意。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空上不能留下名字和电话，句意荒谬。"}, {"text": "小狗", "is_correct": false, "explanation": "配价：「留下名字和电话」需要能承载文字或接收信息的地方或人，小狗不能承载，句子不成立。"}, {"text": "开水", "is_correct": false, "explanation": "语义：开水不能用来留下名字和电话，句意荒谬。"}], "explanations": {"总台": "总台是服务台，可以在那里留下名字和电话，符合句意。", "天空": "语义：天空上不能留下名字和电话，句意荒谬。", "小狗": "配价：「留下名字和电话」需要能承载文字或接收信息的地方或人，小狗不能承载，句子不成立。", "开水": "语义：开水不能用来留下名字和电话，句意荒谬。"}, "sentence_index": 6, "correct_answer": "总台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大楼门口放着一把总台，很结实。", "explanation": "这里应该用〈个〉。「把」用于有把手的东西，总台的量词是「个」。"}, {"text": "大楼的总台负责做饭。", "explanation": "这里应该用〈厨房〉。做饭是厨房的职责，总台负责接待、咨询和转接电话，与做饭无关。"}, {"text": "大厅里有一条总台，很干净。", "explanation": "这里应该用〈个〉。「条」用于细长的东西，总台的量词是「个」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "酒店有一棵总台，二十四小时有人。", "corrected_sentence": "酒店有一个总台，二十四小时有人。", "error_description": "总台是服务台，量词用「个」。「棵」用于树木，这里说「一棵总台」不对，应说「一个总台」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在酒店的总台们上班，很辛苦。", "corrected_sentence": "她在酒店的总台上班，很辛苦。", "error_description": "「们」只能加在指人的名词后面表示复数，「总台」是一个服务台，这里不能说「总台们」，应说「酒店的总台」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4a05ad7-c396-49f8-974f-4cbf30153dd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
