INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98057, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "总量是把所有的都加在一起，一共有多少。", "primary_collocate": null, "pronunciation": "zǒng liàng", "ipa": "tsʊŋ˨˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "把三个仓库的米加起来，总量是五百吨。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我们卖出的水果总量很大。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你算一下这批货的总量。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年全国的粮食总量又增加了。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的总量不变，只是从杯子倒进了瓶子。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先把每天的用电量加起来，再看总量。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市每年用水的总量超过了五亿吨。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里所有苹果的总量是多少？", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把大家交的钱加在一起，总量是三千元。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个班的书加在一起，总量有四百本。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "總量", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把各部分加在一起得到的一共多少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404dc866-8b49-473b-ac7d-65c2910bf2a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98057, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总量", "is_correct": true, "explanation": "正确：“总量”指全部加在一起的总数，与“加起来”一致。"}, {"text": "差额", "is_correct": false, "explanation": "语义：“差额”指两数相减后的余数，与“加起来”的相加意思相反。"}, {"text": "单价", "is_correct": false, "explanation": "搭配：“单价”指每件东西的价钱，不能用“吨”来计量。"}, {"text": "品种", "is_correct": false, "explanation": "语义：“品种”指物种或货物的类别，不是可以加起来的数量。"}], "explanations": {"总量": "正确：“总量”指全部加在一起的总数，与“加起来”一致。", "差额": "语义：“差额”指两数相减后的余数，与“加起来”的相加意思相反。", "单价": "搭配：“单价”指每件东西的价钱，不能用“吨”来计量。", "品种": "语义：“品种”指物种或货物的类别，不是可以加起来的数量。"}, "sentence_index": 0, "correct_answer": "总量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的身高总量是一米八。", "explanation": "这里应该用〈身高〉。身高是一个数值，不能把各部分加起来，不说总量。"}, {"text": "他的心情总量很好。", "explanation": "这里应该用〈心情〉。心情不能相加，不说总量。"}, {"text": "他的名字总量很好听。", "explanation": "这里不能用〈总量〉。名字不能相加，不说总量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总量", "is_correct": true, "explanation": "正确：“总量”指用水的全部数量，与“超过了五亿吨”一致。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”以人为单位计数，不能说超过了多少吨。"}, {"text": "费用", "is_correct": false, "explanation": "搭配：“费用”以元计算，不用“吨”来计量。"}, {"text": "水平", "is_correct": false, "explanation": "搭配：“水平”指高低程度，不能用“吨”来计量。"}], "explanations": {"总量": "正确：“总量”指用水的全部数量，与“超过了五亿吨”一致。", "人口": "语义：“人口”以人为单位计数，不能说超过了多少吨。", "费用": "搭配：“费用”以元计算，不用“吨”来计量。", "水平": "搭配：“水平”指高低程度，不能用“吨”来计量。"}, "sentence_index": 6, "correct_answer": "总量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的温度总量是六十度。", "explanation": "这里应该用〈温度〉。温度不能把各部分加起来，不说总量。"}, {"text": "她的性格总量很开朗。", "explanation": "这里应该用〈性格〉。性格不能相加，不说总量。"}, {"text": "这首歌的节奏总量很快。", "explanation": "这里应该用〈节奏〉。节奏不能相加，不说总量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批货的总量的是三百吨。", "corrected_sentence": "这批货的总量是三百吨。", "error_description": "错误：“总量”后多加了“的”。“总量”后直接接“是”，不能再加“的”，应为“这批货的总量是三百吨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批水果的总量的很大。", "corrected_sentence": "这批水果的总量很大。", "error_description": "错误：“总量”与谓语“很大”之间多加了“的”。谓语前不用“的”，应为“这批水果的总量很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
