INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全部数量的总和。", "primary_collocate": null, "pronunciation": "zǒng liàng", "ipa": "tsʊŋ˨˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "地球上的水总量很大，但能喝的很少。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年的产品总量比去年多了一倍。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖里鱼的总量在慢慢减少。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂要控制排出的污水总量。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学每天读书的时间总量不少。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河一年的流水总量有多大？", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把牛奶的总量控制在一百瓶以内。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界上的石油总量是有限的。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，你每天吃糖的总量太多了。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的粮食总量够全国人吃一年。", "target_word": "总量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "總量", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某种东西全部数量的总和", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404dc866-8b49-473b-ac7d-65c2910bf2a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98058, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总量", "is_correct": true, "explanation": "正确：“总量”指水的全部数量，与“很大，但能喝的很少”的对比一致。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：温度说“高”或“低”，不说“很大”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与“但能喝的很少”的对比没有关系。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格说“高”或“低”，不说“很大”。"}], "explanations": {"总量": "正确：“总量”指水的全部数量，与“很大，但能喝的很少”的对比一致。", "温度": "搭配：温度说“高”或“低”，不说“很大”。", "颜色": "语义：颜色与“但能喝的很少”的对比没有关系。", "价格": "搭配：价格说“高”或“低”，不说“很大”。"}, "sentence_index": 0, "correct_answer": "总量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的年龄总量是二十岁。", "explanation": "这里应该用〈年龄〉。年龄是一个数值，不能把各部分加起来，不说总量。"}, {"text": "这只猫的脾气总量很温和。", "explanation": "这里应该用〈脾气〉。脾气不能相加，不说总量。"}, {"text": "这本书的内容总量很有趣。", "explanation": "这里应该用〈内容〉。“有趣”评价的是内容本身，不是数量，不说总量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总量", "is_correct": true, "explanation": "正确：“总量”指牛奶的全部数量，与“控制在一百瓶以内”一致。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能用瓶数来限定，“一百瓶以内”说的是数量。"}, {"text": "包装", "is_correct": false, "explanation": "搭配：“控制……在……以内”限定的应是数量，“包装”不能这样限定。"}, {"text": "保质期", "is_correct": false, "explanation": "语义：保质期以天或月计，与“一百瓶”不相配。"}], "explanations": {"总量": "正确：“总量”指牛奶的全部数量，与“控制在一百瓶以内”一致。", "价格": "语义：价格不能用瓶数来限定，“一百瓶以内”说的是数量。", "包装": "搭配：“控制……在……以内”限定的应是数量，“包装”不能这样限定。", "保质期": "语义：保质期以天或月计，与“一百瓶”不相配。"}, "sentence_index": 6, "correct_answer": "总量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张桌子的颜色总量是棕色。", "explanation": "这里应该用〈颜色〉。颜色不能相加，不说总量。"}, {"text": "这盘菜的味道总量很咸。", "explanation": "这里应该用〈味道〉。味道不能相加，不说总量。"}, {"text": "他的身体总量很健康。", "explanation": "这里不能用〈总量〉。身体是一个整体状况，不能把各部分加起来，不说总量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "全年的粮食总量了增加到五千吨。", "corrected_sentence": "全年的粮食总量增加到五千吨。", "error_description": "错误：“总量”后多加了“了”。“总量增加”是主谓结构，中间不能插入“了”，应为“全年的粮食总量增加到五千吨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "仓库里粮食的总量的很大。", "corrected_sentence": "仓库里粮食的总量很大。", "error_description": "错误：“总量”与谓语“很大”之间多加了“的”。谓语前不用“的”，应为“仓库里粮食的总量很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98062, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶名", "is_correct": true, "explanation": "恶名指坏的名声，与“美名”的好名声义相反，是反义关系。"}, {"text": "灯笼", "is_correct": false, "explanation": "灯笼指照明或装饰用的器具，与名声义无关，不是反义词。"}, {"text": "树叶", "is_correct": false, "explanation": "树叶指植物的叶子，与名声义无关，不是反义词。"}, {"text": "钢铁", "is_correct": false, "explanation": "钢铁指金属材料，与名声义无关，不是反义词。"}], "correct_answer": "恶名", "explanations": {"恶名": "恶名指坏的名声，与“美名”的好名声义相反，是反义关系。", "灯笼": "灯笼指照明或装饰用的器具，与名声义无关，不是反义词。", "树叶": "树叶指植物的叶子，与名声义无关，不是反义词。", "钢铁": "钢铁指金属材料，与名声义无关，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98062, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶名", "is_correct": true, "explanation": "恶名指坏的名声，与“美名”的好名声义相反，是反义关系。"}, {"text": "窗帘", "is_correct": false, "explanation": "窗帘指遮挡窗户的织物，与名声义无关，不是反义词。"}, {"text": "山峰", "is_correct": false, "explanation": "山峰指山的最高处，与名声义无关，不是反义词。"}, {"text": "瓷器", "is_correct": false, "explanation": "瓷器指陶瓷制品，与名声义无关，不是反义词。"}], "correct_answer": "恶名", "explanations": {"恶名": "恶名指坏的名声，与“美名”的好名声义相反，是反义关系。", "窗帘": "窗帘指遮挡窗户的织物，与名声义无关，不是反义词。", "山峰": "山峰指山的最高处，与名声义无关，不是反义词。", "瓷器": "瓷器指陶瓷制品，与名声义无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好的名声。", "primary_collocate": null, "pronunciation": "měi míng", "ipa": "meɪ˨˩˦ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "好的服务给这家酒店带来了美名。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了美名，做事一直很小心。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板在行业里有美名。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想为了钱丢掉多年的美名。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品牌靠好质量赢得了美名。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王做错事，坏了公司的美名。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街因为好吃的东西而有了美名。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师的美名要用很多年才能得到。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的美名不是别人给的，是自己做出来的。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有和平的美名。", "target_word": "美名", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "好的名声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '244a8996-a574-446d-85a5-426380410052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美名", "is_correct": true, "explanation": "美名指好名声，“好的服务带来了美名”说的是酒店因服务而有了好名声，符合句意。"}, {"text": "体貌", "is_correct": false, "explanation": "语义：“体貌”指人的外貌，不能说服务给酒店带来体貌。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”指地点的高度，不能作为“带来”的对象。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”是人身体的状态，不能说“给酒店带来体温”。"}], "explanations": {"美名": "美名指好名声，“好的服务带来了美名”说的是酒店因服务而有了好名声，符合句意。", "体貌": "语义：“体貌”指人的外貌，不能说服务给酒店带来体貌。", "海拔": "搭配：“海拔”指地点的高度，不能作为“带来”的对象。", "体温": "搭配：“体温”是人身体的状态，不能说“给酒店带来体温”。"}, "sentence_index": 0, "correct_answer": "美名"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他为了赚钱坑害顾客，结果在圈子里有了美名。", "explanation": "这里应该用〈臭名〉。美名只指好名声，坑害顾客带来的是负面名声，与“美名”的褒义相矛盾。"}, {"text": "这家公司因为泄露用户隐私，一夜之间有了美名。", "explanation": "这里应该用〈骂名〉。美名只指好名声，泄露用户隐私只会招来骂名。"}, {"text": "这个明星靠炒作，一夜之间有了美名。", "explanation": "这里应该用〈名气〉。“名气”指知名度，不论好坏；靠炒作得到的只是名气，不能说美名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美名", "is_correct": true, "explanation": "美名指好名声，“这条街因为好吃的东西而有了美名”说的是街道因此得到好口碑，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”属于人，不能说街道“有了年龄”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”指人的高矮，街道没有身高，不能这样搭配。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是个人的医疗记录，街道不会有病历，与“好吃的东西”的语境不符。"}], "explanations": {"美名": "美名指好名声，“这条街因为好吃的东西而有了美名”说的是街道因此得到好口碑，符合句意。", "年龄": "搭配：“年龄”属于人，不能说街道“有了年龄”。", "身高": "搭配：“身高”指人的高矮，街道没有身高，不能这样搭配。", "病历": "语义：病历是个人的医疗记录，街道不会有病历，与“好吃的东西”的语境不符。"}, "sentence_index": 6, "correct_answer": "美名"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家常年打仗，在国际上有了美名。", "explanation": "这里应该用〈恶名〉。美名指好名声，常年打仗的国家不会因此获得美名，与句中的负面事实相矛盾。"}, {"text": "这家餐厅的饭菜又脏又贵，大家都说它有了美名。", "explanation": "这里应该用〈坏名声〉。美名只指好名声，饭菜又脏又贵的餐厅不会得到美名。"}, {"text": "这个官员贪污受贿，在民间却有了美名。", "explanation": "这里应该用〈骂名〉。美名指好名声，贪污受贿只能招致骂名，与“美名”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家饭店因为服务好，有了一件美名。", "corrected_sentence": "这家饭店因为服务好，有了一个美名。", "error_description": "错误：用了“件”。“美名”是抽象名词，应用“个”；“件”多用于物品、事情，不用于名声。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇因为干净，有了一条美名。", "corrected_sentence": "这个小镇因为干净，有了一个美名。", "error_description": "错误：用了“条”。“条”用于细长的东西，不能用于抽象的“美名”，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
