INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98065, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "美金是美国用的钱。", "primary_collocate": null, "pronunciation": "měi jīn", "ipa": "meɪ̯˨˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "这件衣服要五十美金。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去银行把人民币换成了美金。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸在美国工作，每个月寄美金回家。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百美金能换多少人民币？", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时我带了五百美金。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书在美国卖十美金。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把美金放在钱包里。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在那家商店可以用美金付钱。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把美金交给朋友保管。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的零花钱是每周两美金。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "日常说的美国的钱，用于兑换、购物、标价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美金", "is_correct": true, "explanation": "“美金”是美国的钱，用来表示价钱，与“五十”搭配。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“要五十时间”说不通，这里说的是价钱，需要货币单位。"}, {"text": "尺码", "is_correct": false, "explanation": "搭配：“要五十”后面接价钱，“尺码”不能这样标价。"}, {"text": "面料", "is_correct": false, "explanation": "语义：“面料”是布料，不表示花费的钱数。"}], "explanations": {"美金": "“美金”是美国的钱，用来表示价钱，与“五十”搭配。", "时间": "语义：“要五十时间”说不通，这里说的是价钱，需要货币单位。", "尺码": "搭配：“要五十”后面接价钱，“尺码”不能这样标价。", "面料": "语义：“面料”是布料，不表示花费的钱数。"}, "sentence_index": 0, "correct_answer": "美金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的手里拿着一本美金。", "explanation": "这里应该用〈张〉。美金是纸币，量词用“张”，“本”用于书册。"}, {"text": "他给了我一条美金。", "explanation": "这里应该用〈张〉。“条”用于细长的东西，不用于纸币。"}, {"text": "我的口袋里有一只美金。", "explanation": "这里应该用〈张〉。“只”多用于小动物或成对的东西，不用于纸币。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美金", "is_correct": true, "explanation": "“美金”是纸币，可以放进钱包里，与句子相符。"}, {"text": "清晨", "is_correct": false, "explanation": "语义：“清晨”是一段时间，不是能放进钱包的东西。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“放在……里”只接具体物品，“重量”不能这样放。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：“海浪”是水的运动，不能放进钱包里。"}], "explanations": {"美金": "“美金”是纸币，可以放进钱包里，与句子相符。", "清晨": "语义：“清晨”是一段时间，不是能放进钱包的东西。", "重量": "搭配：“放在……里”只接具体物品，“重量”不能这样放。", "海浪": "语义：“海浪”是水的运动，不能放进钱包里。"}, "sentence_index": 6, "correct_answer": "美金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她去美金旅游，拍了很多照片。", "explanation": "这里应该用〈美国〉。“美金”是钱，不是地方，去某个地方旅游要用“美国”。"}, {"text": "他在美金工作，每天都很忙。", "explanation": "这里应该用〈纽约〉。“美金”是钱，不是城市，表示工作地点要用“纽约”之类的地名。"}, {"text": "他每个月都从美金取工资。", "explanation": "这里应该用〈银行〉。“美金”是钱，不是地方，不能从它那里取钱，要从“银行”取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在银行换了一只美金。", "corrected_sentence": "我在银行换了一张美金。", "error_description": "错误：量词用错了。“美金”是纸币，应该用“张”，不能用“只”。正确：“我在银行换了一张美金。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把美金了藏在书包里了。", "corrected_sentence": "她把美金藏在书包里了。", "error_description": "错误：“了”放错了位置。“了”不能夹在“把”字结构的宾语“美金”与动词“藏”之间，应删去该“了”。正确：“她把美金藏在书包里了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
