INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98066, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "美国的货币，即美元。", "primary_collocate": null, "pronunciation": "měi jīn", "ipa": "meɪ̯˨˩ tɕin˥", "syllable_count": 2, "sentences": [{"text": "美金是美国使用的货币，也叫美元。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多国家的人都愿意存美金。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司用美金给员工发工资。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去美国留学需要准备很多美金。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美金和人民币的比价每天都在变。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在机场用人民币买了两百美金。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美金上印着美国总统的头像。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人常常用美金做生意。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷以前每年都存一点美金。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把剩下的美金带回了美国。", "target_word": "美金", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "作为美国货币的美元，用于存款、汇率、国际结算", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美金", "is_correct": true, "explanation": "“美金”是美国使用的货币，也就是美元，与句意相符。"}, {"text": "人民币", "is_correct": false, "explanation": "语义：人民币是中国的货币，不是美国使用的货币。"}, {"text": "日元", "is_correct": false, "explanation": "语义：日元是日本的货币，不是美国使用的货币。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是货币，与“也叫美元”不符。"}], "explanations": {"美金": "“美金”是美国使用的货币，也就是美元，与句意相符。", "人民币": "语义：人民币是中国的货币，不是美国使用的货币。", "日元": "语义：日元是日本的货币，不是美国使用的货币。", "面包": "语义：面包是食物，不是货币，与“也叫美元”不符。"}, "sentence_index": 0, "correct_answer": "美金"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她手里拿着一片美金。", "explanation": "这里应该用〈张〉。美金是纸币，量词用“张”，“片”用于薄而平的东西，不用于纸币。"}, {"text": "我买了一份美金。", "explanation": "这里应该用〈张〉。“份”多用于文件、报纸或饭菜，不用于纸币。"}, {"text": "他的钱包里有一台美金。", "explanation": "这里应该用〈张〉。“台”多用于机器、电器，不用于纸币。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美金", "is_correct": true, "explanation": "“美金”是纸币，纸币上才会印着总统的头像，与句意相符。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能印上图案，句中说的是印在纸币上。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能被印上东西，与“印着头像”不符。"}, {"text": "树林", "is_correct": false, "explanation": "搭配：“印着”要印在纸张、纸币等平面上，“树林”不能这样用。"}], "explanations": {"美金": "“美金”是纸币，纸币上才会印着总统的头像，与句意相符。", "大海": "语义：大海不能印上图案，句中说的是印在纸币上。", "天空": "语义：天空不能被印上东西，与“印着头像”不符。", "树林": "搭配：“印着”要印在纸张、纸币等平面上，“树林”不能这样用。"}, "sentence_index": 6, "correct_answer": "美金"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她想去美金留学。", "explanation": "这里应该用〈美国〉。“美金”是货币，不是地方，去哪里留学要用“美国”。"}, {"text": "她在美金工作。", "explanation": "这里应该用〈中国〉。“美金”是钱，不是工作的地方，表示工作地点时用“中国”这类地名。"}, {"text": "她早饭吃了一碗美金粥。", "explanation": "这里应该用〈小米〉。“美金”是货币，不是食物，粥要说“小米粥”之类的食物名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只美金是我朋友给的。", "corrected_sentence": "这张美金是我朋友给的。", "error_description": "错误：量词用错了。“美金”是纸币，应该用“张”，不能用“只”。正确：“这张美金是我朋友给的。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想把这些美金了换成人民币。", "corrected_sentence": "我想把这些美金换成人民币。", "error_description": "错误：“了”放在了“把”字的宾语“美金”后面。正确：“我想把这些美金换成人民币。”“把”字句中，“了”不能夹在宾语和动词之间，这里表示打算，不需要“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
