INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98069, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "自指是一句话说的是它自己。", "primary_collocate": null, "pronunciation": "zì zhǐ", "ipa": "tsɨ˥˩ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这句话很短，是一句自指的话。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话说的是它自己，所以它是自指的。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么叫自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这句话很短”是自指，因为它说的是自己。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我在说谎”这句话为什么奇怪？因为它自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要句子在说它自己，就是自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有一句话是自指的，你找到了吗？", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子不自指，它说的是别人。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自指的句子说的是自己，有时很有意思。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "句子说到自己，数学家叫它自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自指性", "label": "复合"}, {"form": "自指句", "label": "复合"}], "register": "书面", "sense_fingerprint": "一句话说的是这句话本身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df752ed1-047e-4fbd-b779-b0ded6150625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98069, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自指", "is_correct": true, "explanation": "自指（zì zhǐ）指一句话说的是它自己。"}, {"text": "自知", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是知道自己。"}, {"text": "自此", "is_correct": false, "explanation": "cǐ 与 zhǐ 声母不同（c 与 zh），声调相同，意思是从此以后。"}, {"text": "自制", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是克制自己。"}], "explanations": {"自指": "自指（zì zhǐ）指一句话说的是它自己。", "自知": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是知道自己。", "自此": "cǐ 与 zhǐ 声母不同（c 与 zh），声调相同，意思是从此以后。", "自制": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是克制自己。"}, "sentence_index": null, "correct_answer": "自指"}, "level_3": {"options": [{"text": "自指", "is_correct": true, "explanation": "正确：“自指”说句子指向它自身，与“是一句……的话”的描述相符。"}, {"text": "漫长", "is_correct": false, "explanation": "语义：“漫长”形容时间或距离很长，与“很短”的句子不合。"}, {"text": "深厚", "is_correct": false, "explanation": "搭配：“深厚”多修饰感情、基础，不修饰话语，“深厚的话”不成立。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体形，不能用来描述一句话。"}], "explanations": {"自指": "正确：“自指”说句子指向它自身，与“是一句……的话”的描述相符。", "漫长": "语义：“漫长”形容时间或距离很长，与“很短”的句子不合。", "深厚": "搭配：“深厚”多修饰感情、基础，不修饰话语，“深厚的话”不成立。", "高大": "体貌：“高大”形容人或物的体形，不能用来描述一句话。"}, "sentence_index": 0, "correct_answer": "自指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他自指是一名老师。", "explanation": "这里应该用〈自称〉。自指说的是语句或符号指向它自身，不用来说人对自己身份的称呼。"}, {"text": "我每天晚上都自指，想想今天做了什么。", "explanation": "这里应该用〈自省〉。自指是语句指向它自身，不指人反省自己的言行。"}, {"text": "他每天早起，坚持自指，从不偷懒。", "explanation": "这里应该用〈自律〉。这里说的是约束自己，自指只用于语句指向它自身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = 