INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98069, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "自指", "is_correct": true, "explanation": "自指（zì zhǐ）指一句话说的是它自己。"}, {"text": "自己", "is_correct": false, "explanation": "jǐ 与 zhǐ 声母不同（j 与 zh），声调相同，意思是本人。"}, {"text": "自始", "is_correct": false, "explanation": "shǐ 与 zhǐ 声母不同（sh 与 zh），声调相同，意思是从开始。"}, {"text": "自治", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是自己管理自己。"}], "explanations": {"自指": "自指（zì zhǐ）指一句话说的是它自己。", "自己": "jǐ 与 zhǐ 声母不同（j 与 zh），声调相同，意思是本人。", "自始": "shǐ 与 zhǐ 声母不同（sh 与 zh），声调相同，意思是从开始。", "自治": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是自己管理自己。"}, "sentence_index": null, "correct_answer": "自指"}, "level_3": {"options": [{"text": "自指", "is_correct": true, "explanation": "正确：“自指”说句子指向它自身，与“一句话是……的”的描述相符。"}, {"text": "疲惫", "is_correct": false, "explanation": "语义：“疲惫”形容人的精神状态，句子不会疲惫。"}, {"text": "圆形", "is_correct": false, "explanation": "体貌：“圆形”描述物体的外形，不能用来形容一句话。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”描述人不说话的状态，用在句子上不通。"}], "explanations": {"自指": "正确：“自指”说句子指向它自身，与“一句话是……的”的描述相符。", "疲惫": "语义：“疲惫”形容人的精神状态，句子不会疲惫。", "圆形": "体貌：“圆形”描述物体的外形，不能用来形容一句话。", "沉默": "语义：“沉默”描述人不说话的状态，用在句子上不通。"}, "sentence_index": 6, "correct_answer": "自指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为考试没考好而自指，很难过。", "explanation": "这里应该用〈自责〉。自指是语句指向它自身，不表示责怪自己。"}, {"text": "他在朋友面前总是自指，说自己很厉害。", "explanation": "这里应该用〈自夸〉。自指不表示夸耀自己，夸耀要用〈自夸〉。"}, {"text": "他靠自己的努力自指，不再依赖父母。", "explanation": "这里应该用〈自立〉。自指是语句指向它自身，这里说的是独立生活，要用〈自立〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validati