INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段文字里有一句话是自指地，你能找到吗？", "corrected_sentence": "这段文字里有一句话是自指的，你能找到吗？", "error_description": "错误形式：“自指地”；正确形式：“自指的”。“是……的”结构后要用“的”，“地”只用于修饰动作，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
