INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98070, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "语句、符号等指向其自身。", "primary_collocate": null, "pronunciation": "zì zhǐ", "ipa": "tsɨ˥˩ ʈʂɨ˨˩˦", "syllable_count": 2, "sentences": [{"text": "一份说明写着“本说明共三段”，这种写法就是自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个符号指向它自己，是自指的符号。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个“它”指的是这句话，是自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图里的箭头指向自己，这种情况叫自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图片里有一张它自己的小图，可以说是自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "目录里有一页写着“见本页”，这就是自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画里的画里还有一幅同样的画，有点像自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，语句指向自己时就叫自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网页上的链接指向本页，算不算自指？", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“今天下雨”说的是天气，没有指向自己，不是自指。", "target_word": "自指", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自指性", "label": "复合"}], "register": "书面", "sense_fingerprint": "语句、符号、图示等指向它们自身", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df752ed1-047e-4fbd-b779-b0ded6150625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98070, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自指", "is_correct": true, "explanation": "自指（zì zhǐ）指语句、符号等指向它们自身。"}, {"text": "自知", "is_correct": false, "explanation": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是知道自己。"}, {"text": "自此", "is_correct": false, "explanation": "cǐ 与 zhǐ 声母不同（c 与 zh），声调相同，意思是从此以后。"}, {"text": "自制", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是克制自己。"}], "explanations": {"自指": "自指（zì zhǐ）指语句、符号等指向它们自身。", "自知": "zhī（第一声）与 zhǐ（第三声）声调不同，意思是知道自己。", "自此": "cǐ 与 zhǐ 声母不同（c 与 zh），声调相同，意思是从此以后。", "自制": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是克制自己。"}, "sentence_index": null, "correct_answer": "自指"}, "level_3": {"options": [{"text": "自指", "is_correct": true, "explanation": "正确：“自指”指写法让句子或符号指向自身，与“就是……”的说明相符。"}, {"text": "狼狈", "is_correct": false, "explanation": "语义：“狼狈”形容人处境窘迫，不能用来说一种写法。"}, {"text": "高亢", "is_correct": false, "explanation": "搭配：“高亢”多修饰声音或情绪，不能修饰“写法”。"}, {"text": "肥胖", "is_correct": false, "explanation": "体貌：“肥胖”描述人或动物的体形，不能用来说写法。"}], "explanations": {"自指": "正确：“自指”指写法让句子或符号指向自身，与“就是……”的说明相符。", "狼狈": "语义：“狼狈”形容人处境窘迫，不能用来说一种写法。", "高亢": "搭配：“高亢”多修饰声音或情绪，不能修饰“写法”。", "肥胖": "体貌：“肥胖”描述人或动物的体形，不能用来说写法。"}, "sentence_index": 0, "correct_answer": "自指"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块路牌自指了去车站的方向。", "explanation": "这里应该用〈指示〉。自指只用于语句、符号指向它们自身，路牌指示方向要用〈指示〉。"}, {"text": "老师自指了我的错误。", "explanation": "这里应该用〈指出〉。自指指向的是自身，老师指出别人的错误要用〈指出〉。"}, {"text": "这个代词自指前面的名词。", "explanation": "这里应该用〈指代〉。代词指向前面的词，指向的不是它自身，所以不用“自指”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98070, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "自指", "is_correct": true, "explanation": "自指（zì zhǐ）指语句、符号等指向它们自身。"}, {"text": "自己", "is_correct": false, "explanation": "jǐ 与 zhǐ 声母不同（j 与 zh），声调相同，意思是本人。"}, {"text": "自始", "is_correct": false, "explanation": "shǐ 与 zhǐ 声母不同（sh 与 zh），声调相同，意思是从开始。"}, {"text": "自治", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是自己管理自己。"}], "explanations": {"自指": "自指（zì zhǐ）指语句、符号等指向它们自身。", "自己": "jǐ 与 zhǐ 声母不同（j 与 zh），声调相同，意思是本人。", "自始": "shǐ 与 zhǐ 声母不同（sh 与 zh），声调相同，意思是从开始。", "自治": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是自己管理自己。"}, "sentence_index": null, "correct_answer": "自指"}, "level_3": {"options": [{"text": "自指", "is_correct": true, "explanation": "正确：“自指”说画或符号指向自身，与“有点像……”的比喻相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是人的动作，画中的画不会睡觉，句子不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”是人或动物的生理动作，不能用来比喻画中的画。"}, {"text": "嘚瑟", "is_correct": false, "explanation": "语域：“嘚瑟”是北方口语，意为显摆，与书面的说明语境不合，也不指递归。"}], "explanations": {"自指": "正确：“自指”说画或符号指向自身，与“有点像……”的比喻相符。", "睡觉": "语义：“睡觉”是人的动作，画中的画不会睡觉，句子不通。", "咳嗽": "语义：“咳嗽”是人或动物的生理动作，不能用来比喻画中的画。", "嘚瑟": "语域：“嘚瑟”是北方口语，意为显摆，与书面的说明语境不合，也不指递归。"}, "sentence_index": 6, "correct_answer": "自指"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友自指我怎么写作文。", "explanation": "这里应该用〈指点〉。指点是给别人指出方法，自指只用于指向自身。"}, {"text": "同学自指他迟到。", "explanation": "这里应该用〈指责〉。指责是批评别人的过错，不是指向自身。"}, {"text": "警察自指交通。", "explanation": "这里应该用〈指挥〉。指挥是引导交通，自指只用于语句、符号指向它们自身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张表格里写着“本表有五列”，它是自指地。", "corrected_sentence": "这张表格里写着“本表有五列”，它是自指的。", "error_description": "错误形式：“是自指地”；正确形式：“是自指的”。“是……的”结构后要用“的”，“地”只修饰动作，不能用于这里。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个图标指向它自己，所以它是自指了的。", "corrected_sentence": "这个图标指向它自己，所以它是自指的。", "error_description": "错误形式：“自指了的”；正确形式：“自指的”。“是……的”结构中的“自指”表示性质，这里没有完成的动作，不应加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '569a56e3-4404-4d2f-ad52-b3bb186d0705') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
