INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98073, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "举措是为了做成一件事而想出来、做出来的办法和行动。", "primary_collocate": null, "pronunciation": "jǔ cuò", "ipa": "tɕy˨˩ tsʰwo˥˩", "syllable_count": 2, "sentences": [{"text": "政府出台了新的举措。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项举措帮了很多人。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保护环境，学校想出了一些举措。", "target_word": "举措", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些举措很有用，空气好多了。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司采取了新举措，客人变多了。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都支持这项举措。", "target_word": "举措", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你觉得这项举措怎么样？", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项举措让我们的生活方便多了。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他提出了几项节约用水的举措。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项举措没有成功，因为钱不够。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "舉措", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为做成某事而想出并实行的办法和行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98073, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苹果", "is_correct": false, "explanation": "语义：苹果是实物，不能“出台”，“出台了新的苹果”句意不通。"}, {"text": "举措", "is_correct": true, "explanation": "正确：“出台”的对象是办法或行动，“举措”与之搭配。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“出台”通常用于政策、办法，不说“出台房子”。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“出台”不用于歌曲，不说“出台了新的歌”。"}], "explanations": {"苹果": "语义：苹果是实物，不能“出台”，“出台了新的苹果”句意不通。", "举措": "正确：“出台”的对象是办法或行动，“举措”与之搭配。", "房子": "搭配：“出台”通常用于政策、办法，不说“出台房子”。", "歌": "搭配：“出台”不用于歌曲，不说“出台了新的歌”。"}, "sentence_index": 0, "correct_answer": "举措"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他挥手的举措很快。", "explanation": "这里应该用〈动作〉。举措指为达到目的而采取的办法或行动，不用来形容身体的动作。"}, {"text": "政府出台了一把举措。", "explanation": "这里应该用〈项〉或〈个〉。〈把〉用于有柄的器具，不用来数举措。"}, {"text": "他喊出了响亮的举措。", "explanation": "这里应该用〈口号〉。举措是办法或行动，不能用“喊出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "失误", "is_correct": false, "explanation": "语义：失误是做错的事，不是可以评价好坏的做法，句意不通。"}, {"text": "错误", "is_correct": false, "explanation": "语义：错误是需要改正的问题，不用来讨论“怎么样”的评价。"}, {"text": "伤害", "is_correct": false, "explanation": "搭配：“觉得……怎么样”一般用于评价事物，不说评价“伤害”。"}, {"text": "举措", "is_correct": true, "explanation": "正确：“你觉得这项举措怎么样”是对办法或行动的评价，与句意相合。"}], "explanations": {"失误": "语义：失误是做错的事，不是可以评价好坏的做法，句意不通。", "错误": "语义：错误是需要改正的问题，不用来讨论“怎么样”的评价。", "伤害": "搭配：“觉得……怎么样”一般用于评价事物，不说评价“伤害”。", "举措": "正确：“你觉得这项举措怎么样”是对办法或行动的评价，与句意相合。"}, "sentence_index": 6, "correct_answer": "举措"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他吃完了这项举措，很饱。", "explanation": "这里应该用〈饭〉。举措是为做成一件事而采取的办法和行动，不是食物，不能用“吃”。"}, {"text": "他提出了一块举措。", "explanation": "这里应该用〈项〉。〈块〉用于块状的东西，不用来数举措。"}, {"text": "他写完了举措，很累。", "explanation": "这里应该用〈作业〉。作业可以“写完”，举措应说“采取”或“完成”，不说“写完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府出台了一座新举措。", "corrected_sentence": "政府出台了一项新举措。", "error_description": "“举措”的量词用“项”；“座”用于山、房屋等大型固定的东西，不能用来数举措。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府将采取新的举措们。", "corrected_sentence": "政府将采取新的举措。", "error_description": "错误：“举措们”，“们”用于指人或有生命的事物，不能加在抽象名词“举措”后面，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
