INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98074, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为处理某事而采取的行动或办法。", "primary_collocate": null, "pronunciation": "jǔ cuò", "ipa": "tɕy˨˩ tsʰwo˥˩", "syllable_count": 2, "sentences": [{"text": "面对问题，公司马上采取了举措。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院为病人安全推出了新举措。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的这项举措让学生很高兴。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市里为了减少堵车，想了很多举措。", "target_word": "举措", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一举措得到了家长的支持。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出了事故以后，工厂有哪些举措？", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂的举措很及时，工人都没受伤。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要看政府下一步有什么举措。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些举措都是为了解决问题。", "target_word": "举措", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地铁公司加了车，这项举措很受欢迎。", "target_word": "举措", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}, {"form": "舉措", "label": "繁体"}], "register": "书面", "sense_fingerprint": "为处理某事而采取的行动或办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d67113b-2eb9-4638-9bb1-bf038485b722') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98074, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饭", "is_correct": false, "explanation": "语义：“采取”的对象是办法或行动，“饭”不能被采取，句意不通。"}, {"text": "举措", "is_correct": true, "explanation": "正确：“采取了举措”是为处理问题而行动，与“面对问题”相合。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“采取”不与“电影”搭配，不说“采取了电影”。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“采取”不与“歌”搭配，不说“采取了歌”。"}], "explanations": {"饭": "语义：“采取”的对象是办法或行动，“饭”不能被采取，句意不通。", "举措": "正确：“采取了举措”是为处理问题而行动，与“面对问题”相合。", "电影": "搭配：“采取”不与“电影”搭配，不说“采取了电影”。", "歌": "搭配：“采取”不与“歌”搭配，不说“采取了歌”。"}, "sentence_index": 0, "correct_answer": "举措"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "市里为了减少堵车，喊了很多举措。", "explanation": "这里应该用〈口号〉。举措是为解决问题采取的办法或行动，不能用“喊”。"}, {"text": "市里为了减少堵车，想了一把举措。", "explanation": "这里应该用〈项〉。〈把〉用于有柄的器具，不用来数举措。"}, {"text": "他做了一个投篮举措，得了三分。", "explanation": "这里应该用〈动作〉。举措指办法或行动，不用来说篮球中的投篮动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "衣服", "is_correct": false, "explanation": "语义：衣服不能“及时”地保护大家，句意不通。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜不是行动，不能说“很及时”来避免受伤。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“及时”修饰行动或措施，不说“窗帘很及时”。"}, {"text": "举措", "is_correct": true, "explanation": "正确：“他的举措很及时”指他采取的行动及时，与“大家都没受伤”相合。"}], "explanations": {"衣服": "语义：衣服不能“及时”地保护大家，句意不通。", "眼镜": "语义：眼镜不是行动，不能说“很及时”来避免受伤。", "窗帘": "搭配：“及时”修饰行动或措施，不说“窗帘很及时”。", "举措": "正确：“他的举措很及时”指他采取的行动及时，与“大家都没受伤”相合。"}, "sentence_index": 6, "correct_answer": "举措"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地铁公司修了新的举措，很受欢迎。", "explanation": "这里应该用〈设施〉。举措是办法或行动，不能说“修”。"}, {"text": "地铁公司加了一辆举措，很受欢迎。", "explanation": "这里应该用〈项〉。〈辆〉用于车辆，不用来数举措。"}, {"text": "这项举措很好听，大家都爱唱。", "explanation": "这里应该用〈歌〉。举措不是声音，不能说“好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "面对问题，公司马上采取了一辆举措。", "corrected_sentence": "面对问题，公司马上采取了一项举措。", "error_description": "“举措”的量词用“项”，“辆”只用于车辆。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这项的举措做得很好。", "corrected_sentence": "他把这项举措做得很好。", "error_description": "错误：“这项的举措”，量词“项”与名词之间不加“的”，应去掉“的”，说“这项举措”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4fa7d873-60a4-41de-a4d0-25b69301d7d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
