INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98077, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "虾是生活在水里的小动物，身体弯弯的，有很多腿，煮熟了变红。", "primary_collocate": null, "pronunciation": "xiā", "ipa": "ɕja˥", "syllable_count": 1, "sentences": [{"text": "这盘虾煮熟了，红红的，很好看。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘清蒸的虾很鲜嫩。", "target_word": "虾", "complexity_tier": "T3", "furigana": "zhè pán qīng zhēng de xiā hěn xiān nèn。", "sentence_source": "generated"}, {"text": "池塘里有几只虾在游。", "target_word": "虾", "complexity_tier": "T3", "furigana": "chí táng lǐ yǒu jǐ zhī xiā zài yóu。", "sentence_source": "generated"}, {"text": "他不吃肉，可是爱吃虾。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去海边买了两斤新鲜的虾。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虾的腿很多，身体是弯的。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在河边用网捞虾。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市的虾新鲜，价格也合适。", "target_word": "虾", "complexity_tier": "T3", "furigana": "zhè jiā chāo shì de xiā xīn xiān, jià gé yě hé shì。", "sentence_source": "generated"}, {"text": "请把虾洗干净，再放进锅里。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只虾还活着，还在水里动。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "斤", "label": "量词"}, {"form": "对虾", "label": "复合"}, {"form": "龙虾", "label": "复合"}, {"form": "蝦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水里的小动物，煮熟变红", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98077, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "虾", "is_correct": true, "explanation": "虾：生活在水中、身体弯曲、有壳的动物，是正确答案。"}, {"text": "夏", "is_correct": false, "explanation": "xià（第四声）与 xiā（第一声）声调不同，意思是“夏天”。"}, {"text": "霞", "is_correct": false, "explanation": "xiá（第二声）与 xiā（第一声）声调不同，意思是“晚霞”。"}, {"text": "箱", "is_correct": false, "explanation": "xiāng 与 xiā 韵母不同（ang 与 a），意思是“箱子”。"}], "explanations": {"虾": "虾：生活在水中、身体弯曲、有壳的动物，是正确答案。", "夏": "xià（第四声）与 xiā（第一声）声调不同，意思是“夏天”。", "霞": "xiá（第二声）与 xiā（第一声）声调不同，意思是“晚霞”。", "箱": "xiāng 与 xiā 韵母不同（ang 与 a），意思是“箱子”。"}, "sentence_index": null, "correct_answer": "虾"}, "level_3": {"options": [{"text": "虾", "is_correct": true, "explanation": "正确：“这盘”后面可以接煮熟的菜，虾符合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能煮熟，也不能装在盘子里做成菜。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“盘”用于菜肴，不能用来量书。"}, {"text": "衣服", "is_correct": false, "explanation": "语义：衣服不能煮熟上桌，“红红的，很好看”也不能用来形容它。"}], "explanations": {"虾": "正确：“这盘”后面可以接煮熟的菜，虾符合。", "石头": "语义：石头不能煮熟，也不能装在盘子里做成菜。", "书": "搭配：量词“盘”用于菜肴，不能用来量书。", "衣服": "语义：衣服不能煮熟上桌，“红红的，很好看”也不能用来形容它。"}, "sentence_index": 0, "correct_answer": "虾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈买了一座虾，回家炒着吃。", "explanation": "这里应该用〈只〉。“座”用于山、房屋等大型固定的东西，虾不能用“座”来数。"}, {"text": "孩子在草地上找到一棵虾。", "explanation": "这里应该用〈只〉。“棵”用于树木、草等植物，虾不能用“棵”来数。"}, {"text": "他一口气吃了三本虾。", "explanation": "这里应该用〈只〉。“本”用于书籍、本子，虾不能用“本”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98077, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "虾", "is_correct": true, "explanation": "虾：生活在水中、身体弯曲、有壳的动物，是正确答案。"}, {"text": "下", "is_correct": false, "explanation": "xià（第四声）与 xiā（第一声）声调不同，意思是“下面”。"}, {"text": "侠", "is_correct": false, "explanation": "xiá（第二声）与 xiā（第一声）声调不同，意思是“侠客”。"}, {"text": "香", "is_correct": false, "explanation": "xiāng 与 xiā 韵母不同（ang 与 a），意思是“香气”。"}], "explanations": {"虾": "虾：生活在水中、身体弯曲、有壳的动物，是正确答案。", "下": "xià（第四声）与 xiā（第一声）声调不同，意思是“下面”。", "侠": "xiá（第二声）与 xiā（第一声）声调不同，意思是“侠客”。", "香": "xiāng 与 xiā 韵母不同（ang 与 a），意思是“香气”。"}, "sentence_index": null, "correct_answer": "虾"}, "level_3": {"options": [{"text": "虾", "is_correct": true, "explanation": "正确：“捞”的对象是河里的水生动物，虾符合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能用网从河里捞出来。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“捞”不能与“空气”搭配。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是能用网捞起来的东西。"}], "explanations": {"虾": "正确：“捞”的对象是河里的水生动物，虾符合。", "桌子": "语义：桌子不能用网从河里捞出来。", "空气": "搭配：“捞”不能与“空气”搭配。", "时间": "语义：时间不是能用网捞起来的东西。"}, "sentence_index": 6, "correct_answer": "虾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家冰箱里还放着一本虾。", "explanation": "这里应该用〈只〉。“本”用于书籍、本子，虾不能用“本”来数。"}, {"text": "他把一张虾放进了锅里。", "explanation": "这里应该用〈只〉。“张”用于纸、桌子等平面的东西，虾不能用“张”来数。"}, {"text": "妈妈用一根虾炒了一盘菜。", "explanation": "这里应该用〈只〉。“根”用于细长的条状物，虾不能用“根”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些虾们都还活着。", "corrected_sentence": "这些虾都还活着。", "error_description": "多加了“们”：“们”只用于指人，虾不能加“们”，应说“这些虾都还活着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
