INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98078, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生活在水中的节肢动物，身体弯曲有壳，肉可食用。", "primary_collocate": null, "pronunciation": "xiā", "ipa": "ɕja˥", "syllable_count": 1, "sentences": [{"text": "我在市场买了一斤虾。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只虾的壳很硬，煮熟以后变成了红色。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有一袋冷冻的虾。", "target_word": "虾", "complexity_tier": "T3", "furigana": "chú fáng lǐ yǒu yí dài lěng dòng de xiā。", "sentence_source": "generated"}, {"text": "妈妈用油炒了一盘虾，很香。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一吃虾，身上就起红点。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把钓到的虾养在桶里。", "target_word": "虾", "complexity_tier": "T3", "furigana": "wǒ men bǎ diào dào de xiā yǎng zài tǒng lǐ。", "sentence_source": "generated"}, {"text": "这家饭馆的虾又大又新鲜。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟蹲在河边，看着水里的虾游来游去。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剥虾的时候要先去掉头和壳。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虾的身体弯弯的，有很多条腿。", "target_word": "虾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "斤", "label": "量词"}, {"form": "龙虾", "label": "复合"}, {"form": "虾米", "label": "复合"}, {"form": "蝦", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水中有壳的节肢动物，可食用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98078, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "虾", "is_correct": true, "explanation": "虾：生活在水中、身体弯曲、有壳的动物，是正确答案。"}, {"text": "下", "is_correct": false, "explanation": "xià（第四声）与 xiā（第一声）声调不同，意思是“下面”。"}, {"text": "霞", "is_correct": false, "explanation": "xiá（第二声）与 xiā（第一声）声调不同，意思是“晚霞”。"}, {"text": "香", "is_correct": false, "explanation": "xiāng 与 xiā 韵母不同（ang 与 a），意思是“香气”。"}], "explanations": {"虾": "虾：生活在水中、身体弯曲、有壳的动物，是正确答案。", "下": "xià（第四声）与 xiā（第一声）声调不同，意思是“下面”。", "霞": "xiá（第二声）与 xiā（第一声）声调不同，意思是“晚霞”。", "香": "xiāng 与 xiā 韵母不同（ang 与 a），意思是“香气”。"}, "sentence_index": null, "correct_answer": "虾"}, "level_3": {"options": [{"text": "虾", "is_correct": true, "explanation": "正确：“一斤”后面可以接按斤称卖的虾，市场上买的正是这种东西。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫是陆生宠物，不会在市场上按斤出售。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“斤”是称重单位，不能用来量钢琴。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子是会飞的昆虫，不是水里的动物，也不会按斤卖。"}], "explanations": {"虾": "正确：“一斤”后面可以接按斤称卖的虾，市场上买的正是这种东西。", "猫": "语义：猫是陆生宠物，不会在市场上按斤出售。", "钢琴": "搭配：“斤”是称重单位，不能用来量钢琴。", "蚊子": "语义：蚊子是会飞的昆虫，不是水里的动物，也不会按斤卖。"}, "sentence_index": 0, "correct_answer": "虾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一朵虾，放进了袋子里。", "explanation": "这里应该用〈只〉。“朵”用于花，虾不能用“朵”来数。"}, {"text": "妈妈在河边钓到了一棵虾。", "explanation": "这里应该用〈只〉。“棵”用于树木、草等植物，虾不能用“棵”来数。"}, {"text": "我们店里卖一张虾。", "explanation": "这里应该用〈只〉。“张”用于纸、桌子等平面的东西，虾不能用“张”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98078, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "虾", "is_correct": true, "explanation": "虾：生活在水中、身体弯曲、有壳的动物，是正确答案。"}, {"text": "夏", "is_correct": false, "explanation": "xià（第四声）与 xiā（第一声）声调不同，意思是“夏天”。"}, {"text": "箱", "is_correct": false, "explanation": "xiāng 与 xiā 韵母不同（ang 与 a），意思是“箱子”。"}, {"text": "侠", "is_correct": false, "explanation": "xiá（第二声）与 xiā（第一声）声调不同，意思是“侠客”。"}], "explanations": {"虾": "虾：生活在水中、身体弯曲、有壳的动物，是正确答案。", "夏": "xià（第四声）与 xiā（第一声）声调不同，意思是“夏天”。", "箱": "xiāng 与 xiā 韵母不同（ang 与 a），意思是“箱子”。", "侠": "xiá（第二声）与 xiā（第一声）声调不同，意思是“侠客”。"}, "sentence_index": null, "correct_answer": "虾"}, "level_3": {"options": [{"text": "虾", "is_correct": true, "explanation": "正确：饭馆提供的虾是食材，“又大又新鲜”可以用来形容它。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“新鲜”形容食物，不能用来形容房间。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不属于饭馆，“新鲜”也不能用来形容它。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“新鲜”不能形容钢笔。"}], "explanations": {"虾": "正确：饭馆提供的虾是食材，“又大又新鲜”可以用来形容它。", "房间": "搭配：“新鲜”形容食物，不能用来形容房间。", "月亮": "语义：月亮不属于饭馆，“新鲜”也不能用来形容它。", "钢笔": "搭配：“新鲜”不能形容钢笔。"}, "sentence_index": 6, "correct_answer": "虾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一口气吃了一本虾。", "explanation": "这里应该用〈只〉。“本”用于书籍、本子，虾不能用“本”来数。"}, {"text": "池塘里游着一座虾。", "explanation": "这里应该用〈只〉。“座”用于山、房屋等大型固定的东西，虾不能用“座”来数。"}, {"text": "他把一根虾放进了锅里。", "explanation": "这里应该用〈只〉。“根”用于细长的条状物，虾不能用“根”来数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他今天在超市买了两朵虾。", "corrected_sentence": "他今天在超市买了两只虾。", "error_description": "量词错误：“虾”应该用量词“只”，不能用“朵”。“朵”多用于花。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈昨天买了两粒虾。", "corrected_sentence": "妈妈昨天买了两只虾。", "error_description": "量词错误：“粒”用于米、沙子等颗粒状的小东西，不能用来数虾。数虾一般用“只”，应说“两只虾”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
