INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98079, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "虫是很小的动物，常常在草里或树上爬来爬去。", "primary_collocate": null, "pronunciation": "chóng", "ipa": "ʈʂʰʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "草里有一条虫，正在慢慢地爬。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上的虫爬来爬去，不知道在找什么。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见一条虫在叶子上爬。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用手抓了一条虫，高兴得大叫。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很怕虫，不敢走进草地。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果里有一条虫，不能吃了。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在树上找虫吃。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条虫爬得很慢，过了很久才爬到树上。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一条虫，你走路要小心。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把虫放在叶子上，让它慢慢爬走。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虫子", "label": "复合"}, {"form": "一条虫", "label": "量词"}, {"form": "蟲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "爬在草里、树上的小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98079, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "虫", "is_correct": true, "explanation": "虫（chóng，第二声）指小动物，就是句中所说的意思。"}, {"text": "充", "is_correct": false, "explanation": "充（chōng，第一声）与 chóng 声调不同，意思是充满、充足。"}, {"text": "宠", "is_correct": false, "explanation": "宠（chǒng，第三声）与 chóng 声调不同，意思是宠爱，如宠物。"}, {"text": "常", "is_correct": false, "explanation": "常（cháng）与 chóng 的韵母不同（ang 与 ong），意思是经常。"}, {"text": "从", "is_correct": false, "explanation": "从（cóng）与 chóng 的声母不同（c 与 ch），意思是跟随、从前。"}], "explanations": {"虫": "虫（chóng，第二声）指小动物，就是句中所说的意思。", "充": "充（chōng，第一声）与 chóng 声调不同，意思是充满、充足。", "宠": "宠（chǒng，第三声）与 chóng 声调不同，意思是宠爱，如宠物。", "常": "常（cháng）与 chóng 的韵母不同（ang 与 ong），意思是经常。", "从": "从（cóng）与 chóng 的声母不同（c 与 ch），意思是跟随、从前。"}, "sentence_index": null, "correct_answer": "虫"}, "level_3": {"options": [{"text": "河", "is_correct": false, "explanation": "语义：河是水流，不会在草里慢慢爬行。"}, {"text": "虫", "is_correct": true, "explanation": "正确：虫是会在草里慢慢爬的小动物，与句意相符。"}, {"text": "路", "is_correct": false, "explanation": "语义：路是地面的道路，不能自己爬。"}, {"text": "鱼", "is_correct": false, "explanation": "体貌：鱼生活在水里，身体有鳍而没有足，与会爬的小虫形态不同。"}], "explanations": {"河": "语义：河是水流，不会在草里慢慢爬行。", "虫": "正确：虫是会在草里慢慢爬的小动物，与句意相符。", "路": "语义：路是地面的道路，不能自己爬。", "鱼": "体貌：鱼生活在水里，身体有鳍而没有足，与会爬的小虫形态不同。"}, "sentence_index": 0, "correct_answer": "虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子用手抓了一本虫，高兴得大叫。", "explanation": "这里应该用〈条〉。“本”用于书籍，虫要用“条”或“只”。"}, {"text": "我家院子里有一台虫在草地上爬。", "explanation": "这里应该用〈只〉。“台”用于机器、电器，虫要用“只”或“条”。"}, {"text": "小鸟在树上找一朵虫吃。", "explanation": "这里应该用〈只〉。“朵”用于花、云，虫要用“只”或“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98079, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "虫", "is_correct": true, "explanation": "虫（chóng，第二声）指小动物，就是句中所说的意思。"}, {"text": "冲", "is_correct": false, "explanation": "冲（chōng，第一声）与 chóng 声调不同，意思是冲击、冲刷。"}, {"text": "长", "is_correct": false, "explanation": "长（cháng）与 chóng 的韵母不同（a 与 o），意思是长短的长。"}, {"text": "丛", "is_correct": false, "explanation": "丛（cóng）与 chóng 的声母不同（c 与 ch），意思是丛林、草丛。"}], "explanations": {"虫": "虫（chóng，第二声）指小动物，就是句中所说的意思。", "冲": "冲（chōng，第一声）与 chóng 声调不同，意思是冲击、冲刷。", "长": "长（cháng）与 chóng 的韵母不同（a 与 o），意思是长短的长。", "丛": "丛（cóng）与 chóng 的声母不同（c 与 ch），意思是丛林、草丛。"}, "sentence_index": null, "correct_answer": "虫"}, "level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不是可以吃的东西，与“小鸟找吃的”的情境矛盾。"}, {"text": "虫", "is_correct": true, "explanation": "正确：虫是小鸟在树上找来吃的东西，与句意相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能吃，与“小鸟在树上找”的情境矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“吃”的对象应是食物，“玩具”不能与“吃”搭配。"}], "explanations": {"石头": "语义：石头不是可以吃的东西，与“小鸟找吃的”的情境矛盾。", "虫": "正确：虫是小鸟在树上找来吃的东西，与句意相符。", "书": "语义：书不能吃，与“小鸟在树上找”的情境矛盾。", "玩具": "搭配：“吃”的对象应是食物，“玩具”不能与“吃”搭配。"}, "sentence_index": 6, "correct_answer": "虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那条虫对着我吠了一声。", "explanation": "这里应该用〈狗〉。吠是狗的叫声，虫不会吠。"}, {"text": "这条虫在厨房里做饭。", "explanation": "这里应该用〈人〉。做饭是人的活动，虫不会做饭。"}, {"text": "这条虫在教室里写作业。", "explanation": "这里应该用〈学生〉。写作业是学生的活动，虫不会写作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在花园里看见一头虫在花上爬。", "corrected_sentence": "我在花园里看见一只虫在花上爬。", "error_description": "错误：“一头虫”，“头”用于大牲畜，虫要用“只”或“条”。正确：“一只虫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "草地上有两张虫。", "corrected_sentence": "草地上有两条虫。", "error_description": "错误：“两张虫”，“张”用于纸、桌子等平面的东西，虫要用“条”或“只”。正确：“两条虫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
