INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98080, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体小、多有足或翅的小型动物，多指昆虫。", "primary_collocate": null, "pronunciation": "chóng", "ipa": "ʈʂʰʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "夏天的晚上，灯下有很多虫飞来飞去。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种虫有六条腿，还有两对翅膀。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的虫会飞，有的虫只会爬。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上别开窗，会有虫飞进来。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的夜里，草里的虫叫个不停。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里有各种各样的虫。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只虫的翅膀是绿色的，很漂亮。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了一只很大的虫。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚊子是一种让人讨厌的虫。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种虫白天睡觉，夜里才出来。", "target_word": "虫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "虫子", "label": "复合"}, {"form": "一只虫", "label": "量词"}, {"form": "一种虫", "label": "量词"}, {"form": "蟲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有足有翅的昆虫类小动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98080, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "虫", "is_correct": true, "explanation": "虫（chóng，第二声）指昆虫这类小动物，就是句中所说的意思。"}, {"text": "充", "is_correct": false, "explanation": "充（chōng，第一声）与 chóng 声调不同，意思是充满、充足。"}, {"text": "宠", "is_correct": false, "explanation": "宠（chǒng，第三声）与 chóng 声调不同，意思是宠爱，如宠物。"}, {"text": "常", "is_correct": false, "explanation": "常（cháng）与 chóng 的韵母不同（a 与 o），意思是经常。"}, {"text": "从", "is_correct": false, "explanation": "从（cóng）与 chóng 的声母不同（c 与 ch），意思是跟随、从前。"}], "explanations": {"虫": "虫（chóng，第二声）指昆虫这类小动物，就是句中所说的意思。", "充": "充（chōng，第一声）与 chóng 声调不同，意思是充满、充足。", "宠": "宠（chǒng，第三声）与 chóng 声调不同，意思是宠爱，如宠物。", "常": "常（cháng）与 chóng 的韵母不同（a 与 o），意思是经常。", "从": "从（cóng）与 chóng 的声母不同（c 与 ch），意思是跟随、从前。"}, "sentence_index": null, "correct_answer": "虫"}, "level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "体貌：鱼没有翅膀，身体也不会飞来飞去。"}, {"text": "虫", "is_correct": true, "explanation": "正确：虫有翅膀，能在灯下飞来飞去，与句意相符。"}, {"text": "草", "is_correct": false, "explanation": "语义：草长在地上，不会飞来飞去。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是无生命的东西，不会自己飞。"}], "explanations": {"鱼": "体貌：鱼没有翅膀，身体也不会飞来飞去。", "虫": "正确：虫有翅膀，能在灯下飞来飞去，与句意相符。", "草": "语义：草长在地上，不会飞来飞去。", "石头": "语义：石头是无生命的东西，不会自己飞。"}, "sentence_index": 0, "correct_answer": "虫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚上别开窗，会有一架虫飞进来。", "explanation": "这里应该用〈只〉。“架”用于飞机、桥梁，虫要用“只”。"}, {"text": "晚上别开窗，会有一盏虫飞进来。", "explanation": "这里应该用〈只〉。“盏”用于灯，虫要用“只”。"}, {"text": "晚上别开窗，会有一块虫飞进来。", "explanation": "这里应该用〈只〉。“块”用于块状的东西，虫要用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98080, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "虫", "is_correct": true, "explanation": "虫（chóng，第二声）指昆虫这类小动物，就是句中所说的意思。"}, {"text": "冲", "is_correct": false, "explanation": "冲（chōng，第一声）与 chóng 声调不同，意思是冲击、冲刷。"}, {"text": "长", "is_correct": false, "explanation": "长（cháng）与 chóng 的韵母不同（a 与 o），意思是长短的长。"}, {"text": "丛", "is_correct": false, "explanation": "丛（cóng）与 chóng 的声母不同（c 与 ch），意思是丛林、草丛。"}], "explanations": {"虫": "虫（chóng，第二声）指昆虫这类小动物，就是句中所说的意思。", "冲": "冲（chōng，第一声）与 chóng 声调不同，意思是冲击、冲刷。", "长": "长（cháng）与 chóng 的韵母不同（a 与 o），意思是长短的长。", "丛": "丛（cóng）与 chóng 的声母不同（c 与 ch），意思是丛林、草丛。"}, "sentence_index": null, "correct_answer": "虫"}, "level_3": {"options": [{"text": "猫", "is_correct": false, "explanation": "体貌：猫没有翅膀，“翅膀是绿色的”不可能用于猫。"}, {"text": "虫", "is_correct": true, "explanation": "正确：虫有翅膀，句中所说的绿色翅膀与之相符。"}, {"text": "船", "is_correct": false, "explanation": "语义：船不长翅膀，与句中“翅膀是绿色的，很漂亮”的描述不合。"}, {"text": "手", "is_correct": false, "explanation": "体貌：人手没有翅膀，身体部位与句意不符。"}], "explanations": {"猫": "体貌：猫没有翅膀，“翅膀是绿色的”不可能用于猫。", "虫": "正确：虫有翅膀，句中所说的绿色翅膀与之相符。", "船": "语义：船不长翅膀，与句中“翅膀是绿色的，很漂亮”的描述不合。", "手": "体貌：人手没有翅膀，身体部位与句意不符。"}, "sentence_index": 6, "correct_answer": "虫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只虫在厨房里炒菜。", "explanation": "这里应该用〈厨师〉。炒菜是厨师的工作，虫不会炒菜。"}, {"text": "这只虫在路上开车。", "explanation": "这里应该用〈司机〉。开车要由司机来做，虫不会开车。"}, {"text": "这只虫在工厂里修机器。", "explanation": "这里应该用〈工人〉。修机器是工人的工作，虫不会修机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.