INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98083, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蜡烛是点着了会发光的细长东西，生日时会插在蛋糕上。", "primary_collocate": null, "pronunciation": "là zhú", "ipa": "la⁵¹ ʈʂu³⁵", "syllable_count": 2, "sentences": [{"text": "蛋糕上插着六根蜡烛。", "target_word": "蜡烛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹吹灭了生日蛋糕上的蜡烛。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸给蛋糕插上了十根蜡烛。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点蜡烛以后，大家一起唱生日歌。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们许愿以后，吹灭了蛋糕上的蜡烛。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年你想在蛋糕上插几根蜡烛？", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蜡烛亮了，大家关上灯，唱起生日歌。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明的蛋糕上有三根红色的蜡烛。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生日那天，妈妈买了一盒彩色蜡烛。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把蜡烛插在蛋糕中间，然后关了灯。", "target_word": "蜡烛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "生日蜡烛", "label": "复合"}, {"form": "蠟燭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蜡烛：生日蛋糕上插的发光小蜡烛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aa28573-c80f-4808-aa31-1a2121744695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜡烛", "is_correct": true, "explanation": "正确：蜡烛是细长的、点着后会发光的东西，插在蛋糕上符合句意，且与“六根”搭配。"}, {"text": "柱子", "is_correct": false, "explanation": "体貌：柱子又粗又大，不能插在蛋糕上当装饰，句意不通。"}, {"text": "线", "is_correct": false, "explanation": "语义：线不能插在蛋糕上当装饰，蛋糕上不会插线。"}, {"text": "葱", "is_correct": false, "explanation": "语义：葱是食材，不能插在蛋糕上当装饰，句意不通。"}], "explanations": {"蜡烛": "正确：蜡烛是细长的、点着后会发光的东西，插在蛋糕上符合句意，且与“六根”搭配。", "柱子": "体貌：柱子又粗又大，不能插在蛋糕上当装饰，句意不通。", "线": "语义：线不能插在蛋糕上当装饰，蛋糕上不会插线。", "葱": "语义：葱是食材，不能插在蛋糕上当装饰，句意不通。"}, "sentence_index": 0, "correct_answer": "蜡烛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一张蜡烛，放在窗台上。", "explanation": "这里不能用〈张〉。“张”用于纸、桌子等平面物，蜡烛是细长的条状物，要用“根”或“支”。"}, {"text": "他拧亮了蜡烛，房间里一下子亮了。", "explanation": "这里不能用〈灯〉的搭配。“拧亮”用于电灯，蜡烛要用“点”来点燃，不能说“拧亮”。"}, {"text": "他划了一根蜡烛，想把火点着。", "explanation": "这里应该用〈火柴〉。“划”用于火柴，蜡烛不能划着，要用“点”来点燃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜡烛", "is_correct": true, "explanation": "正确：蜡烛点着后会发光，能用“亮了”描述，后文“关上灯”也说明它是光源。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不会发光，用“亮了”来形容它不通。"}, {"text": "孩子", "is_correct": false, "explanation": "语义：人不会发光，不能用“亮了”来形容孩子。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是纸上的题目，不会发光，“亮了”不能形容作业。"}], "explanations": {"蜡烛": "正确：蜡烛点着后会发光，能用“亮了”描述，后文“关上灯”也说明它是光源。", "数学": "语义：数学是学科，不会发光，用“亮了”来形容它不通。", "孩子": "语义：人不会发光，不能用“亮了”来形容孩子。", "作业": "语义：作业是纸上的题目，不会发光，“亮了”不能形容作业。"}, "sentence_index": 6, "correct_answer": "蜡烛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按了一下蜡烛，点着了香烟。", "explanation": "这里应该用〈打火机〉。“按一下”是打火机的操作，蜡烛要用“点”来点燃。"}, {"text": "他买了一片蜡烛，放在窗边。", "explanation": "这里不能用〈片〉。“片”用于薄的平面物，蜡烛是细长的条状物，要用“根”或“支”。"}, {"text": "他打开了蜡烛，开始看书。", "explanation": "这里应该用〈台灯〉。“打开”用于台灯这类电灯，蜡烛要用“点”来点燃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸给蛋糕插上了两张蜡烛。", "corrected_sentence": "爸爸给蛋糕插上了两根蜡烛。", "error_description": "量词错误：“蜡烛”是细长的条状物，量词应用“根”或“支”，不能用“张”。错误形式是“两张蜡烛”，正确形式是“两根蜡烛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了三根色红的蜡烛。", "corrected_sentence": "他买了三根红色的蜡烛。", "error_description": "词序错误：颜色修饰语“红色”写成“色红”。错误形式是“三根色红的蜡烛”，正确形式是“三根红色的蜡烛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
