INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用蜡制成、中间有芯、点燃后可照明的长条物。", "primary_collocate": null, "pronunciation": "là zhú", "ipa": "la⁵¹ ʈʂu³⁵", "syllable_count": 2, "sentences": [{"text": "停电了，我们点了一根蜡烛。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上没有电，房间里只有一支蜡烛。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根蜡烛是用蜡做的，中间有一根线。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风一吹，桌上的蜡烛就灭了。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里停电，他借着一根蜡烛的光看书。", "target_word": "蜡烛", "complexity_tier": "T3", "furigana": "shān lǐ tíng diàn, tā jiè zhe yì gēn là zhú de guāng kàn shū。", "sentence_source": "generated"}, {"text": "蜡烛烧完了，房间一下子黑了。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈从抽屉里拿出蜡烛和火柴。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "点燃的蜡烛慢慢变短了。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间很黑，她用蜡烛照亮了桌子。", "target_word": "蜡烛", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把蜡烛放在窗边，房间里亮了一点。", "target_word": "蜡烛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "支", "label": "量词"}, {"form": "白蜡烛", "label": "复合"}, {"form": "蠟燭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蜡烛：停电时用来照明的蜡制长条物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9aa28573-c80f-4808-aa31-1a2121744695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蜡烛", "is_correct": true, "explanation": "正确：停电时点的是能照明的蜡烛，“点”也只用于蜡烛这类火光照明物。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线不是照明物，点不燃，停电时也不能用来照明。"}, {"text": "绳子", "is_correct": false, "explanation": "搭配：“点”不能用于绳子，说“点了一根绳子”不通。"}, {"text": "灯管", "is_correct": false, "explanation": "语义：灯管要靠电才能发光，停电时点不亮，与句意冲突。"}], "explanations": {"蜡烛": "正确：停电时点的是能照明的蜡烛，“点”也只用于蜡烛这类火光照明物。", "电线": "语义：电线不是照明物，点不燃，停电时也不能用来照明。", "绳子": "搭配：“点”不能用于绳子，说“点了一根绳子”不通。", "灯管": "语义：灯管要靠电才能发光，停电时点不亮，与句意冲突。"}, "sentence_index": 0, "correct_answer": "蜡烛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一头蜡烛，放在桌上。", "explanation": "这里不能用〈头〉。“头”用于牲畜，蜡烛要用“根”或“支”。"}, {"text": "他按亮了蜡烛，照着楼梯走。", "explanation": "这里应该用〈手电筒〉。“按亮”是开关手电筒的动作，蜡烛要用“点”来点燃。"}, {"text": "他连划了两根蜡烛，才把炉火点着。", "explanation": "这里应该用〈火柴〉。“划”用于火柴，蜡烛不能用来划，要用“点”来点燃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蜡烛", "is_correct": true, "explanation": "正确：蜡烛是能用来照明的小物件，抽屉里拿出蜡烛和火柴符合句意。"}, {"text": "大象", "is_correct": false, "explanation": "体貌：大象体积太大，放不进抽屉，不能从抽屉里拿出。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮挂在天上，不能从抽屉里拿出，句意不通。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不会放在抽屉里，也不会和火柴一起拿出来用，句意不通。"}], "explanations": {"蜡烛": "正确：蜡烛是能用来照明的小物件，抽屉里拿出蜡烛和火柴符合句意。", "大象": "体貌：大象体积太大，放不进抽屉，不能从抽屉里拿出。", "月亮": "语义：月亮挂在天上，不能从抽屉里拿出，句意不通。", "小狗": "语义：小狗是动物，不会放在抽屉里，也不会和火柴一起拿出来用，句意不通。"}, "sentence_index": 6, "correct_answer": "蜡烛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他关了蜡烛，屋里一下子暗了下来。", "explanation": "这里应该用〈电灯〉。“关”用于开关电灯，蜡烛要用“吹灭”来熄灭。"}, {"text": "他送给妈妈一朵蜡烛。", "explanation": "这里不能用〈朵〉。“朵”用于花，蜡烛要用“根”或“支”。"}, {"text": "他打开了蜡烛，开始写作业。", "explanation": "这里应该用〈台灯〉。“打开”用于台灯这类电器，蜡烛要用“点”来点燃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把蜡烛点了着，屋里亮了起来。", "corrected_sentence": "他把蜡烛点着了，屋里亮了起来。", "error_description": "补语与“了”的位置错误：“点着”是动补结构，“了”应放在补语“着”之后。错误形式是“点了着”，正确形式是“点着了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了三张蜡烛，放在桌上。", "corrected_sentence": "他买了三根蜡烛，放在桌上。", "error_description": "量词错误：“蜡烛”是细长的条状物，量词应用“根”或“支”，不能用“张”。错误形式是“三张蜡烛”，正确形式是“三根蜡烛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca6b77a2-13b8-4099-ae77-fb8db23e389d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
