INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98087, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设法是想各种办法去把事情做成。", "primary_collocate": null, "pronunciation": "shè fǎ", "ipa": "ʂɤ˥˩ fa˨˩", "syllable_count": 2, "sentences": [{"text": "他设法把迷路的小狗送回了家。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们必须设法按时完成这个工作。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈设法让生病的孩子吃了药。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你设法跟他联系一下，好吗？", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她设法找到了丢失的钥匙。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师设法让每个学生都开口说话。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了买到票，他设法借到了钱。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家设法把重的箱子搬上了楼。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会设法帮你解决这个问题。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天快黑了，我们要设法在天黑前回到家。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "設法", "label": "繁体"}], "register": "中性", "sense_fingerprint": "遇到困难时想各种办法，努力把事情做成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98087, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设法", "is_correct": true, "explanation": "“设法”是想办法去做成事情，与“送回了家”的完成结果相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再去做，与“把迷路的小狗送回了家”这个已完成的结果相矛盾。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”是躲开该做的事，与“送回了家”的完成结果相矛盾。"}, {"text": "体验", "is_correct": false, "explanation": "搭配：“体验”接经历或感受，不能接“把……送回了家”这样的动作。"}], "explanations": {"设法": "“设法”是想办法去做成事情，与“送回了家”的完成结果相符。", "放弃": "语义：“放弃”是不再去做，与“把迷路的小狗送回了家”这个已完成的结果相矛盾。", "逃避": "语义：“逃避”是躲开该做的事，与“送回了家”的完成结果相矛盾。", "体验": "搭配：“体验”接经历或感受，不能接“把……送回了家”这样的动作。"}, "sentence_index": 0, "correct_answer": "设法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我设法明天能下雨。", "explanation": "这里应该用〈希望〉。“设法”指经过努力去做成可以做到的事，天气不能靠人去设法，表示愿望时用“希望”。"}, {"text": "我设法在路上听到了一声巨响。", "explanation": "这里应该用〈偶然〉。“设法”表示有意想办法去做，听到巨响是无意中发生的，这种情况要用“偶然”。"}, {"text": "我设法感冒了。", "explanation": "这里应该用〈不小心〉。“设法”表示有意想办法去做，感冒是无意中发生的，这种情况要用“不小心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98087, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设法", "is_correct": true, "explanation": "“设法”表示想办法去达到目的，与“为了买到票”的目的相符，也与“借到了钱”的结果相符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”是记不住，与“为了买到票”这个有目的的行动不合。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不同意去做，与“借到了钱”的结果相矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”接待遇或生活，不能接“借到了钱”这类行为。"}], "explanations": {"设法": "“设法”表示想办法去达到目的，与“为了买到票”的目的相符，也与“借到了钱”的结果相符。", "忘记": "语义：“忘记”是记不住，与“为了买到票”这个有目的的行动不合。", "拒绝": "语义：“拒绝”是不同意去做，与“借到了钱”的结果相矛盾。", "享受": "搭配：“享受”接待遇或生活，不能接“借到了钱”这类行为。"}, "sentence_index": 6, "correct_answer": "设法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他设法跌倒了。", "explanation": "这里应该用〈不小心〉。“设法”表示有意去做，跌倒是无意发生的，表示这种情况时用“不小心”。"}, {"text": "他设法打了个喷嚏。", "explanation": "这里应该用〈突然〉。打喷嚏是不受控制的，“设法”表示有意地努力，表示意外发生时用“突然”。"}, {"text": "他设法把钥匙落在车里了。", "explanation": "这里应该用〈无意间〉。“设法”表示有意去做，把钥匙落在车里是无意的，表示这种情况时用“无意间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98087, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她设法了在下雨前收完了衣服。", "corrected_sentence": "她设法在下雨前收完了衣服。", "error_description": "错误：“设法”后面多加了“了”。正确：“她设法在下雨前收完了衣服。”“设法”是动词，表示想办法去做，后面不能直接加“了”，“收完了”的“了”已经表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98087, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他设法着把报告写完了。", "corrected_sentence": "他设法把报告写完了。", "error_description": "错误：“设法”后面多加了“着”。正确：“他设法把报告写完了。”“设法”后面直接接要做的事，不能带“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
