INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98088, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想办法；采取措施去做某事。", "primary_collocate": null, "pronunciation": "shè fǎ", "ipa": "ʂɤ˥˩ fa˨˩", "syllable_count": 2, "sentences": [{"text": "公司正在设法降低成本。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生设法让病人安静下来。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他设法躲开了那辆车。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察设法找到了那个孩子。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你设法通知大家明天开会。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我设法说服了他留下来。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她设法保持冷静，没有哭。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校设法给学生提供更好的学习条件。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们设法在比赛前恢复了体力。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾设法逃走，可是没有成功。", "target_word": "设法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "設法", "label": "繁体"}], "register": "中性", "sense_fingerprint": "采取具体措施去做某事，后面常接要达到的目标或动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a020e93-2349-4c9e-9a6a-791e7b69747e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98088, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "设法", "is_correct": true, "explanation": "“设法”是想办法去做，与“降低成本”这个目标相符。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”接待遇或生活，不能接“降低成本”这类行动。"}, {"text": "体验", "is_correct": false, "explanation": "搭配：“体验”接经历或感受，不能接“降低成本”这类行动。"}, {"text": "窃取", "is_correct": false, "explanation": "语义：“窃取”是偷别人的东西，与公司正当地降低成本的行为矛盾。"}], "explanations": {"设法": "“设法”是想办法去做，与“降低成本”这个目标相符。", "享受": "搭配：“享受”接待遇或生活，不能接“降低成本”这类行动。", "体验": "搭配：“体验”接经历或感受，不能接“降低成本”这类行动。", "窃取": "语义：“窃取”是偷别人的东西，与公司正当地降低成本的行为矛盾。"}, "sentence_index": 0, "correct_answer": "设法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我设法明天能下雨。", "explanation": "这里应该用〈希望〉。“设法”指经过努力去做成可以做到的事，天气不能靠人去设法，表示愿望时用“希望”。"}, {"text": "他设法跌倒了。", "explanation": "这里应该用〈不小心〉。“设法”表示有意去做，跌倒是无意发生的，表示这种情况时用“不小心”。"}, {"text": "她设法忘了妈妈的生日。", "explanation": "这里应该用〈不小心〉。“设法”表示有意想办法去做，忘记生日是无意的，这种情况要用“不小心”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "设法", "is_correct": true, "explanation": "“设法”是想办法去做，与“保持冷静”的目标相符，也与“没有哭”的结果相符。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：“哭泣”就是哭，与“没有哭”直接矛盾。"}, {"text": "放纵", "is_correct": false, "explanation": "语义：“放纵”是任由自己，与“保持冷静”的意思相反。"}, {"text": "饶恕", "is_correct": false, "explanation": "搭配：“饶恕”接的是人或过错，不能接“保持冷静”这种状态。"}], "explanations": {"设法": "“设法”是想办法去做，与“保持冷静”的目标相符，也与“没有哭”的结果相符。", "哭泣": "语义：“哭泣”就是哭，与“没有哭”直接矛盾。", "放纵": "语义：“放纵”是任由自己，与“保持冷静”的意思相反。", "饶恕": "搭配：“饶恕”接的是人或过错，不能接“保持冷静”这种状态。"}, "sentence_index": 6, "correct_answer": "设法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我设法在路上听到了一声巨响。", "explanation": "这里应该用〈偶然〉。“设法”表示有意想办法去做，听到巨响是无意中发生的，这种情况要用“偶然”。"}, {"text": "他设法打了个喷嚏。", "explanation": "这里应该用〈突然〉。打喷嚏是不受控制的，“设法”表示有意地努力，表示意外发生时用“突然”。"}, {"text": "他设法把钥匙落在车里了。", "explanation": "这里应该用〈无意间〉。“设法”表示有意去做，把钥匙落在车里是无意的，表示这种情况时用“无意间”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板把设法提高了员工的收入。", "corrected_sentence": "老板设法提高了员工的收入。", "error_description": "错误：「设法」前面多加了「把」。正确：「老板设法提高了员工的收入。」「设法」是动词，表示想办法去做，不能作「把」的宾语，「把」字句的宾语应是具体的人或事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她设法了让弟弟按时睡觉。", "corrected_sentence": "她设法让弟弟按时睡觉。", "error_description": "错误：“设法”后面多加了“了”。正确：“她设法让弟弟按时睡觉。”“设法”后面接的是要做的事，本身不带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87f481d3-dfa8-416c-abe8-4e64b808ebda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98091, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "反义：误会是理解错了，理解是理解对了，二者意思相反。"}, {"text": "发明", "is_correct": false, "explanation": "与“误会”无反义关系：“发明”指创造新事物，与理解的对错无关。"}, {"text": "参观", "is_correct": false, "explanation": "与“误会”无反义关系：“参观”指去看某个地方，与理解的对错无关。"}, {"text": "保护", "is_correct": false, "explanation": "与“误会”无反义关系：“保护”指防止受到伤害，与理解的对错无关。"}], "correct_answer": "理解", "explanations": {"理解": "反义：误会是理解错了，理解是理解对了，二者意思相反。", "发明": "与“误会”无反义关系：“发明”指创造新事物，与理解的对错无关。", "参观": "与“误会”无反义关系：“参观”指去看某个地方，与理解的对错无关。", "保护": "与“误会”无反义关系：“保护”指防止受到伤害，与理解的对错无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98091, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "反义：误会是理解错了，理解是理解对了，二者意思相反。"}, {"text": "寻找", "is_correct": false, "explanation": "与“误会”无反义关系：“寻找”指去找某物，与理解的对错无关。"}, {"text": "答应", "is_correct": false, "explanation": "与“误会”无反义关系：“答应”指同意或回应，与理解的对错无关。"}, {"text": "收藏", "is_correct": false, "explanation": "与“误会”无反义关系：“收藏”指把东西保存起来，与理解的对错无关。"}], "correct_answer": "理解", "explanations": {"理解": "反义：误会是理解错了，理解是理解对了，二者意思相反。", "寻找": "与“误会”无反义关系：“寻找”指去找某物，与理解的对错无关。", "答应": "与“误会”无反义关系：“答应”指同意或回应，与理解的对错无关。", "收藏": "与“误会”无反义关系：“收藏”指把东西保存起来，与理解的对错无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98091, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "误会是把别人的意思想错了，以为他是那样的意思。", "primary_collocate": null, "pronunciation": "wù huì", "ipa": "u˥˩ xueɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我误会了你的意思，对不起。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他误会了经理的话，做错了事。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她误会我不想去，其实我很想去。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要误会，我只是想帮你。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你误会了，他不是在骂你。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一直误会他，以为他不喜欢我。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说的是明天，我却误会成后天。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人误会你时，先好好说清楚。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把我的玩笑当真，完全误会了。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我误会过她一次，现在很后悔。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "误会了", "label": "体标"}, {"form": "误会过", "label": "体标"}, {"form": "误会着", "label": "体标"}], "register": "中性", "sense_fingerprint": "把别人的意思想错了，以为他是另一个意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '244a8996-a574-446d-85a5-426380410052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98091, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "误会", "is_correct": true, "explanation": "正确：误会 wùhuì，指把别人的意思想错了。"}, {"text": "舞会", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞的聚会。"}, {"text": "不会", "is_correct": false, "explanation": "bù 与 wù 声母不同，意思是不能、不懂得。"}, {"text": "入会", "is_correct": false, "explanation": "rù 与 wù 声母不同，意思是加入某个组织。"}, {"text": "污秽", "is_correct": false, "explanation": "wū（第一声）与 wù（第四声）声调不同，意思是肮脏。"}], "explanations": {"误会": "正确：误会 wùhuì，指把别人的意思想错了。", "舞会": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞的聚会。", "不会": "bù 与 wù 声母不同，意思是不能、不懂得。", "入会": "rù 与 wù 声母不同，意思是加入某个组织。", "污秽": "wū（第一声）与 wù（第四声）声调不同，意思是肮脏。"}, "sentence_index": null, "correct_answer": "误会"}, "level_3": {"options": [{"text": "误会", "is_correct": true, "explanation": "正确：误会表示把你的意思理解错了，与“对不起”相合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮品，“你的意思”不能喝。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“同意”表示赞成，与“对不起”的歉意相悖。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”不能带宾语，不能说“生气了你的意思”。"}], "explanations": {"误会": "正确：误会表示把你的意思理解错了，与“对不起”相合。", "喝": "搭配：“喝”的宾语是饮品，“你的意思”不能喝。", "同意": "语义：“同意”表示赞成，与“对不起”的歉意相悖。", "生气": "配价：“生气”不能带宾语，不能说“生气了你的意思”。"}, "sentence_index": 0, "correct_answer": "误会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把盐误会成了糖，菜很咸。", "explanation": "这里应该用〈当成〉。误会针对别人的话语或行为，把东西弄错要用〈当成〉。"}, {"text": "他骑车时误会了一位行人。", "explanation": "这里应该用〈误伤〉。误会不指伤害别人，撞伤路人要用〈误伤〉。"}, {"text": "裁判误会了这个球。", "explanation": "这里应该用〈误判〉。误会针对言行的理解，判断球是否出界要用〈误判〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "误会", "is_correct": true, "explanation": "正确：误会成后天，指把“明天”理解成了“后天”，与前句相合。"}, {"text": "变", "is_correct": false, "explanation": "语义：「变」表示事物本身的改变，「我变成后天」与句意不合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的对象是歌曲，不能唱出日期，「唱成后天」不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：「切」针对有形的东西，不能把日期切成「后天」。"}], "explanations": {"误会": "正确：误会成后天，指把“明天”理解成了“后天”，与前句相合。", "变": "语义：「变」表示事物本身的改变，「我变成后天」与句意不合。", "唱": "搭配：「唱」的对象是歌曲，不能唱出日期，「唱成后天」不通。", "切": "搭配：「切」针对有形的东西，不能把日期切成「后天」。"}, "sentence_index": 6, "correct_answer": "误会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生误会了他的病，所以开错了药。", "explanation": "这里应该用〈误诊〉。误会针对别人的话语和行为，诊断疾病出错要用〈误诊〉。"}, {"text": "店员误会了账，多收了我十块。", "explanation": "这里应该用〈误算〉。误会不用于算账，算错钱、多收钱要用〈误算〉。"}, {"text": "孩子误会了药，被送进了医院。", "explanation": "这里应该用〈误服〉。误会不指吃错药，误吃药要用〈误服〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我误会了过她，现在很后悔。", "corrected_sentence": "我误会过她，现在很后悔。", "error_description": "错误：“了”和“过”连用在“误会”后。正确：表示曾经的经历只用“过”，说“我误会过她”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我误会他过一次，后来才道歉。", "corrected_sentence": "我误会过他一次，后来才道歉。", "error_description": "错误：“过”放在了宾语“他”之后。正确：“过”应紧跟动词“误会”，说“我误会过他一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98092, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "反义：误会是理解错了，理解是理解对了，二者意思相反。"}, {"text": "发现", "is_correct": false, "explanation": "与“误会”无反义关系：“发现”指找到或看出某种事物，与理解对错无关。"}, {"text": "参加", "is_correct": false, "explanation": "与“误会”无反义关系：“参加”指加入某项活动，与理解的对错无关。"}, {"text": "保存", "is_correct": false, "explanation": "与“误会”无反义关系：“保存”指把东西留住，与理解的对错无关。"}], "correct_answer": "理解", "explanations": {"理解": "反义：误会是理解错了，理解是理解对了，二者意思相反。", "发现": "与“误会”无反义关系：“发现”指找到或看出某种事物，与理解对错无关。", "参加": "与“误会”无反义关系：“参加”指加入某项活动，与理解的对错无关。", "保存": "与“误会”无反义关系：“保存”指把东西留住，与理解的对错无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98092, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "理解", "is_correct": true, "explanation": "反义：误会是理解错了，理解是理解对了，二者意思相反。"}, {"text": "找到", "is_correct": false, "explanation": "与“误会”无反义关系：“找到”指找着了某物，与理解的对错无关。"}, {"text": "答应", "is_correct": false, "explanation": "与“误会”无反义关系：“答应”指同意或回应，与理解的对错无关。"}, {"text": "收藏", "is_correct": false, "explanation": "与“误会”无反义关系：“收藏”指把东西保存起来，与理解的对错无关。"}], "correct_answer": "理解", "explanations": {"理解": "反义：误会是理解错了，理解是理解对了，二者意思相反。", "找到": "与“误会”无反义关系：“找到”指找着了某物，与理解的对错无关。", "答应": "与“误会”无反义关系：“答应”指同意或回应，与理解的对错无关。", "收藏": "与“误会”无反义关系：“收藏”指把东西保存起来，与理解的对错无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98092, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人的言语或行为理解错误。", "primary_collocate": null, "pronunciation": "wù huì", "ipa": "u˥˩ xueɪ˥˩", "syllable_count": 2, "sentences": [{"text": "对不起，我误会了你的话。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别误会他，他不是那个意思。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我误会了老师的行为。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她误会了我的笑，以为我在看不起她。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他误会过我，后来才知道我是好人。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要误会别人的好意。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我误会了他的好意，真不好意思。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话太快，大家都误会了他。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是误会了我的意思？", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她误会了他的做法，所以很生气。", "target_word": "误会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "误会了", "label": "体标"}, {"form": "误会过", "label": "体标"}, {"form": "误会着", "label": "体标"}], "register": "中性", "sense_fingerprint": "对别人的言语或行为理解错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '244a8996-a574-446d-85a5-426380410052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98092, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "误会", "is_correct": true, "explanation": "正确：误会 wùhuì，指把别人的话或行为理解错了。"}, {"text": "舞会", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞的聚会。"}, {"text": "不会", "is_correct": false, "explanation": "bù 与 wù 声母不同，意思是不能、不懂得。"}, {"text": "入会", "is_correct": false, "explanation": "rù 与 wù 声母不同，意思是加入某个组织。"}, {"text": "污秽", "is_correct": false, "explanation": "wū（第一声）与 wù（第四声）声调不同，意思是肮脏。"}], "explanations": {"误会": "正确：误会 wùhuì，指把别人的话或行为理解错了。", "舞会": "wǔ（第三声）与 wù（第四声）声调不同，意思是跳舞的聚会。", "不会": "bù 与 wù 声母不同，意思是不能、不懂得。", "入会": "rù 与 wù 声母不同，意思是加入某个组织。", "污秽": "wū（第一声）与 wù（第四声）声调不同，意思是肮脏。"}, "sentence_index": null, "correct_answer": "误会"}, "level_3": {"options": [{"text": "误会", "is_correct": true, "explanation": "正确：误会表示把你的话理解错了，与“对不起”的歉意相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，“你的话”不能吃。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“同意”表示赞成，与“对不起”的歉意相悖。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”不能带宾语，不能说“生气了你的话”。"}], "explanations": {"误会": "正确：误会表示把你的话理解错了，与“对不起”的歉意相合。", "吃": "搭配：“吃”的宾语应是食物，“你的话”不能吃。", "同意": "语义：“同意”表示赞成，与“对不起”的歉意相悖。", "生气": "配价：“生气”不能带宾语，不能说“生气了你的话”。"}, "sentence_index": 0, "correct_answer": "误会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把那张桌子误会成了床。", "explanation": "这里应该用〈认错〉。误会只用于对别人话语或行为的理解，认错东西时要用〈认错〉。"}, {"text": "他故意说假话，误会了很多人。", "explanation": "这里应该用〈误导〉。误会是自己理解错了，不能指让别人理解错，那要用〈误导〉。"}, {"text": "裁判误会了这个球。", "explanation": "这里应该用〈误判〉。误会针对言语和行为，判断球是否出界要用〈误判〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "误会", "is_correct": true, "explanation": "正确：误会的对象是“他的好意”，指把好意理解错了，与后句的歉意相合。"}, {"text": "搬运", "is_correct": false, "explanation": "搭配：「搬运」的对象是有形的物品，不能搬运「好意」。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”的宾语多是门、盒子等有形之物，不能用来搭配“好意”。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”是骗人，与“好意”及后句的歉意不合。"}], "explanations": {"误会": "正确：误会的对象是“他的好意”，指把好意理解错了，与后句的歉意相合。", "搬运": "搭配：「搬运」的对象是有形的物品，不能搬运「好意」。", "打开": "搭配：“打开”的宾语多是门、盒子等有形之物，不能用来搭配“好意”。", "欺骗": "语义：“欺骗”是骗人，与“好意”及后句的歉意不合。"}, "sentence_index": 6, "correct_answer": "误会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被医生误会为感冒。", "explanation": "这里应该用〈误诊〉。误会针对别人的话语和行为，诊断疾病出错要用〈误诊〉。"}, {"text": "店员误会了账，多收了我十块。", "explanation": "这里应该用〈误算〉。误会不用于算账，算错钱、多收钱要用〈误算〉。"}, {"text": "孩子误会了药，被送进了医院。", "explanation": "这里应该用〈误服〉。误会不指吃错药，误吃药要用〈误服〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她没误会了我的意思，她知道我在开玩笑。", "corrected_sentence": "她没误会我的意思，她知道我在开玩笑。", "error_description": "错误：用“没”否定时，动词“误会”后不能再加“了”。正确：去掉“了”，说“她没误会我的意思”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他误会的我的意思，所以没有理我。", "corrected_sentence": "他误会了我的意思，所以没有理我。", "error_description": "错误：动词“误会”后的“了”误写成“的”，“误会的我的意思”不成句。正确：动词后应用动态助词“了”，说“他误会了我的意思”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
