INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98095, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "贩卖是把东西买来，再卖给别人。", "primary_collocate": null, "pronunciation": "fàn mài", "ipa": "fan˥˩ mai˥˩", "syllable_count": 2, "sentences": [{"text": "他从农村买来水果，再到城里贩卖。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商人专门贩卖各地的茶叶。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在市场上贩卖从南方买来的海鲜。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前很多人挑着担子到各村贩卖布匹。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把便宜的旧书买回来，再拿去贩卖。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在网上贩卖从国外买来的化妆品。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里不能贩卖假货。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他贩卖过几年水果，后来开了超市。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张每天早上去批发市场买菜，然后到街上贩卖。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们靠贩卖旅游纪念品过日子。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贩卖了", "label": "完成体"}, {"form": "贩卖过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把买来的东西再卖给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34d10ddf-7e02-4d9e-8c6e-6ed723a2eab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98095, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贩卖", "is_correct": true, "explanation": "贩卖：买来后再转手卖出，与前一分句「买来水果」及「再到城里」的语境相符。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：「收藏」多用于书画、文物等，不说收藏水果。"}, {"text": "出租", "is_correct": false, "explanation": "搭配：「出租」用于房屋、车辆等，不能用于水果。"}, {"text": "种植", "is_correct": false, "explanation": "语义：水果是从农村买来的，不是在城里种植的，与「买来」矛盾。"}], "explanations": {"贩卖": "贩卖：买来后再转手卖出，与前一分句「买来水果」及「再到城里」的语境相符。", "收藏": "搭配：「收藏」多用于书画、文物等，不说收藏水果。", "出租": "搭配：「出租」用于房屋、车辆等，不能用于水果。", "种植": "语义：水果是从农村买来的，不是在城里种植的，与「买来」矛盾。"}, "sentence_index": 0, "correct_answer": "贩卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把自己写的小说贩卖给了出版社。", "explanation": "这里应该用〈出售〉。贩卖指买进货物后再转手卖出，自己写的小说不是买来的货物，直接卖出要用出售。"}, {"text": "他贩卖一家水果店，生意很好。", "explanation": "这里应该用〈经营〉。贩卖的对象是货物，水果店是经营场所，不能说贩卖。"}, {"text": "他把自己住的旧房子贩卖了，搬到了城里。", "explanation": "这里应该用〈卖掉〉。贩卖指买进货物再转手卖出，卖掉自己住的房子不是贩卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贩卖", "is_correct": true, "explanation": "贩卖：卖出货物赚钱，与「不能」的语境及「假货」的违法含义相符。"}, {"text": "朗读", "is_correct": false, "explanation": "搭配：「朗读」的对象是文字、诗文，不能用于假货。"}, {"text": "维修", "is_correct": false, "explanation": "搭配：「维修」用于机器、设备等，不能说维修假货。"}, {"text": "培育", "is_correct": false, "explanation": "搭配：「培育」用于植物、动物或人才，不能用于假货。"}], "explanations": {"贩卖": "贩卖：卖出货物赚钱，与「不能」的语境及「假货」的违法含义相符。", "朗读": "搭配：「朗读」的对象是文字、诗文，不能用于假货。", "维修": "搭配：「维修」用于机器、设备等，不能说维修假货。", "培育": "搭配：「培育」用于植物、动物或人才，不能用于假货。"}, "sentence_index": 6, "correct_answer": "贩卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把旧书贩卖给学生，一分钱也没要。", "explanation": "这里应该用〈赠送〉。贩卖是卖出赚钱，「一分钱也没要」说明不是卖，与贩卖矛盾。"}, {"text": "他把一个摊位贩卖给了朋友。", "explanation": "这里应该用〈转让〉。贩卖的对象是货物，摊位这类场所要用转让。"}, {"text": "这家医院贩卖免费体检。", "explanation": "这里应该用〈提供〉。贩卖是卖货赚钱，「免费」的服务不能用贩卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在夜市里被贩卖小饰品，生意还不错。", "corrected_sentence": "他在夜市里贩卖小饰品，生意还不错。", "error_description": "错误形式：「被贩卖小饰品」；正确形式：「贩卖小饰品」。「被」字句会使「他」成为受事，而句中的「他」是卖方，所以不能用「被」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前在火车站不贩卖过旧书。", "corrected_sentence": "他以前在火车站没贩卖过旧书。", "error_description": "错误形式：「不贩卖过」；正确形式：「没贩卖过」。表示经历的否定要用「没」，不用「不」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
