INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98096, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买进货物再转手卖出。", "primary_collocate": null, "pronunciation": "fàn mài", "ipa": "fan˥˩ mai˥˩", "syllable_count": 2, "sentences": [{"text": "他低价买进货物，再高价贩卖。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们从海边收购海鲜，转手贩卖给饭店。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在车站贩卖从工厂拿来的便宜鞋子。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把批发来的衣服放在网上贩卖。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们专门贩卖二手手机。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓到了贩卖假药的人。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上有人贩卖水果和蔬菜。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时到处贩卖皮毛，赚了不少钱。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把旧电器买回来修好再贩卖，是他的生意。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小贩靠贩卖蔬菜养家。", "target_word": "贩卖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贩卖了", "label": "完成体"}, {"form": "贩卖过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "买进货物后转手卖出赚差价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34d10ddf-7e02-4d9e-8c6e-6ed723a2eab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贩卖", "is_correct": true, "explanation": "贩卖：买进货物后再转手卖出，与前一分句「低价买进货物」及「高价」的语境相符。"}, {"text": "烹调", "is_correct": false, "explanation": "语义：「烹调」指做菜，与「买进货物」「高价卖出」的语境无关。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：「清洗」是把东西弄干净，不能表示卖出，与句中的买卖语境矛盾。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：「出版」用于书籍、报刊，不能说出版货物。"}], "explanations": {"贩卖": "贩卖：买进货物后再转手卖出，与前一分句「低价买进货物」及「高价」的语境相符。", "烹调": "语义：「烹调」指做菜，与「买进货物」「高价卖出」的语境无关。", "清洗": "语义：「清洗」是把东西弄干净，不能表示卖出，与句中的买卖语境矛盾。", "出版": "搭配：「出版」用于书籍、报刊，不能说出版货物。"}, "sentence_index": 0, "correct_answer": "贩卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把自己编的故事贩卖给了电视台。", "explanation": "这里应该用〈出售〉。贩卖指买进货物后再转手卖出，自己编的故事不是买来的货物，直接卖出要用出售。"}, {"text": "他贩卖一家餐厅，生意很好。", "explanation": "这里应该用〈经营〉。贩卖的对象是货物，餐厅是经营场所，不能说贩卖。"}, {"text": "她为了升职贩卖了同事。", "explanation": "这里应该用〈出卖〉。贩卖只指买卖货物，「为了升职出卖同事」表示背叛，不能用贩卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贩卖", "is_correct": true, "explanation": "贩卖：把货物卖给别人，与「有人」在街上售卖水果和蔬菜的语境相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」用于地方、房间，不能说打扫水果和蔬菜。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：「播放」用于影音节目，不能用于水果和蔬菜。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：「演奏」指演奏乐器或乐曲，与水果和蔬菜无关。"}], "explanations": {"贩卖": "贩卖：把货物卖给别人，与「有人」在街上售卖水果和蔬菜的语境相符。", "打扫": "搭配：「打扫」用于地方、房间，不能说打扫水果和蔬菜。", "播放": "搭配：「播放」用于影音节目，不能用于水果和蔬菜。", "演奏": "语义：「演奏」指演奏乐器或乐曲，与水果和蔬菜无关。"}, "sentence_index": 6, "correct_answer": "贩卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把蔬菜贩卖给邻居，一分钱也没要。", "explanation": "这里应该用〈赠送〉。贩卖是卖出赚钱，「一分钱也没要」说明是白给，与贩卖矛盾。"}, {"text": "他承包了一个鱼塘，又贩卖了它。", "explanation": "这里应该用〈转让〉。贩卖的对象是货物，鱼塘不是货物，不能说贩卖。"}, {"text": "这位律师免费贩卖法律咨询。", "explanation": "这里应该用〈提供〉。贩卖是卖货赚钱，「免费」的咨询服务不能用贩卖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天骑车到处贩卖了煎饼。", "corrected_sentence": "他每天骑车到处贩卖煎饼。", "error_description": "错误形式：「贩卖了煎饼」；正确形式：「贩卖煎饼」。「了」表示动作已经完成，而「每天……到处贩卖」描述的是习惯性、反复进行的动作，不表示完成，因此不用「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上个月去广州贩卖着一批电器。", "corrected_sentence": "他上个月去广州贩卖了一批电器。", "error_description": "错误形式：「贩卖着一批电器」；正确形式：「贩卖了一批电器」。「上个月」说明动作已经完成，「一批电器」是有数量的宾语，应该用表示完成的「了」，不能用表示持续的「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd97f6e18-a76c-4494-b7a3-17dfca0f24be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
