INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98099, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买回是买了东西，再把它带回家。", "primary_collocate": null, "pronunciation": "mǎi huí", "ipa": "maɪ̯˨˩˦ xweɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我在超市买回了一些水果。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈从市场买回了一条鱼。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他下班后买回一个大蛋糕。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能帮我买回一瓶牛奶吗？", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸昨天买回了两瓶酒。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她逛街时买回了一条红裙子。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们买回的菜太多了，吃不完。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟把新买回的玩具放在床上。", "target_word": "买回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每次出差都给孩子买回礼物。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你下班的时候，别忘了买回面包。", "target_word": "买回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "买回来", "label": "复合"}, {"form": "买回了", "label": "体标"}, {"form": "买回过", "label": "体标"}, {"form": "買回", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买东西并带回家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98099, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "买回", "is_correct": true, "explanation": "买回：正确。在超市买了水果，再带回家。"}, {"text": "寄回", "is_correct": false, "explanation": "语义：寄要通过邮局或快递，超市里不会“寄回”水果。"}, {"text": "摘下", "is_correct": false, "explanation": "语义：水果要从树上摘，超市里没有果树。"}, {"text": "种下", "is_correct": false, "explanation": "搭配：“种”配植物或树苗，不配水果。"}], "explanations": {"买回": "买回：正确。在超市买了水果，再带回家。", "寄回": "语义：寄要通过邮局或快递，超市里不会“寄回”水果。", "摘下": "语义：水果要从树上摘，超市里没有果树。", "种下": "搭配：“种”配植物或树苗，不配水果。"}, "sentence_index": 0, "correct_answer": "买回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去医院买回了一个病，回家以后很难受。", "explanation": "这里应该用〈得〉。生病是得来的，不是买的；〈买回〉只用于商品。"}, {"text": "他花钱买回了一场比赛，回家以后很兴奋。", "explanation": "这里应该用〈观看〉。比赛是活动，只能现场观看或看直播，〈买回〉只用于可以带回家的商品。"}, {"text": "他买回了一个朋友，很快就熟悉了。", "explanation": "这里应该用〈结识〉。朋友要靠交往认识，不能买回家；〈买回〉只用于商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98099, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "买回", "is_correct": true, "explanation": "买回：正确。买回来的菜，修饰“菜”。"}, {"text": "吃光", "is_correct": false, "explanation": "语义：吃光的菜不会剩下，与后面的“吃不完”矛盾。"}, {"text": "喝完", "is_correct": false, "explanation": "搭配：菜不能“喝”，“喝完”只配饮料或汤。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉的菜不用再吃，与“吃不完”的语境不合。"}], "explanations": {"买回": "买回：正确。买回来的菜，修饰“菜”。", "吃光": "语义：吃光的菜不会剩下，与后面的“吃不完”矛盾。", "喝完": "搭配：菜不能“喝”，“喝完”只配饮料或汤。", "扔掉": "语义：扔掉的菜不用再吃，与“吃不完”的语境不合。"}, "sentence_index": 6, "correct_answer": "买回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈从医院买回了一张化验单。", "explanation": "这里应该用〈带回〉。化验单是在医院领取的，不用买；〈买回〉指花钱买回家。"}, {"text": "他在车站买回了一列火车，开回了家。", "explanation": "这里应该用〈坐〉。火车是交通工具，只能乘坐，不能买回家；〈买回〉只用于可以带回家的商品。"}, {"text": "他买的衣服太小，于是买回了一个新身材。", "explanation": "这里应该用〈换〉。衣服太小可以换大号，身材不能买；〈买回〉只用于商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98099, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐下班时买回了一条花。", "corrected_sentence": "姐姐下班时买回了一束花。", "error_description": "错误在量词：“花”应该用“束”，不能用“条”。“条”用于细长的东西，如鱼、裙子，不用于花。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98099, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在家里等妈妈，她从超市买回去了很多菜。", "corrected_sentence": "我在家里等妈妈，她从超市买回来了很多菜。", "error_description": "错误在趋向补语：说话人在家，东西要带到说话人这里，应说“买回来”，不能说“买回去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
