INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98100, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买了东西带回来。", "primary_collocate": null, "pronunciation": "mǎi huí", "ipa": "maɪ̯˨˩˦ xweɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "奶奶买回来很多青菜。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你去买回两个西瓜吧。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我昨天买回来的新杯子。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买回来一只小狗，全家都很高兴。", "target_word": "买回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐买回来的衣服太大了。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买回了三本书，都是新的。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买回来的菜很新鲜。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥买回来一台新电视。", "target_word": "买回", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她买回来一束花，放在桌子上。", "target_word": "买回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷买回来一些药，让我放好。", "target_word": "买回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "买回来", "label": "复合"}, {"form": "买回了", "label": "体标"}, {"form": "买回过", "label": "体标"}, {"form": "買回", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买了东西带回来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7f07a40e-2059-4496-aabb-293042db5ec3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98100, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "买回", "is_correct": true, "explanation": "买回：正确。买了青菜带回家。"}, {"text": "拍回", "is_correct": false, "explanation": "语义：拍的是照片，不能把青菜“拍回来”。"}, {"text": "吃回", "is_correct": false, "explanation": "搭配：“吃”不表示把东西带回来，不能说“吃回来青菜”。"}, {"text": "种回", "is_correct": false, "explanation": "语义：种是栽培，青菜不能“种回来”。"}], "explanations": {"买回": "买回：正确。买了青菜带回家。", "拍回": "语义：拍的是照片，不能把青菜“拍回来”。", "吃回": "搭配：“吃”不表示把东西带回来，不能说“吃回来青菜”。", "种回": "语义：种是栽培，青菜不能“种回来”。"}, "sentence_index": 0, "correct_answer": "买回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从流浪动物中心买回来一只小狗，不用花一分钱。", "explanation": "这里应该用〈收养〉。收养不用花钱；〈买回来〉必须付钱，与“不用花一分钱”矛盾。"}, {"text": "他买回来一个好主意，全家都很高兴。", "explanation": "这里应该用〈想出〉。好主意要自己想出来，不能买回来；〈买回来〉只用于商品。"}, {"text": "他去修理店，买回来了自己的手表。", "explanation": "这里应该用〈取回〉。手表本来是他的，只是拿回来，不用买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "买回", "is_correct": true, "explanation": "买回：正确。买了菜带回家，修饰“菜”。"}, {"text": "写下", "is_correct": false, "explanation": "搭配：“写”不能产出菜，“写下来的菜”搭配不当。"}, {"text": "唱出", "is_correct": false, "explanation": "语义：唱出的是歌声，不是可以“很新鲜”的菜。"}, {"text": "喊出", "is_correct": false, "explanation": "语义：喊出的是声音，不是菜，不能说“很新鲜”。"}], "explanations": {"买回": "买回：正确。买了菜带回家，修饰“菜”。", "写下": "搭配：“写”不能产出菜，“写下来的菜”搭配不当。", "唱出": "语义：唱出的是歌声，不是可以“很新鲜”的菜。", "喊出": "语义：喊出的是声音，不是菜，不能说“很新鲜”。"}, "sentence_index": 6, "correct_answer": "买回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷从邻居那里买回来一本书，看完就还给了邻居。", "explanation": "这里应该用〈借来〉。〈买回来〉表示花钱买下，买了就不用还，与“还给邻居”矛盾。"}, {"text": "爷爷买回来一个好习惯，让我学学。", "explanation": "这里应该用〈培养〉。好习惯要培养，不能买回来；〈买回来〉只用于商品。"}, {"text": "爷爷买回来一个老师，让我好好听课。", "explanation": "这里应该用〈请〉。老师要请来，不能买回来；〈买回来〉只用于商品，不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去超市买回来了两瓶米。", "corrected_sentence": "我去超市买回来了两袋米。", "error_description": "错误在量词：“米”应该用“袋”，不能用“瓶”。“瓶”用于液体或瓶装的东西，不用于米。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在家里等她，妹妹去书店买回去几本画册。", "corrected_sentence": "我在家里等她，妹妹去书店买回来几本画册。", "error_description": "错误在趋向补语：说话人在家，东西要带到说话人这里，应说“买回来”，不能说“买回去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5409aa7e-6e53-40ca-8ec9-fd77ceff8ceb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
