INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98103, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赖是做错了事，不肯认，还说是别人的错。", "primary_collocate": null, "pronunciation": "lài", "ipa": "lai˥˩", "syllable_count": 1, "sentences": [{"text": "他打破了杯子，还赖弟弟。", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明明是你的错，别赖我。", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明没做作业，还赖老师没提醒他。", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迟到了就说迟到了，不要赖路上堵车。", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把花瓶摔了，反而赖猫。", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事要认，不能赖别人。", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是赖天气不好，不肯认错。", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你自己忘了，怎么能赖我呢？", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没赖你，是我自己看错了。", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟弄坏了电脑，却赖到我头上。", "target_word": "赖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赖了", "label": "完成体"}, {"form": "賴", "label": "繁体"}], "register": "口语", "sense_fingerprint": "做错事不认错，反而把过错推给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404dc866-8b49-473b-ac7d-65c2910bf2a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98103, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赖", "is_correct": true, "explanation": "正确：lài 是“赖”，指做错事不承认、把过错推给别人。"}, {"text": "来", "is_correct": false, "explanation": "lái（第二声）与 lài（第四声）声调不同，意思是“来”。"}, {"text": "耐", "is_correct": false, "explanation": "nài 与 lài 声母不同（n 与 l），意思是“耐心、忍耐”。"}, {"text": "辣", "is_correct": false, "explanation": "là 与 lài 韵母不同（a 与 ai），意思是“辣”。"}, {"text": "烙", "is_correct": false, "explanation": "lào 与 lài 韵母不同（ao 与 ai），意思是“烙饼”。"}], "explanations": {"赖": "正确：lài 是“赖”，指做错事不承认、把过错推给别人。", "来": "lái（第二声）与 lài（第四声）声调不同，意思是“来”。", "耐": "nài 与 lài 声母不同（n 与 l），意思是“耐心、忍耐”。", "辣": "là 与 lài 韵母不同（a 与 ai），意思是“辣”。", "烙": "lào 与 lài 韵母不同（ao 与 ai），意思是“烙饼”。"}, "sentence_index": null, "correct_answer": "赖"}, "level_3": {"options": [{"text": "赖", "is_correct": true, "explanation": "正确：“赖”表示把过错推给别人，与“打破了杯子”的语境吻合。"}, {"text": "夸", "is_correct": false, "explanation": "语义：“夸”是称赞，打破杯子后还去夸弟弟，与过错语境相反。"}, {"text": "谢", "is_correct": false, "explanation": "语义：“谢”是感谢，与“他打破了杯子”的过错情境矛盾。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指跌落或抛掷，“还摔弟弟”是动手打人，与推卸过错的语境不符。"}], "explanations": {"赖": "正确：“赖”表示把过错推给别人，与“打破了杯子”的语境吻合。", "夸": "语义：“夸”是称赞，打破杯子后还去夸弟弟，与过错语境相反。", "谢": "语义：“谢”是感谢，与“他打破了杯子”的过错情境矛盾。", "摔": "语义：“摔”指跌落或抛掷，“还摔弟弟”是动手打人，与推卸过错的语境不符。"}, "sentence_index": 0, "correct_answer": "赖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他帮我修好了电脑，我真想赖他。", "explanation": "这里应该用〈谢〉。“赖”是把过错推给别人，别人帮了忙没有过错，不能“赖”。"}, {"text": "她考了第一名，大家都赖她。", "explanation": "这里应该用〈夸〉。考第一是好事，“赖”只用于推卸过错。"}, {"text": "妈妈做的饭很好吃，我要赖妈妈。", "explanation": "这里应该用〈感谢〉。“赖”指把错推给别人，不能用于表达感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98103, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赖", "is_correct": true, "explanation": "正确：lài 是“赖”，指做错事不认账、把过错推给别人。"}, {"text": "累", "is_correct": false, "explanation": "lèi 与 lài 韵母不同（ei 与 ai），意思是“劳累”。"}, {"text": "奈", "is_correct": false, "explanation": "nài 与 lài 声母不同（n 与 l），意思是“无奈”。"}, {"text": "涝", "is_correct": false, "explanation": "lào 与 lài 韵母不同（ao 与 ai），意思是“涝灾”。"}, {"text": "莱", "is_correct": false, "explanation": "lái（第二声）与 lài 声调不同，意思是“莱”（蔬菜）。"}], "explanations": {"赖": "正确：lài 是“赖”，指做错事不认账、把过错推给别人。", "累": "lèi 与 lài 韵母不同（ei 与 ai），意思是“劳累”。", "奈": "nài 与 lài 声母不同（n 与 l），意思是“无奈”。", "涝": "lào 与 lài 韵母不同（ao 与 ai），意思是“涝灾”。", "莱": "lái（第二声）与 lài 声调不同，意思是“莱”（蔬菜）。"}, "sentence_index": null, "correct_answer": "赖"}, "level_3": {"options": [{"text": "赖", "is_correct": true, "explanation": "正确：“赖”表示推卸过错，与“不肯认错”的语境吻合。"}, {"text": "认", "is_correct": false, "explanation": "语义：“认”是承认，与后面“不肯认错”的态度矛盾。"}, {"text": "赞", "is_correct": false, "explanation": "语义：“赞”是称赞，说天气不好却去赞扬，与语境不合。"}, {"text": "赔", "is_correct": false, "explanation": "搭配：“赔”后面接的是钱物或损失，不能说“赔天气不好”。"}], "explanations": {"赖": "正确：“赖”表示推卸过错，与“不肯认错”的语境吻合。", "认": "语义：“认”是承认，与后面“不肯认错”的态度矛盾。", "赞": "语义：“赞”是称赞，说天气不好却去赞扬，与语境不合。", "赔": "搭配：“赔”后面接的是钱物或损失，不能说“赔天气不好”。"}, "sentence_index": 6, "correct_answer": "赖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友送我一本好书，我很赖他。", "explanation": "这里应该用〈感谢〉。别人送礼物没有过错，“赖”只用于推卸过错。"}, {"text": "他救了落水的孩子，人们都赖他。", "explanation": "这里应该用〈称赞〉。救人是好事，不能用“赖”。"}, {"text": "老师耐心地教我，我非常赖老师。", "explanation": "这里应该用〈感激〉。“赖”是把过错推给别人，与感激的意思无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把水洒了，却赖服务员身上。", "corrected_sentence": "他把水洒了，却赖到服务员身上。", "error_description": "漏字错误：“赖”引出承担过错者时需用“到”（赖到……身上），此处漏掉“到”，应说“却赖到服务员身上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他偷吃了蛋糕，却赖弟弟身上。", "corrected_sentence": "他偷吃了蛋糕，却赖到弟弟身上。", "error_description": "漏字错误：“赖”引出承担过错者时需用“到”（赖到……身上），此处漏掉“到”，应说“却赖到弟弟身上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
