INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "车辆在行驶中发生的撞击等交通事故。", "primary_collocate": null, "pronunciation": "chē huò", "ipa": "ʈʂʰɤ˥ xuo˥˩", "syllable_count": 2, "sentences": [{"text": "昨天路上发生了一场车祸。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这起车祸造成三人受伤。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车祸发生后，警察很快就来了。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天路滑，容易出车祸。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一次车祸中受了重伤。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为那场车祸，路上堵了两个小时。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机开车不看路，才出了车祸。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有很多车祸受伤的人。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他遇到过一次车祸，现在开车很小心。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路经常发生车祸，大家要小心。", "target_word": "车祸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场车祸", "label": "量词"}, {"form": "一起车祸", "label": "量词"}, {"form": "车祸现场", "label": "复合词"}, {"form": "車禍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "车辆行驶中发生撞击的交通事故", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '76fef613-3ca8-4921-b299-1d3948821c22') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "车祸", "is_correct": true, "explanation": "车祸：车辆行驶中发生撞击的交通事故，与“路上发生了一场”的语境相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是身体的疾病，不会在路上“发生”，句子说不通。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦是睡觉时的幻觉，不会在路上“发生”，句子说不通。"}, {"text": "事变", "is_correct": false, "explanation": "语域：“事变”是书面用语，指重大政治或军事事件，不用于路上的交通事故。"}], "explanations": {"车祸": "车祸：车辆行驶中发生撞击的交通事故，与“路上发生了一场”的语境相符。", "感冒": "语义：感冒是身体的疾病，不会在路上“发生”，句子说不通。", "梦": "语义：梦是睡觉时的幻觉，不会在路上“发生”，句子说不通。", "事变": "语域：“事变”是书面用语，指重大政治或军事事件，不用于路上的交通事故。"}, "sentence_index": 0, "correct_answer": "车祸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在书房看书时出了车祸。", "explanation": "这里应该用〈事故〉。车祸指车辆撞击的交通事故，看书时没有车辆，应说“出了事故”。"}, {"text": "他在厨房切菜时出了车祸，手被割伤了。", "explanation": "这里应该用〈意外〉。车祸指车辆撞击，切菜割伤不是交通事故，应说“出了意外”。"}, {"text": "昨天教室里发生了一起车祸，两个学生打了起来。", "explanation": "这里应该用〈冲突〉。车祸专指车辆撞击的交通事故，学生在教室里打架应说冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "车祸", "is_correct": true, "explanation": "车祸：车辆相撞的交通事故，与“司机开车不看路，才出了”的因果关系相符。"}, {"text": "误会", "is_correct": false, "explanation": "语义：“误会”指人与人之间的理解偏差，与开车不看路造成的后果无关。"}, {"text": "演唱会", "is_correct": false, "explanation": "搭配：“出”用于事故或问题，不说出演唱会，演唱会应说“举行”。"}, {"text": "游戏", "is_correct": false, "explanation": "搭配：“出”不搭配游戏，游戏应说“玩”。"}], "explanations": {"车祸": "车祸：车辆相撞的交通事故，与“司机开车不看路，才出了”的因果关系相符。", "误会": "语义：“误会”指人与人之间的理解偏差，与开车不看路造成的后果无关。", "演唱会": "搭配：“出”用于事故或问题，不说出演唱会，演唱会应说“举行”。", "游戏": "搭配：“出”不搭配游戏，游戏应说“玩”。"}, "sentence_index": 6, "correct_answer": "车祸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他和朋友之间产生了车祸，两人好几天不说话。", "explanation": "这里应该用〈矛盾〉。车祸指车辆撞击的交通事故，朋友之间的不和应说矛盾。"}, {"text": "他的电脑昨天出了一场车祸，开不了机。", "explanation": "这里应该用〈故障〉。车祸指车辆撞击，电脑出问题应说故障。"}, {"text": "这次考试他出了一场车祸，成绩很差。", "explanation": "这里应该用〈失误〉。车祸指车辆撞击，考试出错应说失误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前天晚上路口出了一只车祸。", "corrected_sentence": "前天晚上路口出了一场车祸。", "error_description": "“车祸”的量词错用了“只”。“只”用于动物或成对的东西，车祸是事件，应改为“场”（或“起”），即“一场车祸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些车祸们让交通很乱。", "corrected_sentence": "这些车祸让交通很乱。", "error_description": "“车祸”是事件，不能加“们”表示复数，“们”只用于指人的名词。应去掉“们”，即“这些车祸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b55234a0-c501-4426-b3f5-4df906aca01a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
