INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "转身是把身体转过去，面对另一边。", "primary_collocate": null, "pronunciation": "zhuǎn shēn", "ipa": "ʈ͡ʂu̯an˨˩ ʂən˥", "syllable_count": 2, "sentences": [{"text": "听到声音，我转身往后看。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走到门口，又转身回来了。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都转身看着窗外。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她转身面对镜子，整理头发。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车来了，他转身躲到树后。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“请转身，看后面的图。”", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他转身看了看，没有人。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女孩转身向我挥了挥手。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在台上，他慢慢转身对着大家。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一转身，猫就跳上了桌子。", "target_word": "转身", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转了身", "label": "体标"}, {"form": "转过身", "label": "体标"}, {"form": "转个身", "label": "离合"}, {"form": "轉身", "label": "繁体"}], "register": "中性", "sense_fingerprint": "转身：把身体转过去，面对另一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6cfd6c5-0201-4335-98b8-7045c06a3902') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转身", "is_correct": true, "explanation": "正确。“转身”表示身体转向，与“往后看”衔接自然。"}, {"text": "闭眼", "is_correct": false, "explanation": "语义：闭上眼睛就看不见，与“往后看”矛盾。"}, {"text": "举起", "is_correct": false, "explanation": "配价：“举起”需要带宾语（如“举起手”），“我举起往后看”不完整。"}, {"text": "面对", "is_correct": false, "explanation": "配价：“面对”后要接对象（如“面对大家”），“我面对往后看”不成立。"}], "explanations": {"转身": "正确。“转身”表示身体转向，与“往后看”衔接自然。", "闭眼": "语义：闭上眼睛就看不见，与“往后看”矛盾。", "举起": "配价：“举起”需要带宾语（如“举起手”），“我举起往后看”不完整。", "面对": "配价：“面对”后要接对象（如“面对大家”），“我面对往后看”不成立。"}, "sentence_index": 0, "correct_answer": "转身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套老房子去年就转身了。", "explanation": "这里应该用〈转手〉。房子等财物卖给或交给别人说转手，转身只指人的身体转向。"}, {"text": "这个电视频道刚才转身了。", "explanation": "这里应该用〈转换〉。频道、形式等发生变化说转换，转身只指人的身体转向。"}, {"text": "这个月他要从北京的小学转身到上海的小学。", "explanation": "这里应该用〈转学〉。学生换学校说转学，转身只指人的身体转向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转身", "is_correct": true, "explanation": "正确。“转身”表示身体转过去，与“看了看，没有人”衔接自然。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时无法看，与“看了看，没有人”矛盾。"}, {"text": "抬起", "is_correct": false, "explanation": "配价：“抬起”需要带宾语（如“抬起头”），“他抬起看了看”不完整。"}, {"text": "闭上", "is_correct": false, "explanation": "语义：闭上眼睛就无法看，与“看了看”矛盾。"}], "explanations": {"转身": "正确。“转身”表示身体转过去，与“看了看，没有人”衔接自然。", "睡觉": "语义：睡觉时无法看，与“看了看，没有人”矛盾。", "抬起": "配价：“抬起”需要带宾语（如“抬起头”），“他抬起看了看”不完整。", "闭上": "语义：闭上眼睛就无法看，与“看了看”矛盾。"}, "sentence_index": 6, "correct_answer": "转身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "汽车在路口转身，开向了学校。", "explanation": "这里应该用〈拐弯〉。车辆在路口改变方向说拐弯，转身只指人的身体转向。"}, {"text": "他上个学期转身换了一所学校。", "explanation": "这里应该用〈转学〉。学生换学校说转学，转身只指身体转向。"}, {"text": "出租车在前面转身回去了。", "explanation": "这里应该用〈掉头〉。车辆调转方向说掉头，转身只用于人的身体转向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "听到喊声，他转身起来看。", "corrected_sentence": "听到喊声，他转过身来看。", "error_description": "“转过身来”是正确的补语形式；“起来”不能接在“转身”后，应说“转过身来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他慢慢转身过，看着窗外。", "corrected_sentence": "他慢慢转过身，看着窗外。", "error_description": "“过”应紧跟“转”，说“转过身”，不能说“转身过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f7b1ac4-9947-45f4-8c1f-e3140c5809a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
