INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98115, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迷是在路上找不到方向，不知道往哪里走。", "primary_collocate": null, "pronunciation": "mí", "ipa": "mi˧˥", "syllable_count": 1, "sentences": [{"text": "我们在大山里迷了路，天也黑了。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在公园里迷了路，找不到家。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次来这里，迷了好几次路。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，他在城里迷了路。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在商场里迷了路，哭着找妈妈。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她迷了路，只好问警察。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾里，我们迷了路，只能停下来等天亮。", "target_word": "迷", "complexity_tier": "T3", "furigana": "dà wù lǐ, wǒ men mí le lù, zhǐ néng tíng xià lai děng tiān liàng.", "sentence_source": "generated"}, {"text": "他从来没有迷过路。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的路太多，我们很快就迷了路。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪下得很大，他在树林里迷了路。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迷了", "label": "体标"}, {"form": "迷过", "label": "体标"}, {"form": "迷路", "label": "复合"}], "register": "中性", "sense_fingerprint": "在路上失去方向，找不到路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98115, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迷", "is_correct": true, "explanation": "正确答案：迷（mí，第二声），指在路上失去方向。"}, {"text": "米", "is_correct": false, "explanation": "mǐ（第三声）与 mí（第二声）声调不同，意思是大米。"}, {"text": "密", "is_correct": false, "explanation": "mì（第四声）与 mí（第二声）声调不同，意思是稠密。"}, {"text": "泥", "is_correct": false, "explanation": "ní 与 mí 声母不同（n 与 m），意思是泥土。"}, {"text": "眯", "is_correct": false, "explanation": "mī（第一声）与 mí（第二声）声调不同，意思是眼睛半闭。"}], "explanations": {"迷": "正确答案：迷（mí，第二声），指在路上失去方向。", "米": "mǐ（第三声）与 mí（第二声）声调不同，意思是大米。", "密": "mì（第四声）与 mí（第二声）声调不同，意思是稠密。", "泥": "ní 与 mí 声母不同（n 与 m），意思是泥土。", "眯": "mī（第一声）与 mí（第二声）声调不同，意思是眼睛半闭。"}, "sentence_index": null, "correct_answer": "迷"}, "level_3": {"options": [{"text": "迷", "is_correct": true, "explanation": "正确答案：“迷了路”，表示在大山里失去方向。"}, {"text": "逛", "is_correct": false, "explanation": "搭配：“逛”指随意走走看看，不说“逛了路”，与“大山里”的语境不合。"}, {"text": "怕", "is_correct": false, "explanation": "语义：“怕”表示害怕，与“路”不能组成表示行路情况的动宾结构，句子前后不连贯。"}, {"text": "扫", "is_correct": false, "explanation": "搭配：“扫”用于扫地、扫雪，不说“扫路”来表示在山里找不到方向。"}], "explanations": {"迷": "正确答案：“迷了路”，表示在大山里失去方向。", "逛": "搭配：“逛”指随意走走看看，不说“逛了路”，与“大山里”的语境不合。", "怕": "语义：“怕”表示害怕，与“路”不能组成表示行路情况的动宾结构，句子前后不连贯。", "扫": "搭配：“扫”用于扫地、扫雪，不说“扫路”来表示在山里找不到方向。"}, "sentence_index": 0, "correct_answer": "迷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部动画片太好看了，我一下子就迷上了。", "explanation": "这里的“迷上”是“过分喜爱”的义项，指对某事入迷，与本词“在路上失去方向”的意思无关。"}, {"text": "那些彩灯太亮了，迷了我的眼，我站在街上半天没动。", "explanation": "这里的“迷”是“使眼睛眩晕、看花”的义项（如“迷了眼”），与本词“在路上失去方向”的意思无关。"}, {"text": "这个骗子的花言巧语迷了他的心，他把存款都交了出去。", "explanation": "这里的“迷”是“使人沉迷、被迷惑”的义项，与本词“在路上失去方向”的意思无关，这句说的不是迷路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98115, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "迷", "is_correct": true, "explanation": "正确答案：迷（mí，第二声），指在路上失去方向。"}, {"text": "蜜", "is_correct": false, "explanation": "mì（第四声）与 mí（第二声）声调不同，意思是蜂蜜。"}, {"text": "梨", "is_correct": false, "explanation": "lí 与 mí 声母不同（l 与 m），意思是梨子。"}, {"text": "皮", "is_correct": false, "explanation": "pí 与 mí 声母不同（p 与 m），意思是皮肤或果皮。"}, {"text": "米", "is_correct": false, "explanation": "mǐ（第三声）与 mí（第二声）声调不同，意思是大米。"}], "explanations": {"迷": "正确答案：迷（mí，第二声），指在路上失去方向。", "蜜": "mì（第四声）与 mí（第二声）声调不同，意思是蜂蜜。", "梨": "lí 与 mí 声母不同（l 与 m），意思是梨子。", "皮": "pí 与 mí 声母不同（p 与 m），意思是皮肤或果皮。", "米": "mǐ（第三声）与 mí（第二声）声调不同，意思是大米。"}, "sentence_index": null, "correct_answer": "迷"}, "level_3": {"options": [{"text": "迷", "is_correct": true, "explanation": "正确答案：“迷了路”，表示大雾里找不到方向。"}, {"text": "翻", "is_correct": false, "explanation": "搭配：“翻”用于翻山、翻墙，不说“翻路”，句子无法表示行路受阻。"}, {"text": "吹", "is_correct": false, "explanation": "语义：“吹”指风或嘴的动作，与“了路”不能搭配，与“大雾里”的情境脱节。"}, {"text": "扑", "is_correct": false, "explanation": "搭配：“扑”表示扑向某物，不说“扑路”，与“只能停下来等天亮”的叙述无关。"}], "explanations": {"迷": "正确答案：“迷了路”，表示大雾里找不到方向。", "翻": "搭配：“翻”用于翻山、翻墙，不说“翻路”，句子无法表示行路受阻。", "吹": "语义：“吹”指风或嘴的动作，与“了路”不能搭配，与“大雾里”的情境脱节。", "扑": "搭配：“扑”表示扑向某物，不说“扑路”，与“只能停下来等天亮”的叙述无关。"}, "sentence_index": 6, "correct_answer": "迷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个魔术太精彩了，我看得迷了，忘了鼓掌。", "explanation": "这里的“迷”是“入神、看得出神”的义项，与本词“在路上失去方向”的意思无关，不能指找不到路。"}, {"text": "两张照片太像了，我看迷了眼，分不清哪张是真的。", "explanation": "这里的“迷”是“分辨不清、看花了眼”的义项，与本词“在路上失去方向”的意思无关。"}, {"text": "他的歌声迷住了全场观众。", "explanation": "这里的“迷住”是“吸引、使人入迷”的义项，与本词“在路上失去方向”的意思无关，不能用来说明人迷路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在森林里迷了一条路，只能等待救援。", "corrected_sentence": "我们在森林里迷了路，只能等待救援。", "error_description": "错误：“迷了一条路”，迷路是离合词，“一条”修饰宾语“路”，数量应加在动作上（如“迷了一次路”），此说法不地道。正确：“迷了路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他第二次迷到了路，只好打电话求助。", "corrected_sentence": "他第二次迷了路，只好打电话求助。", "error_description": "错误：“迷到了路”。正确：“迷了路”。迷路表示失去方向，“迷”后用“了”，不用结果补语“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
