INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98116, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对某事物过分喜爱，着迷。", "primary_collocate": null, "pronunciation": "mí", "ipa": "mi˧˥", "syllable_count": 1, "sentences": [{"text": "弟弟迷上了踢足球，每天都去球场。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥迷汽车，家里放着很多汽车的小模型。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都迷手机游戏，不爱出去玩。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸迷上了钓鱼，周末天天去河边。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迷得不想睡觉，一直在看那部动画片。", "target_word": "迷", "complexity_tier": "T3", "furigana": "tā mí de bù xiǎng shuì jiào, yìzhí zài kàn nà bù dònghuàpiàn.", "sentence_source": "generated"}, {"text": "她迷上了画画，每天都在家里画。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迷京剧，已经听了二十年。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友迷唱歌，一有空就去唱。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说太好看了，我一下子就迷上了。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别迷网络游戏，要多看书。", "target_word": "迷", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迷了", "label": "体标"}, {"form": "迷上", "label": "复合"}, {"form": "迷住", "label": "复合"}], "register": "口语", "sense_fingerprint": "对某事物过分喜爱，着迷", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98116, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迷", "is_correct": true, "explanation": "正确答案：迷（mí，第二声），指过分喜爱某事。"}, {"text": "米", "is_correct": false, "explanation": "mǐ（第三声）与 mí（第二声）声调不同，意思是大米。"}, {"text": "密", "is_correct": false, "explanation": "mì（第四声）与 mí（第二声）声调不同，意思是稠密。"}, {"text": "泥", "is_correct": false, "explanation": "ní 与 mí 声母不同（n 与 m），意思是泥土。"}, {"text": "眯", "is_correct": false, "explanation": "mī（第一声）与 mí（第二声）声调不同，意思是眼睛半闭。"}], "explanations": {"迷": "正确答案：迷（mí，第二声），指过分喜爱某事。", "米": "mǐ（第三声）与 mí（第二声）声调不同，意思是大米。", "密": "mì（第四声）与 mí（第二声）声调不同，意思是稠密。", "泥": "ní 与 mí 声母不同（n 与 m），意思是泥土。", "眯": "mī（第一声）与 mí（第二声）声调不同，意思是眼睛半闭。"}, "sentence_index": null, "correct_answer": "迷"}, "level_3": {"options": [{"text": "迷", "is_correct": true, "explanation": "正确答案：“迷上了”，表示对踢足球入迷。"}, {"text": "厌", "is_correct": false, "explanation": "语义：“厌”表示讨厌，与“每天都去球场”的行为矛盾。"}, {"text": "恨", "is_correct": false, "explanation": "语义：“恨”情感过于强烈，与“每天都去球场”的行为不符。"}, {"text": "喜", "is_correct": false, "explanation": "搭配：“喜”后不接“上”构成“喜上”来表示爱好，不能说“喜上了踢足球”。"}], "explanations": {"迷": "正确答案：“迷上了”，表示对踢足球入迷。", "厌": "语义：“厌”表示讨厌，与“每天都去球场”的行为矛盾。", "恨": "语义：“恨”情感过于强烈，与“每天都去球场”的行为不符。", "喜": "搭配：“喜”后不接“上”构成“喜上”来表示爱好，不能说“喜上了踢足球”。"}, "sentence_index": 0, "correct_answer": "迷"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很迷那个邻居，每次见面都想躲开。", "explanation": "这里应该用〈厌恶〉。迷表示喜爱、入迷，不能表示厌恶。"}, {"text": "作业迷了，老师很生气。", "explanation": "这里应该用〈丢〉。迷不用于作业这类物品作主语，表示丢失要用“丢”。"}, {"text": "他一紧张，就迷了朋友的电话号码。", "explanation": "这里应该用〈忘〉。迷表示入迷或失去方向，不表示忘记记住的号码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98116, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "迷", "is_correct": true, "explanation": "正确答案：迷（mí，第二声），指过分喜爱某事。"}, {"text": "蜜", "is_correct": false, "explanation": "mì（第四声）与 mí（第二声）声调不同，意思是蜂蜜。"}, {"text": "梨", "is_correct": false, "explanation": "lí 与 mí 声母不同（l 与 m），意思是梨子。"}, {"text": "皮", "is_correct": false, "explanation": "pí 与 mí 声母不同（p 与 m），意思是皮肤或果皮。"}, {"text": "米", "is_correct": false, "explanation": "mǐ（第三声）与 mí（第二声）声调不同，意思是大米。"}], "explanations": {"迷": "正确答案：迷（mí，第二声），指过分喜爱某事。", "蜜": "mì（第四声）与 mí（第二声）声调不同，意思是蜂蜜。", "梨": "lí 与 mí 声母不同（l 与 m），意思是梨子。", "皮": "pí 与 mí 声母不同（p 与 m），意思是皮肤或果皮。", "米": "mǐ（第三声）与 mí（第二声）声调不同，意思是大米。"}, "sentence_index": null, "correct_answer": "迷"}, "level_3": {"options": [{"text": "迷", "is_correct": true, "explanation": "正确答案：“迷京剧”，表示非常喜爱京剧。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”指拆开、拆散，不能用来表示对京剧的喜好，句子不通。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：“砍”指用刀斧切断，不能用来表示对京剧的态度，句子不通。"}, {"text": "讨", "is_correct": false, "explanation": "搭配：“讨”后接“京剧”不成词，不能表示对京剧的态度。"}], "explanations": {"迷": "正确答案：“迷京剧”，表示非常喜爱京剧。", "拆": "搭配：“拆”指拆开、拆散，不能用来表示对京剧的喜好，句子不通。", "砍": "搭配：“砍”指用刀斧切断，不能用来表示对京剧的态度，句子不通。", "讨": "搭配：“讨”后接“京剧”不成词，不能表示对京剧的态度。"}, "sentence_index": 6, "correct_answer": "迷"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件外套太旧了，我早就迷它了，不想再穿。", "explanation": "这里应该用〈厌倦〉。迷表示过分喜爱，不能表示对物品的厌倦。"}, {"text": "你快去迷一下钥匙，看看它在哪儿。", "explanation": "这里应该用〈找〉。迷不表示寻找，这里要用“找”。"}, {"text": "他一紧张，就迷了方向，半天找不到出口。", "explanation": "这里是“失去方向”的义项（迷路），与本词“过分喜爱”的义项无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹上迷了跳舞，每天放学后都去练。", "corrected_sentence": "妹妹迷上了跳舞，每天放学后都去练。", "error_description": "错误：“上迷了跳舞”，语序错误。结果补语“上”须紧跟“迷”，应为“迷上了跳舞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她迷到了唱歌，每天都练一个小时。", "corrected_sentence": "她迷上了唱歌，每天都练一个小时。", "error_description": "错误：“迷到了唱歌”。正确：“迷上了唱歌”。表示入迷时用结果补语“上”，不用“到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
