INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98119, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "遍是说一件事从头到尾做一次，数几次就说几遍。", "primary_collocate": null, "pronunciation": "biàn", "ipa": "pjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "请你把这个故事再讲一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我看了三遍，还是不懂。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，每个生词要写五遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没听清楚，请再说一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把课文从头到尾读了一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影太好看了，我想再看一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门以前，再检查一遍门窗。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我把房间打扫了两遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌我听了十遍才学会。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一遍又一遍地练习这个动作。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一遍", "label": "数量短语"}, {"form": "遍遍", "label": "重叠"}], "register": "中性", "sense_fingerprint": "动量词，一件事从头到尾做一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98119, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遍", "is_correct": true, "explanation": "遍：从头到尾完整做一次，是正确答案。"}, {"text": "边", "is_correct": false, "explanation": "biān（第一声）与 biàn（第四声）声调不同，意思是“边缘”。"}, {"text": "片", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），意思是“薄片”。"}, {"text": "面", "is_correct": false, "explanation": "miàn 与 biàn 声母不同（m 与 b），意思是“脸面”或“面条”。"}], "explanations": {"遍": "遍：从头到尾完整做一次，是正确答案。", "边": "biān（第一声）与 biàn（第四声）声调不同，意思是“边缘”。", "片": "piàn 与 biàn 声母不同（p 与 b），意思是“薄片”。", "面": "miàn 与 biàn 声母不同（m 与 b），意思是“脸面”或“面条”。"}, "sentence_index": null, "correct_answer": "遍"}, "level_3": {"options": [{"text": "遍", "is_correct": true, "explanation": "正确：“再讲一”后面接量词“遍”，表示从头到尾讲一次。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸、桌子等平面的东西，不能用来计算讲故事的次数。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、房屋等大型固定的东西，不能用来计算讲故事的次数。"}, {"text": "趟", "is_correct": false, "explanation": "搭配：“趟”用于往返的行程，不能用来计算讲故事的次数。"}], "explanations": {"遍": "正确：“再讲一”后面接量词“遍”，表示从头到尾讲一次。", "张": "搭配：“张”用于纸、桌子等平面的东西，不能用来计算讲故事的次数。", "座": "搭配：“座”用于山、房屋等大型固定的东西，不能用来计算讲故事的次数。", "趟": "搭配：“趟”用于往返的行程，不能用来计算讲故事的次数。"}, "sentence_index": 0, "correct_answer": "遍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场比赛我输了三遍，心里很难过。", "explanation": "这里应该用〈次〉。“遍”要求从头到尾完整做一次，输比赛这类事件应用“次”计数。"}, {"text": "他上个月来过我家一遍。", "explanation": "这里应该用〈回〉。“遍”要求从头到尾完整走过一个过程，来访一次应用“回”。"}, {"text": "窗外刮了一遍风，把门吹开了。", "explanation": "这里应该用〈阵〉。“阵”用于一段时间内断续出现的风、雨等，“遍”要求从头到尾完整做一次，不能用来数一阵风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98119, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "遍", "is_correct": true, "explanation": "遍：从头到尾完整做一次，是正确答案。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biàn（第四声）声调不同，意思是“扁平”。"}, {"text": "编", "is_correct": false, "explanation": "biān（第一声）与 biàn（第四声）声调不同，意思是“编织”。"}, {"text": "骗", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），意思是“欺骗”。"}], "explanations": {"遍": "遍：从头到尾完整做一次，是正确答案。", "扁": "biǎn（第三声）与 biàn（第四声）声调不同，意思是“扁平”。", "编": "biān（第一声）与 biàn（第四声）声调不同，意思是“编织”。", "骗": "piàn 与 biàn 声母不同（p 与 b），意思是“欺骗”。"}, "sentence_index": null, "correct_answer": "遍"}, "level_3": {"options": [{"text": "遍", "is_correct": true, "explanation": "正确：“检查一”后面接量词“遍”，表示把门窗从头到尾检查一次。"}, {"text": "件", "is_correct": false, "explanation": "搭配：“件”用于衣物、事情等单个物品，“门窗”是成组的建筑部件，不能说“一件门窗”。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄或可握持的器具，不能用来数门窗。"}, {"text": "场", "is_correct": false, "explanation": "语义：“场”用于比赛、雨这类一次性活动，不能用来计数被检查的门窗。"}], "explanations": {"遍": "正确：“检查一”后面接量词“遍”，表示把门窗从头到尾检查一次。", "件": "搭配：“件”用于衣物、事情等单个物品，“门窗”是成组的建筑部件，不能说“一件门窗”。", "把": "搭配：“把”用于有柄或可握持的器具，不能用来数门窗。", "场": "语义：“场”用于比赛、雨这类一次性活动，不能用来计数被检查的门窗。"}, "sentence_index": 6, "correct_answer": "遍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去了一遍北京，玩得很开心。", "explanation": "这里应该用〈趟〉。“遍”强调从头到尾完成一个动作，外出一次到某地的行程要用“趟”。"}, {"text": "夜里下了一遍雨，早上路都湿了。", "explanation": "这里应该用〈场〉。下雨这类天气现象要用“场”来计数，不能用“遍”。"}, {"text": "他喝了一遍水，就出门了。", "explanation": "这里应该用〈口〉。“遍”要求完整做完一个过程，喝一小口水应用“口”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说我一遍读了，还是没看懂。", "corrected_sentence": "这部小说我读了一遍，还是没看懂。", "error_description": "语序错误：动量补语“一遍”要放在动词后面，不能放在动词前，应说“读了一遍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这个动作练着一遍。", "corrected_sentence": "他把这个动作练了一遍。", "error_description": "体标错误：动量补语“一遍”表示动作已经完成，应与“了”搭配，不能用“着”，应说“把这个动作练了一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
