INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98120, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于动作从开始到结束的整个过程的次数。", "primary_collocate": null, "pronunciation": "biàn", "ipa": "pjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "这篇文章我从头到尾读了两遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把作业检查了一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这个句子念了一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他唱完一遍，又从头唱了一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这份表格再填一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜谱我照着做了一遍，成功了。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书他翻了好几遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把桌子擦了一遍又一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣服要先用水冲一遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，我把笔记复习了三遍。", "target_word": "遍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一遍", "label": "数量短语"}, {"form": "遍遍", "label": "重叠"}], "register": "中性", "sense_fingerprint": "动量词，计算动作整个过程的次数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98120, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "遍", "is_correct": true, "explanation": "遍：动作从开始到结束的整个过程计作一次，是正确答案。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biàn（第四声）声调不同，意思是“扁平”。"}, {"text": "片", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），意思是“薄片”。"}, {"text": "面", "is_correct": false, "explanation": "miàn 与 biàn 声母不同（m 与 b），意思是“脸面”或“面条”。"}], "explanations": {"遍": "遍：动作从开始到结束的整个过程计作一次，是正确答案。", "扁": "biǎn（第三声）与 biàn（第四声）声调不同，意思是“扁平”。", "片": "piàn 与 biàn 声母不同（p 与 b），意思是“薄片”。", "面": "miàn 与 biàn 声母不同（m 与 b），意思是“脸面”或“面条”。"}, "sentence_index": null, "correct_answer": "遍"}, "level_3": {"options": [{"text": "遍", "is_correct": true, "explanation": "正确：“读了两”后面接“遍”，表示从头到尾读两次，符合整个过程的意思。"}, {"text": "座", "is_correct": false, "explanation": "搭配：“座”用于山、房屋等大型固定的东西，不能用来计算读文章的次数。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸、桌子等平面的东西，不能用来计算读文章的次数。"}, {"text": "块", "is_correct": false, "explanation": "搭配：“块”用于块状的东西，不能用来计算读文章的次数。"}], "explanations": {"遍": "正确：“读了两”后面接“遍”，表示从头到尾读两次，符合整个过程的意思。", "座": "搭配：“座”用于山、房屋等大型固定的东西，不能用来计算读文章的次数。", "张": "搭配：“张”用于纸、桌子等平面的东西，不能用来计算读文章的次数。", "块": "搭配：“块”用于块状的东西，不能用来计算读文章的次数。"}, "sentence_index": 0, "correct_answer": "遍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他摔了一遍跤，爬起来就走。", "explanation": "这里应该用〈次〉。“遍”强调动作从头到尾完整做一次，摔跤这类一下子发生的事应用“次”。"}, {"text": "他去年生了一遍病，后来就好了。", "explanation": "这里应该用〈场〉。生病这类一段经历要用“场”，“遍”表示把动作从头到尾完整做一次，不能用来数生病。"}, {"text": "他对我笑了一遍，就转身走了。", "explanation": "这里应该用〈下〉。“下”用于短暂、一瞬间的动作，笑一下这类动作用“下”，“遍”要求从头到尾完整做完一个过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98120, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "遍", "is_correct": true, "explanation": "遍：动作从开始到结束的整个过程计作一次，是正确答案。"}, {"text": "边", "is_correct": false, "explanation": "biān（第一声）与 biàn（第四声）声调不同，意思是“边缘”。"}, {"text": "骗", "is_correct": false, "explanation": "piàn 与 biàn 声母不同（p 与 b），意思是“欺骗”。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn（第三声）与 biàn（第四声）声调不同，意思是“扁平”。"}], "explanations": {"遍": "遍：动作从开始到结束的整个过程计作一次，是正确答案。", "边": "biān（第一声）与 biàn（第四声）声调不同，意思是“边缘”。", "骗": "piàn 与 biàn 声母不同（p 与 b），意思是“欺骗”。", "扁": "biǎn（第三声）与 biàn（第四声）声调不同，意思是“扁平”。"}, "sentence_index": null, "correct_answer": "遍"}, "level_3": {"options": [{"text": "遍", "is_correct": true, "explanation": "正确：“翻了好几”后面接量词“遍”，表示从头到尾翻了好几次。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”用于有柄或可握持的器具，不能用来计算翻书的次数。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“个”不能用来计算翻书的过程，与“翻”搭配不自然。"}, {"text": "趟", "is_correct": false, "explanation": "搭配：“趟”用于往返的行程，不能用来计算翻书的次数。"}], "explanations": {"遍": "正确：“翻了好几”后面接量词“遍”，表示从头到尾翻了好几次。", "把": "搭配：“把”用于有柄或可握持的器具，不能用来计算翻书的次数。", "个": "搭配：“个”不能用来计算翻书的过程，与“翻”搭配不自然。", "趟": "搭配：“趟”用于往返的行程，不能用来计算翻书的次数。"}, "sentence_index": 6, "correct_answer": "遍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们吃了一遍丰盛的晚餐，很满足。", "explanation": "这里应该用〈顿〉。吃饭一次要用“顿”，“遍”不能用来数一餐饭。"}, {"text": "我昨天去了一遍超市，买了很多东西。", "explanation": "这里应该用〈趟〉。去一个地方办事的一次行程要用“趟”，“遍”不是这个用法。"}, {"text": "昨晚下了一遍大雨，院子里全是水。", "explanation": "这里应该用〈场〉。一场雨要用“场”来计数，“遍”不能用于天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.valid