INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98123, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "过少是太少了，比需要的还少。", "primary_collocate": null, "pronunciation": "guò shǎo", "ipa": "kwo˥˩ ʂɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "菜里的盐放得过少，吃起来没有味道。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天睡觉的时间过少，人会很累。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃得过少，所以长得很瘦。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水喝得过少，嘴就会很干。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的雨水过少，河里的水也变少了。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说我穿得过少，让我多加一件衣服。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤里的肉过少，孩子们都没吃饱。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动过少对身体不好，你要多出去走走。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次作业的字数过少，老师让他再写一点。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买的米过少，我们不到一个星期就吃完了。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "過少", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比需要的还少，太少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98123, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过少", "is_correct": true, "explanation": "正确答案：“放得过少”，盐放得太少，吃起来才没有味道。"}, {"text": "过多", "is_correct": false, "explanation": "语义：盐放得过多会很咸，与“吃起来没有味道”的结果相矛盾。"}, {"text": "过快", "is_correct": false, "explanation": "搭配：“过快”形容速度，不能修饰“放”这一动作，与“盐”搭配不通。"}, {"text": "过紧", "is_correct": false, "explanation": "搭配：“过紧”形容松紧程度，不能用来说盐放得多少。"}], "explanations": {"过少": "正确答案：“放得过少”，盐放得太少，吃起来才没有味道。", "过多": "语义：盐放得过多会很咸，与“吃起来没有味道”的结果相矛盾。", "过快": "搭配：“过快”形容速度，不能修饰“放”这一动作，与“盐”搭配不通。", "过紧": "搭配：“过紧”形容松紧程度，不能用来说盐放得多少。"}, "sentence_index": 0, "correct_answer": "过少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这孩子的年龄过少，还不能上学。", "explanation": "这里应该用〈过小〉。过少说的是数量太少，不用于形容年龄。"}, {"text": "这个房间过少，放不下一张床。", "explanation": "这里应该用〈过小〉。过少说的是数量太少，不用于形容房间的大小。"}, {"text": "这件衣服过少，我穿不下。", "explanation": "这里应该用〈过小〉。过少说的是数量，不用于形容衣服的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过少", "is_correct": true, "explanation": "正确答案：汤里的肉太少，孩子们才没吃饱。"}, {"text": "过慢", "is_correct": false, "explanation": "搭配：“过慢”形容速度，不修饰“肉”的数量，无法表示吃不饱的原因。"}, {"text": "过远", "is_correct": false, "explanation": "搭配：“过远”形容距离，不能修饰“肉”的数量，句子不通。"}, {"text": "过快", "is_correct": false, "explanation": "搭配：“过快”形容速度，不能修饰“肉”的数量，句子不通。"}], "explanations": {"过少": "正确答案：汤里的肉太少，孩子们才没吃饱。", "过慢": "搭配：“过慢”形容速度，不修饰“肉”的数量，无法表示吃不饱的原因。", "过远": "搭配：“过远”形容距离，不能修饰“肉”的数量，句子不通。", "过快": "搭配：“过快”形容速度，不能修饰“肉”的数量，句子不通。"}, "sentence_index": 6, "correct_answer": "过少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子过少，装不下这些书。", "explanation": "这里应该用〈过小〉。过少说数量太少，不用于形容箱子的大小。"}, {"text": "这个讲台过少，老师站不下。", "explanation": "这里应该用〈过小〉。过少说的是数量太少，不用于形容讲台的大小。"}, {"text": "他的鞋过少，穿起来很挤。", "explanation": "这里应该用〈过小〉。过少说的是数量，不用于形容鞋的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个月的降雨很过少，庄稼长得不好。", "corrected_sentence": "这个月的降雨过少，庄稼长得不好。", "error_description": "错误：“很过少”。正确：“过少”。“过”本身已表示程度太过，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
