INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98124, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "数量太少，不足。", "primary_collocate": null, "pronunciation": "guò shǎo", "ipa": "kwo˥˩ ʂɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "报名的人数过少，这个班开不了。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来看电影的人过少，电影院只好不放了。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买的书数量过少，不够全班同学用。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来上课的学生过少，老师很担心。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的客人过少，老板有点着急。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的收入过少，不够付房租。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们带的食物数量过少，晚上就吃完了。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的队过少，比赛只好改到下个月。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的货过少，很多东西买不到。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上的杯子过少，客人来了不够用。", "target_word": "过少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "過少", "label": "繁体"}], "register": "中性", "sense_fingerprint": "数量不够，不足", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3bf2352-df69-4533-b827-4defb642019c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_