INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98124, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过少", "is_correct": true, "explanation": "正确答案：报名的人数太少，所以班开不了。"}, {"text": "过多", "is_correct": false, "explanation": "语义：人数过多一般不会导致班开不了，与句中的因果关系相矛盾。"}, {"text": "过窄", "is_correct": false, "explanation": "搭配：“过窄”形容宽度，不用来形容报名的人数。"}, {"text": "过晚", "is_correct": false, "explanation": "搭配：“过晚”形容时间，不用来形容报名的人数。"}], "explanations": {"过少": "正确答案：报名的人数太少，所以班开不了。", "过多": "语义：人数过多一般不会导致班开不了，与句中的因果关系相矛盾。", "过窄": "搭配：“过窄”形容宽度，不用来形容报名的人数。", "过晚": "搭配：“过晚”形容时间，不用来形容报名的人数。"}, "sentence_index": 0, "correct_answer": "过少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室过少，大家都坐不下。", "explanation": "这里应该用〈过小〉。过少说的是数量，不用于形容一间教室的大小。"}, {"text": "这套衣服过少，我穿起来很挤。", "explanation": "这里应该用〈过小〉。过少说的是数量，不用于形容衣服的大小。"}, {"text": "他的脚过少，穿不上这双鞋。", "explanation": "这里应该用〈过小〉。过少说的是数量太少，不用于形容脚的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过少", "is_correct": true, "explanation": "正确答案：食物数量太少，晚上就吃完了。"}, {"text": "过窄", "is_correct": false, "explanation": "搭配：“过窄”形容宽度，不能修饰“食物数量”，句子不通。"}, {"text": "过远", "is_correct": false, "explanation": "搭配：“过远”形容距离，不能修饰“食物数量”，句子不通。"}, {"text": "过慢", "is_correct": false, "explanation": "搭配：“过慢”形容速度，不能修饰“数量”。"}], "explanations": {"过少": "正确答案：食物数量太少，晚上就吃完了。", "过窄": "搭配：“过窄”形容宽度，不能修饰“食物数量”，句子不通。", "过远": "搭配：“过远”形容距离，不能修饰“食物数量”，句子不通。", "过慢": "搭配：“过慢”形容速度，不能修饰“数量”。"}, "sentence_index": 6, "correct_answer": "过少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个杯子过少，只能装半杯水。", "explanation": "这里应该用〈过小〉。过少说的是数量太少，不用于形容杯子的大小。"}, {"text": "这家店的价格过少，大家都不买。", "explanation": "这里应该用〈过低〉。过少说的是数量太少，不用于形容价格的高低。"}, {"text": "他的个子过少，站在人群里很显眼。", "explanation": "这里应该用〈过矮〉。过少说的是数量，不用于形容个子的高矮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次活动的报名人数很过少，只好推迟一周。", "corrected_sentence": "这次活动的报名人数过少，只好推迟一周。", "error_description": "错误：“很过少”。正确：“过少”。“过”本身已表示程度太过，前面不能再加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次演出的观众被过少，主办方只好取消了。", "corrected_sentence": "这次演出的观众过少，主办方只好取消了。", "error_description": "错误：“被过少”。正确：“过少”。“过少”是形容词，表示状态，不能用“被”字句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e698462-5337-4179-b63a-3fa8bc6ad97c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
