INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "清代掌管一道行政事务的地方官员的俗称。", "primary_collocate": null, "pronunciation": "dào tái", "ipa": "taʊ˥˩ tʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "清代的道台管一道的事务。", "target_word": "道台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的道台是清朝的官员。", "target_word": "道台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在清代当过道台。", "target_word": "道台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清朝时，道台比知县的官大。", "target_word": "道台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "道台是清代对这种地方官的俗称。", "target_word": "道台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写了一位清代的道台。", "target_word": "道台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个道台管着全道的税和兵。", "target_word": "道台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爷爷的爷爷是清代的道台。", "target_word": "道台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清代的道台常常去各县看看。", "target_word": "道台", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们说这位清代的道台很清廉。", "target_word": "道台", "complexity_tier": "T3", "furigana": "lǎorénmen shuō zhè wèi qīngdài de dàotái hěn qīnglián", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位道台", "label": "量词"}, {"form": "道臺", "label": "繁体"}], "register": "书面", "sense_fingerprint": "清代道一级地方官的俗称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '244a8996-a574-446d-85a5-426380410052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道台", "is_correct": true, "explanation": "正确：清代的道台管一道的事务，符合该义项的定义。"}, {"text": "知县", "is_correct": false, "explanation": "语义：知县只管一个县，不管一道的事务，与句意不合。"}, {"text": "厨房", "is_correct": false, "explanation": "配价：“厨房”不能作“管”的施事，不能管事务。"}, {"text": "轿夫", "is_correct": false, "explanation": "语义：轿夫不管行政，与“管一道的事务”不合。"}], "explanations": {"道台": "正确：清代的道台管一道的事务，符合该义项的定义。", "知县": "语义：知县只管一个县，不管一道的事务，与句意不合。", "厨房": "配价：“厨房”不能作“管”的施事，不能管事务。", "轿夫": "语义：轿夫不管行政，与“管一道的事务”不合。"}, "sentence_index": 0, "correct_answer": "道台"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "县衙里来了一只道台。", "explanation": "这里量词不对。道台指人，应该用〈位〉，说“来了一位道台”。〈只〉多用于动物。"}, {"text": "他是清代的道台，只管一个县的事。", "explanation": "这里应该用〈知县〉。道台管一道的事务，只管一个县的是知县。"}, {"text": "我们市的道台很能干。", "explanation": "这里应该用〈市长〉。道台是清代的官名，现代城市的官员不用这个词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道台", "is_correct": true, "explanation": "正确：道台管一道的税和兵，符合句意。"}, {"text": "驿站", "is_correct": false, "explanation": "配价：驿站不能管税和兵，不能作“管”的施事。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师不管税和兵，与句意不合。"}, {"text": "书吏", "is_correct": false, "explanation": "语义：书吏只是抄录文书的小吏，不能管全道的税和兵。"}], "explanations": {"道台": "正确：道台管一道的税和兵，符合句意。", "驿站": "配价：驿站不能管税和兵，不能作“管”的施事。", "厨师": "语义：厨师不管税和兵，与句意不合。", "书吏": "语义：书吏只是抄录文书的小吏，不能管全道的税和兵。"}, "sentence_index": 6, "correct_answer": "道台"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个道台很好吃，我吃了两碗。", "explanation": "这里应该用〈面条〉之类的食物。道台是清代的地方官，是人，不能吃。"}, {"text": "我的手机坏了，明天去找道台修一修。", "explanation": "这里应该用〈修理工〉。道台是清代掌管一道行政的官员，不修手机，现代生活中也没有道台。"}, {"text": "农民在地里种庄稼，道台在地里干活。", "explanation": "这里不该用〈道台〉指干农活的人。道台是地方官，在地里干活的应是〈佃户〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只道台在任时修了一座桥。", "corrected_sentence": "那位道台在任时修了一座桥。", "error_description": "错误：“只”是动物量词，指人要用“位”。正确：“那位道台”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位清代地道台非常清廉。", "corrected_sentence": "那位清代的道台非常清廉。", "error_description": "错误：修饰名词“道台”的“清代”后应用助词“的”，不能用“地”。正确：“那位清代的道台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
