INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98132, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "伤势严重，危及生命或造成严重残疾的伤。", "primary_collocate": null, "pronunciation": "zhòng shāng", "ipa": "ʈʂʊŋ⁵¹ ʂɑŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "这场车祸让他受了重伤，差点没命。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种重伤有生命危险。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在战争中受了重伤，一条腿没有了。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重伤让这位运动员再也不能比赛了。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察说，那个人受了重伤，还没有脱离危险。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受了重伤，医生不知道他能不能活下来。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震中他受了重伤，以后走路要用拐杖。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次爆炸，工人受了重伤，手也坏了。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重伤以后，他在床上躺了一年。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机受了重伤，医生说他可能会残疾。", "target_word": "重伤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重伤员", "label": "复合词"}, {"form": "重伤者", "label": "复合词"}], "register": "中性", "sense_fingerprint": "危及生命或造成残疾的严重伤势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bf78ee-7ce4-4c00-a5e3-c90623cde1b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重伤", "is_correct": true, "explanation": "正确。“受了重伤”指伤势严重、危及生命，与“差点没命”相符。"}, {"text": "扭伤", "is_correct": false, "explanation": "语义：扭伤不会危及生命，与“差点没命”矛盾。"}, {"text": "近视", "is_correct": false, "explanation": "搭配：“受了”后接的是伤害类名词，“近视”是视力状况，不能说“受了近视”。"}, {"text": "伤口", "is_correct": false, "explanation": "搭配：“伤口”指伤的部位，不能说“受了伤口”，应说“受了重伤”。"}], "explanations": {"重伤": "正确。“受了重伤”指伤势严重、危及生命，与“差点没命”相符。", "扭伤": "语义：扭伤不会危及生命，与“差点没命”矛盾。", "近视": "搭配：“受了”后接的是伤害类名词，“近视”是视力状况，不能说“受了近视”。", "伤口": "搭配：“伤口”指伤的部位，不能说“受了伤口”，应说“受了重伤”。"}, "sentence_index": 0, "correct_answer": "重伤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他得了重伤，在ICU住了一个月。", "explanation": "这里应该用〈重症〉。得病要说“重症”，“重伤”指外力造成的伤，不能用于疾病。"}, {"text": "他的手指被刀划破了，受了重伤，不用去医院。", "explanation": "这里应该用〈轻伤〉。“重伤”指危及生命或造成严重残疾的伤，手指划破只能说“轻伤”。"}, {"text": "这是一次重伤的灾难，很多人都失去了家。", "explanation": "这里应该用〈重大〉。“重伤”只修饰人或动物受的伤，形容灾难的规模要用“重大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重伤", "is_correct": true, "explanation": "正确。“受了重伤”说明伤势严重，以后走路需要拐杖，与句中的后果相符。"}, {"text": "轻伤", "is_correct": false, "explanation": "语义：轻伤一般不会让人以后走路要用拐杖，与句中的后果矛盾。"}, {"text": "擦伤", "is_correct": false, "explanation": "语义：擦伤不会造成长期行走困难，与“以后走路要用拐杖”矛盾。"}, {"text": "伤痕", "is_correct": false, "explanation": "搭配：“伤痕”是留下的痕迹，不能说“受了伤痕”，应说“留下伤痕”。"}], "explanations": {"重伤": "正确。“受了重伤”说明伤势严重，以后走路需要拐杖，与句中的后果相符。", "轻伤": "语义：轻伤一般不会让人以后走路要用拐杖，与句中的后果矛盾。", "擦伤": "语义：擦伤不会造成长期行走困难，与“以后走路要用拐杖”矛盾。", "伤痕": "搭配：“伤痕”是留下的痕迹，不能说“受了伤痕”，应说“留下伤痕”。"}, "sentence_index": 6, "correct_answer": "重伤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机身上有一只重伤，医生说他可能会残疾。", "explanation": "这里应该用〈处〉。“只”用于动物，人身上的伤要说“一处重伤”。"}, {"text": "司机身上有一颗重伤，医生说他可能会残疾。", "explanation": "这里应该用〈处〉。“颗”用于颗粒状的小东西，人身上的伤要说“一处重伤”。"}, {"text": "司机身上有一头重伤，医生说他可能会残疾。", "explanation": "这里应该用〈处〉。“头”用于大型牲畜，不能用于人身上的伤，应说“一处重伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在工地上受了一个重伤，一条腿截肢了。", "corrected_sentence": "他在工地上受了重伤，一条腿截肢了。", "error_description": "多了量词“一个”。“重伤”前不加量词，应直接说“受了重伤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次事故中，他受了重伤过，昏迷了三天。", "corrected_sentence": "那次事故中，他受了重伤，昏迷了三天。", "error_description": "“了”与“过”同时使用，属于重复体标。去掉“过”，说“受了重伤”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98135, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98135, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98135, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "鉴于是看到了一个原因，所以决定这样做。", "primary_collocate": null, "pronunciation": "jiàn yú", "ipa": "tɕjɛn˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "鉴于天气不好，我们决定明天再去。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于他已经道歉，老师没有再说什么。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于路上堵车，经理决定改坐地铁。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于价格过高，大家都不愿购买。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于孩子还小，他们决定不去远的地方。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于最近太忙，公司决定放一天假。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于去年的经验，今年我们早点准备。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于他身体不好，医生让他多休息。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于学生很多，学校决定再开一个班。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于设备已经陈旧，我们决定更换新设备。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "看到某个原因，因此做出决定或采取做法，后面接决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75b6c6b-1a83-43ea-bf8d-cebf12c05e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98135, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鉴于", "is_correct": true, "explanation": "正确：「鉴于」引出决定的依据「天气不好」，句意通顺。"}, {"text": "为了", "is_correct": false, "explanation": "语义：「为了」引出的是目的，不能表示「天气不好」这一原因。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：「按照」后面接规定、计划或标准，不能接天气状况。"}, {"text": "通过", "is_correct": false, "explanation": "配价：「通过」要接方法或途径，「天气不好」不能作凭借，句意不通。"}], "explanations": {"鉴于": "正确：「鉴于」引出决定的依据「天气不好」，句意通顺。", "为了": "语义：「为了」引出的是目的，不能表示「天气不好」这一原因。", "按照": "搭配：「按照」后面接规定、计划或标准，不能接天气状况。", "通过": "配价：「通过」要接方法或途径，「天气不好」不能作凭借，句意不通。"}, "sentence_index": 0, "correct_answer": "鉴于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鉴于我很喜欢他，所以常常帮他。", "explanation": "这里应该用〈因为〉。鉴于引出的是客观情况作为决定或判断的依据，表达个人感情时要用「因为」。"}, {"text": "鉴于我还是学生的时候，我常去图书馆。", "explanation": "这里应该用〈当〉。鉴于引出的是作为决定依据的情况，不能表示某段时间的情况；说过去某个时候的事要用「当…的时候」。"}, {"text": "鉴于我运气好，考试得了满分。", "explanation": "这里应该用〈因为〉。鉴于要求依据是客观情况，偶然的运气不能作为决定的依据，表示原因要用「因为」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鉴于", "is_correct": true, "explanation": "正确：「鉴于」引出作为依据的「去年的经验」，与后句搭配通顺。"}, {"text": "直到", "is_correct": false, "explanation": "语义：「直到」表示时间的终点，不能用来表示以经验为依据。"}, {"text": "等到", "is_correct": false, "explanation": "语义：「等到」表示等待某个时间点，「去年的经验」不是时间点，句意不通。"}, {"text": "每当", "is_correct": false, "explanation": "语义：「每当」表示反复出现的时间，与「今年早点准备」的依据关系不合。"}], "explanations": {"鉴于": "正确：「鉴于」引出作为依据的「去年的经验」，与后句搭配通顺。", "直到": "语义：「直到」表示时间的终点，不能用来表示以经验为依据。", "等到": "语义：「等到」表示等待某个时间点，「去年的经验」不是时间点，句意不通。", "每当": "语义：「每当」表示反复出现的时间，与「今年早点准备」的依据关系不合。"}, "sentence_index": 6, "correct_answer": "鉴于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鉴于图书馆里，大家都很安静。", "explanation": "这里应该用〈在〉。鉴于引出的是决定或判断的依据，不能表示地点；说某个地方的情况要用「在…里」。"}, {"text": "鉴于北京，我很熟悉。", "explanation": "这里应该用〈对于〉。鉴于引出的是决定或判断的依据，谈论的对象要用「对于」，地点不能作为依据。"}, {"text": "鉴于地图，我们找到了酒店。", "explanation": "这里应该用〈借助〉。鉴于引出的是决定或判断的依据，不能引出凭借的工具；借助地图找路要用「借助」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉴于是下大雨，比赛改到了下周。", "corrected_sentence": "鉴于下大雨，比赛改到了下周。", "error_description": "错误形式：「鉴于」后面多加了「是」。正确形式：「鉴于下大雨」。原因：「鉴于」后面直接接原因小句，不需要「是」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很鉴于今年人数增加，学校决定扩建教室。", "corrected_sentence": "鉴于今年人数增加，学校决定扩建教室。", "error_description": "错误形式：「鉴于」前面用了程度副词「很」。正确形式：「鉴于今年人数增加」。原因：「鉴于」是书面介词，前面不能加「很」，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
