INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98136, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示以某种情况为依据或理由。", "primary_collocate": null, "pronunciation": "jiàn yú", "ipa": "tɕjɛn˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "鉴于目前的情况，学校暂时不开放。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于他的表现，公司给了他一个机会。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于市场变化很快，我们需要新办法。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于过去的做法不太好，大家提出了新想法。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于以上原因，我同意他的看法。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于他经验丰富，大家请他当组长。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于今年雨水很多，农民改种了别的菜。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于这一点，我们应该多听听学生的意见。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于他的年龄，比赛对他不太合适。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鉴于房租越来越贵，不少人搬到了郊外。", "target_word": "鉴于", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "以某种情况、事实为依据或理由，后面常接名词性的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75b6c6b-1a83-43ea-bf8d-cebf12c05e5e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鉴于", "is_correct": true, "explanation": "正确：「鉴于」引出依据「目前的情况」，句意通顺。"}, {"text": "向", "is_correct": false, "explanation": "语义：「向」表示动作的方向或对象，「目前的情况」不能作学校开放的方向，句意不通。"}, {"text": "每当", "is_correct": false, "explanation": "语义：「每当」表示反复出现的时间，与「学校暂时不开放」的依据关系不合。"}, {"text": "趁着", "is_correct": false, "explanation": "配价：「趁着」后面接时机或条件，「目前的情况」不能作它的时机。"}], "explanations": {"鉴于": "正确：「鉴于」引出依据「目前的情况」，句意通顺。", "向": "语义：「向」表示动作的方向或对象，「目前的情况」不能作学校开放的方向，句意不通。", "每当": "语义：「每当」表示反复出现的时间，与「学校暂时不开放」的依据关系不合。", "趁着": "配价：「趁着」后面接时机或条件，「目前的情况」不能作它的时机。"}, "sentence_index": 0, "correct_answer": "鉴于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鉴于我很想念家乡，所以周末常回去。", "explanation": "这里应该用〈因为〉。鉴于引出的是作为决定依据的客观情况，表达个人感情时要用「因为」。"}, {"text": "鉴于他走进教室时，大家都站了起来。", "explanation": "这里应该用〈当〉。鉴于引出的是作为依据的情况，不能表示时间；说某一时刻发生的事要用「当…时」。"}, {"text": "鉴于比赛中，他受伤了。", "explanation": "这里应该用〈在〉。鉴于引出的是作为依据的情况，不能表示范围或过程；说在某个过程中发生的事要用「在…中」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鉴于", "is_correct": true, "explanation": "正确：「鉴于」引出改种作物的依据「今年雨水很多」，句意通顺。"}, {"text": "按照", "is_correct": false, "explanation": "搭配：「按照」后面接规定、计划或标准，不能接「今年雨水很多」这种情况。"}, {"text": "向", "is_correct": false, "explanation": "语义：「向」表示动作的方向，与「农民改种了别的菜」的依据关系不合。"}, {"text": "朝", "is_correct": false, "explanation": "语义：「朝」表示朝向，句中没有可以朝向的对象，句意不通。"}], "explanations": {"鉴于": "正确：「鉴于」引出改种作物的依据「今年雨水很多」，句意通顺。", "按照": "搭配：「按照」后面接规定、计划或标准，不能接「今年雨水很多」这种情况。", "向": "语义：「向」表示动作的方向，与「农民改种了别的菜」的依据关系不合。", "朝": "语义：「朝」表示朝向，句中没有可以朝向的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "鉴于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鉴于这座城市，我很熟悉。", "explanation": "这里应该用〈对于〉。鉴于引出的是决定或判断的依据，谈论的对象要用「对于」，城市不能作为依据。"}, {"text": "鉴于努力，他终于考上了大学。", "explanation": "这里应该用〈通过〉。鉴于引出的是作为依据的情况，表示凭借努力或途径要用「通过」。"}, {"text": "鉴于朋友一起去了北京。", "explanation": "这里应该用〈和〉。鉴于引出的是决定或判断的依据，不能表示与谁共同做某事；说和某人一起做事要用「和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鉴于了疫情变化，学校暂时不开放。", "corrected_sentence": "鉴于疫情变化，学校暂时不开放。", "error_description": "错误形式：「鉴于」后面多加了「了」。正确形式：「鉴于疫情变化」。原因：「了」不能附着在介词「鉴于」上，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "鉴于的物价上涨，超市决定调整价格。", "corrected_sentence": "鉴于物价上涨，超市决定调整价格。", "error_description": "错误形式：「鉴于」后面多加了「的」。正确形式：「鉴于物价上涨」。原因：「鉴于」是介词，后面直接接它引出的依据「物价上涨」，不能加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8817a715-59be-4af8-be65-933ae6c1cbc4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
