INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98139, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "门槛是门下面横着的一条木头，走进去要抬脚迈过。", "primary_collocate": null, "pronunciation": "mén kǎn", "ipa": "mən˧˥ kʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "走进屋子要先迈过门槛。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门槛是木头做的，上面有很多小划痕。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在门槛上钉了一块铁皮。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在门槛上等妈妈回家。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外婆说，站在门槛上说话不好。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗趴在门槛上看着外面。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门槛有点高，轮椅过不去。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抬脚过门槛时，不小心绊了一下。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，水从门槛下面流进了屋。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在门槛旁边脱鞋，再走进客厅。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "门槛儿", "label": "儿化"}, {"form": "门檻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "门下面横着的木头，要抬脚迈过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c715073-07d3-4bb9-b479-83cb8d740dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98139, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "门槛", "is_correct": true, "explanation": "正确。门槛是门下的横木，走进屋子要先迈过去。"}, {"text": "门锁", "is_correct": false, "explanation": "语义：门锁是装在门上用来开关门的部件，不是要迈过的东西，句子说不通。"}, {"text": "门铃", "is_correct": false, "explanation": "语义：门铃是用来按的装置，不是走进屋子时要迈过的部分。"}, {"text": "窗台", "is_correct": false, "explanation": "搭配：“迈过”搭配的是门下的横木或台阶，不说迈过窗台。"}], "explanations": {"门槛": "正确。门槛是门下的横木，走进屋子要先迈过去。", "门锁": "语义：门锁是装在门上用来开关门的部件，不是要迈过的东西，句子说不通。", "门铃": "语义：门铃是用来按的装置，不是走进屋子时要迈过的部分。", "窗台": "搭配：“迈过”搭配的是门下的横木或台阶，不说迈过窗台。"}, "sentence_index": 0, "correct_answer": "门槛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口有一张门槛，又长又旧。", "explanation": "量词错误：这里应该用〈道〉。“张”多用于平面的东西，门槛是门下的横木，要说“一道门槛”。"}, {"text": "过年了，他在门槛两边贴上红色的对联。", "explanation": "近义混淆：这里应该用〈门框〉。对联贴在门框两侧的竖条上，门槛是门下的横木，不贴对联。"}, {"text": "他顺手把门槛关上了，屋里很安静。", "explanation": "搭配错误：这里应该用〈门〉。门可以“关上”，门槛是固定在门下的横木，不能关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "门槛", "is_correct": true, "explanation": "正确。门槛高，轮椅就过不去，符合句意。"}, {"text": "衣柜", "is_correct": false, "explanation": "搭配：“过不去”说的是要通过的地方，衣柜不是能让轮椅通过的通道。"}, {"text": "水杯", "is_correct": false, "explanation": "语义：水杯是盛水的器具，不是轮椅要通过的障碍。"}, {"text": "篮子", "is_correct": false, "explanation": "语义：篮子是装东西的容器，与轮椅能否通过没有关系。"}], "explanations": {"门槛": "正确。门槛高，轮椅就过不去，符合句意。", "衣柜": "搭配：“过不去”说的是要通过的地方，衣柜不是能让轮椅通过的通道。", "水杯": "语义：水杯是盛水的器具，不是轮椅要通过的障碍。", "篮子": "语义：篮子是装东西的容器，与轮椅能否通过没有关系。"}, "sentence_index": 6, "correct_answer": "门槛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "门口有一座门槛，他每天都要跨过去。", "explanation": "量词错误：这里应该用〈道〉。“座”用于山、桥、房屋等大型物体，门槛要说“一道门槛”。"}, {"text": "他把门槛推开，走了进去。", "explanation": "搭配错误：这里应该用〈门〉。门可以“推开”，门槛是固定的横木，推不开。"}, {"text": "他把门槛锁上，才出门去买菜。", "explanation": "搭配错误：这里应该用〈门〉。门可以“锁上”，门槛是固定的横木，不能锁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不小心把门槛撞了坏。", "corrected_sentence": "他不小心把门槛撞坏了。", "error_description": "补语位置错误：“坏”是“撞”的结果补语，要紧跟动词，中间不能插入“了”；应说“把门槛撞坏了”，“撞了坏”语序不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一抬脚，就绊在门槛了上。", "corrected_sentence": "他一抬脚，就绊在门槛上了。", "error_description": "方位词与体标语序错误：“上”是方位词，要紧跟“门槛”，“了”放在句末；应说“绊在门槛上了”，“绊在门槛了上”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
