INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98140, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98140, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "门框下端左右横着的部分。", "primary_collocate": null, "pronunciation": "mén kǎn", "ipa": "mən˧˥ kʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "小孩子太小，跨不过高高的门槛。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶坐在门槛上晒太阳。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进门的时候，小心脚下的门槛。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的门槛很高，我差点摔倒。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一脚踩在门槛上，没有进屋。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家老店的木头门槛已经很旧了。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把椅子放在门槛旁边。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人抬起脚，慢慢迈过门槛。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门槛边放着一双小布鞋。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门槛太高，婴儿车推不进去。", "target_word": "门槛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "道", "label": "量词"}, {"form": "门槛儿", "label": "儿化"}, {"form": "门檻", "label": "繁体"}], "register": "中性", "sense_fingerprint": "门框下端横着的部分，进门要迈过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c715073-07d3-4bb9-b479-83cb8d740dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "门槛", "is_correct": true, "explanation": "正确。门槛是门下横着的部分，要跨过去，符合“跨不过”和“高高的”。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：“跨”用于可以跨过去的障碍，不说“跨”窗帘。"}, {"text": "门把手", "is_correct": false, "explanation": "语义：门把手是用手握的部件，不是要跨过去的东西，句子说不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是背或提的物品，不是横在路上的障碍，“跨不过高高的书包”不成立。"}], "explanations": {"门槛": "正确。门槛是门下横着的部分，要跨过去，符合“跨不过”和“高高的”。", "窗帘": "搭配：“跨”用于可以跨过去的障碍，不说“跨”窗帘。", "门把手": "语义：门把手是用手握的部件，不是要跨过去的东西，句子说不通。", "书包": "语义：书包是背或提的物品，不是横在路上的障碍，“跨不过高高的书包”不成立。"}, "sentence_index": 0, "correct_answer": "门槛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口有一扇门槛，又高又旧。", "explanation": "量词错误：这里应该用〈道〉。“扇”用于门窗，门槛是门下的横木，要说“一道门槛”。"}, {"text": "门槛上挂着一块匾，写着几个大字。", "explanation": "近义混淆：这里应该用〈门楣〉。门楣是门框上方的横木，匾额挂在那里；门槛在门下，挂不了匾。"}, {"text": "门口有三级门槛，我们要小心。", "explanation": "近义混淆：这里应该用〈台阶〉。台阶可以按“级”计数，门槛是一道横木，不说“三级门槛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "门槛", "is_correct": true, "explanation": "正确。门槛是固定的位置，椅子可以放在它旁边。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无处不在的气体，不能作为可以放置椅子的具体位置。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“放在”后面要跟具体的场所或物体，不说“放在声音旁边”。"}, {"text": "星期天", "is_correct": false, "explanation": "语义：星期天是时间，不是可以放椅子的空间位置。"}], "explanations": {"门槛": "正确。门槛是固定的位置，椅子可以放在它旁边。", "空气": "语义：空气是无处不在的气体，不能作为可以放置椅子的具体位置。", "声音": "搭配：“放在”后面要跟具体的场所或物体，不说“放在声音旁边”。", "星期天": "语义：星期天是时间，不是可以放椅子的空间位置。"}, "sentence_index": 6, "correct_answer": "门槛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把门槛打开，走了进去。", "explanation": "搭配错误：这里应该用〈门〉。门可以“打开”，门槛是固定在地上的横木，不能打开。"}, {"text": "他一拉门槛，门就开了。", "explanation": "搭配错误：这里应该用〈门〉。拉的是门，门槛是固定在地上的横木，拉它开不了门。"}, {"text": "门口有一把门槛，他每天都要跨过去。", "explanation": "量词错误：这里应该用〈道〉。“把”多用于有柄的东西，门槛是横木，要说“一道门槛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口那只门槛被磨得发亮。", "corrected_sentence": "门口那道门槛被磨得发亮。", "error_description": "量词错误：门槛应该用“道”，“那只门槛”应改为“那道门槛”。“只”多用于动物或成对物件中的一个，门槛不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫一下子就跨了过门槛。", "corrected_sentence": "小猫一下子就跨过了门槛。", "error_description": "补语位置错误：“过”是“跨”的结果补语，要紧接动词，“了”放在“跨过”之后；应说“跨过了门槛”，“跨了过门槛”语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98143, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98143, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98143, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开拓是把没人去过的地方打开，让它变得能用。", "primary_collocate": null, "pronunciation": "kāi tuò", "ipa": "kʰaɪ˥ tʰwo˥˩", "syllable_count": 2, "sentences": [{"text": "农民们开拓了一片荒地，准备种菜。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早年的移民在山里开拓出一块新田地。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要开拓山脚下的一片荒地，种上庄稼。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧民在草原深处开拓了新牧场。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在开拓荒山，打算建一个果园。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人一个人开拓了这片土地，种满了树。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了有更多的水田，村民们开拓了河边的荒滩。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "探险队在沙漠边上开拓出一块可以住人的地方。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片荒山，爷爷花了十年才把它开拓出来。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在森林里开拓出一块空地，用来种菜。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开拓了", "label": "体标（完成）"}, {"form": "开拓过", "label": "体标（经历）"}, {"form": "开拓者", "label": "复合"}], "register": "书面", "sense_fingerprint": "把荒地、无人到过之处打开并使之可用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96ed990e-6a76-4bf4-be27-bf246034c330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98143, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是观赏美好的事物，与“准备种菜”的用途不合，“欣赏荒地”不通。"}, {"text": "开拓", "is_correct": true, "explanation": "“开拓”指把荒地打开使之能用，符合“准备种菜”的语境。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”多用于房屋、道路，不能说“修建荒地”。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”是美化已有的东西，与把荒地开出来种菜的意思相反。"}], "explanations": {"欣赏": "语义：“欣赏”是观赏美好的事物，与“准备种菜”的用途不合，“欣赏荒地”不通。", "开拓": "“开拓”指把荒地打开使之能用，符合“准备种菜”的语境。", "修建": "搭配：“修建”多用于房屋、道路，不能说“修建荒地”。", "装饰": "语义：“装饰”是美化已有的东西，与把荒地开出来种菜的意思相反。"}, "sentence_index": 0, "correct_answer": "开拓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校开拓了一座新教学楼。", "explanation": "这里应该用〈修建〉。开拓用于荒地、新领域，盖楼房要说“修建”。"}, {"text": "这个月班里的人数开拓了不少。", "explanation": "这里应该用〈增加〉。开拓指开辟土地或领域，人数的增长要说“增加”。"}, {"text": "学校开拓了很多优秀人才。", "explanation": "这里应该用〈培养〉。开拓用于土地和领域，人才要靠“培养”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象多是建筑物，荒滩不能拆除，句子不通。"}, {"text": "冲刷", "is_correct": false, "explanation": "语义：“冲刷”是水流把东西冲走，与“为了有更多的水田”的目的不合。"}, {"text": "开拓", "is_correct": true, "explanation": "“开拓”指把河边的荒滩打开使之能种植，符合“为了有更多的水田”的语境。"}, {"text": "迁移", "is_correct": false, "explanation": "搭配：“迁移”多用于人口、工厂，不能用于荒滩。"}], "explanations": {"拆除": "搭配：“拆除”的对象多是建筑物，荒滩不能拆除，句子不通。", "冲刷": "语义：“冲刷”是水流把东西冲走，与“为了有更多的水田”的目的不合。", "开拓": "“开拓”指把河边的荒滩打开使之能种植，符合“为了有更多的水田”的语境。", "迁移": "搭配：“迁移”多用于人口、工厂，不能用于荒滩。"}, "sentence_index": 6, "correct_answer": "开拓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在街边开拓了一家小饭馆。", "explanation": "这里应该用〈开办〉。开拓用于土地和领域，开店要说“开办”。"}, {"text": "老师开拓了这道难题，同学们都很佩服。", "explanation": "这里应该用〈解答〉。开拓用于土地和领域，难题要说“解答”。"}, {"text": "他把屋子开拓了一下，干干净净的。", "explanation": "这里应该用〈收拾〉。开拓指开辟土地，整理房间要说“收拾”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们开拓了出一块菜地。", "corrected_sentence": "他们开拓出了一块菜地。", "error_description": "补语“出”须紧跟“开拓”，“了”应放在“出”之后，应说“开拓出了一块菜地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们开拓了过这片荒山。", "corrected_sentence": "他们开拓过这片荒山。", "error_description": "“了”和“过”不能同时使用：表示经历要说“开拓过”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
