INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98144, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98144, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开辟新的领域或市场，扩大范围。", "primary_collocate": null, "pronunciation": "kāi tuò", "ipa": "kʰaɪ˥ tʰwo˥˩", "syllable_count": 2, "sentences": [{"text": "公司打算开拓海外市场。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书可以开拓我们的视野。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店想开拓新客源，开始在网上卖东西。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家一直在开拓新的研究领域。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出国留学，是为了开拓自己的眼界。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要开拓思路，就要多听别人的想法。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻人在音乐方面开拓了一片新天地。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的产品卖得不错，下一步要开拓更大的市场。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行开始开拓网上业务，方便客人。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要敢于开拓新路子，不能只等客人来。", "target_word": "开拓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开拓了", "label": "体标（完成）"}, {"form": "开拓过", "label": "体标（经历）"}, {"form": "开拓者", "label": "复合"}], "register": "书面", "sense_fingerprint": "开辟新领域、新市场，扩大范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96ed990e-6a76-4bf4-be27-bf246034c330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修建", "is_correct": false, "explanation": "搭配：“修建”用于房屋、道路，不能说“修建海外市场”。"}, {"text": "开拓", "is_correct": true, "explanation": "“开拓”指开辟新市场、扩大范围，符合“打算……海外市场”的语境。"}, {"text": "解释", "is_correct": false, "explanation": "搭配：“解释”的对象是原因、问题，“解释海外市场”不通。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是观赏美好的事物，与公司“打算”经营市场的意图不合。"}], "explanations": {"修建": "搭配：“修建”用于房屋、道路，不能说“修建海外市场”。", "开拓": "“开拓”指开辟新市场、扩大范围，符合“打算……海外市场”的语境。", "解释": "搭配：“解释”的对象是原因、问题，“解释海外市场”不通。", "欣赏": "语义：“欣赏”是观赏美好的事物，与公司“打算”经营市场的意图不合。"}, "sentence_index": 0, "correct_answer": "开拓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的成绩开拓了很多。", "explanation": "这里应该用〈提高〉。开拓用于开辟新领域，成绩、水平的进步要说“提高”。"}, {"text": "学校开拓了安全教育活动。", "explanation": "这里应该用〈开展〉。开拓指开辟新的范围，活动要说“开展”。"}, {"text": "店里的顾客开拓了不少。", "explanation": "这里应该用〈增加〉。开拓的对象是市场、领域或新客户，描述顾客数量变多要说“增加”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，“收割一片新天地”不通。"}, {"text": "开拓", "is_correct": true, "explanation": "“开拓”指开辟新的领域，符合“在音乐方面”的语境。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、院子等场所，不能说“打扫一片新天地”。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”是美化已有的事物，不能表示开创出一片新领域。"}], "explanations": {"收割": "搭配：“收割”的对象是庄稼，“收割一片新天地”不通。", "开拓": "“开拓”指开辟新的领域，符合“在音乐方面”的语境。", "打扫": "搭配：“打扫”的对象是房间、院子等场所，不能说“打扫一片新天地”。", "装饰": "语义：“装饰”是美化已有的事物，不能表示开创出一片新领域。"}, "sentence_index": 6, "correct_answer": "开拓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很快就开拓了这项任务，大家都夸他能干。", "explanation": "这里应该用〈完成〉。开拓用于开辟领域、市场和业务，任务要说“完成”。"}, {"text": "他的论文终于在杂志上开拓了。", "explanation": "这里应该用〈发表〉。开拓指开辟新领域或市场，论文公开刊出要说“发表”。"}, {"text": "他努力开拓了一个好习惯。", "explanation": "这里应该用〈养成〉。开拓用于开辟领域、市场和业务，习惯要说“养成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司开拓了出一条新路。", "corrected_sentence": "公司开拓出了一条新路。", "error_description": "补语“出”须紧跟“开拓”，“了”应放在“出”之后，应说“开拓出了一条新路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们曾经开拓了过这个市场。", "corrected_sentence": "他们曾经开拓过这个市场。", "error_description": "“了”和“过”不能同时使用：表示经历要说“开拓过”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
