INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98148, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不相识的人。", "primary_collocate": null, "pronunciation": "mò shēng rén", "ipa": "mwo˥˩ ʂəŋ˥ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "街上全是陌生人，我一个也不认识。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他帮助了一个陌生人。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "陌生人给我让了座。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个陌生人在车站聊了起来。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他只见过一次，几乎是陌生人。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对我很冷淡，好像我是陌生人。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，我身边都是陌生人。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个陌生人捡到了我的手机。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，邻居们都是陌生人。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们走过时，像陌生人一样没打招呼。", "target_word": "陌生人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "陌生人", "label": "复合"}], "register": "中性", "sense_fingerprint": "彼此不相识的人，如路人、萍水相逢的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404dc866-8b49-473b-ac7d-65c2910bf2a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陌生人", "is_correct": true, "explanation": "正确：指街上互不相识的人，与“我一个也不认识”相符。"}, {"text": "熟人", "is_correct": false, "explanation": "语义：“熟人”是认识的人，与“我一个也不认识”直接矛盾。"}, {"text": "亲戚", "is_correct": false, "explanation": "语义：“亲戚”是有血缘或姻缘关系的人，与“我一个也不认识”矛盾。"}, {"text": "人士", "is_correct": false, "explanation": "搭配：“人士”需带修饰语（如“专业人士”）才能独立指称，“街上全是人士”不成立。"}], "explanations": {"陌生人": "正确：指街上互不相识的人，与“我一个也不认识”相符。", "熟人": "语义：“熟人”是认识的人，与“我一个也不认识”直接矛盾。", "亲戚": "语义：“亲戚”是有血缘或姻缘关系的人，与“我一个也不认识”矛盾。", "人士": "搭配：“人士”需带修饰语（如“专业人士”）才能独立指称，“街上全是人士”不成立。"}, "sentence_index": 0, "correct_answer": "陌生人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市给我一种陌生人的感觉，我很不习惯。", "explanation": "“陌生人”指人，不表示心理感受。表示“不熟悉的感觉”应用〈陌生感〉。"}, {"text": "我的妹妹是个陌生人，每天都和我一起上学。", "explanation": "这里把〈陌生人〉（不认识的人）用于自己的家人。家人应说〈亲人〉，两者意思相反。"}, {"text": "这个地方我很陌生人，从来没来过。", "explanation": "〈陌生人〉是名词，不能作谓语形容地方。这里应该用形容词〈陌生〉：“这个地方我很陌生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陌生人", "is_correct": true, "explanation": "正确：指身边都是互不相识的人，与“在这个城市”的语境相符。"}, {"text": "人员", "is_correct": false, "explanation": "搭配：“人员”需带限定语（如“工作人员”）才能指人，不说“身边都是人员”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是人，与“身边都是……”指人的语境不合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物件，不能用在指人的“身边都是”结构中。"}], "explanations": {"陌生人": "正确：指身边都是互不相识的人，与“在这个城市”的语境相符。", "人员": "搭配：“人员”需带限定语（如“工作人员”）才能指人，不说“身边都是人员”。", "桌子": "语义：“桌子”不是人，与“身边都是……”指人的语境不合。", "窗户": "语义：“窗户”是物件，不能用在指人的“身边都是”结构中。"}, "sentence_index": 6, "correct_answer": "陌生人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫是陌生人，我每天都喂它。", "explanation": "这里把指人的〈陌生人〉用于小猫。小猫是动物，〈陌生人〉只指不认识的人，这个意思不能这样表达。"}, {"text": "这把旧椅子是陌生人，我们一起坐了很多年。", "explanation": "这里把指人的〈陌生人〉用于家具。椅子不是人，〈陌生人〉不能指家具。"}, {"text": "我早就认识他，他是我的老朋友，也是陌生人。", "explanation": "这里应用〈熟人〉。〈陌生人〉指不相识的人，与“认识”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街角站着一条陌生人，他一直看着我。", "corrected_sentence": "街角站着一个陌生人，他一直看着我。", "error_description": "量词错误：“条”用于细长的东西，指人的“陌生人”应用“个”或“位”。正确说法是“一个陌生人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在图书馆门口遇见一陌生人，他借给我一支笔。", "corrected_sentence": "我在图书馆门口遇见一位陌生人，他借给我一支笔。", "error_description": "量词漏掉：“陌生人”前要带量词，应为“一位陌生人”，漏掉“位”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
