INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98151, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "阵营是为了同一个目标站在一起的一群人。", "primary_collocate": null, "pronunciation": "zhèn yíng", "ipa": "ʈʂən˥˩ iŋ˧˥", "syllable_count": 2, "sentences": [{"text": "比赛开始了，两个阵营的球迷都很激动。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里的同学分成了两个阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和他立场不同，不在同一个阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家选一个阵营站好。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里，红色阵营赢了这一局。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换到了朋友的阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个阵营的人都想赢这场比赛。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家站在不同的阵营，吵了起来。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想加入我们的阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这个阵营人多，一定能赢。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "陣營", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比赛、游戏或日常争论中，为同一目标站在一起的一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404dc866-8b49-473b-ac7d-65c2910bf2a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阵营", "is_correct": true, "explanation": "正确：“阵营”指为同一目标站在一起的一群人，与“两个……的球迷”搭配。"}, {"text": "阵地", "is_correct": false, "explanation": "搭配：“阵地”指战场上的防御地点，不指一群支持者，“两个阵地的球迷”不通。"}, {"text": "课堂", "is_correct": false, "explanation": "语义：“课堂”是上课的地方，与比赛和球迷的语境无关。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”是地理图，不能说“两个地图的球迷”。"}], "explanations": {"阵营": "正确：“阵营”指为同一目标站在一起的一群人，与“两个……的球迷”搭配。", "阵地": "搭配：“阵地”指战场上的防御地点，不指一群支持者，“两个阵地的球迷”不通。", "课堂": "语义：“课堂”是上课的地方，与比赛和球迷的语境无关。", "地图": "语义：“地图”是地理图，不能说“两个地图的球迷”。"}, "sentence_index": 0, "correct_answer": "阵营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他刚加入了一张阵营，大家都很欢迎他。", "explanation": "这里应该用〈个〉。“张”用于纸张、桌子等平面的东西，不能数“阵营”。"}, {"text": "我们班的同学都选了一本阵营。", "explanation": "这里应该用〈个〉。“本”用于书册，不能数“阵营”。"}, {"text": "我们班在运动会上有一辆阵营。", "explanation": "这里应该用〈个〉。“辆”用于车辆，不能数“阵营”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阵营", "is_correct": true, "explanation": "正确：“阵营”指为同一目标站在一起的一群人，与“两个……的人都想赢”搭配。"}, {"text": "战场", "is_correct": false, "explanation": "搭配：“战场”是地点，不能指参加比赛的一方人群。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，与“想赢这场比赛”的语境不合。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，不能指参加比赛的人，语境不合。"}], "explanations": {"阵营": "正确：“阵营”指为同一目标站在一起的一群人，与“两个……的人都想赢”搭配。", "战场": "搭配：“战场”是地点，不能指参加比赛的一方人群。", "厨房": "语义：“厨房”是做饭的地方，与“想赢这场比赛”的语境不合。", "课本": "语义：“课本”是书，不能指参加比赛的人，语境不合。"}, "sentence_index": 6, "correct_answer": "阵营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中加入了一颗阵营，很快就输了。", "explanation": "这里应该用〈个〉。“颗”用于颗粒状或小圆的东西，不能数“阵营”。"}, {"text": "我们这扇阵营的目标是保护环境。", "explanation": "这里应该用〈个〉。“扇”用于门窗，不能数“阵营”。"}, {"text": "我们这只阵营人多，一定能赢。", "explanation": "这里应该用〈个〉。“只”多用于动物，不能数“阵营”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他选择了一条阵营，并且坚持到底。", "corrected_sentence": "他选择了一个阵营，并且坚持到底。", "error_description": "量词错误：“阵营”的量词应为“个”，“条”用于细长的东西，不能数“阵营”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个阵营们的人都在拼命呐喊。", "corrected_sentence": "两个阵营的人都在拼命呐喊。", "error_description": "“阵营”指一个集团，不能加“们”，应说“两个阵营的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
