INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "目标、立场相同的人结成的集团。", "primary_collocate": null, "pronunciation": "zhèn yíng", "ipa": "ʈʂən˥˩ iŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这两个国家属于不同的阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷战时，世界分成了两大阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们立场一样，属于同一个阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家不想加入任何阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个阵营的意见完全不同。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举时，他站在了对方的阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里分成了支持和反对两个阵营。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开了原来的阵营，去支持别人。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个阵营的人在会上吵了起来。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这个阵营的目标是保护环境。", "target_word": "阵营", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "陣營", "label": "繁体"}], "register": "中性", "sense_fingerprint": "政治、国家或团体中立场相同而结成的集团", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '404dc866-8b49-473b-ac7d-65c2910bf2a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阵营", "is_correct": true, "explanation": "正确：“阵营”指立场相同的人结成的集团，与“属于不同的”搭配。"}, {"text": "城市", "is_correct": false, "explanation": "语义：“城市”是人口聚居的地方，国家不属于城市，与语境不合。"}, {"text": "语言", "is_correct": false, "explanation": "语义：“语言”不是国家所属的组织，“属于不同的语言”说不通。"}, {"text": "方式", "is_correct": false, "explanation": "语义：“属于”后接团体或类别，“方式”只是做事的办法，“这两个国家属于不同的方式”语义说不通。"}], "explanations": {"阵营": "正确：“阵营”指立场相同的人结成的集团，与“属于不同的”搭配。", "城市": "语义：“城市”是人口聚居的地方，国家不属于城市，与语境不合。", "语言": "语义：“语言”不是国家所属的组织，“属于不同的语言”说不通。", "方式": "语义：“属于”后接团体或类别，“方式”只是做事的办法，“这两个国家属于不同的方式”语义说不通。"}, "sentence_index": 0, "correct_answer": "阵营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们国家在外交上选择了一条阵营。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，不能数“阵营”。"}, {"text": "这个国家在外交上有一首阵营。", "explanation": "这里应该用〈个〉。“首”用于诗歌、歌曲，不能数“阵营”。"}, {"text": "这个国家在选举中有一把阵营。", "explanation": "这里应该用〈个〉。“把”用于有柄的器具，不能数“阵营”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阵营", "is_correct": true, "explanation": "正确：“阵营”指立场相同的人结成的集团，与“分成了支持和反对两个”搭配。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是薪水，不能分成支持和反对两方，与语境不合。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“分成……两个”后接的是群体或阵营，“考试”不能这样分。"}, {"text": "课程", "is_correct": false, "explanation": "语义：“课程”是教学内容，与“支持和反对”的分裂无关。"}], "explanations": {"阵营": "正确：“阵营”指立场相同的人结成的集团，与“分成了支持和反对两个”搭配。", "工资": "语义：“工资”是薪水，不能分成支持和反对两方，与语境不合。", "考试": "搭配：“分成……两个”后接的是群体或阵营，“考试”不能这样分。", "课程": "语义：“课程”是教学内容，与“支持和反对”的分裂无关。"}, "sentence_index": 6, "correct_answer": "阵营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们这枚阵营的目标是保护环境。", "explanation": "这里应该用〈个〉。“枚”用于硬币、奖章等小件物品，不能数“阵营”。"}, {"text": "这个国家在谈判中组成了一件阵营。", "explanation": "这里应该用〈个〉。“件”用于物品、事情，不能数“阵营”。"}, {"text": "我们这幅阵营的目标是保护环境。", "explanation": "这里应该用〈个〉。“幅”用于画作、布匹等，不能数“阵营”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个国家结成了同一张阵营。", "corrected_sentence": "这两个国家结成了同一个阵营。", "error_description": "量词错误：“阵营”应用“个”，“张”用于纸张、桌子等平面的东西，不能数“阵营”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次谈判后，各国重新组成了新的阵营们。", "corrected_sentence": "这次谈判后，各国重新组成了新的阵营。", "error_description": "“阵营”是集合性的名词，不能加“们”，应说“新的阵营”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e94c3-6baa-470a-9fc9-937b9ecdc75c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
