INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98155, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "震撼是让人心里一下子受到很大的触动。", "primary_collocate": null, "pronunciation": "zhèn hàn", "ipa": "tʂən˥˩ xan˥˩", "syllable_count": 2, "sentences": [{"text": "站在大瀑布前，我感到非常震撼。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息太让人震撼了。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的表演让现场观众很震撼。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次看到大海，我心里很震撼。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个画面真的令人震撼。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完她的经历，大家都很震撼。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火箭起飞的声音太震撼了。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的经历太震撼了，我一直没缓过神来。", "target_word": "震撼", "complexity_tier": "T3", "furigana": "tā jiǎng de jīnglì tài zhènhàn le, wǒ yìzhí méi huǎnguò shén lái.", "sentence_source": "generated"}, {"text": "这场雪景让我震撼得说不出话。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶的日出美得让人震撼。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "震撼了", "label": "完成体"}, {"form": "震撼着", "label": "持续体"}, {"form": "震撼过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "人心里一下子受到很大触动，常说感到震撼、令人震撼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b192761-8a5e-44d0-af8b-6677718ed4de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98155, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "震撼", "is_correct": true, "explanation": "正确：震撼表示大瀑布带来的强烈触动，与“站在大瀑布前”的情境一致。"}, {"text": "厨房", "is_correct": false, "explanation": "词性：“厨房”是名词，不能放在“感到非常”后面表示感受。"}, {"text": "铅笔", "is_correct": false, "explanation": "词性：“铅笔”是名词，不能说“感到非常铅笔”。"}, {"text": "星期", "is_correct": false, "explanation": "词性：“星期”是时间名词，不能表示人的感受。"}], "explanations": {"震撼": "正确：震撼表示大瀑布带来的强烈触动，与“站在大瀑布前”的情境一致。", "厨房": "词性：“厨房”是名词，不能放在“感到非常”后面表示感受。", "铅笔": "词性：“铅笔”是名词，不能说“感到非常铅笔”。", "星期": "词性：“星期”是时间名词，不能表示人的感受。"}, "sentence_index": 0, "correct_answer": "震撼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "洗完澡，他很震撼。", "explanation": "这里应该用〈舒服〉。舒服指身体或心情的舒适感，震撼指强烈的心灵冲击，洗完澡后用震撼不通。"}, {"text": "走了一整天，我很震撼。", "explanation": "这里应该用〈疲惫〉。疲惫指身体劳累，震撼指心灵上的强烈触动，身体累不能用震撼。"}, {"text": "喝了一杯水，我很震撼。", "explanation": "这里应该用〈解渴〉。解渴指水消除口渴，震撼指强烈的心灵冲击，喝水这样的小事不能用震撼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98155, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "震撼", "is_correct": true, "explanation": "正确：震撼形容火箭声音带来的强烈冲击，与“太……了”搭配。"}, {"text": "感动", "is_correct": false, "explanation": "语义：“感动”的主语应是人，声音不会被感动。"}, {"text": "感慨", "is_correct": false, "explanation": "搭配：“感慨”是人的主观感叹，不能说“声音太感慨了”。"}, {"text": "伤心", "is_correct": false, "explanation": "语义：声音不会伤心，与火箭起飞的场景不符。"}], "explanations": {"震撼": "正确：震撼形容火箭声音带来的强烈冲击，与“太……了”搭配。", "感动": "语义：“感动”的主语应是人，声音不会被感动。", "感慨": "搭配：“感慨”是人的主观感叹，不能说“声音太感慨了”。", "伤心": "语义：声音不会伤心，与火箭起飞的场景不符。"}, "sentence_index": 6, "correct_answer": "震撼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在山顶震撼日出。", "explanation": "这里应该用〈欣赏〉。欣赏指喜爱地观看，震撼是事物对人的强烈冲击，不能作用于人去观看日出。"}, {"text": "吃完饭，我很震撼。", "explanation": "这里应该用〈满足〉。满足指吃饱后的满意感，震撼是强烈的心灵冲击，饭后用它完全不合适。"}, {"text": "想到明天要考试，心里很震撼。", "explanation": "这里应该用〈忧虑〉。忧虑指对考试的担心，震撼指强烈的心灵冲击，因考试的焦虑不能用震撼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的话让我震撼说不出话。", "corrected_sentence": "他的话让我震撼得说不出话。", "error_description": "错误：补语标记漏掉。表示结果的补语“说不出话”前须用“得”引出，“震撼”后不能直接接它。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场雪景曾经让我震撼了过。", "corrected_sentence": "那场雪景曾经让我震撼过。", "error_description": "错误：“了”与“过”同用。“震撼过”表示曾经经历，不能再加“了”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
