INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98156, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "强烈地触动人心。", "primary_collocate": null, "pronunciation": "zhèn hàn", "ipa": "tʂən˥˩ xan˥˩", "syllable_count": 2, "sentences": [{"text": "那部电影的结局震撼了所有人。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的大浪声震撼着我的心。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的故事深深震撼了我们。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么高的瀑布震撼了第一次来的游客。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲的真实事件震撼了全班同学。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的勇敢行为震撼了整个城市。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没见过这样震撼人心的画面。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场大火的照片震撼了每一个人。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长城的壮观景色震撼过很多外国游客。", "target_word": "震撼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场演出的歌声震撼了全场观众。", "target_word": "震撼", "complexity_tier": "T3", "furigana": "zhè chǎng yǎnchū de gēshēng zhènhàn le quánchǎng guānzhòng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "震撼了", "label": "完成体"}, {"form": "震撼着", "label": "持续体"}, {"form": "震撼过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "强烈冲击并触动人心，宾语多为人或人心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b192761-8a5e-44d0-af8b-6677718ed4de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "震撼", "is_correct": true, "explanation": "正确：震撼表示强烈触动人心，句中“那部电影的结局”触动了“所有人”，语义吻合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，结局不能吃人，“结局吃了所有人”不通。"}, {"text": "陪", "is_correct": false, "explanation": "配价：“陪”要求施事是能陪伴的人，电影结局不能陪伴所有人。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”针对食物或液体，不能用于结局对人的作用。"}], "explanations": {"震撼": "正确：震撼表示强烈触动人心，句中“那部电影的结局”触动了“所有人”，语义吻合。", "吃": "语义：“吃”的对象是食物，结局不能吃人，“结局吃了所有人”不通。", "陪": "配价：“陪”要求施事是能陪伴的人，电影结局不能陪伴所有人。", "煮": "语义：“煮”针对食物或液体，不能用于结局对人的作用。"}, "sentence_index": 0, "correct_answer": "震撼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很震撼明天会下雨。", "explanation": "这里应该用〈担心〉。担心指对事情的忧虑，震撼指强烈的心灵冲击，对天气的担忧不能用震撼。"}, {"text": "我每天早上震撼一杯牛奶。", "explanation": "这里应该用〈喝〉。喝的对象是饮料，震撼指强烈触动人心，不能用于喝牛奶。"}, {"text": "这个苹果很震撼。", "explanation": "这里应该用〈好吃〉。好吃指味道好，震撼指强烈的心灵冲击，形容苹果的味道不能用震撼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "震撼", "is_correct": true, "explanation": "正确：震撼修饰“人心”，表示画面强烈触动人心，与“这样”的程度相合。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”的对象是食物，不能烤人心。"}, {"text": "晒", "is_correct": false, "explanation": "语义：“晒”是把东西放在阳光下，不用于人心。"}, {"text": "捏", "is_correct": false, "explanation": "语义：“捏”是用手按压物体，不能用于人心。"}], "explanations": {"震撼": "正确：震撼修饰“人心”，表示画面强烈触动人心，与“这样”的程度相合。", "烤": "语义：“烤”的对象是食物，不能烤人心。", "晒": "语义：“晒”是把东西放在阳光下，不用于人心。", "捏": "语义：“捏”是用手按压物体，不能用于人心。"}, "sentence_index": 6, "correct_answer": "震撼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家都震撼他的勇气。", "explanation": "这里应该用〈佩服〉。佩服是人对事物的欣赏，震撼的主语须是事物或事件，不能由人去震撼勇气。"}, {"text": "他常常震撼童年的时光。", "explanation": "这里应该用〈怀念〉。怀念是对往事的回想，震撼是事物对人的强烈冲击，时光不能被震撼。"}, {"text": "我很震撼下雨天。", "explanation": "这里应该用〈讨厌〉。讨厌指反感，震撼指强烈的心灵冲击，对下雨天表示厌恶不能用震撼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这首歌震撼了过很多听众。", "corrected_sentence": "这首歌震撼了很多听众。", "error_description": "错误：“了”与“过”同用，经历体“过”与完成体“了”不能同时出现，应只保留“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场演出很震撼了我们。", "corrected_sentence": "那场演出震撼了我们。", "error_description": "错误：“震撼”在这里是带宾语“我们”的动词，后面还有“了”，前面不能加程度副词“很”，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
