INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98159, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "音乐会是很多人坐着听别人唱歌或弹琴的活动。", "primary_collocate": null, "pronunciation": "yīn yuè huì", "ipa": "in˥ ɥe˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "今晚我们去听音乐会。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会上有人在弹钢琴。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会开始前，大家都坐好了。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了两张音乐会的票。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次去音乐会，很兴奋。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场音乐会的歌都很好听。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会在晚上七点开始。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们一家人去听了一场音乐会。", "target_word": "音乐会", "complexity_tier": "T3", "furigana": "zhōu mò wǒ men yì jiā rén qù tīng le yì chǎng yīnyuèhuì.", "sentence_source": "generated"}, {"text": "他喜欢和朋友一起听音乐会。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会结束了，大家都鼓掌。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场音乐会", "label": "量词"}, {"form": "音樂會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大家坐着听唱歌弹琴的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '244a8996-a574-446d-85a5-426380410052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98159, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐会", "is_correct": true, "explanation": "正确：音乐会是很多人坐着听演出的活动，可以说“去听音乐会”。"}, {"text": "公园", "is_correct": false, "explanation": "语义：“听”要接声音或演出，公园是地点，不能被听。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：电影一般说“看电影”，不说“听电影”。"}, {"text": "动物园", "is_correct": false, "explanation": "语义：动物园是去看动物的地方，不是可以去听的活动。"}], "explanations": {"音乐会": "正确：音乐会是很多人坐着听演出的活动，可以说“去听音乐会”。", "公园": "语义：“听”要接声音或演出，公园是地点，不能被听。", "电影": "搭配：电影一般说“看电影”，不说“听电影”。", "动物园": "语义：动物园是去看动物的地方，不是可以去听的活动。"}, "sentence_index": 0, "correct_answer": "音乐会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场音乐会进了三个球。", "explanation": "这里应该用〈比赛〉。音乐会是演出活动，不能进球；进球的是比赛中的球员或球队。"}, {"text": "这个音乐会每天早上都开会排练。", "explanation": "这里应该用〈乐团〉。音乐会是一次演出，不会开会排练；会排练的是乐团。"}, {"text": "他是很有名的音乐会。", "explanation": "这里应该用〈音乐家〉。音乐会指演出活动，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐会", "is_correct": true, "explanation": "正确：音乐会有固定的开始时间，可以说“音乐会在晚上七点开始”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是能“开始”的活动。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不是能“开始”的活动或事件。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是地点，不是能开始的事件。"}], "explanations": {"音乐会": "正确：音乐会有固定的开始时间，可以说“音乐会在晚上七点开始”。", "冰箱": "语义：冰箱是家用电器，不是能“开始”的活动。", "椅子": "语义：椅子是家具，不是能“开始”的活动或事件。", "图书馆": "语义：图书馆是地点，不是能开始的事件。"}, "sentence_index": 6, "correct_answer": "音乐会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把音乐会放进了书包里。", "explanation": "音乐会是演出活动，不是物品，不能放进书包；这里应指票或节目单等实物。"}, {"text": "这场音乐会展出了很多古代文物。", "explanation": "这里应该用〈博物馆〉。音乐会是演出，不展出文物；展出文物要说博物馆。"}, {"text": "我们午饭吃了音乐会。", "explanation": "这里应该用〈饭〉或〈面条〉。音乐会是演出活动，不是食物，不能拿来吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们昨天参加了一部音乐会。", "corrected_sentence": "我们昨天参加了一场音乐会。", "error_description": "量词错误：“音乐会”应用量词“场”，“部”通常用于电影、书等，应说“一场音乐会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天去听了一把音乐会。", "corrected_sentence": "我们昨天去听了一场音乐会。", "error_description": "量词错误：“音乐会”应用量词“场”，“把”多用于有柄的器具、椅子等，不能用于演出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
