INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "由乐队或歌手现场演奏、演唱供观众欣赏的演出。", "primary_collocate": null, "pronunciation": "yīn yuè huì", "ipa": "in˥ ɥe˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "这支乐队下个月开音乐会。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的音乐会门票很快卖完了。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手在音乐会上唱了新歌。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐队在体育馆办了一场音乐会。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听现场音乐会比听录音更有感觉。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在网上看了那场音乐会。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的音乐会每年夏天举行。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众在音乐会上跟着歌手一起唱。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会的灯光和音响都很好。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出那天，音乐会现场坐满了观众。", "target_word": "音乐会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场音乐会", "label": "量词"}, {"form": "音樂會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "乐队或歌手面向观众的现场演出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '244a8996-a574-446d-85a5-426380410052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98160, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "音乐会", "is_correct": true, "explanation": "正确：乐队为观众表演的活动可以说“开音乐会”。"}, {"text": "灯", "is_correct": false, "explanation": "语义：“开灯”是操作电器，不能表示乐队举办演出。"}, {"text": "花", "is_correct": false, "explanation": "搭配：“开花”是植物的变化，不能用“开”接“花”来指乐队的活动。"}, {"text": "窗", "is_correct": false, "explanation": "语义：“开窗”指打开窗户，不是演出活动。"}], "explanations": {"音乐会": "正确：乐队为观众表演的活动可以说“开音乐会”。", "灯": "语义：“开灯”是操作电器，不能表示乐队举办演出。", "花": "搭配：“开花”是植物的变化，不能用“开”接“花”来指乐队的活动。", "窗": "语义：“开窗”指打开窗户，不是演出活动。"}, "sentence_index": 0, "correct_answer": "音乐会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们昨天在体育馆的音乐会踢了一场足球。", "explanation": "这里应该用〈球队〉。音乐会是演出，不会踢球；踢足球的是球队。"}, {"text": "这次音乐会展出了很多油画。", "explanation": "这里应该用〈画展〉。音乐会是演出，不展出油画；展出作品要说画展。"}, {"text": "他是一场很有名的音乐会。", "explanation": "这里应该用〈乐手〉或〈歌手〉。音乐会是演出活动，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "音乐会", "is_correct": true, "explanation": "正确：音乐会是有固定时间的演出活动，可以说“每年夏天举行”。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是能举行的活动。"}, {"text": "菜", "is_correct": false, "explanation": "搭配：“举行”接活动或仪式，不接“菜”。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不能被举行。"}], "explanations": {"音乐会": "正确：音乐会是有固定时间的演出活动，可以说“每年夏天举行”。", "冰箱": "语义：冰箱是家用电器，不是能举行的活动。", "菜": "搭配：“举行”接活动或仪式，不接“菜”。", "雨": "语义：雨是天气现象，不能被举行。"}, "sentence_index": 6, "correct_answer": "音乐会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把音乐会挂在墙上当装饰。", "explanation": "音乐会是演出活动，不是可以挂在墙上的物品；这里应指画或装饰品。"}, {"text": "这家音乐会每天生产一千个零件。", "explanation": "这里应该用〈工厂〉。音乐会是一次演出，不生产零件；生产零件要说工厂。"}, {"text": "我们每天坐音乐会去上学。", "explanation": "这里应该用〈公交车〉。音乐会是演出活动，不是交通工具，不能坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校每年都会举办一只音乐会。", "corrected_sentence": "我们学校每年都会举办一场音乐会。", "error_description": "量词错误：“音乐会”应用量词“场”，不能用“只”（“只”多用于动物或成对、单个的物品）。应说“举办一场音乐会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天听了一本音乐会。", "corrected_sentence": "我们昨天听了一场音乐会。", "error_description": "量词错误：“音乐会”应用量词“场”，“本”多用于书籍、本子等，不能用于演出。应说“听了一场音乐会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
