INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "领导者是带着大家一起往前走、做决定的人。", "primary_collocate": null, "pronunciation": "lǐng dǎo zhě", "ipa": "liŋ˨˩˦ taʊ˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "领导者要为大家做决定。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是个带着大家往前走的领导者。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到困难时，领导者不能先放弃。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的领导者不会只想自己。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们团队的领导者今天做了决定。", "target_word": "领导者", "complexity_tier": "T3", "furigana": "wǒ men tuán duì de lǐng dǎo zhě jīn tiān zuò le jué dìng.", "sentence_source": "generated"}, {"text": "球队需要一个能做决定的领导者。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不是老板，却是大家心中的领导者。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导者先走，大家就跟着走。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想做一个有爱心的领导者。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导者做错了决定，要自己负责。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位领导者", "label": "量词"}, {"form": "領導者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "带大家前进并做决定的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '244a8996-a574-446d-85a5-426380410052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领导者", "is_correct": true, "explanation": "正确：领导者负责带领大家并做决定，“领导者要为大家做决定”符合语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能为大家做决定。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，不能替大家做决定。"}, {"text": "台灯", "is_correct": false, "explanation": "配价：“做决定”要求有意识的主语，台灯不能满足。"}], "explanations": {"领导者": "正确：领导者负责带领大家并做决定，“领导者要为大家做决定”符合语境。", "天气": "语义：天气是自然现象，不能为大家做决定。", "课本": "语义：课本是学习用的书，不能替大家做决定。", "台灯": "配价：“做决定”要求有意识的主语，台灯不能满足。"}, "sentence_index": 0, "correct_answer": "领导者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的右手是我们班的领导者。", "explanation": "这里应该用〈班长〉。领导者指人，手不能带领班级。"}, {"text": "这把椅子是我们的领导者，大家都听它的。", "explanation": "这里应该用〈组长〉。领导者指带领群体的人，椅子不能带领大家。"}, {"text": "这次考试是我们班的领导者。", "explanation": "这里应该用〈班长〉。领导者指人，考试不能带领班级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领导者", "is_correct": true, "explanation": "正确：他虽不是老板，却是大家心中的带领者，“领导者”符合语境。"}, {"text": "老板", "is_correct": false, "explanation": "语义：前一分句已说“不是老板”，这里不能再用“老板”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“心中的”后接人或抽象事物，不接“冰箱”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不能成为大家心中的人物。"}], "explanations": {"领导者": "正确：他虽不是老板，却是大家心中的带领者，“领导者”符合语境。", "老板": "语义：前一分句已说“不是老板”，这里不能再用“老板”。", "冰箱": "搭配：“心中的”后接人或抽象事物，不接“冰箱”。", "手机": "语义：手机是通讯工具，不能成为大家心中的人物。"}, "sentence_index": 6, "correct_answer": "领导者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "晚上七点是我们组的领导者，大家都听它的。", "explanation": "这里应该用〈组长〉。领导者指人，时间不能带领群体。"}, {"text": "比赛时，领导者负责吹哨子判罚。", "explanation": "这里应该用〈裁判〉。领导者负责带领群体，不负责吹哨判罚；判罚是裁判的工作。"}, {"text": "这盏台灯是我们组的领导者，负责分配任务。", "explanation": "这里应该用〈组长〉。领导者指人，台灯不能带领群体，也不能分配任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只有经验的领导者。", "corrected_sentence": "她是一个有经验的领导者。", "error_description": "量词错误：指人的“领导者”应用“个”或“位”，不能用“只”（“只”多用于动物或单个物品）。应说“一个有经验的领导者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一位很好地领导者。", "corrected_sentence": "他是一位很好的领导者。", "error_description": "结构助词错误：修饰名词应用“的”，不能用“地”，应说“很好的领导者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
