INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "带领和指挥群体的人。", "primary_collocate": null, "pronunciation": "lǐng dǎo zhě", "ipa": "liŋ˨˩˦ taʊ˨˩˦ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是这个小组的领导者。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的领导者会听大家的话。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要一位有经验的领导者。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支队伍的领导者很年轻。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导者要带着大家完成工作。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她成了我们班的领导者。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个领导者要有好的想法。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导者指挥大家把箱子搬走。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的领导者是王老师。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都相信这位领导者。", "target_word": "领导者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位领导者", "label": "量词"}, {"form": "領導者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "带领并指挥群体的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '244a8996-a574-446d-85a5-426380410052') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领导者", "is_correct": true, "explanation": "正确：领导者指带领小组的人，“他是这个小组的领导者”符合语境。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是地点，不是能带领小组的人。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能带领小组。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“是……的”后接人物时，“咖啡”不能指小组里的人。"}], "explanations": {"领导者": "正确：领导者指带领小组的人，“他是这个小组的领导者”符合语境。", "教室": "语义：教室是地点，不是能带领小组的人。", "作业": "语义：作业是学习任务，不能带领小组。", "咖啡": "搭配：“是……的”后接人物时，“咖啡”不能指小组里的人。"}, "sentence_index": 0, "correct_answer": "领导者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我生病了，领导者给我开了药。", "explanation": "这里应该用〈医生〉。领导者是带领群体的人，给病人开药是医生的工作。"}, {"text": "这本书的领导者是鲁迅。", "explanation": "这里应该用〈作者〉。写书的人叫作者，领导者是带领群体的人。"}, {"text": "商店的领导者把水果卖给了我。", "explanation": "这里应该用〈售货员〉。在商店卖东西给顾客的人是售货员，不是带领群体的领导者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领导者", "is_correct": true, "explanation": "正确：领导者要有好的想法，指带领大家的人，符合语境。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不是能有想法的人。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能有好的想法。"}, {"text": "树", "is_correct": false, "explanation": "配价：“要有好的想法”要求有意识的主语，树不能满足。"}], "explanations": {"领导者": "正确：领导者要有好的想法，指带领大家的人，符合语境。", "手机": "语义：手机是通讯工具，不是能有想法的人。", "桌子": "语义：桌子是家具，不能有好的想法。", "树": "配价：“要有好的想法”要求有意识的主语，树不能满足。"}, "sentence_index": 6, "correct_answer": "领导者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛时，领导者负责吹哨子判罚。", "explanation": "这里应该用〈裁判〉。领导者负责带领群体，不负责吹哨判罚；判罚是裁判的工作。"}, {"text": "上课时，领导者在黑板上写字，教我们数学。", "explanation": "这里应该用〈老师〉。在课堂上教学生的人是老师，领导者是带领群体的人。"}, {"text": "这首歌的领导者唱得很好听。", "explanation": "这里应该用〈歌手〉。唱歌的人是歌手，领导者是带领群体的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是我们班的一只领导者。", "corrected_sentence": "她是我们班的一位领导者。", "error_description": "量词错误：指人的“领导者”应用量词“位”，“只”用于动物等，应说“一位领导者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司有三个领导者们。", "corrected_sentence": "我们公司有三个领导者。", "error_description": "错误：“三个领导者”前已有数量词，后面不能再加“们”。正确：去掉“们”，说“三个领导者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac620260-7a47-4041-a838-56c62ed397a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
