INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98167, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "餐馆是人们去吃饭的地方，付钱就有人把饭菜送来。", "primary_collocate": null, "pronunciation": "cān guǎn", "ipa": "tsʰan˥ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们在一家小餐馆吃了午饭。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐馆的鱼很好吃。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常和朋友去餐馆吃饭。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边新开了一家餐馆。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "餐馆里的服务员给我们送来了菜单。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在餐馆点了两个菜和一碗汤。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐馆晚上人很多，要早点去。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在餐馆吃完饭，付了钱就回家了。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个餐馆离我家很近，走路五分钟。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在餐馆做服务员。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "中餐馆", "label": "复合词"}, {"form": "餐館", "label": "繁体"}], "register": "通用", "sense_fingerprint": "人们付钱吃饭的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c715073-07d3-4bb9-b479-83cb8d740dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐馆", "is_correct": true, "explanation": "正确。“吃了午饭”说明这是供顾客吃饭的场所，量词“家”也适用于餐馆。"}, {"text": "药店", "is_correct": false, "explanation": "语义：药店卖的是药品，不供应饭菜，不能在那里吃午饭。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行不供应饭菜，“在一家小银行吃了午饭”不通。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：量词“家”不能用于面包，且面包不是吃饭的地方。"}], "explanations": {"餐馆": "正确。“吃了午饭”说明这是供顾客吃饭的场所，量词“家”也适用于餐馆。", "药店": "语义：药店卖的是药品，不供应饭菜，不能在那里吃午饭。", "银行": "语义：银行不供应饭菜，“在一家小银行吃了午饭”不通。", "面包": "搭配：量词“家”不能用于面包，且面包不是吃饭的地方。"}, "sentence_index": 0, "correct_answer": "餐馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我发烧了，妈妈带我去餐馆看医生。", "explanation": "这里应该用〈医院〉。餐馆是吃饭的地方，看病要去医院。"}, {"text": "学校旁边新开了一张餐馆。", "explanation": "这里应该用〈家〉。餐馆用“家”计量，“张”用于桌子、纸张等扁平的东西。"}, {"text": "我们住在一家餐馆里，房间很干净。", "explanation": "这里应该用〈旅馆〉。餐馆是吃饭的地方，住宿要用旅馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐馆", "is_correct": true, "explanation": "正确。“这家……晚上人很多，要早点去”描述的是可以去的营业场所。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以去的营业场所，句子不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：量词“家”不用于蛋糕，蛋糕也不能说“人很多”。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是可以去的地方，“晚上人很多要早点去”不通。"}], "explanations": {"餐馆": "正确。“这家……晚上人很多，要早点去”描述的是可以去的营业场所。", "天空": "语义：天空不是可以去的营业场所，句子不通。", "蛋糕": "搭配：量词“家”不用于蛋糕，蛋糕也不能说“人很多”。", "月亮": "语义：月亮不是可以去的地方，“晚上人很多要早点去”不通。"}, "sentence_index": 6, "correct_answer": "餐馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我去餐馆买衣服，老板很热情。", "explanation": "这里应该用〈商店〉。餐馆是吃饭的地方，买衣服要去〈商店〉。"}, {"text": "妈妈在街上开了一台餐馆，生意很好。", "explanation": "这里应该用〈家〉。餐馆用“家”计量，“台”用于机器、电器。"}, {"text": "我出差时住在餐馆里，房间很安静。", "explanation": "这里应该用〈宾馆〉。餐馆是吃饭的场所，不能住宿；住宿要用宾馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐下班后带我去了一只餐馆。", "corrected_sentence": "姐姐下班后带我去了一家餐馆。", "error_description": "“餐馆”的量词应为“家”。“只”用于小动物或成对物品中的一个，写成“一只餐馆”是错误的，正确形式是“一家餐馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下班以后，我常去很餐馆吃晚饭。", "corrected_sentence": "下班以后，我常去餐馆吃晚饭。", "error_description": "“餐馆”是名词，前面不能加副词“很”修饰。写成“去很餐馆”是错误的，应删去“很”，正确形式是“去餐馆吃晚饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
