INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98168, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供顾客用餐的营业场所。", "primary_collocate": null, "pronunciation": "cān guǎn", "ipa": "tsʰan˥ kwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "他开了一家四川餐馆。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上有很多餐馆。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐馆下午两点关门。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "餐馆门口坐着一只小猫。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在餐馆里订一张桌子。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把朋友带到了一家有名的餐馆。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐馆的老板是我同学。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家餐馆的环境又干净又安静。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的餐馆明天开始营业。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们过年的时候去餐馆吃过饭。", "target_word": "餐馆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "中餐馆", "label": "复合词"}, {"form": "餐館", "label": "繁体"}], "register": "通用", "sense_fingerprint": "对顾客营业的用餐场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c715073-07d3-4bb9-b479-83cb8d740dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "餐馆", "is_correct": true, "explanation": "正确。“开了一家四川……”指开的是供顾客用餐的店，“四川”修饰菜系。"}, {"text": "银行", "is_correct": false, "explanation": "语义：“四川”修饰的是菜系，银行不是菜系，句子不通。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：量词“家”不能用于面包，“四川面包”也不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“开”的是店，不能开饭菜。"}], "explanations": {"餐馆": "正确。“开了一家四川……”指开的是供顾客用餐的店，“四川”修饰菜系。", "银行": "语义：“四川”修饰的是菜系，银行不是菜系，句子不通。", "面包": "搭配：量词“家”不能用于面包，“四川面包”也不通。", "饭菜": "搭配：“开”的是店，不能开饭菜。"}, "sentence_index": 0, "correct_answer": "餐馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天去餐馆买了一件大衣，店员很热情。", "explanation": "这里应该用〈商店〉。餐馆是吃饭的地方，买大衣要去〈商店〉。"}, {"text": "我们学校门口新开了一只餐馆。", "explanation": "这里应该用〈家〉。餐馆用“家”计量，“只”用于小动物或成对物品中的一个。"}, {"text": "我们在餐馆住了三天，房间很干净。", "explanation": "这里应该用〈宾馆〉。餐馆是吃饭的场所，不能住宿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "餐馆", "is_correct": true, "explanation": "正确。“这家……的老板”指经营餐饮的店铺，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不是营业场所，不能说“这家桌子的老板”。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用品，不是营业场所，不能说“这家雨伞的老板”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不是营业场所，不能说“这家钥匙的老板”。"}], "explanations": {"餐馆": "正确。“这家……的老板”指经营餐饮的店铺，符合句意。", "桌子": "语义：桌子是家具，不是营业场所，不能说“这家桌子的老板”。", "雨伞": "语义：雨伞是遮雨的用品，不是营业场所，不能说“这家雨伞的老板”。", "钥匙": "语义：钥匙是开锁的工具，不是营业场所，不能说“这家钥匙的老板”。"}, "sentence_index": 6, "correct_answer": "餐馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想借几本书，就去了附近的餐馆。", "explanation": "这里应该用〈图书馆〉。餐馆是吃饭的地方，借书要去图书馆。"}, {"text": "妈妈在街上开了一张餐馆，生意很好。", "explanation": "这里应该用〈家〉。餐馆用“家”计量，“张”用于桌子、纸张等扁平的东西。"}, {"text": "出差的时候，我住在餐馆里，很安静。", "explanation": "这里应该用〈旅馆〉。餐馆是吃饭的场所，不能住宿；住宿要用旅馆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表哥在市中心租了一台餐馆。", "corrected_sentence": "表哥在市中心租了一家餐馆。", "error_description": "“餐馆”的量词应为“家”。“台”用于机器、电器，写成“一台餐馆”是错误的，正确形式是“一家餐馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们曾去过那家很餐馆，菜很好吃。", "corrected_sentence": "我们曾去过那家餐馆，菜很好吃。", "error_description": "“餐馆”是名词，前面不能加副词“很”修饰。写成“那家很餐馆”是错误的，应删去“很”，正确形式是“那家餐馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
