INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "三份；也指十分之三，或某种程度上的少量。", "primary_collocate": null, "pronunciation": "sān fēn", "ipa": "san˥˥ fən˥˥", "syllable_count": 2, "sentences": [{"text": "他脸上带着三分笑意。", "target_word": "三分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个办法，我只有三分把握。", "target_word": "三分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "七分靠努力，三分靠运气。", "target_word": "三分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说话要留三分余地。", "target_word": "三分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喝了酒，有三分醉意。", "target_word": "三分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长得有三分像爸爸。", "target_word": "三分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话，我只听懂了三分。", "target_word": "三分", "complexity_tier": "T3", "furigana": "tā shuō de huà, wǒ zhǐ tīngdǒng le sān fēn.", "sentence_source": "generated"}, {"text": "她说话时带着三分害羞。", "target_word": "三分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事三分真，七分假。", "target_word": "三分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话里有三分玩笑。", "target_word": "三分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "十分之三，引申为一定程度上的少量，常与七分对举", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b192761-8a5e-44d0-af8b-6677718ed4de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98172, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三分", "is_correct": true, "explanation": "正确：三分表示笑意的少量程度，与“带着……笑意”搭配。"}, {"text": "三斤", "is_correct": false, "explanation": "语义：笑意是程度，不以斤计量。"}, {"text": "三本", "is_correct": false, "explanation": "搭配：“三本”只用于书，不能形容笑意。"}, {"text": "三天", "is_correct": false, "explanation": "语义：笑意是程度，不是时间。"}], "explanations": {"三分": "正确：三分表示笑意的少量程度，与“带着……笑意”搭配。", "三斤": "语义：笑意是程度，不以斤计量。", "三本": "搭配：“三本”只用于书，不能形容笑意。", "三天": "语义：笑意是程度，不是时间。"}, "sentence_index": 0, "correct_answer": "三分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天只睡三分。", "explanation": "这里应该用〈三个小时〉。“三分”不表示睡眠时长，说时长要用“个小时”。"}, {"text": "这个房间的门是三分。", "explanation": "这里应该用〈一扇〉。“三分”表示份额，不能用来数门，应说“一扇门”。"}, {"text": "我们班的人数是三分。", "explanation": "这里应该用〈三十〉。“三分”表示份额，不能用来计数人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三分", "is_correct": true, "explanation": "正确：三分表示听懂的部分，是少量程度，与“只听懂了”搭配。"}, {"text": "三升", "is_correct": false, "explanation": "语义：听懂的程度不以升计。"}, {"text": "三张", "is_correct": false, "explanation": "搭配：“三张”不能用来计算听懂的部分。"}, {"text": "三寸", "is_correct": false, "explanation": "语义：“三寸”是长度，不能用于听懂的程度。"}], "explanations": {"三分": "正确：三分表示听懂的部分，是少量程度，与“只听懂了”搭配。", "三升": "语义：听懂的程度不以升计。", "三张": "搭配：“三张”不能用来计算听懂的部分。", "三寸": "语义：“三寸”是长度，不能用于听懂的程度。"}, "sentence_index": 6, "correct_answer": "三分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的话里有三分书。", "explanation": "这里应该用〈三本〉。“三分”表示程度或份额，不能用来数“书”，应说“三本书”。"}, {"text": "我们家有三分人。", "explanation": "这里应该用〈三口〉。“三分”表示程度或份额，不能用来数家里的人，应说“三口人”。"}, {"text": "他的生日是三分。", "explanation": "这里应该用〈三月〉。“三分”表示份额或程度，不表示月份，说日期要用“月”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看我的时候带着一个三分笑意。", "corrected_sentence": "他看我的时候带着三分笑意。", "error_description": "错误：“三分”前多加了“一个”。“三分”表示程度，本身不用数量词，应直接说“带着三分笑意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的话里有三分了认真。", "corrected_sentence": "她的话里有三分认真。", "error_description": "错误：“了”位置错误。“有三分认真”表示程度，“三分”后不能直接加“了”，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98187, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下映", "is_correct": true, "explanation": "下映：影片停止在影院放映，与“上映”意思相反。"}, {"text": "出版", "is_correct": false, "explanation": "与“上映”没有反义关系，出版指书刊等正式发行。"}, {"text": "开业", "is_correct": false, "explanation": "与“上映”没有反义关系，开业指店铺等开始营业。"}, {"text": "完工", "is_correct": false, "explanation": "与“上映”没有反义关系，完工指工程或任务做完。"}], "correct_answer": "下映", "explanations": {"下映": "下映：影片停止在影院放映，与“上映”意思相反。", "出版": "与“上映”没有反义关系，出版指书刊等正式发行。", "开业": "与“上映”没有反义关系，开业指店铺等开始营业。", "完工": "与“上映”没有反义关系，完工指工程或任务做完。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98187, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下映", "is_correct": true, "explanation": "下映：影片停止在影院放映，与“上映”意思相反。"}, {"text": "竣工", "is_correct": false, "explanation": "与“上映”没有反义关系，竣工指工程完成。"}, {"text": "发车", "is_correct": false, "explanation": "与“上映”没有反义关系，发车指车辆开出。"}, {"text": "停工", "is_correct": false, "explanation": "与“上映”没有反义关系，停工指停止工作。"}], "correct_answer": "下映", "explanations": {"下映": "下映：影片停止在影院放映，与“上映”意思相反。", "竣工": "与“上映”没有反义关系，竣工指工程完成。", "发车": "与“上映”没有反义关系，发车指车辆开出。", "停工": "与“上映”没有反义关系，停工指停止工作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98187, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上映是电影在电影院里放出来给大家看。", "primary_collocate": null, "pronunciation": "shàng yìng", "ipa": "ʂaŋ˥˩ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这部电影下个月上映。", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电影昨天在全国上映了。", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部动画片明天上映，我已经买好票了。", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影上映以前，演员们去很多城市做宣传。", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影上映了三天，就有很多人去看。", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那部老电影下周重新上映。", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，电影上映的时间改到了晚上八点。", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一部爱情片，春节的时候上映。", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的导演的新片什么时候上映？", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院里正在上映一部有意思的外国电影。", "target_word": "上映", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上映了", "label": "体标（完成）"}, {"form": "上映过", "label": "体标（经历）"}, {"form": "重新上映", "label": "复合"}], "register": "中性", "sense_fingerprint": "电影在电影院开始放给观众看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96ed990e-6a76-4bf4-be27-bf246034c330') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开业", "is_correct": false, "explanation": "搭配：开业用于商店、公司等机构，不说电影开业。"}, {"text": "上映", "is_correct": true, "explanation": "上映：影片在电影院开始公开放映，与“电影”搭配。"}, {"text": "出版", "is_correct": false, "explanation": "搭配：出版用于书刊等印刷品，电影不能出版。"}, {"text": "通车", "is_correct": false, "explanation": "语义：通车指道路、铁路开放通行，与电影无关。"}], "explanations": {"开业": "搭配：开业用于商店、公司等机构，不说电影开业。", "上映": "上映：影片在电影院开始公开放映，与“电影”搭配。", "出版": "搭配：出版用于书刊等印刷品，电影不能出版。", "通车": "语义：通车指道路、铁路开放通行，与电影无关。"}, "sentence_index": 0, "correct_answer": "上映"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部话剧下个月在剧院上映。", "explanation": "这里应该用〈上演〉。上映只用于影片；话剧在剧场演出要说上演。"}, {"text": "这本小说下个月在书店上映。", "explanation": "这里应该用〈上架〉。上映只用于影片；书在书店陈列出售要说上架。"}, {"text": "我的爷爷下个月在电影院上映。", "explanation": "这里应该用〈露面〉。上映的主语只能是影片；人在场合中公开露面要说露面，不能说上映。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竣工", "is_correct": false, "explanation": "搭配：竣工用于工程、建筑，电影不能竣工。"}, {"text": "发车", "is_correct": false, "explanation": "搭配：发车用于车辆，不说电影发车。"}, {"text": "开学", "is_correct": false, "explanation": "语义：开学指学校开始上课，与电影无关。"}, {"text": "上映", "is_correct": true, "explanation": "上映：影片开始在电影院公开放映，与“电影……的时间”搭配。"}], "explanations": {"竣工": "搭配：竣工用于工程、建筑，电影不能竣工。", "发车": "搭配：发车用于车辆，不说电影发车。", "开学": "语义：开学指学校开始上课，与电影无关。", "上映": "上映：影片开始在电影院公开放映，与“电影……的时间”搭配。"}, "sentence_index": 6, "correct_answer": "上映"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电视剧今晚在全国上映。", "explanation": "这里应该用〈播出〉。上映只用于影片在影院放映；电视剧通过电视播放要说播出。"}, {"text": "这款新车下个月在市场上映。", "explanation": "这里应该用〈上市〉。上映只用于影片；新车投放市场要说上市。"}, {"text": "这支乐队今晚在体育馆上映。", "explanation": "这里应该用〈演出〉。上映只用于影片；乐队的音乐会要说演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部新片下周上映过。", "corrected_sentence": "这部新片下周上映。", "error_description": "“上映过”中的“过”表示曾经有过的经历，不能用于“下周”这个将来时间。应说“这部新片下周上映”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部老片下周重新上映过。", "corrected_sentence": "这部老片下周重新上映。", "error_description": "体标错误：“过”表示曾经有过的经历，不能与“下周”这样的将来时间搭配；应去掉“过”，说“这部老片下周重新上映”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f63dc11f-4661-4967-85b9-a246b6df6a27') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
