INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98189, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上街是走出家门，到马路上或商店那里去。", "primary_collocate": null, "pronunciation": "shàng jiē", "ipa": "ʂɑŋ˥˩ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "天气很好，我们上街走走吧。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天要上街办点事。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈上街前，先把窗户关好了。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们高兴地上街玩儿。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，你别上街了。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶腿不好，很少上街。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太冷，我不想上街。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天早上上街散步。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿着新衣服上街。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你上街的时候，帮我寄封信。", "target_word": "上街", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上了街", "label": "体标（了）"}, {"form": "上过街", "label": "体标（过）"}], "register": "口语", "sense_fingerprint": "走出家门到街上去（离合词），不限于购物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bf78ee-7ce4-4c00-a5e3-c90623cde1b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98189, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上街", "is_correct": true, "explanation": "上街：走出家门到街上去，与所听读音一致。"}, {"text": "商街", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，商街指商业街，与走出家门的意思无关。"}, {"text": "上节", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，上节指上一节，意思不同。"}, {"text": "商界", "is_correct": false, "explanation": "shāng 与 shàng 声调不同，jiè 与 jiē 声调也不同，商界指工商业领域，意思不同。"}], "explanations": {"上街": "上街：走出家门到街上去，与所听读音一致。", "商街": "shāng（第一声）与 shàng（第四声）声调不同，商街指商业街，与走出家门的意思无关。", "上节": "jié（第二声）与 jiē（第一声）声调不同，上节指上一节，意思不同。", "商界": "shāng 与 shàng 声调不同，jiè 与 jiē 声调也不同，商界指工商业领域，意思不同。"}, "sentence_index": null, "correct_answer": "上街"}, "level_3": {"options": [{"text": "上街", "is_correct": true, "explanation": "「上街」指走到街上去，与「走走吧」的散步语境相合。"}, {"text": "上课", "is_correct": false, "explanation": "语义：「上课」指去学校听讲，不能与「走走吧」的散步说法搭配。"}, {"text": "出差", "is_correct": false, "explanation": "语义：出差是因公外出办事，不是随意散步。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：「工作」不能与「走走吧」这种表示轻松移动的说法搭配。"}], "explanations": {"上街": "「上街」指走到街上去，与「走走吧」的散步语境相合。", "上课": "语义：「上课」指去学校听讲，不能与「走走吧」的散步说法搭配。", "出差": "语义：出差是因公外出办事，不是随意散步。", "工作": "搭配：「工作」不能与「走走吧」这种表示轻松移动的说法搭配。"}, "sentence_index": 0, "correct_answer": "上街"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上七点上街去上班。", "explanation": "这里应该用〈出门〉。上街指走到街上去，多为买东西或散步，去单位上班不能说上街。"}, {"text": "我们周末去商场上街。", "explanation": "这里应该用〈逛街〉。上街表示走出家门到街上去，人已在商场里时要说逛街。"}, {"text": "爸爸周末上街钓鱼。", "explanation": "这里应该用〈上山〉。上街指走到街上去，多为买东西或散步，去山上钓鱼要说上山，上街不能表示到山上去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98189, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "上街", "is_correct": true, "explanation": "上街：走出家门到街上去，与所听读音一致。"}, {"text": "上届", "is_correct": false, "explanation": "jiè（第四声）与 jiē（第一声）声调不同，上届指上一届，意思不同。"}, {"text": "商家", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，商家指做买卖的人，意思不同。"}, {"text": "上截", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，上截指上面的一截，意思不同。"}], "explanations": {"上街": "上街：走出家门到街上去，与所听读音一致。", "上届": "jiè（第四声）与 jiē（第一声）声调不同，上届指上一届，意思不同。", "商家": "shāng（第一声）与 shàng（第四声）声调不同，商家指做买卖的人，意思不同。", "上截": "jié（第二声）与 jiē（第一声）声调不同，上截指上面的一截，意思不同。"}, "sentence_index": null, "correct_answer": "上街"}, "level_3": {"options": [{"text": "上街", "is_correct": true, "explanation": "「上街」指走出家门到街上去，与「我不想」的表达相合。"}, {"text": "中暑", "is_correct": false, "explanation": "语义：中暑由高温引起，与「太冷」的天气矛盾。"}, {"text": "降温", "is_correct": false, "explanation": "语义：气温已经很低，「降温」会使天更冷，与「太冷」的语境矛盾。"}, {"text": "晒伤", "is_correct": false, "explanation": "搭配：晒伤需要强烈阳光，与「太冷」的天气不相配。"}], "explanations": {"上街": "「上街」指走出家门到街上去，与「我不想」的表达相合。", "中暑": "语义：中暑由高温引起，与「太冷」的天气矛盾。", "降温": "语义：气温已经很低，「降温」会使天更冷，与「太冷」的语境矛盾。", "晒伤": "搭配：晒伤需要强烈阳光，与「太冷」的天气不相配。"}, "sentence_index": 6, "correct_answer": "上街"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷每天在院子里上街。", "explanation": "这里应该用〈散步〉。上街指走到街上去，在院子里活动不能说上街。"}, {"text": "他明天要上街开会。", "explanation": "这里应该用〈外出〉。上街指到街上去，开会要在会议室等场所进行，不能说上街。"}, {"text": "周末他去郊外上街。", "explanation": "这里应该用〈散心〉。上街指到街上去，郊外不是街道，不能说上街。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98189, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我今天上街的，买了些东西。", "corrected_sentence": "我今天上街了，买了些东西。", "error_description": "错误：「上街」后应加体标「了」表示动作已经完成，「的」使句子不通，正确说法是「我今天上街了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98189, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我昨天上街来了，买了几件衣服。", "corrected_sentence": "我昨天上街去了，买了几件衣服。", "error_description": "错误：「上街」表示从家里出去，方向应用「去」，「来」表示朝说话人所在处移动，正确说法是「我昨天上街去了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
