INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98191, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不住是一直在做，停不下来。", "primary_collocate": null, "pronunciation": "bù zhù", "ipa": "pu˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "他不住地咳嗽，一晚上没睡好。", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不住地说谢谢。", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风不住地吹，窗户一直在响。", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不住地看着门口，等朋友来。", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不住地摇头。", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车里的孩子不住地问：“到了吗？”", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不住地喝水，因为天太热了。", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家不住地鼓掌，不想让他走。", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不住地跟在我后面跑。", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不住地擦眼睛，好像有东西进去了。", "target_word": "不住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不住地", "label": "副词形式（+地）"}], "register": "口语", "sense_fingerprint": "不住：副词，动作一直进行、停不下来，常说不住地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98191, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不住", "is_correct": true, "explanation": "正确：不住 bù zhù，副词，表示动作一直进行、停不下来。"}, {"text": "补助", "is_correct": false, "explanation": "bǔ（第三声）与 bù（第四声）声调不同，「补助」指资助，是另一个词。"}, {"text": "步数", "is_correct": false, "explanation": "shù 与 zhù 声母不同（sh 与 zh），「步数」指走路的步数。"}, {"text": "堵住", "is_correct": false, "explanation": "dǔ 与 bù 声母不同（d 与 b），「堵住」指堵塞。"}], "explanations": {"不住": "正确：不住 bù zhù，副词，表示动作一直进行、停不下来。", "补助": "bǔ（第三声）与 bù（第四声）声调不同，「补助」指资助，是另一个词。", "步数": "shù 与 zhù 声母不同（sh 与 zh），「步数」指走路的步数。", "堵住": "dǔ 与 bù 声母不同（d 与 b），「堵住」指堵塞。"}, "sentence_index": null, "correct_answer": "不住"}, "level_3": {"options": [{"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示瞬间发生，与“一晚上”的持续时间矛盾。"}, {"text": "不住", "is_correct": true, "explanation": "正确：“不住地”表示持续不停，与“一晚上没睡好”的情形一致。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上发生，与“一晚上”的持续时间不符。"}, {"text": "蓦然", "is_correct": false, "explanation": "语域：“蓦然”是书面语，与口语句的语域不协调。"}], "explanations": {"忽然": "语义：“忽然”表示瞬间发生，与“一晚上”的持续时间矛盾。", "不住": "正确：“不住地”表示持续不停，与“一晚上没睡好”的情形一致。", "立刻": "语义：“立刻”表示马上发生，与“一晚上”的持续时间不符。", "蓦然": "语域：“蓦然”是书面语，与口语句的语域不协调。"}, "sentence_index": 0, "correct_answer": "不住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不住地考上了大学。", "explanation": "这里应该用〈终于〉。不住地表示持续不停，不能用于一次性完成的结果。"}, {"text": "他不住三天没有出门，身体很虚弱。", "explanation": "这里应该用〈一连〉。不住表示动作持续，不能用来计算天数。"}, {"text": "他不住地记得那件事。", "explanation": "这里应该用〈一直〉。不住地修饰反复进行的动作，不能修饰“记得”这类状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间隔出现，与因为天热而持续喝水的情形矛盾。"}, {"text": "不住", "is_correct": true, "explanation": "正确：“不住地”表示持续不停，与“因为天太热”而不停喝水的语义一致。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“因为天太热了”而喝水的情形相矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”不能加“地”作状语，也不表示动作持续不停。"}], "explanations": {"偶尔": "语义：“偶尔”表示间隔出现，与因为天热而持续喝水的情形矛盾。", "不住": "正确：“不住地”表示持续不停，与“因为天太热”而不停喝水的语义一致。", "从不": "语义：“从不”表示从来没有，与“因为天太热了”而喝水的情形相矛盾。", "已经": "语法：“已经”不能加“地”作状语，也不表示动作持续不停。"}, "sentence_index": 6, "correct_answer": "不住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不住地赢了那场比赛，很高兴。", "explanation": "这里应该用〈终于〉。不住地表示持续不停，不能用于一次性完成的结果。"}, {"text": "他不住地是我们班的学生。", "explanation": "这里应该用〈一直〉。不住地只修饰不停进行的动作，不能修饰“是”这类判断。"}, {"text": "他不住地跑了一次，就停下了。", "explanation": "这里应该用〈偶尔〉。不住地表示持续不停，不能用于有限次数的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不住的揉眼睛，很不舒服。", "corrected_sentence": "他不住地揉眼睛，很不舒服。", "error_description": "错误：“不住”后用了“的”。正确：副词“不住”后应用状语标记“地”，即“不住地揉眼睛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不住的擦汗，因为天太热了。", "corrected_sentence": "他不住地擦汗，因为天太热了。", "error_description": "错误：“不住”后用了“的”。正确：副词“不住”后应用状语标记“地”，即“不住地擦汗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
