INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98193, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不动是身体或东西不移动，一直停在那里。", "primary_collocate": null, "pronunciation": "bú dòng", "ipa": "pu˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "照相的时候，请大家站着不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在椅子上，一直不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只鸟站在树上不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯亮了，汽车停在路口不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他躺着不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子放在那里，一年都不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看着电视，坐在沙发上不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人站在门口不动，好像在想什么。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭着眼睛，躺在草地上不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块石头在河边，几十年都不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "动词，人或物保持原位，不移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98193, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不同", "is_correct": false, "explanation": "tóng（第二声）与 dòng（第四声）声母不同（t／d），声调也不同，意思是不一样。"}, {"text": "不动", "is_correct": true, "explanation": "正确：bú dòng，指身体或东西不移动，停在原处。"}, {"text": "不通", "is_correct": false, "explanation": "tōng（第一声）与 dòng 声母不同（t／d），声调也不同，意思是不能通过。"}, {"text": "不痛", "is_correct": false, "explanation": "tòng 与 dòng 声母不同（t／d），声调相同，意思是没有疼痛。"}, {"text": "不重", "is_correct": false, "explanation": "zhòng 与 dòng 声母不同（zh／d），声调相同，意思是不沉。"}], "explanations": {"不同": "tóng（第二声）与 dòng（第四声）声母不同（t／d），声调也不同，意思是不一样。", "不动": "正确：bú dòng，指身体或东西不移动，停在原处。", "不通": "tōng（第一声）与 dòng 声母不同（t／d），声调也不同，意思是不能通过。", "不痛": "tòng 与 dòng 声母不同（t／d），声调相同，意思是没有疼痛。", "不重": "zhòng 与 dòng 声母不同（zh／d），声调相同，意思是不沉。"}, "sentence_index": null, "correct_answer": "不动"}, "level_3": {"options": [{"text": "游泳", "is_correct": false, "explanation": "搭配：游泳要在水里进行，不说“站着游泳”。"}, {"text": "不动", "is_correct": true, "explanation": "正确：照相时要求站着保持静止，符合句意。"}, {"text": "爬山", "is_correct": false, "explanation": "语义：爬山要不断移动，与“站着”的要求相反。"}, {"text": "散步", "is_correct": false, "explanation": "语义：散步要走动，与照相时的“站着”要求相反。"}], "explanations": {"游泳": "搭配：游泳要在水里进行，不说“站着游泳”。", "不动": "正确：照相时要求站着保持静止，符合句意。", "爬山": "语义：爬山要不断移动，与“站着”的要求相反。", "散步": "语义：散步要走动，与照相时的“站着”要求相反。"}, "sentence_index": 0, "correct_answer": "不动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "调皮的孩子一刻也不动。", "explanation": "这里应该用〈不停〉。“不动”说静止，乱跑的孩子要说“不停”。"}, {"text": "他在房间里来回不动。", "explanation": "这里应该用〈走动〉。“来回”说明在移动，“不动”说静止，两者矛盾。"}, {"text": "他一边走路，一边不动。", "explanation": "“不动”说静止，“走路”要移动，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98193, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "搏动", "is_correct": false, "explanation": "bó（第二声）与 bú（第二声）韵母不同（o／u），声调相同，意思是心脏等有节律地跳动。"}, {"text": "不懂", "is_correct": false, "explanation": "dǒng（第三声）与 dòng（第四声）韵母相同，声调不同，意思是不明白。"}, {"text": "别动", "is_correct": false, "explanation": "bié 与 bú 韵母不同（ie／u），声调相同，意思是不要移动。"}, {"text": "不动", "is_correct": true, "explanation": "正确：bú dòng，指身体或东西不移动，停在原处。"}], "explanations": {"搏动": "bó（第二声）与 bú（第二声）韵母不同（o／u），声调相同，意思是心脏等有节律地跳动。", "不懂": "dǒng（第三声）与 dòng（第四声）韵母相同，声调不同，意思是不明白。", "别动": "bié 与 bú 韵母不同（ie／u），声调相同，意思是不要移动。", "不动": "正确：bú dòng，指身体或东西不移动，停在原处。"}, "sentence_index": null, "correct_answer": "不动"}, "level_3": {"options": [{"text": "走动", "is_correct": false, "explanation": "语义：走动要起身移动，与“坐在沙发上”矛盾。"}, {"text": "爬行", "is_correct": false, "explanation": "语义：爬行是趴在地上前进，与“坐在沙发上”不符。"}, {"text": "不动", "is_correct": true, "explanation": "正确：孩子看电视，坐在沙发上不动，符合句意。"}, {"text": "跑步", "is_correct": false, "explanation": "搭配：“坐”和“跑步”不搭配，跑步要站起来才能做。"}], "explanations": {"走动": "语义：走动要起身移动，与“坐在沙发上”矛盾。", "爬行": "语义：爬行是趴在地上前进，与“坐在沙发上”不符。", "不动": "正确：孩子看电视，坐在沙发上不动，符合句意。", "跑步": "搭配：“坐”和“跑步”不搭配，跑步要站起来才能做。"}, "sentence_index": 6, "correct_answer": "不动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大风刮着，旗子在风里左右不动。", "explanation": "这里应该用〈摆动〉。“不动”说静止，风中的旗子要说“摆动”，两者矛盾。"}, {"text": "他的心脏在剧烈不动。", "explanation": "这里应该用〈跳动〉。“不动”说静止，剧烈的心跳要说“跳动”。"}, {"text": "他一直在跑步，却一直不动。", "explanation": "这里应该用〈不停〉。“不动”说静止，一直跑步的人要说“一直不停”，不能说不动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98193, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈让孩子坐着不动着，先别玩了。", "corrected_sentence": "妈妈让孩子坐着不动，先别玩了。", "error_description": "“不动”后面不能再加“着”，应说“坐着不动”，不说“不动着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98193, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶一直坐在窗边不动的。", "corrected_sentence": "奶奶一直坐在窗边不动。", "error_description": "“不动”作谓语，句末不能直接加“的”，应说“奶奶一直坐在窗边不动”，不说“奶奶一直坐在窗边不动的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
