INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98194, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不移动，保持静止；也指动不了。", "primary_collocate": null, "pronunciation": "bú dòng", "ipa": "pu˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "手机屏幕卡住了，怎么按都不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了，怎么开都不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门卡住了，我用力推也不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子太重了，我使劲搬，它还是不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累得坐在地上，好久都不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石头太大了，三个人推了半天，还是不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面很平，船停在那里不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说话时，学生们都坐着不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跑了很久，现在腿都软了，坐在地上不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器停了，怎么试都不动。", "target_word": "不动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "动词，保持静止，或因故无法移动、动不了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98194, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不通", "is_correct": false, "explanation": "tōng（第一声）与 dòng（第四声）声母不同（t／d），声调也不同，意思是不能通过。"}, {"text": "不动", "is_correct": true, "explanation": "正确：bú dòng，指保持静止，或因故动不了。"}, {"text": "不痛", "is_correct": false, "explanation": "tòng 与 dòng 声母不同（t／d），声调相同，意思是没有疼痛。"}, {"text": "不重", "is_correct": false, "explanation": "zhòng 与 dòng 声母不同（zh／d），声调相同，意思是不沉。"}, {"text": "搏动", "is_correct": false, "explanation": "bó（第二声）与 bú（第二声）韵母不同（o／u），声调相同，意思是心脏等有节律地跳动。"}], "explanations": {"不通": "tōng（第一声）与 dòng（第四声）声母不同（t／d），声调也不同，意思是不能通过。", "不动": "正确：bú dòng，指保持静止，或因故动不了。", "不痛": "tòng 与 dòng 声母不同（t／d），声调相同，意思是没有疼痛。", "不重": "zhòng 与 dòng 声母不同（zh／d），声调相同，意思是不沉。", "搏动": "bó（第二声）与 bú（第二声）韵母不同（o／u），声调相同，意思是心脏等有节律地跳动。"}, "sentence_index": null, "correct_answer": "不动"}, "level_3": {"options": [{"text": "不说话", "is_correct": false, "explanation": "语义：手机屏幕不会说话，与“怎么按”的句意不合。"}, {"text": "不动", "is_correct": true, "explanation": "正确：屏幕卡住，怎么按都动不了，符合句意。"}, {"text": "不走", "is_correct": false, "explanation": "语义：“走”说人或车移动，屏幕不会走。"}, {"text": "不吃", "is_correct": false, "explanation": "搭配：“吃”的对象不是手机，说“不吃”搭配的是人或动物。"}], "explanations": {"不说话": "语义：手机屏幕不会说话，与“怎么按”的句意不合。", "不动": "正确：屏幕卡住，怎么按都动不了，符合句意。", "不走": "语义：“走”说人或车移动，屏幕不会走。", "不吃": "搭配：“吃”的对象不是手机，说“不吃”搭配的是人或动物。"}, "sentence_index": 0, "correct_answer": "不动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边走路，一边不动。", "explanation": "“不动”表示静止或动不了，“走路”要移动，二者矛盾。"}, {"text": "他跑得很快，却一直不动。", "explanation": "“跑得很快”要移动，与“不动”的静止或动不了义项矛盾。"}, {"text": "他一边唱歌，一边不动地跳舞。", "explanation": "“跳舞”要移动，与“不动”的静止或动不了义项矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98194, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不同", "is_correct": false, "explanation": "tóng（第二声）与 dòng（第四声）声母不同（t／d），声调也不同，意思是相同。"}, {"text": "不懂", "is_correct": false, "explanation": "dǒng（第三声）与 dòng（第四声）韵母相同，声调不同，意思是不明白。"}, {"text": "别动", "is_correct": false, "explanation": "bié 与 bú 韵母不同（ie／u），声调相同，意思是不要移动。"}, {"text": "不动", "is_correct": true, "explanation": "正确：bú dòng，指保持静止，或因故动不了。"}], "explanations": {"不同": "tóng（第二声）与 dòng（第四声）声母不同（t／d），声调也不同，意思是相同。", "不懂": "dǒng（第三声）与 dòng（第四声）韵母相同，声调不同，意思是不明白。", "别动": "bié 与 bú 韵母不同（ie／u），声调相同，意思是不要移动。", "不动": "正确：bú dòng，指保持静止，或因故动不了。"}, "sentence_index": null, "correct_answer": "不动"}, "level_3": {"options": [{"text": "不飞", "is_correct": false, "explanation": "语义：船不会飞，与“停在那里”的句意不合。"}, {"text": "不唱", "is_correct": false, "explanation": "语义：船停在那里，不会唱歌，句意不合。"}, {"text": "不动", "is_correct": true, "explanation": "正确：水面平静，船停在那里不动，符合句意。"}, {"text": "不游", "is_correct": false, "explanation": "搭配：“游”说人或动物在水中活动，不说船“游”。"}], "explanations": {"不飞": "语义：船不会飞，与“停在那里”的句意不合。", "不唱": "语义：船停在那里，不会唱歌，句意不合。", "不动": "正确：水面平静，船停在那里不动，符合句意。", "不游": "搭配：“游”说人或动物在水中活动，不说船“游”。"}, "sentence_index": 6, "correct_answer": "不动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车发动后猛地向前冲，却一直不动。", "explanation": "“冲”要移动，与“不动”的静止或动不了义项矛盾。"}, {"text": "孩子们在操场上奔跑，却一直不动。", "explanation": "“奔跑”要移动，与“不动”的静止或动不了义项矛盾。"}, {"text": "钥匙掉在草丛里，我怎么找也不动。", "explanation": "这里应该用〈找不到〉。“不动”不能用来说找不到东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卡车陷在泥里，我怎么开都不动着。", "corrected_sentence": "卡车陷在泥里，我怎么开都不动。", "error_description": "“不动”后面不能再加“着”，应说“怎么开都不动”，不说“不动着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块铁板很重，我怎么抬都不动的。", "corrected_sentence": "这块铁板很重，我怎么抬都不动。", "error_description": "“不动”作谓语，句末不能直接加“的”，应说“我怎么抬都不动”，不说“我怎么抬都不动的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
