INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98195, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由国家直接管理的大型企业。", "primary_collocate": null, "pronunciation": "zhōng yāng qǐ yè", "ipa": "ʈʂʊŋ˥ jɑŋ˥ tɕʰi˨˩˦ jɛ˥˩", "syllable_count": 4, "sentences": [{"text": "中央企业是由国家直接管理的大公司。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业后进了一家中央企业工作。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家中央企业在很多城市都有分公司。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央企业的工资比较稳定，很多人想去。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐在一家中央企业做会计。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央企业要把国家的钱用好。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大桥是一家中央企业修的。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央企业每年都会招很多大学生。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸在中央企业工作了二十年。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说，几家中央企业今年赚了很多钱。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "央企", "label": "简称"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "由国家直接管理的大公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98195, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外资企业", "is_correct": false, "explanation": "语义：外资企业由外国资本投资，不由国家直接管理，与句中“由国家直接管理”矛盾。"}, {"text": "私营企业", "is_correct": false, "explanation": "语义：私营企业由私人出资经营，不由国家直接管理，与句意矛盾。"}, {"text": "中央企业", "is_correct": true, "explanation": "正确：中央企业即由国家直接管理的大公司，与定义和句意一致。"}, {"text": "地方企业", "is_correct": false, "explanation": "语义：地方企业由地方政府管理，不由国家直接管理，与句意矛盾。"}], "explanations": {"外资企业": "语义：外资企业由外国资本投资，不由国家直接管理，与句中“由国家直接管理”矛盾。", "私营企业": "语义：私营企业由私人出资经营，不由国家直接管理，与句意矛盾。", "中央企业": "正确：中央企业即由国家直接管理的大公司，与定义和句意一致。", "地方企业": "语义：地方企业由地方政府管理，不由国家直接管理，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "中央企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐进了一只中央企业工作。", "explanation": "这里应该用〈家〉。企业的量词是“家”，“只”用于动物等，不能用于企业。"}, {"text": "这个城市的中央企业都由市政府管理。", "explanation": "这里应该用〈地方企业〉。市政府管理的是地方企业，中央企业由中央政府直接管理。"}, {"text": "他想开一家中央企业，自己当老板。", "explanation": "这里应该用〈私营企业〉。个人可以开私营企业，中央企业由国家直接管理，个人不能开办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大学", "is_correct": false, "explanation": "语义：大学是学校，不负责修建大桥。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的地方，不修建桥梁。"}, {"text": "中央企业", "is_correct": true, "explanation": "正确：中央企业是企业，可以承建大桥，与“修”的动作相符。"}, {"text": "超市", "is_correct": false, "explanation": "语义：超市是卖东西的商店，不修建大桥。"}], "explanations": {"大学": "语义：大学是学校，不负责修建大桥。", "医院": "语义：医院是治病的地方，不修建桥梁。", "中央企业": "正确：中央企业是企业，可以承建大桥，与“修”的动作相符。", "超市": "语义：超市是卖东西的商店，不修建大桥。"}, "sentence_index": 6, "correct_answer": "中央企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家中央企业是我叔叔一个人出资开办的。", "explanation": "这里应该用〈个人独资企业〉。中央企业由国家出资、直接管理，不是个人出资开办的。"}, {"text": "村里的中央企业由全体村民共同经营。", "explanation": "这里应该用〈集体企业〉。中央企业由国家直接管理，不是村民共同经营的。"}, {"text": "这家中央企业由村委会管理。", "explanation": "这里应该用〈乡镇企业〉。乡镇企业由村委会等基层组织管理，中央企业由国家直接管理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹大学毕业后在一中央企业上班。", "corrected_sentence": "我妹妹大学毕业后在一家中央企业上班。", "error_description": "错误：“一”后漏了量词“家”。应为“一家中央企业”，“家”是“企业”的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅在一条中央企业干了三十年。", "corrected_sentence": "我舅舅在一家中央企业干了三十年。", "error_description": "错误：“企业”的量词用了“条”。“条”用于长条形事物，应为“家”：“一家中央企业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
