INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98196, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由中央政府直接管理的国有企业。", "primary_collocate": null, "pronunciation": "zhōng yāng qǐ yè", "ipa": "ʈʂʊŋ˥ jɑŋ˥ tɕʰi˨˩˦ jɛ˥˩", "syllable_count": 4, "sentences": [{"text": "国资委负责管理中央企业。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央企业属于国有企业，不是私人公司。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央企业和地方企业不一样，地方企业由省市管理。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国石油是一家有名的中央企业。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央企业要为国家发展做贡献。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上写着，中央企业要带头节约能源。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想进中央企业工作。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议请来了十几家中央企业的代表。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央企业的总部大多在北京。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些中央企业都由中央政府直接管理。", "target_word": "中央企业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "央企", "label": "简称"}, {"form": "家", "label": "量词"}], "register": "中性", "sense_fingerprint": "中央政府直接管理的国有企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外资企业", "is_correct": false, "explanation": "语义：外资企业由外国资本投资，不归国资委管理。"}, {"text": "私人公司", "is_correct": false, "explanation": "搭配：国资委只管理国有资产，“管理”一般不与“私人公司”搭配。"}, {"text": "合伙企业", "is_correct": false, "explanation": "语义：合伙企业由合伙人自己出资经营，不是国资委管理的对象。"}, {"text": "中央企业", "is_correct": true, "explanation": "正确：国资委负责管理的正是中央企业，与定义和句意一致。"}], "explanations": {"外资企业": "语义：外资企业由外国资本投资，不归国资委管理。", "私人公司": "搭配：国资委只管理国有资产，“管理”一般不与“私人公司”搭配。", "合伙企业": "语义：合伙企业由合伙人自己出资经营，不是国资委管理的对象。", "中央企业": "正确：国资委负责管理的正是中央企业，与定义和句意一致。"}, "sentence_index": 0, "correct_answer": "中央企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国石油是一座有名的中央企业。", "explanation": "这里应该用〈家〉。企业的量词是“家”，“座”多用于山、桥、楼等，不用于企业。"}, {"text": "这座城市的自来水公司是一家有名的中央企业。", "explanation": "这里应该用〈地方企业〉。城市自来水公司由市里管理，属于地方企业；中央企业由中央政府直接管理。"}, {"text": "我舅舅开了一家中央企业，规模不大。", "explanation": "这里应该用〈私营企业〉。个人开办的公司是私营企业，中央企业由国家直接管理，个人不能开办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不是可以“进”去工作的单位。"}, {"text": "夜空", "is_correct": false, "explanation": "搭配：“进”后接的是单位或场所，“夜空”不能用于“进……工作”。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是工作单位，不能“进”去工作。"}, {"text": "中央企业", "is_correct": true, "explanation": "正确：中央企业是可以进去工作的单位，与“进……工作”相符。"}], "explanations": {"小说": "语义：小说是文学作品，不是可以“进”去工作的单位。", "夜空": "搭配：“进”后接的是单位或场所，“夜空”不能用于“进……工作”。", "水果": "语义：水果不是工作单位，不能“进”去工作。", "中央企业": "正确：中央企业是可以进去工作的单位，与“进……工作”相符。"}, "sentence_index": 6, "correct_answer": "中央企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家中央企业的大股东来自美国。", "explanation": "这里应该用〈外资企业〉。中央企业由国家出资，不会以外国股东为大股东。"}, {"text": "这家中央企业由几个朋友合伙开办。", "explanation": "这里应该用〈民营企业〉。中央企业由国家直接管理，不是几个朋友合伙开办的。"}, {"text": "这家中央企业只有老板一个人。", "explanation": "这里应该用〈个人独资企业〉。个人独资企业只有一个出资人，中央企业是国家直接管理的大公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司是国资委监管的一中央企业。", "corrected_sentence": "这家公司是国资委监管的一家中央企业。", "error_description": "错误：“一”后漏了量词“家”。应为“一家中央企业”，“家”是“企业”的量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一条中央企业，由中央政府直接管理。", "corrected_sentence": "这是一家中央企业，由中央政府直接管理。", "error_description": "错误：“企业”的量词用了“条”。“条”用于长条形事物，应为“家”：“一家中央企业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98197, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98197, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98197, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中帮是鞋子的一种，鞋口高度在脚踝下面一点。", "primary_collocate": null, "pronunciation": "zhōng bāng", "ipa": "ʈʂʊŋ˥ paŋ˥", "syllable_count": 2, "sentences": [{"text": "这双运动鞋是中帮的，穿着很舒服。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢低帮，想买一双中帮。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中帮的鞋口在脚踝下面一点。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天我常穿中帮，脚不容易湿。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的新鞋是黑色的中帮。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员说，这款中帮有三种颜色。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高帮太热，低帮太凉，我选中帮。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的中帮已经穿了两年。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双中帮的鞋底很软，走路不累。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的时候，我喜欢穿中帮配牛仔裤。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "双", "label": "量词"}, {"form": "中帮鞋", "label": "复合"}, {"form": "中幫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鞋口在脚踝下面一点的鞋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c715073-07d3-4bb9-b479-83cb8d740dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98197, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中帮", "is_correct": true, "explanation": "正确：中帮是鞋的一种，鞋口在脚踝下面一点。"}, {"text": "中班", "is_correct": false, "explanation": "bān（班）与 bāng（帮）韵尾 n 与 ng 不同，意思是幼儿园的中班，不是鞋。"}, {"text": "中榜", "is_correct": false, "explanation": "中榜读 zhòngbǎng，两个音节的声调都与 zhōngbāng 不同，意思是考试或选拔中被录取上榜，与鞋无关。"}, {"text": "中方", "is_correct": false, "explanation": "中方读 zhōngfāng，第二个音节的声母是 f 不是 b，意思是中国一方，与鞋无关。"}, {"text": "重磅", "is_correct": false, "explanation": "重磅读 zhòngbàng，两个音节都是第四声，与 zhōngbāng 的第一声不同，意思是分量重、影响大，与鞋无关。"}], "explanations": {"中帮": "正确：中帮是鞋的一种，鞋口在脚踝下面一点。", "中班": "bān（班）与 bāng（帮）韵尾 n 与 ng 不同，意思是幼儿园的中班，不是鞋。", "中榜": "中榜读 zhòngbǎng，两个音节的声调都与 zhōngbāng 不同，意思是考试或选拔中被录取上榜，与鞋无关。", "中方": "中方读 zhōngfāng，第二个音节的声母是 f 不是 b，意思是中国一方，与鞋无关。", "重磅": "重磅读 zhòngbàng，两个音节都是第四声，与 zhōngbāng 的第一声不同，意思是分量重、影响大，与鞋无关。"}, "sentence_index": null, "correct_answer": "中帮"}, "level_3": {"options": [{"text": "中帮", "is_correct": true, "explanation": "正确。“运动鞋”可按鞋帮高度分为低帮、中帮、高帮，此处指中帮。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋与运动鞋不是同一类鞋，“这双运动鞋是拖鞋的”自相矛盾。"}, {"text": "凉鞋", "is_correct": false, "explanation": "语义：凉鞋是露脚背的鞋，与运动鞋不是同一类，句子不通。"}, {"text": "高跟鞋", "is_correct": false, "explanation": "搭配：“穿着很舒服”通常不用来形容高跟鞋，且“运动鞋是高跟鞋的”也与运动鞋的类别冲突。"}], "explanations": {"中帮": "正确。“运动鞋”可按鞋帮高度分为低帮、中帮、高帮，此处指中帮。", "拖鞋": "语义：拖鞋与运动鞋不是同一类鞋，“这双运动鞋是拖鞋的”自相矛盾。", "凉鞋": "语义：凉鞋是露脚背的鞋，与运动鞋不是同一类，句子不通。", "高跟鞋": "搭配：“穿着很舒服”通常不用来形容高跟鞋，且“运动鞋是高跟鞋的”也与运动鞋的类别冲突。"}, "sentence_index": 0, "correct_answer": "中帮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一件中帮，穿起来很舒服。", "explanation": "这里应该用〈双〉。鞋按双计量，“件”用于衣服、物品，不用于鞋。"}, {"text": "这双中帮把脚踝完全包住了，爬雪山时很保暖。", "explanation": "这里应该用〈高帮〉。中帮的鞋口在脚踝下面，包不住整个脚踝；完全包住脚踝的是高帮。"}, {"text": "妈妈给我买了一顶中帮，戴着很暖和。", "explanation": "这里应该用〈帽子〉。中帮是鞋的一种，指鞋口在脚踝下面的鞋，不能用来指戴在头上的帽子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98197, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中帮", "is_correct": true, "explanation": "正确。前句说高帮太热、低帮太凉，应选介于两者之间的中帮。"}, {"text": "高帮", "is_correct": false, "explanation": "语义：前句已说“高帮太热”，再选高帮与之矛盾。"}, {"text": "低帮", "is_correct": false, "explanation": "语义：前句说“低帮太凉”，选低帮与之矛盾。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是戴在手上的，与前文讨论的鞋帮高低无关。"}], "explanations": {"中帮": "正确。前句说高帮太热、低帮太凉，应选介于两者之间的中帮。", "高帮": "语义：前句已说“高帮太热”，再选高帮与之矛盾。", "低帮": "语义：前句说“低帮太凉”，选低帮与之矛盾。", "手套": "语义：手套是戴在手上的，与前文讨论的鞋帮高低无关。"}, "sentence_index": 6, "correct_answer": "中帮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双中帮的鞋口很高，能盖住小腿。", "explanation": "这里应该用〈靴子〉。中帮的鞋口在脚踝下面，盖不住小腿；鞋口能盖到小腿的是靴子。"}, {"text": "这件外套的中帮很厚实。", "explanation": "这里应该用〈领子〉。“中帮”只指鞋的一种，不能用来指外套的部位；外套的部位要说〈领子〉。"}, {"text": "我买了一条中帮，穿着很轻。", "explanation": "这里应该用〈双〉。鞋按双计量，“条”用于裤子、绳子等细长的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一个中帮，穿着很舒服。", "corrected_sentence": "我昨天买了一双中帮，穿着很舒服。", "error_description": "“中帮”是鞋，应使用量词“双”。写成“一个中帮”是错误的，正确形式是“一双中帮”，因为鞋按双计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在商店里买了一双很中帮鞋，很合脚。", "corrected_sentence": "我在商店里买了一双中帮鞋，很合脚。", "error_description": "“中帮”是名词，修饰“鞋”时前面不能加副词“很”。写成“一双很中帮鞋”是错误的，应删去“很”，正确形式是“一双中帮鞋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
