INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98198, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98198, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鞋帮高度介于低帮与高帮之间的鞋。", "primary_collocate": null, "pronunciation": "zhōng bāng", "ipa": "ʈʂʊŋ˥ paŋ˥", "syllable_count": 2, "sentences": [{"text": "这家店的中帮卖得最好。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一双白色中帮放进了包里。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时我穿低帮，爬山时我穿中帮。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中帮比低帮高，比高帮低。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥送了我一双灰色的中帮。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的中帮都打折了。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的脚踝受过伤，所以常穿中帮。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双中帮穿着很轻，我很喜欢。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天我想买一双厚一点的中帮。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起高帮，中帮穿脱更方便。", "target_word": "中帮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "双", "label": "量词"}, {"form": "中帮鞋", "label": "复合"}, {"form": "中幫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鞋帮高度介于低帮与高帮之间的鞋", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c715073-07d3-4bb9-b479-83cb8d740dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98198, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中帮", "is_correct": true, "explanation": "正确：中帮指鞋帮高度介于低帮与高帮之间的鞋。"}, {"text": "中班", "is_correct": false, "explanation": "bān（班）与 bāng（帮）韵尾 n 与 ng 不同，意思是幼儿园的中班，不是鞋。"}, {"text": "中榜", "is_correct": false, "explanation": "bǎng（第三声）与 bāng（第一声）声调不同，意思是考试或选拔中录取上榜，与鞋无关。"}, {"text": "中板", "is_correct": false, "explanation": "bǎn 与 bāng 的韵母与声调都不同，中板指中速的板式或中厚钢板，与鞋无关。"}], "explanations": {"中帮": "正确：中帮指鞋帮高度介于低帮与高帮之间的鞋。", "中班": "bān（班）与 bāng（帮）韵尾 n 与 ng 不同，意思是幼儿园的中班，不是鞋。", "中榜": "bǎng（第三声）与 bāng（第一声）声调不同，意思是考试或选拔中录取上榜，与鞋无关。", "中板": "bǎn 与 bāng 的韵母与声调都不同，中板指中速的板式或中厚钢板，与鞋无关。"}, "sentence_index": null, "correct_answer": "中帮"}, "level_3": {"options": [{"text": "中帮", "is_correct": true, "explanation": "正确。“这家店的中帮”指店里卖的鞋，符合“卖得最好”。"}, {"text": "餐馆", "is_correct": false, "explanation": "搭配：“卖”的对象应是商品，餐馆不能被当作商品来卖。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是店里出售的东西，句子不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是店里出售的东西，“这家店的月亮卖得最好”不通。"}], "explanations": {"中帮": "正确。“这家店的中帮”指店里卖的鞋，符合“卖得最好”。", "餐馆": "搭配：“卖”的对象应是商品，餐馆不能被当作商品来卖。", "天气": "语义：天气不是店里出售的东西，句子不通。", "月亮": "语义：月亮不是店里出售的东西，“这家店的月亮卖得最好”不通。"}, "sentence_index": 0, "correct_answer": "中帮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一条中帮，穿着很舒服。", "explanation": "这里应该用〈双〉。鞋按双计量，“条”用于裤子、绳子等细长的东西。"}, {"text": "这双中帮的鞋帮很低，连脚踝都碰不到。", "explanation": "这里应该用〈低帮〉。中帮的鞋帮高度介于低帮与高帮之间，鞋帮低到碰不到脚踝的鞋是低帮。"}, {"text": "这把伞的中帮很结实。", "explanation": "这里应该用〈伞面〉。“中帮”只指鞋的一种，伞的部位要说〈伞面〉或〈伞骨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98198, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中帮", "is_correct": true, "explanation": "正确。“我的脚踝受过伤，所以常穿”后接鞋的类型，中帮符合语境。"}, {"text": "手套", "is_correct": false, "explanation": "语义：手套是戴在手上的，不说“穿”，也与脚踝受伤无关。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：眼镜是戴的，不说“穿”。"}, {"text": "拐杖", "is_correct": false, "explanation": "搭配：拐杖是拿的或用的，不是穿的。"}], "explanations": {"中帮": "正确。“我的脚踝受过伤，所以常穿”后接鞋的类型，中帮符合语境。", "手套": "语义：手套是戴在手上的，不说“穿”，也与脚踝受伤无关。", "眼镜": "搭配：眼镜是戴的，不说“穿”。", "拐杖": "搭配：拐杖是拿的或用的，不是穿的。"}, "sentence_index": 6, "correct_answer": "中帮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天下雪，我穿中帮出门，小腿不会湿。", "explanation": "这里应该用〈靴子〉。中帮的鞋帮只到脚踝左右，挡不住小腿；要防小腿打湿得穿靴子。"}, {"text": "中帮没有鞋帮，所以夏天穿着很凉快。", "explanation": "这里应该用〈凉鞋〉。中帮是按鞋帮高度区分的鞋，本身有鞋帮，不能说没有鞋帮。"}, {"text": "我买了一件中帮，穿着很轻。", "explanation": "这里应该用〈双〉。鞋按双计量，“件”用于衣服、物品，不用于鞋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98198, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她给弟弟挑了一个中帮，很合脚。", "corrected_sentence": "她给弟弟挑了一双中帮，很合脚。", "error_description": "“中帮”是鞋，应使用量词“双”。写成“一个中帮”是错误的，正确形式是“一双中帮”，因为鞋按双计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98198, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在网上看到一双很中帮鞋，颜色很漂亮。", "corrected_sentence": "我在网上看到一双中帮鞋，颜色很漂亮。", "error_description": "“中帮”是名词，修饰“鞋”时前面不能加副词“很”。写成“一双很中帮鞋”是错误的，应删去“很”，正确形式是“一双中帮鞋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
