INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98199, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "也就是；用后面的话把前面的内容换个说法讲清楚。", "primary_collocate": null, "pronunciation": "yì jí", "ipa": "i˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "他是我的叔叔，亦即我爸爸的弟弟。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的老人，亦即六十岁以上的人，可以免费坐车。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是十二月一日，亦即冬天的第一天。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住的城市，亦即中国的首都，非常大。", "target_word": "亦即", "complexity_tier": "T3", "furigana": "tā zhù de chéng shì yì jí zhōng guó de shǒu dū fēi cháng dà", "sentence_source": "generated"}, {"text": "一年有四个季节，亦即春夏秋冬。", "target_word": "亦即", "complexity_tier": "T3", "furigana": "yī nián yǒu sì gè jì jié yì jí chūn xià qiū dōng", "sentence_source": "generated"}, {"text": "周末，亦即星期六和星期日，我不上班。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是他的母校，亦即他读书的学校。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长，亦即孩子的爸爸妈妈，请先到这里。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥全长一千米，亦即一公里。", "target_word": "亦即", "complexity_tier": "T3", "furigana": "zhè zuò qiáo quán cháng yì qiān mǐ yì jí yì gōng lǐ", "sentence_source": "generated"}, {"text": "我们的学校，亦即那所位于山上的小学，很安静。", "target_word": "亦即", "complexity_tier": "T3", "furigana": "wǒ men de xué xiào yì jí nà suǒ wèi yú shān shàng de xiǎo xué hěn ān jìng", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面用语，用后面的话把前面的内容换个说法解释清楚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b192761-8a5e-44d0-af8b-6677718ed4de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98199, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亦即", "is_correct": true, "explanation": "亦即：连词，书面用语，意为“也就是”，是正确答案。"}, {"text": "益己", "is_correct": false, "explanation": "yì 相同，jǐ（第三声）与 jí（第二声）声调不同，益己指对自己有好处。"}, {"text": "一击", "is_correct": false, "explanation": "“一”在第一声前读 yì，与亦即第一音节相同；jī（第一声）与 jí（第二声）声调不同，一击指打一下。"}, {"text": "异己", "is_correct": false, "explanation": "yì 相同，jǐ（第三声）与 jí（第二声）声调不同，异己指持不同意见的人。"}, {"text": "密集", "is_correct": false, "explanation": "mì（第四声）与 yì（第四声）只有声母不同（m 与 y），意思是数量多而集中。"}], "explanations": {"亦即": "亦即：连词，书面用语，意为“也就是”，是正确答案。", "益己": "yì 相同，jǐ（第三声）与 jí（第二声）声调不同，益己指对自己有好处。", "一击": "“一”在第一声前读 yì，与亦即第一音节相同；jī（第一声）与 jí（第二声）声调不同，一击指打一下。", "异己": "yì 相同，jǐ（第三声）与 jí（第二声）声调不同，异己指持不同意见的人。", "密集": "mì（第四声）与 yì（第四声）只有声母不同（m 与 y），意思是数量多而集中。"}, "sentence_index": null, "correct_answer": "亦即"}, "level_3": {"options": [{"text": "亦即", "is_correct": true, "explanation": "亦即：连词，引出对前面“叔叔”的换种说法的解释，即“爸爸的弟弟”。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，前后两句没有对比关系，句子说不通。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，“是爸爸的弟弟”不是“是叔叔”的结果。"}, {"text": "甚至", "is_correct": false, "explanation": "语义：“甚至”表示程度递进，这里前后并无递进关系，“甚至我爸爸的弟弟”也不成句。"}], "explanations": {"亦即": "亦即：连词，引出对前面“叔叔”的换种说法的解释，即“爸爸的弟弟”。", "但是": "语义：“但是”表示转折，前后两句没有对比关系，句子说不通。", "所以": "语义：“所以”表示因果，“是爸爸的弟弟”不是“是叔叔”的结果。", "甚至": "语义：“甚至”表示程度递进，这里前后并无递进关系，“甚至我爸爸的弟弟”也不成句。"}, "sentence_index": 0, "correct_answer": "亦即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天我们去公园，亦即去博物馆。", "explanation": "这里应该用〈或者〉。亦即表示换个说法解释前面的内容，“去公园”和“去博物馆”是两件不同的事，不能互相解释。"}, {"text": "他很聪明，亦即很努力。", "explanation": "这里应该用〈而且〉。亦即要求后面是前面内容的另一种说法，“聪明”和“努力”是两个不同的特点，不能这样解释。"}, {"text": "这个方法很便宜，亦即质量不好。", "explanation": "这里应该用〈但是〉。“便宜”和“质量不好”前后是转折关系，亦即不表示转折，不能这样连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98199, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亦即", "is_correct": true, "explanation": "亦即：连词，书面用语，意为“也就是”，是正确答案。"}, {"text": "乙级", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，乙级指第二等级。"}, {"text": "遗迹", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，jì（第四声）与 jí（第二声）也不同，遗迹指留下来的痕迹。"}, {"text": "雨季", "is_correct": false, "explanation": "yǔ（第三声）与 yì（第四声）声调不同，jì（第四声）与 jí（第二声）也不同，雨季指多雨的季节。"}, {"text": "意识", "is_correct": false, "explanation": "亦即的第二音节是 jí，意识的第二音节是 shí，两者声母不同，意思是对事物的觉察和认知。"}], "explanations": {"亦即": "亦即：连词，书面用语，意为“也就是”，是正确答案。", "乙级": "yǐ（第三声）与 yì（第四声）声调不同，乙级指第二等级。", "遗迹": "yí（第二声）与 yì（第四声）声调不同，jì（第四声）与 jí（第二声）也不同，遗迹指留下来的痕迹。", "雨季": "yǔ（第三声）与 yì（第四声）声调不同，jì（第四声）与 jí（第二声）也不同，雨季指多雨的季节。", "意识": "亦即的第二音节是 jí，意识的第二音节是 shí，两者声母不同，意思是对事物的觉察和认知。"}, "sentence_index": null, "correct_answer": "亦即"}, "level_3": {"options": [{"text": "亦即", "is_correct": true, "explanation": "亦即：连词，引出对前面“母校”的换种说法的解释，即“他读书的学校”。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，“他读书的学校”不是“母校”的结果。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示时间先后，这里前后两句没有先后关系。"}, {"text": "即便", "is_correct": false, "explanation": "搭配：“即便”要和“也”或“就”配合表示让步，后面不能直接接名词性的解释。"}], "explanations": {"亦即": "亦即：连词，引出对前面“母校”的换种说法的解释，即“他读书的学校”。", "因此": "语义：“因此”表示因果，“他读书的学校”不是“母校”的结果。", "然后": "语义：“然后”表示时间先后，这里前后两句没有先后关系。", "即便": "搭配：“即便”要和“也”或“就”配合表示让步，后面不能直接接名词性的解释。"}, "sentence_index": 6, "correct_answer": "亦即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先下班，亦即去健身房。", "explanation": "这里应该用〈然后〉。“下班”和“去健身房”是先后发生的两件事，不是同一件事的不同说法，亦即不能这样用。"}, {"text": "下大雨了，亦即比赛取消了。", "explanation": "这里应该用〈因此〉。“下大雨”和“比赛取消”是因果关系，亦即只用于换种说法解释，不表示因果。"}, {"text": "他听到消息，亦即马上出发。", "explanation": "这里应该用〈于是〉。“听到消息”和“马上出发”是前后承接的动作，亦即不能表示这种承接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老师，亦即了我的班主任，很和气。", "corrected_sentence": "这位老师，亦即我的班主任，很和气。", "error_description": "错误：“亦即”后多加了“了”。“亦即”是连词，不能带“了”，应直接说“亦即我的班主任”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的爱好，亦即的画画，一直没变。", "corrected_sentence": "我的爱好，亦即画画，一直没变。", "error_description": "错误：“亦即”后面不能加“的”。正确应为“亦即画画”，“亦即”后直接接解释的内容。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98200, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
