INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98200, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "也就是；用来对前面所说的内容加以说明。", "primary_collocate": null, "pronunciation": "yì jí", "ipa": "i˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "立春，亦即春天的开始，天气慢慢变暖。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我的老同学，亦即从小一起长大的朋友。", "target_word": "亦即", "complexity_tier": "T3", "furigana": "tā shì wǒ de lǎo tóng xué yì jí cóng xiǎo yì qǐ zhǎng dà de péng you", "sentence_source": "generated"}, {"text": "全班四十人，其中二十人去了，亦即一半的同学去了。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我母亲的父亲，亦即我的外公，今年八十岁了。", "target_word": "亦即", "complexity_tier": "T3", "furigana": "wǒ mǔ qīn de fù qīn yì jí wǒ de wài gōng jīn nián bā shí suì le", "sentence_source": "generated"}, {"text": "明天是周日，亦即休息日。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的计划很简单，亦即每天学习一个小时。", "target_word": "亦即", "complexity_tier": "T3", "furigana": "wǒ men de jì huà hěn jiǎn dān yì jí měi tiān xué xí yí gè xiǎo shí", "sentence_source": "generated"}, {"text": "我的生日，亦即五月一日，正好是假日。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡，亦即南方的一个小城，非常美。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一小时，亦即六十分钟，足够做完这件事。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的目标，亦即今年的任务，是学好汉语。", "target_word": "亦即", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面用语，放在名词或短语后，点明它具体指什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b192761-8a5e-44d0-af8b-6677718ed4de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亦即", "is_correct": true, "explanation": "亦即：连词，书面用语，意为“也就是”，是正确答案。"}, {"text": "一季", "is_correct": false, "explanation": "“一”在第四声前读 yí，与 yì（第四声）声调不同；jì（第四声）与 jí（第二声）也不同，一季指一个季节。"}, {"text": "遗迹", "is_correct": false, "explanation": "yí（第二声）与 yì（第四声）声调不同，jì（第四声）与 jí（第二声）也不同，遗迹指留下来的痕迹。"}, {"text": "密集", "is_correct": false, "explanation": "mì（第四声）与 yì（第四声）只有声母不同（m 与 y），意思是数量多而集中。"}, {"text": "异己", "is_correct": false, "explanation": "yì 相同，jǐ（第三声）与 jí（第二声）声调不同，异己指持不同意见的人。"}], "explanations": {"亦即": "亦即：连词，书面用语，意为“也就是”，是正确答案。", "一季": "“一”在第四声前读 yí，与 yì（第四声）声调不同；jì（第四声）与 jí（第二声）也不同，一季指一个季节。", "遗迹": "yí（第二声）与 yì（第四声）声调不同，jì（第四声）与 jí（第二声）也不同，遗迹指留下来的痕迹。", "密集": "mì（第四声）与 yì（第四声）只有声母不同（m 与 y），意思是数量多而集中。", "异己": "yì 相同，jǐ（第三声）与 jí（第二声）声调不同，异己指持不同意见的人。"}, "sentence_index": null, "correct_answer": "亦即"}, "level_3": {"options": [{"text": "亦即", "is_correct": true, "explanation": "亦即：连词，放在“立春”之后，点明它具体指“春天的开始”。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，“春天的开始”不是“立春”的结果。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，“立春”和“春天的开始”之间没有对比关系。"}, {"text": "即便", "is_correct": false, "explanation": "搭配：“即便”要和“也”或“就”配合表示让步，后面不能直接接名词性的解释。"}], "explanations": {"亦即": "亦即：连词，放在“立春”之后，点明它具体指“春天的开始”。", "因此": "语义：“因此”表示因果，“春天的开始”不是“立春”的结果。", "然而": "语义：“然而”表示转折，“立春”和“春天的开始”之间没有对比关系。", "即便": "搭配：“即便”要和“也”或“就”配合表示让步，后面不能直接接名词性的解释。"}, "sentence_index": 0, "correct_answer": "亦即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个周末我们可以去爬山，亦即去游泳。", "explanation": "这里应该用〈或者〉。“爬山”和“游泳”是两个可选项，亦即只点明前面具体指什么，不能表示选择。"}, {"text": "他会说英语，亦即会说法语。", "explanation": "这里应该用〈而且〉。“英语”和“法语”是两种不同的语言，亦即不能用来补充说明并列的事情。"}, {"text": "这个菜很好吃，亦即有点咸。", "explanation": "这里应该用〈不过〉。“好吃”和“有点咸”是前后转折的关系，亦即不能这样连接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亦即", "is_correct": true, "explanation": "亦即：连词，书面用语，意为“也就是”，是正确答案。"}, {"text": "益己", "is_correct": false, "explanation": "yì 相同，jǐ（第三声）与 jí（第二声）声调不同，益己指对自己有好处。"}, {"text": "雨季", "is_correct": false, "explanation": "yǔ（第三声）与 yì（第四声）声调不同，jì（第四声）与 jí（第二声）也不同，雨季指多雨的季节。"}, {"text": "意识", "is_correct": false, "explanation": "亦即的第二音节是 jí，意识的第二音节是 shí，两者声母不同，意思是对事物的觉察和认知。"}, {"text": "一击", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，jī（第一声）与 jí（第二声）也不同，一击指打一下。"}], "explanations": {"亦即": "亦即：连词，书面用语，意为“也就是”，是正确答案。", "益己": "yì 相同，jǐ（第三声）与 jí（第二声）声调不同，益己指对自己有好处。", "雨季": "yǔ（第三声）与 yì（第四声）声调不同，jì（第四声）与 jí（第二声）也不同，雨季指多雨的季节。", "意识": "亦即的第二音节是 jí，意识的第二音节是 shí，两者声母不同，意思是对事物的觉察和认知。", "一击": "yī（第一声）与 yì（第四声）声调不同，jī（第一声）与 jí（第二声）也不同，一击指打一下。"}, "sentence_index": null, "correct_answer": "亦即"}, "level_3": {"options": [{"text": "亦即", "is_correct": true, "explanation": "亦即：连词，放在“我的生日”之后，点明它具体指“五月一日”。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，“五月一日”不是“我的生日”的结果。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，“我的生日”和“五月一日”之间没有对比关系。"}, {"text": "甚至", "is_correct": false, "explanation": "语义：“甚至”表示程度递进，“我的生日”和“五月一日”之间没有递进关系。"}], "explanations": {"亦即": "亦即：连词，放在“我的生日”之后，点明它具体指“五月一日”。", "所以": "语义：“所以”表示因果，“五月一日”不是“我的生日”的结果。", "但是": "语义：“但是”表示转折，“我的生日”和“五月一日”之间没有对比关系。", "甚至": "语义：“甚至”表示程度递进，“我的生日”和“五月一日”之间没有递进关系。"}, "sentence_index": 6, "correct_answer": "亦即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我生病了，亦即没有去上课。", "explanation": "这里应该用〈所以〉。“生病”和“没去上课”是因果关系，亦即只用于换种说法解释，不表示因果。"}, {"text": "这家店很近，亦即很少有人来。", "explanation": "这里应该用〈然而〉。“很近”和“很少有人来”是转折关系，亦即不能表示转折。"}, {"text": "雨停了，亦即我们出发了。", "explanation": "这里应该用〈于是〉。“雨停了”和“我们出发了”是承接的关系，亦即不能表示这种承接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我最喜欢的运动，亦即了游泳，让我很放松。", "corrected_sentence": "我最喜欢的运动，亦即游泳，让我很放松。", "error_description": "错误：“亦即”后多加了“了”。“亦即”是连词，不能带“了”，应直接说“亦即游泳”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的老师，亦即的教我汉语的人，很有耐心。", "corrected_sentence": "我的老师，亦即教我汉语的人，很有耐心。", "error_description": "错误：“亦即”后面不能加“的”。正确应为“亦即教我汉语的人”，“亦即”后直接接解释的内容。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
