INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98203, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "亮相是第一次让大家看见。", "primary_collocate": null, "pronunciation": "liàng xiàng", "ipa": "li̯ɑŋ⁵¹ ɕi̯ɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这家公司的新手机下周亮相。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车在车展上亮相，吸引了很多人。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器人第一次亮相，大家都想看看。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的新产品昨天正式亮相了。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电影的海报今天亮相，朋友都在讨论。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新款电脑在展览上亮相，价格不贵。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小学生做的玩具在学校展览上亮相。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台新机器首次亮相，工人们都围过来看。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的新标志明年一月亮相。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新设计的校服在开学典礼上亮相。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亮相了", "label": "体标（了）"}], "register": "中性", "sense_fingerprint": "新事物首次让大家看见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bf78ee-7ce4-4c00-a5e3-c90623cde1b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98203, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亮相", "is_correct": true, "explanation": "亮相（liàng xiàng）为正确答案，指新事物首次让大家看见。"}, {"text": "两项", "is_correct": false, "explanation": "两项（liǎng xiàng）第一个音节为第三声，与 liàng 的第四声不同，意思是两个项目。"}, {"text": "良相", "is_correct": false, "explanation": "良相（liáng xiàng）第一个音节为第二声，与 liàng 的第四声不同，意思是贤良的宰相。"}, {"text": "粮饷", "is_correct": false, "explanation": "粮饷（liáng xiǎng）两个音节声调都与亮相不同，意思是军队的粮食和薪饷。"}, {"text": "两厢", "is_correct": false, "explanation": "两厢（liǎng xiāng）两个音节的声调都与亮相不同，意思是两边、双方。"}], "explanations": {"亮相": "亮相（liàng xiàng）为正确答案，指新事物首次让大家看见。", "两项": "两项（liǎng xiàng）第一个音节为第三声，与 liàng 的第四声不同，意思是两个项目。", "良相": "良相（liáng xiàng）第一个音节为第二声，与 liàng 的第四声不同，意思是贤良的宰相。", "粮饷": "粮饷（liáng xiǎng）两个音节声调都与亮相不同，意思是军队的粮食和薪饷。", "两厢": "两厢（liǎng xiāng）两个音节的声调都与亮相不同，意思是两边、双方。"}, "sentence_index": null, "correct_answer": "亮相"}, "level_3": {"options": [{"text": "亮相", "is_correct": true, "explanation": "正确：“亮相”指新事物首次让大家看见，符合“这家公司的新手机下周”的语境。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”只用于人，新手机不能退休，句子不通。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：“辞职”指人离开工作岗位，用于新手机说不通。"}, {"text": "道歉", "is_correct": false, "explanation": "搭配：“道歉”的主语须是人，不能与“新手机”搭配。"}], "explanations": {"亮相": "正确：“亮相”指新事物首次让大家看见，符合“这家公司的新手机下周”的语境。", "退休": "语义：“退休”只用于人，新手机不能退休，句子不通。", "辞职": "语义：“辞职”指人离开工作岗位，用于新手机说不通。", "道歉": "搭配：“道歉”的主语须是人，不能与“新手机”搭配。"}, "sentence_index": 0, "correct_answer": "亮相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项技术一直亮相，外人一概不知。", "explanation": "这里应该用〈保密〉。“亮相”指首次让大家看见，与“外人一概不知”相矛盾。"}, {"text": "这个旧杯子我家用了二十年，今天亮相了。", "explanation": "这里应该用〈拿出来〉。“亮相”指新事物第一次让大家看见，家里用了二十年的旧杯子不是新事物。"}, {"text": "这台机器在仓库里亮相，没有人能看到它。", "explanation": "这里“亮相”指第一次让大家看见，与“没有人能看到”相矛盾，应改用〈入库〉之类不涉及展示的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98203, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亮相", "is_correct": true, "explanation": "亮相（liàng xiàng）为正确答案，指新事物首次让大家看见。"}, {"text": "两相", "is_correct": false, "explanation": "两相（liǎng xiāng）第一个音节为第三声、第二个音节为第一声，与亮相（liàng xiàng）声调不同，意思是双方、彼此。"}, {"text": "良乡", "is_correct": false, "explanation": "良乡（liáng xiāng）第一个音节为第二声、第二个音节为第一声，与亮相声调不同，是北京的一个地名。"}, {"text": "两箱", "is_correct": false, "explanation": "两箱（liǎng xiāng）第一个音节为第三声、第二个音节为第一声，与亮相声调不同，意思是两个箱子。"}], "explanations": {"亮相": "亮相（liàng xiàng）为正确答案，指新事物首次让大家看见。", "两相": "两相（liǎng xiāng）第一个音节为第三声、第二个音节为第一声，与亮相（liàng xiàng）声调不同，意思是双方、彼此。", "良乡": "良乡（liáng xiāng）第一个音节为第二声、第二个音节为第一声，与亮相声调不同，是北京的一个地名。", "两箱": "两箱（liǎng xiāng）第一个音节为第三声、第二个音节为第一声，与亮相声调不同，意思是两个箱子。"}, "sentence_index": null, "correct_answer": "亮相"}, "level_3": {"options": [{"text": "亮相", "is_correct": true, "explanation": "正确：“亮相”指新事物首次让大家看见，符合“小学生做的玩具在学校展览上”的语境。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指人因公外出，玩具不能出差，句子不通。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，用来形容玩具在学校展览上语域不合，句子不通。"}, {"text": "上学", "is_correct": false, "explanation": "语义：“上学”指学生到学校学习，与“在学校展览上”的玩具语境不符。"}], "explanations": {"亮相": "正确：“亮相”指新事物首次让大家看见，符合“小学生做的玩具在学校展览上”的语境。", "出差": "语义：“出差”指人因公外出，玩具不能出差，句子不通。", "驾临": "语域：“驾临”是敬辞，用来形容玩具在学校展览上语域不合，句子不通。", "上学": "语义：“上学”指学生到学校学习，与“在学校展览上”的玩具语境不符。"}, "sentence_index": 6, "correct_answer": "亮相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套校服昨天亮相，前天就已经有人穿了。", "explanation": "这里“亮相”指第一次让大家看见，“前天就已经有人穿”说明早已被看见，二者相矛盾。"}, {"text": "这件玩具已经亮相过很多年，今年才第一次和孩子见面。", "explanation": "这里“亮相”指第一次让大家看见，“已经亮相过很多年”与“今年才第一次见面”自相矛盾。"}, {"text": "这套校服已经亮相十年了，大家都穿腻了。", "explanation": "这里“亮相”指第一次让大家看见，与“已经亮相十年”的时间说法相矛盾，已经存在多年的校服不能说“亮相”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这款新耳机下个月对展会上亮相。", "corrected_sentence": "这款新耳机下个月在展会上亮相。", "error_description": "引出亮相场所的介词用错。应说“在展会上亮相”，“对”不能引出亮相的地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台新电脑去年在展览上亮相了过，价格不贵。", "corrected_sentence": "这台新电脑去年在展览上亮相过，价格不贵。", "error_description": "错误：“了”和“过”不能同时用在“亮相”后，只保留“过”，应说“亮相过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
