INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98204, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公开露面；首次在公众面前出现。", "primary_collocate": null, "pronunciation": "liàng xiàng", "ipa": "li̯ɑŋ⁵¹ ɕi̯ɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "新来的歌手昨晚第一次在舞台上亮相。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位明星今天上午在发布会上亮相了。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队的新教练明天将在大家面前亮相。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王第一次在公司会议上亮相，有点紧张。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长很久没有公开亮相，大家都很担心。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员们穿着漂亮的衣服，在红地毯上亮相。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学今天在班里亮相，向大家问好。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老歌星多年后再次亮相，观众都很高兴。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，运动员一个一个上台亮相。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新队长在晚会上亮相，大家鼓掌欢迎。", "target_word": "亮相", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亮相了", "label": "体标（了）"}], "register": "中性", "sense_fingerprint": "人物首次在公众面前露面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bf78ee-7ce4-4c00-a5e3-c90623cde1b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98204, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亮相", "is_correct": true, "explanation": "亮相（liàng xiàng）为正确答案，指人物首次在公众面前露面。"}, {"text": "两项", "is_correct": false, "explanation": "两项（liǎng xiàng）第一个音节为第三声，与 liàng 的第四声不同，意思是两个项目。"}, {"text": "良相", "is_correct": false, "explanation": "良相（liáng xiàng）第一个音节为第二声，与 liàng 的第四声不同，意思是贤良的宰相。"}, {"text": "粮饷", "is_correct": false, "explanation": "粮饷（liáng xiǎng）两个音节声调都与亮相不同，意思是军队的粮食和薪饷。"}, {"text": "两厢", "is_correct": false, "explanation": "两厢（liǎng xiāng）两个音节的声调都与亮相不同，意思是两边、双方。"}], "explanations": {"亮相": "亮相（liàng xiàng）为正确答案，指人物首次在公众面前露面。", "两项": "两项（liǎng xiàng）第一个音节为第三声，与 liàng 的第四声不同，意思是两个项目。", "良相": "良相（liáng xiàng）第一个音节为第二声，与 liàng 的第四声不同，意思是贤良的宰相。", "粮饷": "粮饷（liáng xiǎng）两个音节声调都与亮相不同，意思是军队的粮食和薪饷。", "两厢": "两厢（liǎng xiāng）两个音节的声调都与亮相不同，意思是两边、双方。"}, "sentence_index": null, "correct_answer": "亮相"}, "level_3": {"options": [{"text": "亮相", "is_correct": true, "explanation": "正确：“亮相”指首次在公众面前露面，符合“第一次在舞台上”的语境。"}, {"text": "辞职", "is_correct": false, "explanation": "语义：“辞职”指离开工作岗位，与“在舞台上”的语境不符，句子不通。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指结束工作，与“新来的”“第一次”的语境矛盾。"}, {"text": "请假", "is_correct": false, "explanation": "搭配：“请假”不能用在“在舞台上”之后作谓语，句子不通。"}], "explanations": {"亮相": "正确：“亮相”指首次在公众面前露面，符合“第一次在舞台上”的语境。", "辞职": "语义：“辞职”指离开工作岗位，与“在舞台上”的语境不符，句子不通。", "退休": "语义：“退休”指结束工作，与“新来的”“第一次”的语境矛盾。", "请假": "搭配：“请假”不能用在“在舞台上”之后作谓语，句子不通。"}, "sentence_index": 0, "correct_answer": "亮相"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个人悄悄亮相，没有人知道他来过。", "explanation": "这里应该用〈现身〉。“亮相”是公开、首次露面，与“悄悄”“没有人知道”相矛盾。"}, {"text": "这家餐厅亮相了十年，老顾客很多。", "explanation": "这里应该用〈营业〉。“亮相”只指首次公开露面，用于一次性的出现，不能说持续十年的营业。"}, {"text": "他私下亮相，从不让人知道。", "explanation": "这里“亮相”指公开、首次出现在大众面前，与“私下”“从不让人知道”的隐秘含义矛盾，不能与“私下”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98204, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亮相", "is_correct": true, "explanation": "亮相（liàng xiàng）为正确答案，指人物首次在公众面前露面。"}, {"text": "两相", "is_correct": false, "explanation": "两相（liǎng xiāng）第一个音节为第三声、第二个音节为第一声，与亮相（liàng xiàng）声调不同，意思是双方、彼此。"}, {"text": "良乡", "is_correct": false, "explanation": "良乡（liáng xiāng）第一个音节为第二声、第二个音节为第一声，与亮相声调不同，是北京的一个地名。"}, {"text": "两箱", "is_correct": false, "explanation": "两箱（liǎng xiāng）第一个音节为第三声、第二个音节为第一声，与亮相声调不同，意思是两个箱子。"}], "explanations": {"亮相": "亮相（liàng xiàng）为正确答案，指人物首次在公众面前露面。", "两相": "两相（liǎng xiāng）第一个音节为第三声、第二个音节为第一声，与亮相（liàng xiàng）声调不同，意思是双方、彼此。", "良乡": "良乡（liáng xiāng）第一个音节为第二声、第二个音节为第一声，与亮相声调不同，是北京的一个地名。", "两箱": "两箱（liǎng xiāng）第一个音节为第三声、第二个音节为第一声，与亮相声调不同，意思是两个箱子。"}, "sentence_index": null, "correct_answer": "亮相"}, "level_3": {"options": [{"text": "亮相", "is_correct": true, "explanation": "正确：“亮相”指首次在公众面前露面，符合“新同学今天在班里”的语境。"}, {"text": "缺席", "is_correct": false, "explanation": "语义：“缺席”指不在场，与后句“向大家问好”相矛盾。"}, {"text": "退学", "is_correct": false, "explanation": "语义：“退学”指离开学校，与“在班里”“向大家问好”相矛盾。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，只用于尊贵的客人，用在同学身上语域不合，句子不通。"}], "explanations": {"亮相": "正确：“亮相”指首次在公众面前露面，符合“新同学今天在班里”的语境。", "缺席": "语义：“缺席”指不在场，与后句“向大家问好”相矛盾。", "退学": "语义：“退学”指离开学校，与“在班里”“向大家问好”相矛盾。", "驾临": "语域：“驾临”是敬辞，只用于尊贵的客人，用在同学身上语域不合，句子不通。"}, "sentence_index": 6, "correct_answer": "亮相"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位歌手上周已经亮相，今天才第一次出现在大家面前。", "explanation": "这里“亮相”只指首次公开露面，“上周已经亮相”与“今天才第一次出现”自相矛盾，应说〈露过面〉之类的表述。"}, {"text": "他在自己家里亮相，只有妈妈看见了。", "explanation": "这里应该用〈出现〉。“亮相”指在公众面前公开露面，自己家里只有妈妈看见，不是公开场合。"}, {"text": "这块石头在博物馆里亮相了，但谁也没见过。", "explanation": "这里“亮相”指公开露面，与“谁也没见过”相矛盾，应改用〈陈列〉之类表示展示的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位新人对音乐节上亮相，获得了不少关注。", "corrected_sentence": "这位新人在音乐节上亮相，获得了不少关注。", "error_description": "引出亮相场所的介词用错。应说“在音乐节上亮相”，“对”不能引出亮相的地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位老歌手去年在电视节目中亮相了过，很多人都还记得他。", "corrected_sentence": "那位老歌手去年在电视节目中亮相过，很多人都还记得他。", "error_description": "错误：“了”和“过”不能同时用在“亮相”后，只保留“过”，应说“亮相过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
