INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98207, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98207, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人口学是研究一个地方有多少人、有多少老人和小孩的学问。", "primary_collocate": null, "pronunciation": "rén kǒu xué", "ipa": "ʐən kʰou ɕɥe", "syllable_count": 3, "sentences": [{"text": "人口学研究一个地方有多少人。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在大学学人口学。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口学可以告诉我们老人和小孩有多少。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天给我们讲了人口学。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对人口学很感兴趣。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了人口学以后，我知道了城市里有多少老人。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口学书里有很多关于老人和小孩的数字。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的专业是人口学。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我借了一本人口学的书。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口学老师说，这个城市的小孩越来越少。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人口学家", "label": "复合词"}, {"form": "人口學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "研究一地人口多少和老幼情况的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c715073-07d3-4bb9-b479-83cb8d740dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98207, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物理学", "is_correct": false, "explanation": "语义：物理学研究物质和能量，不研究一个地方有多少人。"}, {"text": "人口学", "is_correct": true, "explanation": "正确：人口学研究一个地方的人口数量，与句意相符。"}, {"text": "化学", "is_correct": false, "explanation": "语义：化学研究物质的组成与变化，与人口多少无关。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“研究”后接学科或问题，“数字”不能作研究的主体。"}], "explanations": {"物理学": "语义：物理学研究物质和能量，不研究一个地方有多少人。", "人口学": "正确：人口学研究一个地方的人口数量，与句意相符。", "化学": "语义：化学研究物质的组成与变化，与人口多少无关。", "数字": "搭配：“研究”后接学科或问题，“数字”不能作研究的主体。"}, "sentence_index": 0, "correct_answer": "人口学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的表哥是个人口学，专门研究城市里的人数。", "explanation": "这里应该用〈人口学家〉。“人口学”指学科，指从事这门学科的人要用“人口学家”。"}, {"text": "这个城市的人口学很多。", "explanation": "这里应该用〈人口〉。“人口学”指学科，说人数多少要用“人口”。"}, {"text": "政府明年要进行一次人口学。", "explanation": "这里应该用〈人口普查〉。“人口学”指学科，全国性的人口调查要说“人口普查”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地质学", "is_correct": false, "explanation": "语义：地质学研究岩石和地层，书里不会有老人和小孩的数字。"}, {"text": "人口学", "is_correct": true, "explanation": "正确：人口学书研究人口，与“老人和小孩的数字”的内容相符。"}, {"text": "植物学", "is_correct": false, "explanation": "语义：植物学研究植物的构造和分类，与老人和小孩的人数无关。"}, {"text": "物理学", "is_correct": false, "explanation": "语义：物理学研究物质与运动规律，书里不会有老人和小孩的人数数字。"}], "explanations": {"地质学": "语义：地质学研究岩石和地层，书里不会有老人和小孩的数字。", "人口学": "正确：人口学书研究人口，与“老人和小孩的数字”的内容相符。", "植物学": "语义：植物学研究植物的构造和分类，与老人和小孩的人数无关。", "物理学": "语义：物理学研究物质与运动规律，书里不会有老人和小孩的人数数字。"}, "sentence_index": 6, "correct_answer": "人口学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人口学研究不同民族的文化和习俗。", "explanation": "这里应该用〈人类学〉。“人口学”研究人口的数量和分布，研究民族的文化和习俗属于人类学。"}, {"text": "他每天早上八点坐车去人口学上班。", "explanation": "这里应该用〈研究所〉。“人口学”指学科，不是上班的地点，应说“去人口研究所上班”。"}, {"text": "我每天都去人口学散步。", "explanation": "这里应该用〈公园〉。“人口学”是学科，不是能去散步的场所，应说“去公园散步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想学一本人口学。", "corrected_sentence": "我想学一门人口学。", "error_description": "“人口学”是学科，计量学科要用“门”，不用“本”（“本”用于书籍）。错误形式：一本人口学；正确形式：一门人口学。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前学了过人口学。", "corrected_sentence": "我以前学过人口学。", "error_description": "“了”和“过”都是动词后的体标记，不能同时用在“学”后面。多加的“了”是错误，正确形式只用“过”。错误形式：学了过人口学；正确形式：学过人口学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98208, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
