INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究人口数量、结构、分布及其变化规律的学科。", "primary_collocate": null, "pronunciation": "rén kǒu xué", "ipa": "ʐən kʰou ɕɥe", "syllable_count": 3, "sentences": [{"text": "人口学是一门研究人口变化的学科。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口学研究人口的数量和分布。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学有人口学专业。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口学要研究人口的结构。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一篇关于人口学的文章。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口学的研究方法包括调查和统计。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口学帮助政府了解人口变化的规律。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在人口学研究所工作。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人口学和经济学有很深的关系。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习人口学需要懂一点统计。", "target_word": "人口学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人口学家", "label": "复合词"}, {"form": "人口學", "label": "繁体"}], "register": "书面", "sense_fingerprint": "研究人口数量结构分布和变化规律的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c715073-07d3-4bb9-b479-83cb8d740dd8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天文学", "is_correct": false, "explanation": "语义：天文学研究天体，不研究人口变化。"}, {"text": "人口学", "is_correct": true, "explanation": "正确：人口学是研究人口变化的学科，与句意相符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪是做菜的技术，不研究人口变化。"}, {"text": "社会", "is_correct": false, "explanation": "搭配：“是一门……学科”要求学科名，“社会”不是学科名。"}], "explanations": {"天文学": "语义：天文学研究天体，不研究人口变化。", "人口学": "正确：人口学是研究人口变化的学科，与句意相符。", "烹饪": "语义：烹饪是做菜的技术，不研究人口变化。", "社会": "搭配：“是一门……学科”要求学科名，“社会”不是学科名。"}, "sentence_index": 0, "correct_answer": "人口学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她是一位人口学。", "explanation": "这里应该用〈人口学家〉。“人口学”指学科，指人要用“人口学家”。"}, {"text": "这座城市的人口学在去年减少了五万。", "explanation": "这里应该用〈人口〉。“人口学”指学科，说人数减少要用“人口”。"}, {"text": "人口学研究古代人的生活和文化。", "explanation": "这里应该用〈人类学〉。“人口学”研究人口的数量和分布，研究古代人的生活和文化属于人类学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气预报", "is_correct": false, "explanation": "语义：天气预报报告天气变化，不负责了解人口变化的规律。"}, {"text": "人口学", "is_correct": true, "explanation": "正确：人口学是研究人口规律的学科，能帮助政府了解人口变化，与句意相符。"}, {"text": "健身房", "is_correct": false, "explanation": "语义：健身房是锻炼身体的地方，与了解人口变化规律无关。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语化的闲话，不符合这句的书面语域。"}], "explanations": {"天气预报": "语义：天气预报报告天气变化，不负责了解人口变化的规律。", "人口学": "正确：人口学是研究人口规律的学科，能帮助政府了解人口变化，与句意相符。", "健身房": "语义：健身房是锻炼身体的地方，与了解人口变化规律无关。", "八卦": "语域：“八卦”是口语化的闲话，不符合这句的书面语域。"}, "sentence_index": 6, "correct_answer": "人口学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天都去人口学吃午饭。", "explanation": "这里应该用〈食堂〉。“人口学”是学科，不是能吃饭的场所，应说“去食堂吃午饭”。"}, {"text": "我们正在做人口学，要挨家挨户登记人数。", "explanation": "这里应该用〈人口普查〉。“人口学”指学科，挨家挨户登记人数的活动要说“人口普查”。"}, {"text": "我的邻居是一位人口学，每天骑车上班。", "explanation": "这里应该用〈人口学者〉。“人口学”指学科，指研究人口的人要说“人口学者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所大学新开了一本人口学。", "corrected_sentence": "这所大学新开了一门人口学。", "error_description": "“人口学”是学科，计量学科要用“门”，不用“本”（“本”用于书籍）。错误形式：一本人口学；正确形式：一门人口学。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前研究了过人口学。", "corrected_sentence": "我以前研究过人口学。", "error_description": "“了”和“过”都是动词后的体标记，不能同时用在“研究”后面。多加的“了”是错误，正确形式只用“过”。错误形式：研究了过人口学；正确形式：研究过人口学。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd33eb534-72d7-4470-b198-f48105b6d211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
