INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98211, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人质是被坏人抓住的人，坏人用他来逼别人听话。", "primary_collocate": null, "pronunciation": "rén zhì", "ipa": "ɻən˧˥ ʈʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "坏人抓了三个人质。", "target_word": "人质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察想办法救出了人质。", "target_word": "人质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人质一直很害怕。", "target_word": "人质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "坏人用人质要钱。", "target_word": "人质", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们把人质关在一个小房子里。", "target_word": "人质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个小女孩成了坏人的人质。", "target_word": "人质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察和坏人说话，希望他放了人质。", "target_word": "人质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人质的家人在外面等着消息。", "target_word": "人质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人手里还有两个人质，大家都很担心。", "target_word": "人质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最后，所有的人质都平安回家了。", "target_word": "人质", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名人质", "label": "量词"}, {"form": "人質", "label": "繁体"}, {"form": "人质危机", "label": "复合词"}], "register": "中性", "sense_fingerprint": "被坏人抓住、用来逼迫他人的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8eeb9b7-da00-4ad1-a443-5d1569c7e006') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98211, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人质", "is_correct": true, "explanation": "正确：人质 rén zhì，指被坏人抓住、用来要挟别人的人。"}, {"text": "任职", "is_correct": false, "explanation": "任职 rèn zhí 两个音节的声调都与 rén zhì 不同，意思是担任职务。"}, {"text": "认知", "is_correct": false, "explanation": "认知 rènzhī 两个音节的声调都与 rén zhì 不同，意思是认识、知道。"}, {"text": "人事", "is_correct": false, "explanation": "人事 rénshì 与 rén zhì 的声母不同：shì 是 sh，zhì 是 zh，声调相同，意思是人事、人员方面的事务。"}, {"text": "人字", "is_correct": false, "explanation": "人字 rénzì 与 rén zhì 的第二个音节声母不同：zì 是 z，zhì 是 zh，声调相同，意思是汉字“人”或人字形。"}], "explanations": {"人质": "正确：人质 rén zhì，指被坏人抓住、用来要挟别人的人。", "任职": "任职 rèn zhí 两个音节的声调都与 rén zhì 不同，意思是担任职务。", "认知": "认知 rènzhī 两个音节的声调都与 rén zhì 不同，意思是认识、知道。", "人事": "人事 rénshì 与 rén zhì 的声母不同：shì 是 sh，zhì 是 zh，声调相同，意思是人事、人员方面的事务。", "人字": "人字 rénzì 与 rén zhì 的第二个音节声母不同：zì 是 z，zhì 是 zh，声调相同，意思是汉字“人”或人字形。"}, "sentence_index": null, "correct_answer": "人质"}, "level_3": {"options": [{"text": "人质", "is_correct": true, "explanation": "正确：“抓了”的对象是人，人质是被坏人抓住的人，“三个”也能计量人。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“抓”的对象通常是人或动物，房子不能被抓。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以被抓住的人或物，句中所指的必须是人。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，不能被坏人抓住。"}], "explanations": {"人质": "正确：“抓了”的对象是人，人质是被坏人抓住的人，“三个”也能计量人。", "房子": "搭配：“抓”的对象通常是人或动物，房子不能被抓。", "天气": "语义：天气不是可以被抓住的人或物，句中所指的必须是人。", "作业": "语义：作业是学习任务，不能被坏人抓住。"}, "sentence_index": 0, "correct_answer": "人质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "售票员向人质收了车费。", "explanation": "这里应该用〈乘客〉。售票员收车费的对象是乘客；人质是被坏人扣押、用来要挟别人的人。"}, {"text": "这家公司新招了两百名人质。", "explanation": "这里应该用〈员工〉。公司招聘的对象是员工；人质是被坏人劫持、用来要挟别人的人。"}, {"text": "医院里住满了等着看病的人质。", "explanation": "这里应该用〈病人〉。在医院等着看病的人是病人；人质是被坏人抓住、用来要挟别人的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98211, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人质", "is_correct": true, "explanation": "正确：“放了”的对象是被扣押的人，句中只有人质符合句意。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不能被“放了”，句中要放的是被扣押的人。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“放了”一般不与“汽车”搭配，“希望他放了汽车”说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是身体器官，不能被“放了”，与句意无关。"}], "explanations": {"人质": "正确：“放了”的对象是被扣押的人，句中只有人质符合句意。", "名字": "语义：名字不能被“放了”，句中要放的是被扣押的人。", "汽车": "搭配：“放了”一般不与“汽车”搭配，“希望他放了汽车”说不通。", "眼睛": "语义：眼睛是身体器官，不能被“放了”，与句意无关。"}, "sentence_index": 6, "correct_answer": "人质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "难民营里住着三百名人质。", "explanation": "这里应该用〈难民〉。人质是被劫持、用来要挟别人的人；因战乱或灾害逃离家园的人称难民。"}, {"text": "警察抓了两名人质，正在审问。", "explanation": "这里应该用〈嫌疑人〉。警察抓来审问的人是嫌疑人；人质是被坏人劫持、用来要挟别人的人。"}, {"text": "这位人质每天在学校给学生上课。", "explanation": "这里应该用〈老师〉。在学校给学生上课的人是老师；人质是被坏人抓住、用来要挟别人的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "绑匪放了两只人质。", "corrected_sentence": "绑匪放了两名人质。", "error_description": "“人质”指人，计量时要用量词“名”或“个”，不能用“只”（“只”用于动物或成对物品中的一个）。错误形式：两只人质；正确形式：两名人质。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "救援队在凌晨救了出所有人质。", "corrected_sentence": "救援队在凌晨救出了所有人质。", "error_description": "补语位置错误：“出”是“救”的趋向补语，要紧跟动词，“了”接在“救出”后。应说“救出了所有人质”，不能说“救了出所有人质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98215, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98215, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98215, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "仍旧是和以前一样，没有变。", "primary_collocate": null, "pronunciation": "réng jiù", "ipa": "ʐɤŋ˧˥ tɕjoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "搬家以后，他仍旧每天骑自行车上班。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了十年，这条街仍旧没有变。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说了很多次，他仍旧不明白。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了一天，天空仍旧是灰色的。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然换了新手机，她仍旧用旧号码。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶仍旧住在那个小村子里。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回国多年，他仍旧喜欢吃家乡菜。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了两次，结果仍旧一样。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司搬走了，门口仍旧挂着旧牌子。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们仍旧常常见面，还是老样子。", "target_word": "仍旧", "complexity_tier": "T3", "furigana": "réng jiù", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示情况和以前一样，没有变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98215, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仍旧", "is_correct": true, "explanation": "仍旧：表示搬家以后骑车上班的习惯没有改变，与语境一致。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指自始至终一直如此，与“搬家以后”这一变化的语境冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“每天”的意思矛盾。"}, {"text": "刚", "is_correct": false, "explanation": "搭配：“刚”表示刚刚发生，不能与“每天”这种长期习惯搭配。"}], "explanations": {"仍旧": "仍旧：表示搬家以后骑车上班的习惯没有改变，与语境一致。", "从来": "语义：“从来”指自始至终一直如此，与“搬家以后”这一变化的语境冲突。", "偶尔": "语义：“偶尔”表示不经常，与“每天”的意思矛盾。", "刚": "搭配：“刚”表示刚刚发生，不能与“每天”这种长期习惯搭配。"}, "sentence_index": 0, "correct_answer": "仍旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他仍旧第一次来北京，什么都不熟悉。", "explanation": "这里把“仍旧”误当成单纯表示时间的副词，但它表示延续以前的状态，不能和表示以前从未发生的“第一次”搭配。"}, {"text": "他仍旧搬到了北京，现在在一家公司工作。", "explanation": "这里应该用〈后来〉。“仍旧”表示没有变化，“搬到了北京”是变化，二者不能搭配。"}, {"text": "最近他仍旧换了工作。", "explanation": "这里应该用〈又〉。“仍旧”表示没有变化，“换了工作”是变化，学习者常把它当成表示再次的“又”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仍旧", "is_correct": true, "explanation": "仍旧：表示回国多年后，他还是和以前一样喜欢吃家乡菜。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎发生某事，与“喜欢吃家乡菜”的意思不符。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示必要，不能用来修饰个人偏好，句子意思不通。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词连用，与肯定的“喜欢”不搭配。"}], "explanations": {"仍旧": "仍旧：表示回国多年后，他还是和以前一样喜欢吃家乡菜。", "差点": "语义：“差点”表示几乎发生某事，与“喜欢吃家乡菜”的意思不符。", "必须": "语义：“必须”表示必要，不能用来修饰个人偏好，句子意思不通。", "根本": "搭配：“根本”通常与否定词连用，与肯定的“喜欢”不搭配。"}, "sentence_index": 6, "correct_answer": "仍旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天才认识，他仍旧每天给我打电话。", "explanation": "这里把“仍旧”误当成表示经常、重复的副词，但它要求以前已经如此，“昨天才认识”说明没有以前。"}, {"text": "他刚见过我一次，仍旧天天来找我。", "explanation": "这里应该用〈开始〉。“仍旧”要求以前已经如此，“刚见过我一次”说明还没有形成持续的状态。"}, {"text": "城市经过改造，老房子仍旧变得崭新。", "explanation": "这里应该用〈重新〉。“仍旧”表示不变，“变得崭新”是变化，学习者常把它当成表示更新的“重新”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他仍旧的没有回家。", "corrected_sentence": "他仍旧没有回家。", "error_description": "“仍旧”是副词，后面不能加“的”。应说“仍旧没有回家”，不说“仍旧的没有回家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路仍旧仍旧很安静。", "corrected_sentence": "这条路仍旧很安静。", "error_description": "重复：“仍旧”只用一次，不能说“仍旧仍旧”。应说“仍旧很安静”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98216, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98216, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98216, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "依然；仍然，情况保持不变。", "primary_collocate": null, "pronunciation": "réng jiù", "ipa": "ʐɤŋ˧˥ tɕjoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "已经很晚了，他仍旧在办公室工作。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药以后，他仍旧觉得头疼。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都走了，她仍旧坐在教室里。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，我们仍旧决定继续走。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格涨了，来买东西的人仍旧很多。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬到了北京，仍旧常常给我写信。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了课，学生们仍旧讨论着那个问题。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天到了，公园里的花仍旧开着。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我等了一个小时，他仍旧没有来。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么多年过去了，那家小店仍旧很有名。", "target_word": "仍旧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示尽管有变化或阻碍，情况依然保持不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98216, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仍旧", "is_correct": true, "explanation": "仍旧：表示已经很晚了，他还是和平时一样在办公室工作。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎发生某事，与“在办公室工作”的描述不符，句子不通。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词连用，与肯定的“在办公室工作”不搭配。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸，与“已经很晚了还在工作”的描述不协调。"}], "explanations": {"仍旧": "仍旧：表示已经很晚了，他还是和平时一样在办公室工作。", "差点": "语义：“差点”表示几乎发生某事，与“在办公室工作”的描述不符，句子不通。", "根本": "搭配：“根本”通常与否定词连用，与肯定的“在办公室工作”不搭配。", "幸好": "语义：“幸好”表示庆幸，与“已经很晚了还在工作”的描述不协调。"}, "sentence_index": 0, "correct_answer": "仍旧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司刚成立，仍旧是老牌企业。", "explanation": "这里把“仍旧”误当成强调“本来就是”的副词，但它表示延续以前的状态，“刚成立”说明没有以前。"}, {"text": "他刚搬来这里，仍旧熟悉所有的街道。", "explanation": "这里应该用〈很快〉。“仍旧”要求以前已经如此，“刚搬来这里”说明还没有熟悉街道的过程。"}, {"text": "他刚买这辆车，仍旧开了三年。", "explanation": "“仍旧”要求以前已经如此，而“刚买这辆车”说明还没有那段时间，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仍旧", "is_correct": true, "explanation": "仍旧：下课以后，学生们还是和之前一样讨论着那个问题。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于劝阻或提醒，不能与“讨论着”这种陈述搭配。"}, {"text": "从未", "is_correct": false, "explanation": "搭配：“从未”需要与否定词连用，与肯定的“讨论着”不搭配。"}, {"text": "不必", "is_correct": false, "explanation": "语义：“不必”表示没有必要，与“学生们讨论”的描述相矛盾。"}], "explanations": {"仍旧": "仍旧：下课以后，学生们还是和之前一样讨论着那个问题。", "千万": "搭配：“千万”多用于劝阻或提醒，不能与“讨论着”这种陈述搭配。", "从未": "搭配：“从未”需要与否定词连用，与肯定的“讨论着”不搭配。", "不必": "语义：“不必”表示没有必要，与“学生们讨论”的描述相矛盾。"}, "sentence_index": 6, "correct_answer": "仍旧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他才来这里三天，仍旧每天都去图书馆。", "explanation": "这里把“仍旧”误当成单纯表示经常的副词，但它要求以前已经如此，“才来三天”说明还没有以前的习惯。"}, {"text": "这个包我昨天刚买，仍旧很旧。", "explanation": "这里误用了“仍旧”。它表示延续以前的状态，而“昨天刚买”说明还没有以前，与“很旧”矛盾。"}, {"text": "他刚转学到这所学校，仍旧是班里的老同学。", "explanation": "“仍旧”要求以前已经如此，而“刚转学到这所学校”说明还没有以前，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她仍旧的没有回复我的消息。", "corrected_sentence": "她仍旧没有回复我的消息。", "error_description": "“仍旧”是副词，后面不能加“的”。应说“仍旧没有回复”，不说“仍旧的没有回复”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的猫仍旧仍旧不喜欢洗澡。", "corrected_sentence": "我的猫仍旧不喜欢洗澡。", "error_description": "重复：“仍旧”只用一次，不能说“仍旧仍旧”。应说“仍旧不喜欢洗澡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
