INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98219, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98219, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "不管选哪一个都可以。", "primary_collocate": null, "pronunciation": "rèn yí gè", "ipa": "ɻən˥˩ i˧˥ kɤ˥˩", "syllable_count": 3, "sentences": [{"text": "这三个杯子，你选任一个都可以。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上有五个苹果，你吃任一个吧。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个房间都很干净，你住任一个都行。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任一个学生都能回答这个问题。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个路口你走任一个，都能到火车站。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以选任一个好朋友陪你去。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题很简单，你做任一个都行。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，任一个同学都可以来问问题。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个门都开着，你从任一个进去都行。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对任一个孩子都很好。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不管选哪一个都可以", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98219, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任一个", "is_correct": true, "explanation": "正确。“任一个”表示不论选哪一个都可以，与“你选……都可以”相符。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指全体人，不能作为从三个杯子中挑选的对象。"}, {"text": "任何人", "is_correct": false, "explanation": "搭配：“任何人”指人，不能与“三个杯子”这样的物品搭配。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，与句中指物的“杯子”冲突。"}], "explanations": {"任一个": "正确。“任一个”表示不论选哪一个都可以，与“你选……都可以”相符。", "大家": "语义：“大家”指全体人，不能作为从三个杯子中挑选的对象。", "任何人": "搭配：“任何人”指人，不能与“三个杯子”这样的物品搭配。", "谁": "语义：“谁”指人，与句中指物的“杯子”冲突。"}, "sentence_index": 0, "correct_answer": "任一个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在车站遇见任一个老朋友。", "explanation": "这里应该用〈某个〉。“任一个”表示不论哪一个都可以，不能用来指说话人遇见的特定老朋友。"}, {"text": "我手里拿的是任一个。", "explanation": "这里应该用〈这一个〉。“任一个”表示任选，不能指说话人手里确定拿着的那一个。"}, {"text": "我最喜欢任一个。", "explanation": "这里应该用〈那一个〉。“最喜欢”需要明确的对象，“任一个”表示无所谓选哪个，两者意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任一个", "is_correct": true, "explanation": "正确。“任一个”表示不论做哪一个都行，与“这些问题很简单”的语境相符。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指他人，与“问题”不是人，不能作为“做”的对象。"}, {"text": "人家", "is_correct": false, "explanation": "搭配：“人家”指他人，与“做”的对象“问题”搭配不当。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”指包括说话人在内的人群，不能作为“做”的对象。"}], "explanations": {"任一个": "正确。“任一个”表示不论做哪一个都行，与“这些问题很简单”的语境相符。", "别人": "语义：“别人”指他人，与“问题”不是人，不能作为“做”的对象。", "人家": "搭配：“人家”指他人，与“做”的对象“问题”搭配不当。", "咱们": "语义：“咱们”指包括说话人在内的人群，不能作为“做”的对象。"}, "sentence_index": 6, "correct_answer": "任一个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他最疼的孩子是任一个。", "explanation": "这里应该用〈某一个〉。“任一个”表示任选，不能用来指说话人心里已确定的孩子，指特定的一个要用〈某一个〉。"}, {"text": "任一个老师是我的班主任。", "explanation": "这里应该用〈这位〉。“任一个”指任选的人，不能用来指明说话人具体的班主任。"}, {"text": "弟弟昨天摔碎的是任一个杯子。", "explanation": "这里应该用〈那个〉。“任一个”表示不论哪一个都可以，不能用来指弟弟昨天确实摔碎的那个特定杯子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个碗都很干净，你拿任一个很都可以。", "corrected_sentence": "这几个碗都很干净，你拿任一个都可以。", "error_description": "副词误用：“任一个”与“都”之间多了“很”，“很”不能置于“都”前，应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个水果都很甜，你吃任一个个都行。", "corrected_sentence": "这几个水果都很甜，你吃任一个都行。", "error_description": "重复量词：“任一个”已经包含量词“个”，后面不能再加“个”，应改为“任一个都行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
