INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98220, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98220, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "不论哪一个；随便哪一个。", "primary_collocate": null, "pronunciation": "rèn yí gè", "ipa": "ɻən˥˩ i˧˥ kɤ˥˩", "syllable_count": 3, "sentences": [{"text": "这两个包都很好看，你买任一个我都喜欢。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任一个人都可以参加这个活动。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的题目有三个，你回答任一个就行。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你从这些礼物里挑任一个吧。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任一个办法都比不做好。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几个电话号码，打任一个都能找到他。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选任一个颜色，我都没有意见。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "任一个小朋友都不能一个人过马路。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们有两个出口，走任一个都不远。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请从五个题里做任一个就可以了。", "target_word": "任一个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不论哪一个、随便哪一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "任一个", "is_correct": true, "explanation": "正确。“任一个”表示不论哪一个都可以，与“你买……我都喜欢”相符。"}, {"text": "别人", "is_correct": false, "explanation": "语义：“别人”指他人，不是包，不能作为“买”的对象。"}, {"text": "咱们", "is_correct": false, "explanation": "搭配：“咱们”指我们，不能作为“买”的对象，与“两个包”不搭配。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”指人，与句中指物的“包”冲突。"}], "explanations": {"任一个": "正确。“任一个”表示不论哪一个都可以，与“你买……我都喜欢”相符。", "别人": "语义：“别人”指他人，不是包，不能作为“买”的对象。", "咱们": "搭配：“咱们”指我们，不能作为“买”的对象，与“两个包”不搭配。", "谁": "语义：“谁”指人，与句中指物的“包”冲突。"}, "sentence_index": 0, "correct_answer": "任一个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我最想要的是任一个洋娃娃。", "explanation": "这里应该用〈那个〉。“任一个”表示任选，不能用来表明“我最想要”的特定对象。"}, {"text": "我挑中了任一个。", "explanation": "这里应该用〈这个〉。“挑中”指选定某一个特定的，“任一个”表示无所谓选哪个，两者矛盾。"}, {"text": "我们班的第一名是任一个人。", "explanation": "这里应该用〈某一位〉。“任一个”表示任选，不能用来指“第一名”这个确定的人，指确定的某一位要用〈某一位〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "任一个", "is_correct": true, "explanation": "正确。“任一个”表示任选其中一种，与“没有意见”的语境相符。"}, {"text": "所有", "is_correct": false, "explanation": "语义：“所有”指全部，与“选”（挑其中一个）的意思冲突。"}, {"text": "整个", "is_correct": false, "explanation": "语义：“整个”指完整的全部，不能表示从中任选一种。"}, {"text": "每个", "is_correct": false, "explanation": "语义：“每个”指逐一的全部，与“选”其中一种的意思冲突。"}], "explanations": {"任一个": "正确。“任一个”表示任选其中一种，与“没有意见”的语境相符。", "所有": "语义：“所有”指全部，与“选”（挑其中一个）的意思冲突。", "整个": "语义：“整个”指完整的全部，不能表示从中任选一种。", "每个": "语义：“每个”指逐一的全部，与“选”其中一种的意思冲突。"}, "sentence_index": 6, "correct_answer": "任一个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请问任一个题最难？", "explanation": "这里应该用〈哪个〉。“任一个”表示任选，不能用来指明“最难”的特定题目。"}, {"text": "昨天任一个人来过我家。", "explanation": "这里应该用〈某个人〉。“任一个”表示任选，不能用来指昨天确实来过我家的特定的人，指特定的人要用〈某个人〉。"}, {"text": "老师刚刚表扬了任一个学生。", "explanation": "这里应该用〈那位〉。“任一个”表示任选，不能用来指老师刚刚表扬的那位特定学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个礼物都很精致，你挑任一个的都可以。", "corrected_sentence": "这几个礼物都很精致，你挑任一个都可以。", "error_description": "多余的助词：“任一个”后面不能加“的”，应说“你挑任一个都可以”，不能写成“任一个的都可以”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几个面包都很新鲜，你选任一个个都行。", "corrected_sentence": "这几个面包都很新鲜，你选任一个都行。", "error_description": "重复量词：“任一个”已经包含量词“个”，后面不能再加“个”，应改为“任一个都行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
