INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98223, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98223, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "位次是排队或比赛时，你排在第几个。", "primary_collocate": null, "pronunciation": "wèi cì", "ipa": "wei⁵¹ tsʰɨ⁵¹", "syllable_count": 2, "sentences": [{"text": "抽签以后，我的位次是第三个。", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队买票，你的位次在我后面。", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步比赛中，他的位次一直很靠前。", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问大家：你们的位次是第几？", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在队伍里的位次太靠后，等了很久。", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的位次是用抽签决定的。", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看看名单，你的位次在谁的前面？", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的位次靠前，所以先上场了。", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们按位次一个一个上车。", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到我了吗？我的位次是第十个。", "target_word": "位次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "排队或比赛时排在第几个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb946ea4-a520-4b59-879c-bf006e8ec368') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98223, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "位次", "is_correct": true, "explanation": "位次指排队或比赛时排在第几个，“是第三个”正好说明抽签后的顺序。"}, {"text": "分数", "is_correct": false, "explanation": "语义：分数不是排队的顺序，抽签后不会得到“第三个分数”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格没有“第几个”的说法，抽签不决定价格。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不能数成“第三个”，与“是第三个”不搭配。"}], "explanations": {"位次": "位次指排队或比赛时排在第几个，“是第三个”正好说明抽签后的顺序。", "分数": "语义：分数不是排队的顺序，抽签后不会得到“第三个分数”。", "价格": "语义：价格没有“第几个”的说法，抽签不决定价格。", "体温": "搭配：“体温”不能数成“第三个”，与“是第三个”不搭配。"}, "sentence_index": 0, "correct_answer": "位次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们的位次相差五岁。", "explanation": "这里应该用〈年龄〉。年龄以岁计，位次指排队的先后，不能说“相差几岁”。"}, {"text": "我们的位次在教室的前面。", "explanation": "这里应该用〈座位〉。座位指可以坐的地方，位次指排队的顺序，不能指地点。"}, {"text": "我们花了很长的位次才排到队尾。", "explanation": "这里应该用〈时间〉。时间表示时长，位次不能用来表示排队花了多久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98223, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "位次", "is_correct": true, "explanation": "位次指排列的顺序，“在谁的前面”正好说明排队的先后。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有前后顺序，名单上不能比较“在谁的前面”。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：字迹不能按前后排列，“在谁的前面”说不通。"}, {"text": "纸张", "is_correct": false, "explanation": "搭配：“纸张”不与“在谁的前面”搭配，名单上的顺序不是纸张的位置。"}], "explanations": {"位次": "位次指排列的顺序，“在谁的前面”正好说明排队的先后。", "颜色": "语义：颜色没有前后顺序，名单上不能比较“在谁的前面”。", "字迹": "语义：字迹不能按前后排列，“在谁的前面”说不通。", "纸张": "搭配：“纸张”不与“在谁的前面”搭配，名单上的顺序不是纸张的位置。"}, "sentence_index": 6, "correct_answer": "位次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离学校的位次很远。", "explanation": "这里应该用〈距离〉。距离指两地之间空间的远近，位次指顺序，不能表示远近。"}, {"text": "这件衣服的位次很便宜。", "explanation": "这里应该用〈价格〉。价格指商品的钱数，位次不能用来形容商品的价钱。"}, {"text": "他的位次有五十公斤重。", "explanation": "这里应该用〈体重〉。体重指人的重量，位次指排队或比赛的先后，不能用公斤计算。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "排队的时候，我的位次是他的后面。", "corrected_sentence": "排队的时候，我的位次在他的后面。", "error_description": "错误在于动词：表示位置关系要用“在”，应说“位次在他的后面”，不能用“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "排队买票，我的位次是五个。", "corrected_sentence": "排队买票，我的位次是第五个。", "error_description": "“位次”表示顺序，要用序数“第五个”，不能说“五个”，“五个”只表示数量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
