INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "低地是比旁边的地方矮一些的土地。", "primary_collocate": null, "pronunciation": "dī dì", "ipa": "ti⁵⁵ ti⁵¹", "syllable_count": 2, "sentences": [{"text": "村子在一块低地上，雨天容易积水。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那片低地比旁边的路矮很多。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨后，低地里全是水。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在低地上种了很多水稻。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把帐篷搭在高处，不要搭在低地。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有一片低地，草长得很绿。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从山上看，那块低地像一个小碗。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块低地比马路低半米。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在低地里玩水。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块低地的土很软，适合种菜。", "target_word": "低地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比旁边矮一些的一块土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb946ea4-a520-4b59-879c-bf006e8ec368') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98227, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "低地", "is_correct": true, "explanation": "低地：地势比旁边低的土地，是本题的正确答案。"}, {"text": "弟弟", "is_correct": false, "explanation": "dìdi 与 dīdì 两个音节的声调都不同，意思是弟弟。"}, {"text": "滴滴", "is_correct": false, "explanation": "dīdī 只有第二个音节声调不同（第一声与第四声），意思是滴滴（拟声词）。"}, {"text": "基地", "is_correct": false, "explanation": "jīdì 与 dīdì 只有声母不同（j 与 d），意思是基地。"}], "explanations": {"低地": "低地：地势比旁边低的土地，是本题的正确答案。", "弟弟": "dìdi 与 dīdì 两个音节的声调都不同，意思是弟弟。", "滴滴": "dīdī 只有第二个音节声调不同（第一声与第四声），意思是滴滴（拟声词）。", "基地": "jīdì 与 dīdì 只有声母不同（j 与 d），意思是基地。"}, "sentence_index": null, "correct_answer": "低地"}, "level_3": {"options": [{"text": "低地", "is_correct": true, "explanation": "低地：地势低，雨天水容易积在这里，与句意相符。"}, {"text": "高地", "is_correct": false, "explanation": "语义：高地地势高，水不易积存，与“雨天容易积水”矛盾。"}, {"text": "屋顶", "is_correct": false, "explanation": "语义：屋顶是房屋的顶部，村子不能建在一块屋顶上，与句意不符。"}, {"text": "山峰", "is_correct": false, "explanation": "搭配：“山峰”的量词是“座”，不说“一块山峰”。"}], "explanations": {"低地": "低地：地势低，雨天水容易积在这里，与句意相符。", "高地": "语义：高地地势高，水不易积存，与“雨天容易积水”矛盾。", "屋顶": "语义：屋顶是房屋的顶部，村子不能建在一块屋顶上，与句意不符。", "山峰": "搭配：“山峰”的量词是“座”，不说“一块山峰”。"}, "sentence_index": 0, "correct_answer": "低地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的事业在那段时间陷入了低地。", "explanation": "这里应该用〈低谷〉。低谷比喻事业、情绪等处于低落的时期；低地指地形上较低的土地，不用于比喻。"}, {"text": "这座楼的低地有一家超市。", "explanation": "这里应该用〈低层〉。低层指楼房较低的几层；低地指地面的低洼处，不能用来指楼层。"}, {"text": "这只碗的低地上有一道裂缝。", "explanation": "这里应该用〈碗底〉。碗底指碗的内底；低地指地面上比周围低的土地，不用于器物的底部。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98227, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "低地", "is_correct": true, "explanation": "低地：地势比旁边低的土地，是本题的正确答案。"}, {"text": "地底", "is_correct": false, "explanation": "dìdǐ 与 dīdì 声母韵母相同，只有声调不同，意思是地面以下深处。"}, {"text": "敌地", "is_correct": false, "explanation": "dídì 与 dīdì 只有第一个音节声调不同（第二声与第一声），意思是敌人占领的地方。"}, {"text": "低低", "is_correct": false, "explanation": "dīdī 与 dīdì 只有第二个音节声调不同（第一声与第四声），是形容词“低”的重叠，如“低低地说”。"}], "explanations": {"低地": "低地：地势比旁边低的土地，是本题的正确答案。", "地底": "dìdǐ 与 dīdì 声母韵母相同，只有声调不同，意思是地面以下深处。", "敌地": "dídì 与 dīdì 只有第一个音节声调不同（第二声与第一声），意思是敌人占领的地方。", "低低": "dīdī 与 dīdì 只有第二个音节声调不同（第一声与第四声），是形容词“低”的重叠，如“低低地说”。"}, "sentence_index": null, "correct_answer": "低地"}, "level_3": {"options": [{"text": "低地", "is_correct": true, "explanation": "低地：地势凹下，从山上看像一个小碗，与句意相符。"}, {"text": "平原", "is_correct": false, "explanation": "语义：平原地势平坦，不会像一个凹下去的小碗。"}, {"text": "山顶", "is_correct": false, "explanation": "语义：山顶处于最高处，是凸起的，不像凹下去的小碗。"}, {"text": "悬崖", "is_correct": false, "explanation": "搭配：“悬崖”不用量词“块”，应说“一道悬崖”或“一处悬崖”。"}], "explanations": {"低地": "低地：地势凹下，从山上看像一个小碗，与句意相符。", "平原": "语义：平原地势平坦，不会像一个凹下去的小碗。", "山顶": "语义：山顶处于最高处，是凸起的，不像凹下去的小碗。", "悬崖": "搭配：“悬崖”不用量词“块”，应说“一道悬崖”或“一处悬崖”。"}, "sentence_index": 6, "correct_answer": "低地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出身在社会低地。", "explanation": "这里应该用〈底层〉。底层指社会地位较低的阶层；低地指地形，不能用来说社会阶层。"}, {"text": "这家公司的股价跌到了低地。", "explanation": "这里应该用〈谷底〉。谷底比喻价格跌到的最低点；低地是地形名词，不用于描述价格。"}, {"text": "这双鞋的低地磨破了。", "explanation": "这里应该用〈鞋底〉。鞋底指鞋子下面的部分；低地指地面上比周围低的土地，不能指鞋的部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只低地的水排得很慢。", "corrected_sentence": "这块低地的水排得很慢。", "error_description": "量词错误：“低地”是一块土地，应用量词“块”，不能用“只”。正确说法是“这块低地的水排得很慢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水把那块低地淹。", "corrected_sentence": "雨水把那块低地淹了。", "error_description": "把字句错误：“把……淹”后需要带“了”或其他补语，应说“雨水把那块低地淹了”，不能只说“淹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
