INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98231, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "信息时代是人们用电脑和手机很快知道各种消息的时代。", "primary_collocate": null, "pronunciation": "xìn xī shí dài", "ipa": "ɕin˥˩ ɕi˥ ʂʐ̩˧˥ taɪ˥˩", "syllable_count": 4, "sentences": [{"text": "在信息时代，新闻几秒钟就传遍全国。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代里，我们每天都上网看消息。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说信息时代真快，什么都能查到。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代，坐在家里也能买东西。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个信息时代，不会上网很不方便。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代的年轻人喜欢在手机上读书。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在信息时代，朋友的消息马上就能知道。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代到了，学校也有了网课。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生活在信息时代，大家都离不开手机。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代的学生可以在网上问老师。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人们用电脑、手机很快获得各种消息的时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b192761-8a5e-44d0-af8b-6677718ed4de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98231, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信息时代", "is_correct": true, "explanation": "信息时代指人们很快获得消息的时代，与“新闻几秒钟就传遍全国”相符。"}, {"text": "古代", "is_correct": false, "explanation": "语义：古代指过去的时代，与“新闻几秒钟就传遍全国”矛盾。"}, {"text": "石器时代", "is_correct": false, "explanation": "语义：石器时代是远古时期，与“几秒钟传遍全国”不合。"}, {"text": "草原", "is_correct": false, "explanation": "搭配：草原是地点，不是时代，“在草原”与句意不符。"}], "explanations": {"信息时代": "信息时代指人们很快获得消息的时代，与“新闻几秒钟就传遍全国”相符。", "古代": "语义：古代指过去的时代，与“新闻几秒钟就传遍全国”矛盾。", "石器时代": "语义：石器时代是远古时期，与“几秒钟传遍全国”不合。", "草原": "搭配：草原是地点，不是时代，“在草原”与句意不符。"}, "sentence_index": 0, "correct_answer": "信息时代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张表格里的信息时代很清楚。", "explanation": "这里表示表格里的具体内容，应该用〈数据〉。信息时代是时代名称，不能指表格中的内容。"}, {"text": "我们在做作业的信息时代不要玩手机。", "explanation": "这里应该用〈时间〉。〈时代〉指较长的历史阶段，做作业这样的短时段要用〈时间〉。"}, {"text": "这个孩子非常信息时代。", "explanation": "信息时代是名词，不能用程度副词“非常”修饰，这里的用法错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98231, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息时代", "is_correct": true, "explanation": "信息时代指人们很快获得消息的时代，与“朋友的消息马上就能知道”相符。"}, {"text": "清朝", "is_correct": false, "explanation": "语义：清朝没有手机和网络，朋友的消息不能马上知道，与句意矛盾。"}, {"text": "一百年前", "is_correct": false, "explanation": "语义：一百年前没有手机和网络，消息不可能马上知道，与句意矛盾。"}, {"text": "冰河时期", "is_correct": false, "explanation": "语义：冰河时期是远古时期，那时没有手机和网络，与“消息马上就能知道”矛盾。"}], "explanations": {"信息时代": "信息时代指人们很快获得消息的时代，与“朋友的消息马上就能知道”相符。", "清朝": "语义：清朝没有手机和网络，朋友的消息不能马上知道，与句意矛盾。", "一百年前": "语义：一百年前没有手机和网络，消息不可能马上知道，与句意矛盾。", "冰河时期": "语义：冰河时期是远古时期，那时没有手机和网络，与“消息马上就能知道”矛盾。"}, "sentence_index": 6, "correct_answer": "信息时代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很信息时代。", "explanation": "信息时代是名词，不能用程度副词“很”修饰，这里的用法错误。"}, {"text": "这道菜的信息时代很香。", "explanation": "这里应该用〈饭菜〉。信息时代是时代名称，不能作为食物的属性，不能说“很香”。"}, {"text": "信息时代生病了，我们去医院看它。", "explanation": "这里应该用〈小狗〉。信息时代是时代名称，没有生命，不会生病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98231, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一本信息时代，新闻传得很快。", "corrected_sentence": "这是一个信息时代，新闻传得很快。", "error_description": "错误：量词。“时代”应该用量词“个”，不能用“本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98231, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "信息时代得孩子可以在网上查资料。", "corrected_sentence": "信息时代的孩子可以在网上查资料。", "error_description": "错误：结构助词。“信息时代”修饰“孩子”时应用“的”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
