INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98232, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以信息的获取、传递和处理为主要特征的时代。", "primary_collocate": null, "pronunciation": "xìn xī shí dài", "ipa": "ɕin˥˩ ɕi˥ ʂʐ̩˧˥ taɪ˥˩", "syllable_count": 4, "sentences": [{"text": "我们生活在信息时代。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代的孩子从小就用手机。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在信息时代，学习新知识很方便。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代让世界变得越来越小。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，信息时代最重要的是会选择。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进入信息时代以后，工作方式变了。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代的老人也在学用手机。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代，每个人都能发表意见。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是信息时代的生活。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信息时代需要会用电脑的人。", "target_word": "信息时代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "以信息获取、传递和处理为特征的时代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b192761-8a5e-44d0-af8b-6677718ed4de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信息时代", "is_correct": true, "explanation": "信息时代是时代名称，可以用在“生活在”之后。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地点，不是时代，“生活在厨房”与语境不符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：数学是学科，不能作为“生活在”的地点或时代。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“生活在”后接时代或场所，“手机”不宜作为生活的环境。"}], "explanations": {"信息时代": "信息时代是时代名称，可以用在“生活在”之后。", "厨房": "语义：厨房是地点，不是时代，“生活在厨房”与语境不符。", "数学": "语义：数学是学科，不能作为“生活在”的地点或时代。", "手机": "搭配：“生活在”后接时代或场所，“手机”不宜作为生活的环境。"}, "sentence_index": 0, "correct_answer": "信息时代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告的信息时代很多，我看不完。", "explanation": "这里表示报告的具体内容，应该用〈内容〉。信息时代是时代名称，不能指某份报告里的内容。"}, {"text": "这个信息时代很干净。", "explanation": "这里应该用〈房间〉。信息时代是抽象的时代名称，不能用“很干净”来形容。"}, {"text": "她非常信息时代。", "explanation": "信息时代是名词，不能用程度副词“非常”修饰，这里的用法错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信息时代", "is_correct": true, "explanation": "信息时代修饰“老人”，表示老人所处的时代，语义通顺。"}, {"text": "童年", "is_correct": false, "explanation": "语义：童年指儿童时期，与“老人”的身份相矛盾。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能修饰“老人”表示所属时代或群体。"}, {"text": "幼儿园", "is_correct": false, "explanation": "搭配：“幼儿园”是机构名称，“幼儿园的老人”搭配不当。"}], "explanations": {"信息时代": "信息时代修饰“老人”，表示老人所处的时代，语义通顺。", "童年": "语义：童年指儿童时期，与“老人”的身份相矛盾。", "钢琴": "语义：钢琴是乐器，不能修饰“老人”表示所属时代或群体。", "幼儿园": "搭配：“幼儿园”是机构名称，“幼儿园的老人”搭配不当。"}, "sentence_index": 6, "correct_answer": "信息时代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事很信息时代。", "explanation": "信息时代是名词，不能用程度副词“很”修饰，这里的用法错误。"}, {"text": "我们班的信息时代今天考试得了满分。", "explanation": "这里应该用〈学生〉。信息时代是时代名称，不能参加考试，也不能得分。"}, {"text": "我花了两年的信息时代学习英语。", "explanation": "这里应该用〈时间〉。〈时代〉指较长的历史阶段，不能用来计算学习的时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只信息时代，人们学习很方便。", "corrected_sentence": "这是一个信息时代，人们学习很方便。", "error_description": "错误：量词。“时代”应该用量词“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "进入信息时代了以后，学习方式变了。", "corrected_sentence": "进入信息时代以后，学习方式变了。", "error_description": "错误：“了”的位置。“信息时代”后不能加“了”，应去掉，说“进入信息时代以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
