INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98235, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "传闻是大家一个传一个，听来的话，不一定是真的。", "primary_collocate": null, "pronunciation": "chuán wén", "ipa": "ʈʂʰwan˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "我听到一个传闻，说公司要搬家。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是传闻，不一定是真的。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里有个传闻，说山上有一只大熊。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于他的传闻很多，我一个也不信。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别信这些传闻，等老师说清楚再说。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有个有趣的传闻，大家都在议论。", "target_word": "传闻", "complexity_tier": "T3", "furigana": "xué xiào lǐ yǒu ge yǒu qù de chuán wén, dà jiā dōu zài yì lùn", "sentence_source": "generated"}, {"text": "这个传闻很快就传到了我耳朵里。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢听传闻，只相信自己看到的。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传闻中的那家饭馆终于开门了。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些传闻让大家很担心。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "大家互相传来传去、不一定是真的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98235, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“听到”后接的是声音或话语，“颜色”不能被听到。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是虚构的作品，不会“说公司要搬家”。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：菜谱讲的是做菜的步骤，不会说公司要搬家。"}, {"text": "传闻", "is_correct": true, "explanation": "正确：“传闻”指听来的、不一定真的消息，与“听到一个……说公司要搬家”相符。"}], "explanations": {"颜色": "搭配：“听到”后接的是声音或话语，“颜色”不能被听到。", "小说": "语义：小说是虚构的作品，不会“说公司要搬家”。", "菜谱": "语义：菜谱讲的是做菜的步骤，不会说公司要搬家。", "传闻": "正确：“传闻”指听来的、不一定真的消息，与“听到一个……说公司要搬家”相符。"}, "sentence_index": 0, "correct_answer": "传闻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个传闻是一位画家画的风景画，挂在博物馆里。", "explanation": "这里应该用〈作品〉。传闻是辗转流传、未经证实的消息，不是绘画作品，不能挂在博物馆里。"}, {"text": "这只传闻很有意思，你听说了吗？", "explanation": "这里应该用〈条〉。传闻的量词是“条”，“只”用于动物等，不用于传闻。"}, {"text": "这条传闻是中国古代的重要典籍，书中记载了很多历史事件。", "explanation": "这里应该用〈典籍〉。传闻是口头辗转流传、未经证实的消息，不是书籍，不能说是典籍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香味", "is_correct": false, "explanation": "搭配：“传到耳朵里”需要声音或话语，“香味”是用鼻子闻的，不能传到耳朵。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是物体，不是可以“传到耳朵里”的声音或消息，句子不成立。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以“传到耳朵里”的消息，句子不成立。"}, {"text": "传闻", "is_correct": true, "explanation": "正确：传闻是辗转流传、听来的消息，可以“传到耳朵里”，与句意相符。"}], "explanations": {"香味": "搭配：“传到耳朵里”需要声音或话语，“香味”是用鼻子闻的，不能传到耳朵。", "石头": "语义：石头是物体，不是可以“传到耳朵里”的声音或消息，句子不成立。", "天气": "语义：天气不是可以“传到耳朵里”的消息，句子不成立。", "传闻": "正确：传闻是辗转流传、听来的消息，可以“传到耳朵里”，与句意相符。"}, "sentence_index": 6, "correct_answer": "传闻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校发了一个传闻，明天放假。", "explanation": "这里应该用〈通知〉。学校发出的是正式通知；传闻是未经证实的消息，不能由学校正式发出。"}, {"text": "他给我提了一个传闻，希望我采纳。", "explanation": "这里应该用〈建议〉。“提”与“采纳”搭配的是建议，传闻不能被“提”出来供人采纳。"}, {"text": "这个传闻的作者是一位科学家，他发表了一篇论文。", "explanation": "这里应该用〈论文〉。传闻是辗转流传、未经证实的消息，不是科学家发表的学术成果，不能有“作者”，也不能“发表”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我听到一只传闻，说学校要放假。", "corrected_sentence": "我听到一条传闻，说学校要放假。", "error_description": "错误：“传闻”的量词用了“只”。“只”用于动物等，应为“条”：“一条传闻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我听过两传闻，都没有证实。", "corrected_sentence": "我听过两条传闻，都没有证实。", "error_description": "错误：数词“两”后漏了量词“条”。应为“两条传闻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
