INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98236, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98236, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "辗转流传的消息，真实性未经证实。", "primary_collocate": null, "pronunciation": "chuán wén", "ipa": "ʈʂʰwan˧˥ wən˧˥", "syllable_count": 2, "sentences": [{"text": "有传闻说，那位歌手要来我们城市开音乐会。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的传闻还没有得到证实。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传闻没有人能证明是真的。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司老板要换人的传闻传了很久。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说这些传闻都是假的。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司要关门的传闻是真的吗？", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者想弄清楚这个传闻是不是真的。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "传闻越传越多，越传越奇怪。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这些传闻一点也不在意。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有关这座老房子的传闻，我听过好几个。", "target_word": "传闻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "辗转流传、真实性未经证实的消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7155aefb-858f-446a-814e-20518e39b4af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会说话，不能“说”那位歌手要来开音乐会。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有……说”的主语应是人或消息，“颜色”不能用于这一结构。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不会说话，不能“说”这件事。"}, {"text": "传闻", "is_correct": true, "explanation": "正确：“有传闻说”是常见说法，表示辗转听来、未经证实的消息，与句意相符。"}], "explanations": {"石头": "语义：石头不会说话，不能“说”那位歌手要来开音乐会。", "颜色": "搭配：“有……说”的主语应是人或消息，“颜色”不能用于这一结构。", "天气": "语义：天气是自然现象，不会说话，不能“说”这件事。", "传闻": "正确：“有传闻说”是常见说法，表示辗转听来、未经证实的消息，与句意相符。"}, "sentence_index": 0, "correct_answer": "传闻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个传闻能证明他说的是真的。", "explanation": "这里应该用〈证据〉。传闻未经证实，不能用来证明事实，应该说“证据能证明”。"}, {"text": "这座传闻传了很久，说公司老板要换人。", "explanation": "这里应该用〈条〉。传闻的量词是“条”，“座”用于山、桥、楼等。"}, {"text": "公司制定了一个传闻。", "explanation": "这里应该用〈计划〉。“制定”的对象应是计划、方案，传闻不能被制定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景物，不是可以“是不是真的”的消息。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“是不是真的”一般用于消息、说法，“饭菜”不搭配这一结构。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是食物，不是可以辨别真假的消息，句子不成立。"}, {"text": "传闻", "is_correct": true, "explanation": "正确：“传闻”指未经证实的消息，记者要弄清楚它是否属实，与句意相符。"}], "explanations": {"天空": "语义：天空是自然景物，不是可以“是不是真的”的消息。", "饭菜": "搭配：“是不是真的”一般用于消息、说法，“饭菜”不搭配这一结构。", "早餐": "语义：早餐是食物，不是可以辨别真假的消息，句子不成立。", "传闻": "正确：“传闻”指未经证实的消息，记者要弄清楚它是否属实，与句意相符。"}, "sentence_index": 6, "correct_answer": "传闻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "昨天的传闻是一场精彩的足球比赛。", "explanation": "这里应该用〈比赛〉。传闻是消息，不是比赛，不能说是“一场精彩的足球比赛”。"}, {"text": "科学家得出了一个传闻。", "explanation": "这里应该用〈结论〉。“得出”的对象是结论、答案，传闻不能被“得出”。"}, {"text": "这段传闻是他画的一幅油画，挂在客厅里。", "explanation": "这里应该用〈油画〉。传闻是辗转流传的消息，不是绘画作品，不能是他画的，也不能挂在客厅里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我听过几传闻，都没有证实。", "corrected_sentence": "我听过几条传闻，都没有证实。", "error_description": "错误：数词“几”后漏了量词“条”。应为“几条传闻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我听过很多关于他传闻。", "corrected_sentence": "我听过很多关于他的传闻。", "error_description": "错误：“关于他”修饰“传闻”时漏了“的”。应为“关于他的传闻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd40ad437-0878-481d-8f89-2f2e125e981e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
