INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98243, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "恶劣", "is_correct": true, "explanation": "与“优越”构成反义：指条件或环境差、不好。"}, {"text": "清晰", "is_correct": false, "explanation": "与“优越”无反义关系：清晰指明白、分明，与条件的好坏无关。"}, {"text": "顺利", "is_correct": false, "explanation": "与“优越”无反义关系：顺利指进展没有阻碍，不是条件的对立面。"}, {"text": "响亮", "is_correct": false, "explanation": "与“优越”无反义关系：响亮指声音大而清楚，与条件无关。"}], "correct_answer": "恶劣", "explanations": {"恶劣": "与“优越”构成反义：指条件或环境差、不好。", "清晰": "与“优越”无反义关系：清晰指明白、分明，与条件的好坏无关。", "顺利": "与“优越”无反义关系：顺利指进展没有阻碍，不是条件的对立面。", "响亮": "与“优越”无反义关系：响亮指声音大而清楚，与条件无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98243, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "优越是比别的地方更好，条件很好。", "primary_collocate": null, "pronunciation": "yōu yuè", "ipa": "joʊ˥ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个小区的交通条件很优越。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的学校有优越的学习环境。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的自然条件十分优越。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个海岛的位置很优越。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山下的村子水源条件很优越。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住的地方比我们的优越多了。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大城市的医疗条件比小地方优越。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园的环境优越，空气也很好。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的位置优越，坐地铁五分钟就到。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的生活环境很优越，人们住得很舒服。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "优越：形容某个地方或环境比别处更好，条件很好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98243, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忧郁", "is_correct": false, "explanation": "yù（韵母 ü）与 yuè（韵母 üe）只差一个 e 音，且声调不同。忧郁的意思是心情低落、郁闷。"}, {"text": "优越", "is_correct": true, "explanation": "正确：优越 yōu yuè，形容某地方或环境比别处更好，条件很好。"}, {"text": "有约", "is_correct": false, "explanation": "yǒu（第三声）与 yōu（第一声）声调不同，yuē（第一声）与 yuè（第四声）声调也不同。有约的意思是约好了、有约会。"}, {"text": "犹豫", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，第二音节 yù 少了 e 音。犹豫的意思是拿不定主意。"}], "explanations": {"忧郁": "yù（韵母 ü）与 yuè（韵母 üe）只差一个 e 音，且声调不同。忧郁的意思是心情低落、郁闷。", "优越": "正确：优越 yōu yuè，形容某地方或环境比别处更好，条件很好。", "有约": "yǒu（第三声）与 yōu（第一声）声调不同，yuē（第一声）与 yuè（第四声）声调也不同。有约的意思是约好了、有约会。", "犹豫": "yóu（第二声）与 yōu（第一声）声调不同，第二音节 yù 少了 e 音。犹豫的意思是拿不定主意。"}, "sentence_index": null, "correct_answer": "优越"}, "level_3": {"options": [{"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容人或物的高度，交通条件不能说矮。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”指颜色，与交通条件的好坏无关。"}, {"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，不能用来形容交通条件。"}, {"text": "优越", "is_correct": true, "explanation": "正确：“优越”修饰条件，与“很”搭配，符合句意。"}], "explanations": {"矮": "体貌：“矮”形容人或物的高度，交通条件不能说矮。", "红": "语义：“红”指颜色，与交通条件的好坏无关。", "辣": "搭配：“辣”形容味道，不能用来形容交通条件。", "优越": "正确：“优越”修饰条件，与“很”搭配，符合句意。"}, "sentence_index": 0, "correct_answer": "优越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的数学成绩非常优越，年年都是第一名。", "explanation": "这里应该用〈优异〉。优越用于条件、地位、位置，成绩和表现要用优异。"}, {"text": "这次聚会很优越，大家都玩得很开心。", "explanation": "这里应该用〈热闹〉。优越不用来形容场面的热闹与否，聚会的氛围要用热闹。"}, {"text": "这位老师很优越，学生都很喜欢他。", "explanation": "这里应该用〈优秀〉。优越形容条件、位置，形容人的水平要用优秀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉", "is_correct": false, "explanation": "语义：“沉”指分量重，与医疗条件无关。"}, {"text": "满意", "is_correct": false, "explanation": "配价：“满意”的主体须是人，不能说医疗条件满意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的形体，医疗条件不能说高大。"}, {"text": "优越", "is_correct": true, "explanation": "正确：“比”字句中的“优越”表示大城市的医疗条件更好，符合句意。"}], "explanations": {"沉": "语义：“沉”指分量重，与医疗条件无关。", "满意": "配价：“满意”的主体须是人，不能说医疗条件满意。", "高大": "体貌：“高大”形容人或物的形体，医疗条件不能说高大。", "优越": "正确：“比”字句中的“优越”表示大城市的医疗条件更好，符合句意。"}, "sentence_index": 6, "correct_answer": "优越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的字写得很优越，每个字都很整齐。", "explanation": "这里应该用〈整齐〉。优越用于条件、位置、性能等，不用来形容书写的工整程度。"}, {"text": "我家到学校的距离很优越，要坐一个小时的车。", "explanation": "这里应该用〈远〉。优越不用来形容距离的远近。"}, {"text": "这把椅子的颜色很优越，我很喜欢。", "explanation": "这里应该用〈鲜艳〉。优越不用来形容颜色的鲜明程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个车站的交通条件很很优越。", "corrected_sentence": "这个车站的交通条件很优越。", "error_description": "错误：程度副词「很」重复叠用，多写了一个「很」。应只用一个「很」，说「很优越」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所幼儿园的户外条件很的优越。", "corrected_sentence": "这所幼儿园的户外条件很优越。", "error_description": "错误：副词“很”后面不能直接加结构助词“的”。应说“很优越”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98244, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低劣", "is_correct": true, "explanation": "与“优越”构成反义：优越指性能好，低劣指质量差。"}, {"text": "清晰", "is_correct": false, "explanation": "与“优越”无反义关系：清晰形容声音、图像等明白，与性能无关。"}, {"text": "辛苦", "is_correct": false, "explanation": "与“优越”无反义关系：辛苦指费力、劳累，不是性能的对立面。"}, {"text": "顺利", "is_correct": false, "explanation": "与“优越”无反义关系：顺利指进展没有阻碍，不用来说性能。"}], "correct_answer": "低劣", "explanations": {"低劣": "与“优越”构成反义：优越指性能好，低劣指质量差。", "清晰": "与“优越”无反义关系：清晰形容声音、图像等明白，与性能无关。", "辛苦": "与“优越”无反义关系：辛苦指费力、劳累，不是性能的对立面。", "顺利": "与“优越”无反义关系：顺利指进展没有阻碍，不用来说性能。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
