INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98244, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "优良；比一般的更好。", "primary_collocate": null, "pronunciation": "yōu yuè", "ipa": "joʊ˥ ɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这所学校的学习条件很优越。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的地理位置十分优越。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小生活在优越的环境里。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种手机的性能非常优越。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方的气候很优越，适合种茶。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司给我们提供了优越的工作条件。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的位置很优越，客人很多。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的经济条件比较优越。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过着优越的生活，什么都不缺。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的房子位置优越，价格也不便宜。", "target_word": "优越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "优越：形容条件、位置、环境、性能等优良，比一般的更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '405c76ef-3959-401d-a94b-7098e7dfd3e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98244, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "忧郁", "is_correct": false, "explanation": "yù（韵母 ü）与 yuè（韵母 üe）只差一个 e 音，且声调不同。忧郁的意思是心情低落、郁闷。"}, {"text": "优越", "is_correct": true, "explanation": "正确：优越 yōu yuè，形容条件、位置、环境、性能等优良，比一般的更好。"}, {"text": "有约", "is_correct": false, "explanation": "yǒu（第三声）与 yōu（第一声）声调不同，yuē（第一声）与 yuè（第四声）声调也不同。有约的意思是约好了、有约会。"}, {"text": "犹豫", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，第二音节 yù 少了 e 音。犹豫的意思是拿不定主意。"}], "explanations": {"忧郁": "yù（韵母 ü）与 yuè（韵母 üe）只差一个 e 音，且声调不同。忧郁的意思是心情低落、郁闷。", "优越": "正确：优越 yōu yuè，形容条件、位置、环境、性能等优良，比一般的更好。", "有约": "yǒu（第三声）与 yōu（第一声）声调不同，yuē（第一声）与 yuè（第四声）声调也不同。有约的意思是约好了、有约会。", "犹豫": "yóu（第二声）与 yōu（第一声）声调不同，第二音节 yù 少了 e 音。犹豫的意思是拿不定主意。"}, "sentence_index": null, "correct_answer": "优越"}, "level_3": {"options": [{"text": "辣", "is_correct": false, "explanation": "搭配：“辣”形容味道，不能用来形容学习条件。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，学习条件不能说高大。"}, {"text": "锋利", "is_correct": false, "explanation": "语义：“锋利”指刃口锐利，与学习条件的好坏不相容。"}, {"text": "优越", "is_correct": true, "explanation": "正确：“优越”修饰条件，与“很”搭配，符合句意。"}], "explanations": {"辣": "搭配：“辣”形容味道，不能用来形容学习条件。", "高大": "体貌：“高大”形容人或物的体型，学习条件不能说高大。", "锋利": "语义：“锋利”指刃口锐利，与学习条件的好坏不相容。", "优越": "正确：“优越”修饰条件，与“很”搭配，符合句意。"}, "sentence_index": 0, "correct_answer": "优越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名很优越的医生，病人都很信任他。", "explanation": "这里应该用〈优秀〉。优越多指条件、地位、环境等客观情况好，形容人的能力和水平要用优秀。"}, {"text": "这块地的面积很优越，足够盖三栋楼。", "explanation": "这里应该用〈大〉。优越用于条件、位置、性能等，不用来形容面积的大小，说面积大要用大。"}, {"text": "这场演出的表演很优越。", "explanation": "这里应该用〈精彩〉。优越用于条件、位置、性能，评价演出和表演的好坏要用精彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "满意", "is_correct": false, "explanation": "配价：“满意”的主体须是人，不能说饭店的位置满意。"}, {"text": "酸", "is_correct": false, "explanation": "语义：“酸”指味道，与饭店的位置无关。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能用来形容位置。"}, {"text": "优越", "is_correct": true, "explanation": "正确：“优越”修饰位置，与“很”搭配，符合句意。"}], "explanations": {"满意": "配价：“满意”的主体须是人，不能说饭店的位置满意。", "酸": "语义：“酸”指味道，与饭店的位置无关。", "聪明": "搭配：“聪明”形容人的智力，不能用来形容位置。", "优越": "正确：“优越”修饰位置，与“很”搭配，符合句意。"}, "sentence_index": 6, "correct_answer": "优越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个西瓜很优越，又甜又脆。", "explanation": "这里应该用〈甜〉。优越指条件、位置、性能等优良，形容水果的味道要用甜。"}, {"text": "这台冰箱的噪音很优越，晚上也不影响睡觉。", "explanation": "这里应该用〈小〉。优越用于条件、位置、性能等，不用来形容噪音的大小，说噪音小要用小。"}, {"text": "比赛开始前，现场的气氛很优越。", "explanation": "这里应该用〈紧张〉。优越不用来形容气氛，描述现场的紧张程度要用紧张。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套房子的采光很很优越。", "corrected_sentence": "这套房子的采光很优越。", "error_description": "错误：程度副词「很」重复叠用，多写了一个「很」。应只用一个「很」，说「很优越」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院的设备条件很的优越。", "corrected_sentence": "这家医院的设备条件很优越。", "error_description": "错误：副词“很”后面不能直接加结构助词“的”。应说“很优越”，去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd60d13a-136e-40a5-a0a4-75de0ccda112') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98247, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "不足：“充足”的反义词，指数量不够，与“够多、一点也不缺”正相反。"}, {"text": "辽阔", "is_correct": false, "explanation": "与“充足”无反义关系：“辽阔”形容面积大，与数量够不够无关。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“充足”无反义关系：“陡峭”形容地势，与数量无关。"}, {"text": "灿烂", "is_correct": false, "explanation": "与“充足”无反义关系：“灿烂”形容光彩明亮，与数量无关。"}], "correct_answer": "不足", "explanations": {"不足": "不足：“充足”的反义词，指数量不够，与“够多、一点也不缺”正相反。", "辽阔": "与“充足”无反义关系：“辽阔”形容面积大，与数量够不够无关。", "陡峭": "与“充足”无反义关系：“陡峭”形容地势，与数量无关。", "灿烂": "与“充足”无反义关系：“灿烂”形容光彩明亮，与数量无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98247, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "不足：“充足”的反义词，指数量不够，与“够多、一点也不缺”正相反。"}, {"text": "寂静", "is_correct": false, "explanation": "与“充足”无反义关系：“寂静”形容没有声音，与数量无关。"}, {"text": "沉重", "is_correct": false, "explanation": "与“充足”无反义关系：“沉重”形容重量大或心情压抑，与数量够不够无关。"}, {"text": "简单", "is_correct": false, "explanation": "与“充足”无反义关系：“简单”形容事情不复杂，与数量无关。"}], "correct_answer": "不足", "explanations": {"不足": "不足：“充足”的反义词，指数量不够，与“够多、一点也不缺”正相反。", "寂静": "与“充足”无反义关系：“寂静”形容没有声音，与数量无关。", "沉重": "与“充足”无反义关系：“沉重”形容重量大或心情压抑，与数量够不够无关。", "简单": "与“充足”无反义关系：“简单”形容事情不复杂，与数量无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98247, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "充足是够多，一点也不缺。", "primary_collocate": null, "pronunciation": "chōng zú", "ipa": "tʂʰʊŋ˥ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "山里的空气很新鲜，氧气也充足。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡眠充足，人才有精力。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察有充足的证据。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里有充足的牛奶。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里水源充足，人们不缺水。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有充足的时间做作业。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年夏天雨水充足，河里水很多。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校给孩子们准备了充足的饭菜。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为光线充足，照片拍得很清楚。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的粮食很充足，够吃一年。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "够多、一点也不缺（氧气、水源、粮食、证据等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b192761-8a5e-44d0-af8b-6677718ed4de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98247, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "充足", "is_correct": true, "explanation": "充足：形容词，指氧气数量够多、不缺少，与“空气很新鲜”一致。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的品质，不能用来形容氧气，“氧气也勇敢”搭配不当。"}, {"text": "干燥", "is_correct": false, "explanation": "搭配：“干燥”形容空气或土地的湿度，不用来形容氧气，“氧气也干燥”搭配不当。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼睛等透明的东西，不用来形容氧气，搭配不当。"}], "explanations": {"充足": "充足：形容词，指氧气数量够多、不缺少，与“空气很新鲜”一致。", "勇敢": "搭配：“勇敢”形容人的品质，不能用来形容氧气，“氧气也勇敢”搭配不当。", "干燥": "搭配：“干燥”形容空气或土地的湿度，不用来形容氧气，“氧气也干燥”搭配不当。", "清澈": "搭配：“清澈”形容水或眼睛等透明的东西，不用来形容氧气，搭配不当。"}, "sentence_index": 0, "correct_answer": "充足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑得很充足。", "explanation": "这里应该用〈快〉。充足只说数量够，不能用来形容动作的快慢，“跑得很快”才是自然的说法。"}, {"text": "我的心情很充足。", "explanation": "这里应该用〈愉快〉。充足只说数量够，不能用来形容心情，说心情要用“愉快”之类的词。"}, {"text": "这一周的成绩很充足。", "explanation": "这里应该用〈优秀〉。充足只说数量够，不能用来评价成绩的好坏，说成绩要用“优秀”之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98247, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充足", "is_correct": true, "explanation": "充足：形容词，指雨水数量够多，与“河里水很多”的结果一致。"}, {"text": "干涸", "is_correct": false, "explanation": "语义：“干涸”指河水枯竭，与后面“河里水很多”的描述相矛盾。"}, {"text": "稀罕", "is_correct": false, "explanation": "语义：“稀罕”指少见，与后面“河里水很多”的描述相矛盾。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不用来形容雨水的多少，“雨水清脆”搭配不当。"}], "explanations": {"充足": "充足：形容词，指雨水数量够多，与“河里水很多”的结果一致。", "干涸": "语义：“干涸”指河水枯竭，与后面“河里水很多”的描述相矛盾。", "稀罕": "语义：“稀罕”指少见，与后面“河里水很多”的描述相矛盾。", "清脆": "搭配：“清脆”形容声音，不用来形容雨水的多少，“雨水清脆”搭配不当。"}, "sentence_index": 6, "correct_answer": "充足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个子很充足，比同学都高。", "explanation": "这里不能用〈充足〉。个子是高矮，应说“高”，充足只说数量够。"}, {"text": "他的口音很充足，大家都有点听不懂。", "explanation": "这里应该用〈重〉。充足只说数量够，不能用来说口音的轻重，口音“很重”才是自然的说法。"}, {"text": "他的脾气很充足，大家都有点怕他。", "explanation": "这里不能用〈充足〉。脾气不说多少，充足不能用来形容性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98247, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她每天都有充足地睡眠，所以精神很好。", "corrected_sentence": "她每天都有充足的睡眠，所以精神很好。", "error_description": "错误：“充足”修饰名词“睡眠”时要用“的”，不能用“地”。“地”用来修饰动词。正确应为“充足的睡眠”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98247, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个仓库里的粮食没充足。", "corrected_sentence": "这个仓库里的粮食不充足。", "error_description": "错误：“充足”的否定要用“不”，“没”不能直接否定形容词“充足”。正确应为“不充足”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98248, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "不足：“充足”的反义词，指数量不够，与“数量足够，不缺少”正相反。"}, {"text": "清楚", "is_correct": false, "explanation": "与“充足”无反义关系：“清楚”指明白、不模糊，与数量多少无关。"}, {"text": "宽广", "is_correct": false, "explanation": "与“充足”无反义关系：“宽广”形容空间面积大，与数量够不够无关。"}, {"text": "坚硬", "is_correct": false, "explanation": "与“充足”无反义关系：“坚硬”形容物体质地，与数量无关。"}], "correct_answer": "不足", "explanations": {"不足": "不足：“充足”的反义词，指数量不够，与“数量足够，不缺少”正相反。", "清楚": "与“充足”无反义关系：“清楚”指明白、不模糊，与数量多少无关。", "宽广": "与“充足”无反义关系：“宽广”形容空间面积大，与数量够不够无关。", "坚硬": "与“充足”无反义关系：“坚硬”形容物体质地，与数量无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98248, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不足", "is_correct": true, "explanation": "不足：“充足”的反义词，指数量不够，与“数量足够，不缺少”正相反。"}, {"text": "明亮", "is_correct": false, "explanation": "与“充足”无反义关系：“明亮”形容光线强或颜色鲜明，与数量无关。"}, {"text": "柔软", "is_correct": false, "explanation": "与“充足”无反义关系：“柔软”形容物体质地，与数量多少无关。"}, {"text": "漫长", "is_correct": false, "explanation": "与“充足”无反义关系：“漫长”形容时间很长，与数量够不够无关。"}], "correct_answer": "不足", "explanations": {"不足": "不足：“充足”的反义词，指数量不够，与“数量足够，不缺少”正相反。", "明亮": "与“充足”无反义关系：“明亮”形容光线强或颜色鲜明，与数量无关。", "柔软": "与“充足”无反义关系：“柔软”形容物体质地，与数量多少无关。", "漫长": "与“充足”无反义关系：“漫长”形容时间很长，与数量够不够无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98248, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "数量足够，不缺少。", "primary_collocate": null, "pronunciation": "chōng zú", "ipa": "tʂʰʊŋ˥ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "这个房间阳光很充足。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家里的食物很充足，别担心。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的时间不太充足。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨晚睡眠充足，今天很有精神。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的资金非常充足。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机电量还充足，可以再用一天。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天雨水充足，庄稼长得好。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出发前，我们带的水很充足。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子要吃得好，营养才充足。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的货很充足，不用着急买。", "target_word": "充足", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量够多、不缺少（阳光、时间、资金等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b192761-8a5e-44d0-af8b-6677718ed4de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "充足", "is_correct": true, "explanation": "充足：形容词，指阳光数量够多、不缺少，与“阳光很”搭配自然。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的品质，不能用来形容阳光，“阳光很勇敢”搭配不当。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”形容空间，不能用来形容阳光，“阳光很狭窄”搭配不当。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体的厚度，不用来形容阳光，“阳光很厚”搭配不当。"}], "explanations": {"充足": "充足：形容词，指阳光数量够多、不缺少，与“阳光很”搭配自然。", "勇敢": "搭配：“勇敢”形容人的品质，不能用来形容阳光，“阳光很勇敢”搭配不当。", "狭窄": "搭配：“狭窄”形容空间，不能用来形容阳光，“阳光很狭窄”搭配不当。", "厚": "搭配：“厚”形容物体的厚度，不用来形容阳光，“阳光很厚”搭配不当。"}, "sentence_index": 0, "correct_answer": "充足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑得很充足。", "explanation": "这里应该用〈快〉。充足只说数量够，不能用来形容动作的快慢，“跑得很快”才是自然的说法。"}, {"text": "这批产品的质量很充足。", "explanation": "这里应该用〈优良〉。充足只说数量够，不用来说质量的好坏；说质量要用“优良”。"}, {"text": "他的口才很充足，大家都爱听他讲话。", "explanation": "这里应该用〈好〉。充足只说数量够，不能用来说口才的高低，说口才要用“好”之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "充足", "is_correct": true, "explanation": "充足：形容词，指雨水数量够多，与“庄稼长得好”的因果关系一致。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指缺水，与后面“庄稼长得好”的结果相矛盾。"}, {"text": "尖锐", "is_correct": false, "explanation": "搭配：“尖锐”形容物体或声音，不用来形容雨水，“雨水尖锐”搭配不当。"}, {"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”指数量少，与“庄稼长得好”的结果相矛盾。"}], "explanations": {"充足": "充足：形容词，指雨水数量够多，与“庄稼长得好”的因果关系一致。", "干燥": "语义：“干燥”指缺水，与后面“庄稼长得好”的结果相矛盾。", "尖锐": "搭配：“尖锐”形容物体或声音，不用来形容雨水，“雨水尖锐”搭配不当。", "稀少": "语义：“稀少”指数量少，与“庄稼长得好”的结果相矛盾。"}, "sentence_index": 6, "correct_answer": "充足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性格很充足，大家都喜欢他。", "explanation": "这里不能用〈充足〉。充足只说数量够多，不用来形容性格；说性格要用“开朗”之类的词。"}, {"text": "这首歌的速度很充足，听起来很舒服。", "explanation": "这里不能用〈充足〉。速度是快慢，应说“快”或“慢”，充足只说数量够。"}, {"text": "他的身高很充足，比同学都高。", "explanation": "这里不能用〈充足〉。身高是高矮，应说“高”，充足只说数量够，不说长度或高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间教室光线非常很充足。", "corrected_sentence": "这间教室光线很充足。", "error_description": "错误：程度副词重复。“非常”和“很”都表示程度，不能叠用，只用其一。正确应为“光线很充足”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学校的资金没充足。", "corrected_sentence": "这个学校的资金不充足。", "error_description": "错误：否定词用错。“没”不能用来否定形容词“充足”，形容词前应用“不”。正确应为“不充足”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e6c22de-54c0-4ce5-acf1-a8b98eda994e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
