INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98251, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98251, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "身体有抵抗病菌、病毒的力量，不容易因此生病。", "primary_collocate": null, "pronunciation": "miǎn yì", "ipa": "mjɛn˨˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "小明对水痘免疫，不会再得。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种疫苗让孩子对病毒免疫。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她得过那种病，现在对它免疫。", "target_word": "免疫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说你已经对麻疹免疫了。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷还没有对这种病免疫，要小心。", "target_word": "免疫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打针以后，大家都对这种病免疫了。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这种病毒免疫，所以没有生病。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗打过针，对这种病免疫。", "target_word": "免疫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你打了针，就对这种病免疫了。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的人大多对那种病免疫。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "免疫了", "label": "体标"}, {"form": "免疫力", "label": "复合"}, {"form": "免疫系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "身体有抵抗力，病菌病毒不容易使人生病，常说“对…免疫”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98251, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治疗", "is_correct": false, "explanation": "搭配：不说“对水痘治疗”，“治疗”要直接带“水痘”作宾语。"}, {"text": "免疫", "is_correct": true, "explanation": "正确：免疫指小明对水痘有了抵抗力，所以不会再得，与句中语境相合。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”与“水痘”搭配不通，“对水痘挖”说不清楚。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”与疾病不搭，“对水痘烧”句意不通。"}], "explanations": {"治疗": "搭配：不说“对水痘治疗”，“治疗”要直接带“水痘”作宾语。", "免疫": "正确：免疫指小明对水痘有了抵抗力，所以不会再得，与句中语境相合。", "挖": "语义：“挖”与“水痘”搭配不通，“对水痘挖”说不清楚。", "烧": "语义：“烧”与疾病不搭，“对水痘烧”句意不通。"}, "sentence_index": 0, "correct_answer": "免疫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士给孩子免疫了疫苗。", "explanation": "这里应该用〈接种〉。接种是给人打疫苗，免疫不能带疫苗作宾语。"}, {"text": "他昨天免疫了流感，烧得很厉害。", "explanation": "这里应该用〈感染〉。感染指病菌侵入身体，免疫指对病菌的抵抗力，不能用来描述发病。"}, {"text": "为了免疫生病，她每天洗手。", "explanation": "这里应该用〈避免〉。免疫指身体有抵抗力，防止生病要用“避免”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98251, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反对", "is_correct": false, "explanation": "语义：“反对”针对意见、计划或政策，不能用于病毒，“对这种病毒反对”句意不通。"}, {"text": "免疫", "is_correct": true, "explanation": "正确：免疫指他对病毒有了抵抗力，所以没有生病，与句中语境相合。"}, {"text": "咬", "is_correct": false, "explanation": "语义：病毒不能被“咬”，“对这种病毒咬”句意不通。"}, {"text": "吞", "is_correct": false, "explanation": "语义：病毒不能被“吞”，句子说不通。"}], "explanations": {"反对": "语义：“反对”针对意见、计划或政策，不能用于病毒，“对这种病毒反对”句意不通。", "免疫": "正确：免疫指他对病毒有了抵抗力，所以没有生病，与句中语境相合。", "咬": "语义：病毒不能被“咬”，“对这种病毒咬”句意不通。", "吞": "语义：病毒不能被“吞”，句子说不通。"}, "sentence_index": 6, "correct_answer": "免疫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服能免疫寒冷。", "explanation": "这里应该用〈抵御〉。免疫指身体对病原体的抵抗，衣服防寒要用“抵御”。"}, {"text": "人体的白细胞能免疫病菌。", "explanation": "这里应该用〈抵抗〉。免疫要说“对…免疫”，不能直接带病菌作宾语。"}, {"text": "这学期成绩好的同学可以免疫作业。", "explanation": "这里应该用〈免除〉。免疫指身体对病菌的抵抗力，免去作业要用“免除”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98251, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈说他把流感已经免疫了。", "corrected_sentence": "妈妈说他对流感已经免疫了。", "error_description": "错误：“免疫”的对象要用“对…”引出，“把”不能与“免疫”搭配。正确形式是“对流感免疫”，应使用“对”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98251, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子打过针，他给麻疹已经免疫了。", "corrected_sentence": "孩子打过针，他对麻疹已经免疫了。", "error_description": "错误：“免疫”的对象要用“对…”引出，不能用“给”。正确形式是“他对麻疹已经免疫了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
