INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98252, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98252, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "机体抵抗病原体侵害而不被感染。", "primary_collocate": null, "pronunciation": "miǎn yì", "ipa": "mjɛn˨˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "打了疫苗以后，他对这种病免疫了。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "得过水痘的人，一般会终身免疫。", "target_word": "免疫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这种病毒已经免疫了。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有人对所有的病都免疫。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打过疫苗的人对这种病免疫。", "target_word": "免疫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗还没有对这种病免疫，要打针。", "target_word": "免疫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这个孩子对麻疹免疫。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人得过一次这种病，就会对它免疫。", "target_word": "免疫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种疫苗能让人对麻疹免疫。", "target_word": "免疫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病变化很快，旧疫苗未必能让人免疫。", "target_word": "免疫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "免疫了", "label": "体标"}, {"form": "免疫力", "label": "复合"}, {"form": "免疫系统", "label": "复合"}], "register": "中性", "sense_fingerprint": "机体对某种病原体具有抵抗力而不被感染，常说“对…免疫”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab11b7c9-d5a8-4a17-9c0b-0279c3fa91db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "治疗", "is_correct": false, "explanation": "搭配：不说“对这种病治疗”，应说“治疗这种病”，“对…治疗”不通。"}, {"text": "免疫", "is_correct": true, "explanation": "正确：免疫指打了疫苗后对这种病有了抵抗力，与句中语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：疫苗是打进身体的，病不能被“吃”，句意不通。"}, {"text": "吐", "is_correct": false, "explanation": "语义：“吐”与“这种病”搭配不通，句子说不清楚。"}], "explanations": {"治疗": "搭配：不说“对这种病治疗”，应说“治疗这种病”，“对…治疗”不通。", "免疫": "正确：免疫指打了疫苗后对这种病有了抵抗力，与句中语境相合。", "吃": "语义：疫苗是打进身体的，病不能被“吃”，句意不通。", "吐": "语义：“吐”与“这种病”搭配不通，句子说不清楚。"}, "sentence_index": 0, "correct_answer": "免疫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药能帮助身体免疫细菌。", "explanation": "这里应该用〈抵抗〉。免疫要说“对…免疫”，不能直接带病菌作宾语，对细菌要说“抵抗”。"}, {"text": "学生可以免疫学费。", "explanation": "这里应该用〈免除〉。免疫指身体对病菌的抵抗力，免去学费要用“免除”。"}, {"text": "注射疫苗可以免疫感冒。", "explanation": "这里应该用〈预防〉。免疫要说“对…免疫”，防止感冒要用“预防”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：麻疹是一种疾病，不能被“欣赏”，句意不通。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”针对意见、计划或政策，不能用于疾病，“对麻疹反对”句意不通。"}, {"text": "免疫", "is_correct": true, "explanation": "正确：免疫指孩子对麻疹有了抵抗力，与“医生说”的语境相合。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”用于人或计划，不能对疾病放弃。"}], "explanations": {"欣赏": "语义：麻疹是一种疾病，不能被“欣赏”，句意不通。", "反对": "语义：“反对”针对意见、计划或政策，不能用于疾病，“对麻疹反对”句意不通。", "免疫": "正确：免疫指孩子对麻疹有了抵抗力，与“医生说”的语境相合。", "放弃": "语义：“放弃”用于人或计划，不能对疾病放弃。"}, "sentence_index": 6, "correct_answer": "免疫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校组织学生免疫疫苗。", "explanation": "这里应该用〈接种〉。接种是给人打疫苗的动作，免疫是身体的抵抗力，不能带疫苗作宾语。"}, {"text": "医生免疫了那个病人的伤口。", "explanation": "这里应该用〈治疗〉。免疫指对病原体不再感染，不能用来指处理伤口，要说“治疗”。"}, {"text": "为了免疫感冒，他经常锻炼。", "explanation": "这里应该用〈避免〉。免疫指身体有抵抗力，防止感冒要用“避免”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "接种以后，她把这种病免疫了。", "corrected_sentence": "接种以后，她对这种病免疫了。", "error_description": "错误：“免疫”的对象要用介词“对”引出，“把”不能用于“免疫”。正确形式是“对这种病免疫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经被水痘免疫了。", "corrected_sentence": "他已经对水痘免疫了。", "error_description": "错误：“免疫”要用“对…免疫”，“被”表示被动，与句意不符。正确形式是“他已经对水痘免疫了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '494d947b-f319-4c7d-a008-1ce9aea36414') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
