INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98255, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "内场是比赛场地里面靠中间的地方。", "primary_collocate": null, "pronunciation": "nèi chǎng", "ipa": "nei⁵¹ ʈʂʰaŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "运动员都站在内场里准备比赛。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑道围着内场转了一圈。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内场的草地上，有几个小朋友在踢球。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判请大家先走进内场。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内场很大，可以同时有两场比赛。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个体育场的内场铺着绿色的草。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，工作人员在内场画线。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑道在外面，内场在中间。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在内场里玩球，大人坐在外面。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众只能坐在外面，不能进内场。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "比赛场地里面靠中间的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb946ea4-a520-4b59-879c-bf006e8ec368') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98255, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内场", "is_correct": true, "explanation": "内场指比赛场地里面靠中间的地方，运动员在那里准备比赛，符合语境。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂不是比赛场地，运动员不会在食堂里准备比赛。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理业务的地方，与准备比赛无关。"}, {"text": "超市", "is_correct": false, "explanation": "搭配：“准备比赛”通常不在超市里进行，超市与比赛不搭配。"}], "explanations": {"内场": "内场指比赛场地里面靠中间的地方，运动员在那里准备比赛，符合语境。", "食堂": "语义：食堂不是比赛场地，运动员不会在食堂里准备比赛。", "银行": "语义：银行是办理业务的地方，与准备比赛无关。", "超市": "搭配：“准备比赛”通常不在超市里进行，超市与比赛不搭配。"}, "sentence_index": 0, "correct_answer": "内场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钱放在衣服的内场里。", "explanation": "这里应该用〈内袋〉。内场指比赛场地里面靠中间的地方，衣服里面的口袋应说“内袋”。"}, {"text": "我们在内场看电视。", "explanation": "这里应该用〈客厅〉。内场指比赛场地里面靠中间的地方，家里看电视的房间应说“客厅”。"}, {"text": "他在内场里理发。", "explanation": "这里应该用〈理发店〉。内场指比赛场地里面靠中间的地方，理发的地方应说“理发店”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98255, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内场", "is_correct": true, "explanation": "内场是比赛场地里面靠中间的地方，比赛前在那里画线符合语境。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋面积太大，比赛前不会在海洋上画线。"}, {"text": "夜空", "is_correct": false, "explanation": "语义：夜空不是可以画线的场地，与比赛前的画线无关。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不能与“画线”搭配，不能在时间上画线。"}], "explanations": {"内场": "内场是比赛场地里面靠中间的地方，比赛前在那里画线符合语境。", "海洋": "语义：海洋面积太大，比赛前不会在海洋上画线。", "夜空": "语义：夜空不是可以画线的场地，与比赛前的画线无关。", "时间": "搭配：“时间”不能与“画线”搭配，不能在时间上画线。"}, "sentence_index": 6, "correct_answer": "内场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块蛋糕的内场很甜。", "explanation": "这里应该用〈内部〉。内场指比赛场地里面靠中间的地方，食物的内部不能说“内场”。"}, {"text": "这个国家的内场很稳定。", "explanation": "这里应该用〈内阁〉。内场指比赛场地，国家的最高行政机构叫内阁，不能说“内场”。"}, {"text": "他在医院的内场工作。", "explanation": "这里应该用〈内科〉。内场指比赛场地，医院的内科是科室名称，工作在哪个科室应说“内科”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98255, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛开始前，裁判走了进内场。", "corrected_sentence": "比赛开始前，裁判走进了内场。", "error_description": "“走进”是动补结构，“了”应放在“进”之后，应说“走进了内场”，不能说“走了进内场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98255, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "运动员是内场里热身。", "corrected_sentence": "运动员在内场里热身。", "error_description": "“内场”表示地点，要用“在”，“是”不能表示动作发生的地方，应说“在内场里热身”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
