INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "场地中靠内的区域；也指棒球场的内野。", "primary_collocate": null, "pronunciation": "nèi chǎng", "ipa": "nei⁵¹ ʈʂʰaŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "棒球比赛时，他守在内场。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球落在内场，二垒手马上接住了。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内场的草比外场的短一些。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在内场接住了一个滚地球。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作人员正在整理内场的土。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个棒球场的内场很干净。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，内场里到处是水。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三垒手站在内场的左边。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球飞过内场，落到了外场。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众不能进入棒球场的内场。", "target_word": "内场", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "场地靠内的区域；棒球场的内野", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb946ea4-a520-4b59-879c-bf006e8ec368') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内场", "is_correct": true, "explanation": "内场指棒球场的内野，“守在内场”正符合棒球比赛的语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是比赛场地，与“棒球比赛时”冲突。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是读书的地方，与棒球比赛无关。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“守在”后面接的是比赛场地，教室与棒球比赛不搭配。"}], "explanations": {"内场": "内场指棒球场的内野，“守在内场”正符合棒球比赛的语境。", "厨房": "语义：厨房不是比赛场地，与“棒球比赛时”冲突。", "图书馆": "语义：图书馆是读书的地方，与棒球比赛无关。", "教室": "搭配：“守在”后面接的是比赛场地，教室与棒球比赛不搭配。"}, "sentence_index": 0, "correct_answer": "内场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个房间的内场很干净。", "explanation": "这里应该用〈内部〉。内场专指体育场地靠内的区域，房间的里面不叫“内场”。"}, {"text": "他的内场受伤了。", "explanation": "这里应该用〈内脏〉。内场指场地里面靠中间的区域，人身体里的器官应说“内脏”。"}, {"text": "这是我家门前的内场。", "explanation": "这里应该用〈院子〉。内场是体育场地的概念，家门前的空地应说“院子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内场", "is_correct": true, "explanation": "内场指场地靠内的区域，下雨后场地里积水，“内场里到处是水”符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空在上方，不会是“里面到处是水”。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是书，下雨不会让字典里到处是水。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“时间”不能与“到处是水”搭配，时间里不会有水。"}], "explanations": {"内场": "内场指场地靠内的区域，下雨后场地里积水，“内场里到处是水”符合语境。", "天空": "语义：天空在上方，不会是“里面到处是水”。", "字典": "语义：字典是书，下雨不会让字典里到处是水。", "时间": "搭配：“时间”不能与“到处是水”搭配，时间里不会有水。"}, "sentence_index": 6, "correct_answer": "内场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不太清楚这件事的内场。", "explanation": "这里应该用〈内情〉。内场指场地中靠内的区域，事情内部的真实情况应说“内情”。"}, {"text": "我的电脑内场不够了。", "explanation": "这里应该用〈内存〉。内场指场地，电脑的存储空间应说“内存”。"}, {"text": "别的国家不应该干涉我们的内场。", "explanation": "这里应该用〈内政〉。内场指场地中靠内的区域，国家内部的政治事务应说“内政”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "裁判是内场的中间。", "corrected_sentence": "裁判站在内场的中间。", "error_description": "“内场”是场所，要用“在”表示位置，应说“站在内场的中间”，不能用“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作人员已经把内场整理了好。", "corrected_sentence": "工作人员已经把内场整理好了。", "error_description": "“整理好”是动补结构，“了”应放在补语“好”之后，应说“整理好了”，不能说“整理了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1ec50922-1bb0-46cc-96dd-fe536769415b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
