INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98259, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两边是左边和右边这两个地方。", "primary_collocate": null, "pronunciation": "liǎng biān", "ipa": "ljɑŋ˨˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "路的两边都是树。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你站在门的两边。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河两边住着很多人。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了看两边，才过马路。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两边的商店都开着门。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子两边各放一把椅子。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街道两边有很多花。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发梳到两边。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐在中间，两边都是同学。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路时，要先看两边。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兩邊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "空间上的左右两侧，物体或道路的两旁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bf78ee-7ce4-4c00-a5e3-c90623cde1b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98259, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "两边", "is_correct": true, "explanation": "正确。“两边”指左右两侧，读作 liǎng biān。"}, {"text": "量变", "is_correct": false, "explanation": "liàng 与 liǎng 声调不同，biàn 与 biān 声调不同，意思是数量上的变化。"}, {"text": "两篇", "is_correct": false, "explanation": "piān 与 biān 声母不同（p 与 b），意思是两篇文章。"}, {"text": "两遍", "is_correct": false, "explanation": "biàn 与 biān 声调不同，意思是两次。"}], "explanations": {"两边": "正确。“两边”指左右两侧，读作 liǎng biān。", "量变": "liàng 与 liǎng 声调不同，biàn 与 biān 声调不同，意思是数量上的变化。", "两篇": "piān 与 biān 声母不同（p 与 b），意思是两篇文章。", "两遍": "biàn 与 biān 声调不同，意思是两次。"}, "sentence_index": null, "correct_answer": "两边"}, "level_3": {"options": [{"text": "两边", "is_correct": true, "explanation": "正确。“路的两边”指道路的左右两侧，与“都是树”相符。"}, {"text": "人", "is_correct": false, "explanation": "语义：“路的人”说不通，路上不能都是人，与“都是树”的描述矛盾。"}, {"text": "两者", "is_correct": false, "explanation": "语义：“两者”需有前文所指，且不能指路的两侧，“路的两者都是树”句意不通。"}, {"text": "车", "is_correct": false, "explanation": "语义：“路的车”说不通，句中说的是路旁的树，不是车。"}], "explanations": {"两边": "正确。“路的两边”指道路的左右两侧，与“都是树”相符。", "人": "语义：“路的人”说不通，路上不能都是人，与“都是树”的描述矛盾。", "两者": "语义：“两者”需有前文所指，且不能指路的两侧，“路的两者都是树”句意不通。", "车": "语义：“路的车”说不通，句中说的是路旁的树，不是车。"}, "sentence_index": 0, "correct_answer": "两边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两边都不肯让步，事情拖了很久。", "explanation": "这里是争论中双方的意思，不是道路或空间的左右两侧。"}, {"text": "这件事两边都有责任。", "explanation": "这里是争论中双方的意思，不是道路或空间的左右两侧。"}, {"text": "两边的意见不一样，我们再谈谈吧。", "explanation": "这里是争论中双方的意思，不是道路或空间的左右两侧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98259, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "两边", "is_correct": true, "explanation": "正确。“街道两边”指街道的左右两侧，与“有很多花”相符。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“街道学校”说不通，学校不是街道的位置，句意不合理。"}, {"text": "河", "is_correct": false, "explanation": "语义：“街道河”说不通，街道不是河流，句意不合理。"}, {"text": "班级", "is_correct": false, "explanation": "语义：“班级”是学校的编制单位，不能作街道的位置，“街道班级有很多花”句意不通。"}], "explanations": {"两边": "正确。“街道两边”指街道的左右两侧，与“有很多花”相符。", "学校": "语义：“街道学校”说不通，学校不是街道的位置，句意不合理。", "河": "语义：“街道河”说不通，街道不是河流，句意不合理。", "班级": "语义：“班级”是学校的编制单位，不能作街道的位置，“街道班级有很多花”句意不通。"}, "sentence_index": 6, "correct_answer": "两边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两边都让一步，问题就解决了。", "explanation": "这里是争论或关系中双方的意思，不是道路或空间的左右两侧。"}, {"text": "这次争吵，两边都有错。", "explanation": "这里是争论中双方的意思，不是道路或空间的左右两侧。"}, {"text": "我听了两边的话，才知道真相。", "explanation": "这里是争论中双方的意思，不是道路或空间的左右两侧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98259, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路的两边个都种着树。", "corrected_sentence": "路的两边都种着树。", "error_description": "错误：“两边”后面不能插入量词“个”，“都”应直接接在“两边”之后，正确说法是“路的两边都种着树”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98259, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "马路两边停了着很多车。", "corrected_sentence": "马路两边停着很多车。", "error_description": "错误：“了”和“着”不能同时用在“停”后，应去掉“了”，说“停着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
