INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "相对的两个方面或两侧。", "primary_collocate": null, "pronunciation": "liǎng biān", "ipa": "ljɑŋ˨˩ pjɛn˥", "syllable_count": 2, "sentences": [{"text": "这件事两边都有责任。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两边的意见不一样，我们再谈谈吧。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想得罪两边的人。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两边都说自己是对的。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架的时候，妈妈两边都劝。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛，两边的老师都来了。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两边的家人今天第一次见面。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸夹在两边，不知道帮谁。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听了两边的话，才知道真相。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两边都让一步，问题就解决了。", "target_word": "两边", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "兩邊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "相对的双方或两个方面，如争论、关系中的两方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4bf78ee-7ce4-4c00-a5e3-c90623cde1b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98260, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "两边", "is_correct": true, "explanation": "正确。“两边”指相对的双方，读作 liǎng biān。"}, {"text": "量变", "is_correct": false, "explanation": "liàng 与 liǎng 声调不同，biàn 与 biān 声调不同，意思是数量上的变化。"}, {"text": "两篇", "is_correct": false, "explanation": "piān 与 biān 声母不同（p 与 b），意思是两篇文章。"}, {"text": "两遍", "is_correct": false, "explanation": "biàn 与 biān 声调不同，意思是两次。"}], "explanations": {"两边": "正确。“两边”指相对的双方，读作 liǎng biān。", "量变": "liàng 与 liǎng 声调不同，biàn 与 biān 声调不同，意思是数量上的变化。", "两篇": "piān 与 biān 声母不同（p 与 b），意思是两篇文章。", "两遍": "biàn 与 biān 声调不同，意思是两次。"}, "sentence_index": null, "correct_answer": "两边"}, "level_3": {"options": [{"text": "两边", "is_correct": true, "explanation": "正确。“两边”指争论中的双方，与“都有责任”相符。"}, {"text": "前后", "is_correct": false, "explanation": "语义：“前后”指时间顺序，不指争论中的双方，与“都有责任”不搭。"}, {"text": "东西", "is_correct": false, "explanation": "语义：“东西”指方位或物品，不能指争论的双方，“这件事东西都有责任”句意不通。"}, {"text": "两手", "is_correct": false, "explanation": "语义：“两手”指人的两只手，不能指争论的双方，“这件事两手都有责任”句意不通。"}], "explanations": {"两边": "正确。“两边”指争论中的双方，与“都有责任”相符。", "前后": "语义：“前后”指时间顺序，不指争论中的双方，与“都有责任”不搭。", "东西": "语义：“东西”指方位或物品，不能指争论的双方，“这件事东西都有责任”句意不通。", "两手": "语义：“两手”指人的两只手，不能指争论的双方，“这件事两手都有责任”句意不通。"}, "sentence_index": 0, "correct_answer": "两边"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他两边吃饭两边看书。", "explanation": "这里应该用〈一边〉。“两边”指相对的双方或两侧，不表示同一人同时做的两件事，应说“一边吃饭一边看书”。"}, {"text": "他去医院两边都没见到医生。", "explanation": "这里应该用〈两次〉。“两边”指双方或两侧，不表示次数，去了两次应说“两次都没见到医生”。"}, {"text": "他两边一起拿着笔写字。", "explanation": "这里应该用〈双手〉。“两边”指相对的两方或两侧，不指一个人的两只手，应说“双手”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "两边", "is_correct": true, "explanation": "正确。“两边的家人”指争论或关系中双方的家人，与句意相符。"}, {"text": "左右", "is_correct": false, "explanation": "语义：“左右”指方位，不能指家人，句意说不通。"}, {"text": "南北", "is_correct": false, "explanation": "语义：“南北”指方位，不能指家人，与“第一次见面”不搭。"}, {"text": "两次", "is_correct": false, "explanation": "语义：“两次”表示次数，不能指双方，“两次的家人今天第一次见面”句意不通。"}], "explanations": {"两边": "正确。“两边的家人”指争论或关系中双方的家人，与句意相符。", "左右": "语义：“左右”指方位，不能指家人，句意说不通。", "南北": "语义：“南北”指方位，不能指家人，与“第一次见面”不搭。", "两次": "语义：“两次”表示次数，不能指双方，“两次的家人今天第一次见面”句意不通。"}, "sentence_index": 6, "correct_answer": "两边"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天两边都没吃饭，饿得不行。", "explanation": "这里应该用〈两顿〉。“两边”不表示次数，两顿都没吃应说“两顿都没吃”。"}, {"text": "他两边都会唱歌和跳舞。", "explanation": "这里应该用〈两样〉。“两边”指相对的双方或两侧，不指一个人的两种技能，应说“两样都会”。"}, {"text": "节日两边都很忙，大家都没有空。", "explanation": "这里应该用〈前后〉。“两边”不指时间的前后，应说“节日前后都很忙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个两边都愿意退一步，事情就好办了。", "corrected_sentence": "两边都愿意退一步，事情就好办了。", "error_description": "多加了“两个”。“两边”已含“两”，前面不能再加数量词，应说“两边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次争吵中，两边都都有不对的地方。", "corrected_sentence": "这次争吵中，两边都有不对的地方。", "error_description": "副词“都”重复了。“两边都”后面只用一个“都”，应说“两边都有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd19e4a69-9f8a-4683-b5b6-4c52d08c4bcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
