INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98264, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "再次作出保证。", "primary_collocate": null, "pronunciation": "zài bǎo zhèng", "ipa": "tsai˥˩ pɑʊ˨˩ ʈʂɤŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我再保证一次，明天一定准时到。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板问了三次，他再保证不会迟到。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不放心，我只好再保证一遍。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他再保证过，这件事一定办好。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，你要再保证一下。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理已经再保证了，大家可以放心。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭着再保证，以后不玩手机了。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天他保证了，今天再保证一次。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再保证一次，别再忘了。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人担心质量，老板再保证产品没问题。", "target_word": "再保证", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "再保证了", "label": "完成体"}, {"form": "再保证过", "label": "经历体"}, {"form": "再保證", "label": "繁体"}], "register": "口语", "sense_fingerprint": "在已经保证过之后，又一次正式作出保证", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4ec718-f884-4ff9-9343-ff0c14937f8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98264, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再保证", "is_correct": true, "explanation": "正确：“再保证”表示又一次作出保证，与“明天一定准时到”的承诺语境相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与“明天一定准时到”的承诺毫无关系，句子说不通。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”表达不满，与“保证准时到”的承诺语气不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“一次，明天一定准时到”的承诺毫无关系，句子说不通。"}], "explanations": {"再保证": "正确：“再保证”表示又一次作出保证，与“明天一定准时到”的承诺语境相符。", "吃饭": "语义：“吃饭”与“明天一定准时到”的承诺毫无关系，句子说不通。", "抱怨": "语义：“抱怨”表达不满，与“保证准时到”的承诺语气不符。", "唱歌": "语义：“唱歌”与“一次，明天一定准时到”的承诺毫无关系，句子说不通。"}, "sentence_index": 0, "correct_answer": "再保证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他第一次再保证，这件事一定办好。", "explanation": "这里应该用〈承诺〉。“再保证”表示又一次作出保证，句中是第一次许诺，不能用“再”。"}, {"text": "老板再保证了楼下那棵树的来历。", "explanation": "这里应该用〈讲述〉。“再保证”的对象是要做到的事，不能是已经存在的来历。"}, {"text": "他再保证了自己的错误，以后不会再犯。", "explanation": "这里应该用〈承认〉。“再保证”的对象是要做到的事，不能是已经犯下的错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98264, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再保证", "is_correct": true, "explanation": "正确：“再保证”表示又一次许诺一定做到，与“以后不玩手机了”的保证语境相符。"}, {"text": "玩耍", "is_correct": false, "explanation": "语义：“玩耍”与“以后不玩手机了”的承诺正相反。"}, {"text": "大笑", "is_correct": false, "explanation": "语义：“大笑”与“哭着”的情绪矛盾，也与承诺的语境不符。"}, {"text": "摔倒", "is_correct": false, "explanation": "搭配：“摔倒”是身体跌倒的动作，不能用来表示哭着作出的承诺。"}], "explanations": {"再保证": "正确：“再保证”表示又一次许诺一定做到，与“以后不玩手机了”的保证语境相符。", "玩耍": "语义：“玩耍”与“以后不玩手机了”的承诺正相反。", "大笑": "语义：“大笑”与“哭着”的情绪矛盾，也与承诺的语境不符。", "摔倒": "搭配：“摔倒”是身体跌倒的动作，不能用来表示哭着作出的承诺。"}, "sentence_index": 6, "correct_answer": "再保证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫再保证产品没问题。", "explanation": "这里应该用〈老板〉。“再保证”的主语须是能作出承诺的人，小猫不能作出保证。"}, {"text": "老板再保证了那天的经过。", "explanation": "这里应该用〈讲述〉。“再保证”的对象是将来要做到的事，不能是已经发生的经过。"}, {"text": "老板再保证了那张桌子的历史。", "explanation": "这里应该用〈介绍〉。“再保证”的对象是要做到的事，不能是已经存在的历史。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98264, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你放心，我明天再保证了一次，这件事不会再出错。", "corrected_sentence": "你放心，我明天再保证一次，这件事不会再出错。", "error_description": "“了”表示动作已完成，不能与表示将来的“明天”同用；应说“明天再保证一次”，不能说“明天再保证了一次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98264, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板再保证一个，客人才放心。", "corrected_sentence": "老板再保证一次，客人才放心。", "error_description": "动作次数的量词应为“次”，不能用“个”；应说“再保证一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98267, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热战", "is_correct": true, "explanation": "热战指真正动武的战争，与“不动武”的冷战相对，是这个义项的反义词。"}, {"text": "天空", "is_correct": false, "explanation": "天空指地面以上的空间，与冷战不构成反义关系。"}, {"text": "文化", "is_correct": false, "explanation": "文化指社会的知识、习俗和艺术等，与冷战不构成反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行指外出游览，与冷战不构成反义关系。"}], "correct_answer": "热战", "explanations": {"热战": "热战指真正动武的战争，与“不动武”的冷战相对，是这个义项的反义词。", "天空": "天空指地面以上的空间，与冷战不构成反义关系。", "文化": "文化指社会的知识、习俗和艺术等，与冷战不构成反义关系。", "旅行": "旅行指外出游览，与冷战不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98267, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "热战", "is_correct": true, "explanation": "热战指真正动武的战争，与“不动武”的冷战相对，是这个义项的反义词。"}, {"text": "钢笔", "is_correct": false, "explanation": "钢笔是写字的工具，与冷战不构成反义关系。"}, {"text": "季节", "is_correct": false, "explanation": "季节指一年中的春夏秋冬，与冷战不构成反义关系。"}, {"text": "节日", "is_correct": false, "explanation": "节日指特定的庆祝日子，与冷战不构成反义关系。"}], "correct_answer": "热战", "explanations": {"热战": "热战指真正动武的战争，与“不动武”的冷战相对，是这个义项的反义词。", "钢笔": "钢笔是写字的工具，与冷战不构成反义关系。", "季节": "季节指一年中的春夏秋冬，与冷战不构成反义关系。", "节日": "节日指特定的庆祝日子，与冷战不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98267, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "冷战是两个国家不打仗，可是互相不友好，暗暗较劲。", "primary_collocate": null, "pronunciation": "lěng zhàn", "ipa": "ləŋ˨˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "这两个国家之间的冷战已经很多年了。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷战期间，两国都不愿意先说话。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们没有打仗，只是互相不友好，这就是冷战。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷战让这两个国家的人民很少来往。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场冷战持续了很多年，最后才结束。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了一段冷战的历史。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷战不是真的战争，没有人上战场。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国领导人见面以后，冷战慢慢结束了。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的故事发生在冷战时期。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷战的时候，两个大国都在暗暗比较实力。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷战时期", "label": "复合"}, {"form": "新冷战", "label": "复合"}, {"form": "冷戰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国家之间不打仗但互相不友好、暗中较劲", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98267, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷战", "is_correct": true, "explanation": "冷战：两国不打仗但互相不友好、暗中较劲，与“这两个国家之间已经很多年了”的语境相符。"}, {"text": "早餐", "is_correct": false, "explanation": "语义：早餐是一天中的一顿饭，不能指两国之间的关系。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是戴在眼睛上的用品，与两国之间的状态无关。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“这两个国家之间的”不能修饰“教室”这类场所名词。"}], "explanations": {"冷战": "冷战：两国不打仗但互相不友好、暗中较劲，与“这两个国家之间已经很多年了”的语境相符。", "早餐": "语义：早餐是一天中的一顿饭，不能指两国之间的关系。", "眼镜": "语义：眼镜是戴在眼睛上的用品，与两国之间的状态无关。", "教室": "搭配：“这两个国家之间的”不能修饰“教室”这类场所名词。"}, "sentence_index": 0, "correct_answer": "冷战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国在边界上发生了冷战，双方都死了很多士兵。", "explanation": "这里应该用〈战争〉。冷战指不使用武力的暗中对抗，不会造成士兵死亡，与“死了很多士兵”矛盾。"}, {"text": "两国为了边界问题大声冷战。", "explanation": "这里应该用〈争吵〉。冷战指不动武、暗中较劲，不能和“大声”搭配。"}, {"text": "两国关系非常友好，经常互相帮助，这就是冷战。", "explanation": "这里应该用〈友好关系〉。冷战指双方互相不友好、暗中较劲，不能用来形容友好互助的关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98267, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷战", "is_correct": true, "explanation": "冷战：指不打仗但互相对抗的局面，与“不是真的战争，没有人上战场”相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是大气的状况，不能指“不是真的战争”这类事件。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，与“上战场”的战争语境完全不符。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“不是真的战争”的主语应是政治、军事或社会事件，“午饭”不能作这里的主语。"}], "explanations": {"冷战": "冷战：指不打仗但互相对抗的局面，与“不是真的战争，没有人上战场”相符。", "天气": "语义：天气是大气的状况，不能指“不是真的战争”这类事件。", "钢琴": "语义：钢琴是乐器，与“上战场”的战争语境完全不符。", "午饭": "搭配：“不是真的战争”的主语应是政治、军事或社会事件，“午饭”不能作这里的主语。"}, "sentence_index": 6, "correct_answer": "冷战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国在边界上互相开炮，这场冷战打得很激烈。", "explanation": "“互相开炮”属于武装冲突，与冷战“不使用武力”的含义相矛盾，这里用错了。"}, {"text": "这场冷战的双方公开宣布要立刻动武。", "explanation": "这里应该用〈战争〉。冷战是不使用武力的对抗，“公开宣布要立刻动武”描述的是战争，二者混淆了。"}, {"text": "两国通过冷战解决了边界问题。", "explanation": "这里应该用〈谈判〉。冷战是双方的对抗状态，不是解决问题的办法，“通过”后面应接具体方法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98267, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只冷战终于结束了。", "corrected_sentence": "这场冷战终于结束了。", "error_description": "量词错误：“冷战”是一段持续的对抗局面，量词应用“场”，不能用“只”。正确说法是“这场冷战”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98267, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷战们结束以后，两国领导人才开始见面。", "corrected_sentence": "冷战结束以后，两国领导人才开始见面。", "error_description": "复数错误：“冷战”是抽象名词，不能加“们”表示复数。正确说法是“冷战结束以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
