INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98268, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不使用武力的、双方在政治经济等方面的对抗。", "primary_collocate": null, "pronunciation": "lěng zhàn", "ipa": "ləŋ˨˩ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "冷战中双方在经济上互相限制。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场冷战主要是政治和经济上的对抗。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用贸易限制代替武力，开始了新的冷战。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷战时，两个阵营都不使用武力。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家担心这两个大国会陷入新的冷战。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷战的结束让世界经济有了新的变化。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科技比赛也是冷战的一部分。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是冷战中的政治故事。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个大国在冷战里争着发展经济。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他研究的是冷战时期的经济政策。", "target_word": "冷战", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "冷战时期", "label": "复合"}, {"form": "新冷战", "label": "复合"}, {"form": "冷戰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不用武力、在政治经济等方面的对抗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冷战", "is_correct": true, "explanation": "冷战：不使用武力的政治经济对抗，与“双方在经济上互相限制”的语境相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种植花草的地方，与双方在经济上互相限制无关。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是大片的水域，不能作为双方经济限制的场所或领域。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是考核学习成绩的活动，不能指双方在经济上互相限制的局面。"}], "explanations": {"冷战": "冷战：不使用武力的政治经济对抗，与“双方在经济上互相限制”的语境相符。", "花园": "语义：花园是种植花草的地方，与双方在经济上互相限制无关。", "海洋": "语义：海洋是大片的水域，不能作为双方经济限制的场所或领域。", "考试": "语义：考试是考核学习成绩的活动，不能指双方在经济上互相限制的局面。"}, "sentence_index": 0, "correct_answer": "冷战"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两国在港口一带发生了冷战，双方死伤惨重。", "explanation": "这里应该用〈战争〉。冷战不使用武力，不会造成“死伤惨重”，与它的含义矛盾。"}, {"text": "两国为了贸易问题大声冷战。", "explanation": "这里应该用〈争吵〉。冷战指不使用武力的暗中较劲，不能和“大声”搭配。"}, {"text": "两国在经济上互相帮助、共同发展，这就是冷战。", "explanation": "这里应该用〈合作〉。冷战是双方在政治经济上的对抗，不能指互相帮助、共同发展。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冷战", "is_correct": true, "explanation": "冷战：双方在政治经济领域的对抗，与“科技比赛也是……的一部分”相符。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，与“科技比赛”不能构成“……的一部分”的关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用品，与科技比赛毫无关系。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：“也是……的一部分”要求后面是可以作为整体一部分的事件或领域，“牛奶”不能这样使用。"}], "explanations": {"冷战": "冷战：双方在政治经济领域的对抗，与“科技比赛也是……的一部分”相符。", "钥匙": "语义：钥匙是开锁的工具，与“科技比赛”不能构成“……的一部分”的关系。", "雨伞": "语义：雨伞是遮雨的用品，与科技比赛毫无关系。", "牛奶": "搭配：“也是……的一部分”要求后面是可以作为整体一部分的事件或领域，“牛奶”不能这样使用。"}, "sentence_index": 6, "correct_answer": "冷战"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国在港口互相开炮，这场冷战的局面很激烈。", "explanation": "“互相开炮”属于武装冲突，与冷战“不使用武力”的含义相矛盾，这里用错了。"}, {"text": "冷战中的双方公开宣布要立刻开战。", "explanation": "这里应该用〈战争〉。冷战是不使用武力的对抗，“立刻开战”描述的是战争，二者混淆了。"}, {"text": "两国通过冷战解决了贸易纠纷。", "explanation": "这里应该用〈谈判〉。冷战是双方的对抗状态，不是解决问题的办法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只冷战已经持续了好几年。", "corrected_sentence": "这场冷战已经持续了好几年。", "error_description": "量词错误：“冷战”是持续的对抗局面，量词应用“场”，不能用“只”。正确说法是“这场冷战”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冷战们结束了，两国之间的贸易限制也放松了。", "corrected_sentence": "冷战结束了，两国之间的贸易限制也放松了。", "error_description": "复数错误：“冷战”是抽象名词，不能加“们”表示复数。正确说法是“冷战结束了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
