INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98275, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出手是伸手做出动作，比如扔东西或帮忙。", "primary_collocate": null, "pronunciation": "chū shǒu", "ipa": "ʈʂʰu˥ ʂoʊ˨˩", "syllable_count": 2, "sentences": [{"text": "看到老人摔倒，他马上出手帮忙。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王出手一扔，球飞进了篮筐。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友有困难，我一定出手帮他。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出手很快，一下接住了杯子。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个孩子打人，老师赶紧出手拦住。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出手一传，球到了队友手里。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居出手救了落水的小孩。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都不动，只有他先出手帮忙。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看到花瓶要掉，立刻出手扶住了。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学吵架时，班长出手拉开了他们。", "target_word": "出手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出手了", "label": "完成体"}, {"form": "出过手", "label": "经历体"}], "register": "中性", "sense_fingerprint": "伸出手做动作，如投扔东西、出手相助", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4ec718-f884-4ff9-9343-ff0c14937f8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98275, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出手", "is_correct": true, "explanation": "正确：“出手”（chū shǒu）指伸手做动作，如帮忙、投掷。"}, {"text": "出售", "is_correct": false, "explanation": "shòu（第四声）与 shǒu（第三声）声调不同，“出售”意思是卖出。"}, {"text": "触手", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，“触手”指某些动物身上的长须，如章鱼的触手。"}, {"text": "猪手", "is_correct": false, "explanation": "zh 与 ch 声母不同，“猪手”指猪蹄。"}], "explanations": {"出手": "正确：“出手”（chū shǒu）指伸手做动作，如帮忙、投掷。", "出售": "shòu（第四声）与 shǒu（第三声）声调不同，“出售”意思是卖出。", "触手": "chù（第四声）与 chū（第一声）声调不同，“触手”指某些动物身上的长须，如章鱼的触手。", "猪手": "zh 与 ch 声母不同，“猪手”指猪蹄。"}, "sentence_index": null, "correct_answer": "出手"}, "level_3": {"options": [{"text": "出手", "is_correct": true, "explanation": "正确：“出手帮忙”指伸手去做动作来帮助别人，符合老人摔倒的语境。"}, {"text": "观望", "is_correct": false, "explanation": "语义：“观望”指看情况而不动，与“马上帮忙”的意思相反。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：“逃跑”与“帮忙”的意思正相反，句子说不通。"}, {"text": "抱怨", "is_correct": false, "explanation": "搭配：“抱怨”的对象通常是事情或人，不能与“帮忙”搭配。"}], "explanations": {"出手": "正确：“出手帮忙”指伸手去做动作来帮助别人，符合老人摔倒的语境。", "观望": "语义：“观望”指看情况而不动，与“马上帮忙”的意思相反。", "逃跑": "语义：“逃跑”与“帮忙”的意思正相反，句子说不通。", "抱怨": "搭配：“抱怨”的对象通常是事情或人，不能与“帮忙”搭配。"}, "sentence_index": 0, "correct_answer": "出手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批货他终于出手了，卖了一大笔钱。", "explanation": "这里的“出手”指卖出、脱手，是另一义项，与本句伸手做动作的意思不同，不需要替换词。"}, {"text": "他请客时出手很大方，花了好几百块。", "explanation": "这里的“出手”指拿出钱财花费，是另一义项，与伸手接东西的动作无关。"}, {"text": "这位画家的新作出手不凡，很有味道。", "explanation": "这里的“出手”指作品或手笔的水平，是另一义项，与伸手做动作无关，不需要替换词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98275, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出手", "is_correct": true, "explanation": "正确：“出手救”指伸手去做动作救人，与“救了落水的小孩”相符。"}, {"text": "旁观", "is_correct": false, "explanation": "语义：“旁观”指只看不管，与“救了落水的小孩”的结果矛盾。"}, {"text": "围观", "is_correct": false, "explanation": "语义：“围观”指站在一旁看热闹，与“救了”的行为不相符。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”的对象通常是目标或努力，不能直接接“救了落水的小孩”这样的行为结果。"}], "explanations": {"出手": "正确：“出手救”指伸手去做动作救人，与“救了落水的小孩”相符。", "旁观": "语义：“旁观”指只看不管，与“救了落水的小孩”的结果矛盾。", "围观": "语义：“围观”指站在一旁看热闹，与“救了”的行为不相符。", "放弃": "搭配：“放弃”的对象通常是目标或努力，不能直接接“救了落水的小孩”这样的行为结果。"}, "sentence_index": 6, "correct_answer": "出手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一出手就花了好几百块，大家都很吃惊。", "explanation": "这里的“出手”指拿出钱财花费，是另一义项，与伸手做动作无关，不需要替换词。"}, {"text": "这位选手第一场比赛就出手不凡，拿到了高分。", "explanation": "这里的“出手”指表现出的水平或风格，是另一义项，与伸手做动作无关，不需要替换词。"}, {"text": "老板让店员把积压的货尽快出手。", "explanation": "这里的“出手”指卖出、脱手，是另一义项，与伸手做动作无关，不需要替换词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98275, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上次有人摔倒，他也出手过，扶起了老人。", "corrected_sentence": "上次有人摔倒，他也出过手，扶起了老人。", "error_description": "“过”是经历体，应紧跟动词：应说“出过手”，不能说“出手过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98275, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天要是有人落水，他会出手了帮忙。", "corrected_sentence": "明天要是有人落水，他会出手帮忙。", "error_description": "“了”表示动作已经完成，不能与表示将来的“会”和“明天”同用；应说“会出手帮忙”，不能说“会出手了帮忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aabc3365-a1a5-461c-b57b-c44f6cd1f928') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98279, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
