INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98279, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "利息是把钱放在银行里，银行多给你的那一点钱。", "primary_collocate": null, "pronunciation": "lì xī", "ipa": "li˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "我把钱存在银行，每年有一点利息。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行今天给了我五十块钱利息。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存了一年，利息不多。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱的利息要到月底才能拿。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每个月都去银行问问存款的利息。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用存款的利息买了一本书。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在银行的利息很低，存钱不太合算。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，利息就是银行多给的钱。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱放在家里没有利息，放在银行就有。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的利息已经到我的卡里了。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，存款时银行多给存款人的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98279, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "利息", "is_correct": true, "explanation": "正确：lì xī 是“利息”，指存款时银行多给存款人的钱。"}, {"text": "力气", "is_correct": false, "explanation": "声母混淆：lì qi 与 lì xī 第二个字声母不同（q／x），意思是身体的力量。"}, {"text": "离析", "is_correct": false, "explanation": "声调混淆：lí xī 与 lì xī 只有第一个字声调不同（第二声与第四声），意思是分解、分散。"}, {"text": "利基", "is_correct": false, "explanation": "声母混淆：lì jī 与 lì xī 只有第二个字声母不同（j／x），声调相同，意思是商业上的细分空白市场。"}], "explanations": {"利息": "正确：lì xī 是“利息”，指存款时银行多给存款人的钱。", "力气": "声母混淆：lì qi 与 lì xī 第二个字声母不同（q／x），意思是身体的力量。", "离析": "声调混淆：lí xī 与 lì xī 只有第一个字声调不同（第二声与第四声），意思是分解、分散。", "利基": "声母混淆：lì jī 与 lì xī 只有第二个字声母不同（j／x），声调相同，意思是商业上的细分空白市场。"}, "sentence_index": null, "correct_answer": "利息"}, "level_3": {"options": [{"text": "本金", "is_correct": false, "explanation": "语义：本金是存进去的本钱，不是每年多得的钱，与“每年有一点”不合。"}, {"text": "利息", "is_correct": true, "explanation": "正确：利息是存款每年多得的钱，符合句意。"}, {"text": "利率", "is_correct": false, "explanation": "搭配：“有一点”说的是钱的数量，利率是比率，不说“有一点利率”。"}, {"text": "存折", "is_correct": false, "explanation": "语义：存折是银行的账本，不是钱，句中要的是一笔钱的数额。"}], "explanations": {"本金": "语义：本金是存进去的本钱，不是每年多得的钱，与“每年有一点”不合。", "利息": "正确：利息是存款每年多得的钱，符合句意。", "利率": "搭配：“有一点”说的是钱的数量，利率是比率，不说“有一点利率”。", "存折": "语义：存折是银行的账本，不是钱，句中要的是一笔钱的数额。"}, "sentence_index": 0, "correct_answer": "利息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这项政策对农民很有利息。", "explanation": "这里应该用〈利益〉。利益指好处，利息指存款或借贷多付的钱，政策的好处不能说利息。"}, {"text": "这家商场今天的利息是八折。", "explanation": "这里应该用〈折扣〉。折扣指打折的比例，利息指存款或借贷多付的钱，商场打折不能说利息。"}, {"text": "我在公司上班，每个月的利息是五千块。", "explanation": "这里应该用〈工资〉。工资是上班挣的钱，利息是存款或借贷多付的钱，上班挣的钱不叫利息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98279, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "利息", "is_correct": true, "explanation": "正确：lì xī 是“利息”，指存款时银行多给存款人的钱。"}, {"text": "窒息", "is_correct": false, "explanation": "声母混淆：zhì xī 与 lì xī 只有第一个字声母不同（zh／l），声调相同，意思是呼吸受阻、气不通。"}, {"text": "气息", "is_correct": false, "explanation": "声母混淆：qì xī 与 lì xī 只有第一个字声母不同（q／l），声调相同，意思是呼吸时的气，也指气味或气氛。"}, {"text": "离析", "is_correct": false, "explanation": "声调混淆：lí xī 与 lì xī 只有第一个字声调不同（第二声与第四声），意思是分解、分散。"}], "explanations": {"利息": "正确：lì xī 是“利息”，指存款时银行多给存款人的钱。", "窒息": "声母混淆：zhì xī 与 lì xī 只有第一个字声母不同（zh／l），声调相同，意思是呼吸受阻、气不通。", "气息": "声母混淆：qì xī 与 lì xī 只有第一个字声母不同（q／l），声调相同，意思是呼吸时的气，也指气味或气氛。", "离析": "声调混淆：lí xī 与 lì xī 只有第一个字声调不同（第二声与第四声），意思是分解、分散。"}, "sentence_index": null, "correct_answer": "利息"}, "level_3": {"options": [{"text": "本金", "is_correct": false, "explanation": "语义：本金是存入的钱数，与“利息很低”无关，句中说的是利息的高低。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动所得，与存钱和利息无关。"}, {"text": "利息", "is_correct": true, "explanation": "正确：利息低，存钱不合算，符合句意。"}, {"text": "门票", "is_correct": false, "explanation": "搭配：“银行的……很低”说不通，门票是入场凭证，与存钱合不合算无关。"}], "explanations": {"本金": "语义：本金是存入的钱数，与“利息很低”无关，句中说的是利息的高低。", "工资": "语义：工资是劳动所得，与存钱和利息无关。", "利息": "正确：利息低，存钱不合算，符合句意。", "门票": "搭配：“银行的……很低”说不通，门票是入场凭证，与存钱合不合算无关。"}, "sentence_index": 6, "correct_answer": "利息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店今年卖衣服的利息翻了一倍。", "explanation": "这里应该用〈利润〉。利润是卖东西赚的钱，利息是存款或借贷多付的钱，卖衣服赚的钱不叫利息。"}, {"text": "他靠写文章的利息养活一家人。", "explanation": "这里应该用〈收入〉。利息指存款或借贷多付的钱，写文章的报酬不叫利息。"}, {"text": "这笔钱的利息很快。", "explanation": "这里应该用〈到账〉。利息是钱的数额，本身没有快慢，应说“这笔利息很快到账”，不能说“利息很快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98279, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "银行去年给了我一个利息，有三百块。", "corrected_sentence": "银行去年给了我一笔利息，有三百块。", "error_description": "“利息”是一笔钱，应该用量词“笔”，不说“一个利息”。“个”是通用量词，不用于存款得到的钱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98279, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的存款利息们今年涨了一点。", "corrected_sentence": "我的存款利息今年涨了一点。", "error_description": "“利息”是抽象名词，不能加“们”表示复数。应说“存款利息”，不说“存款利息们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98280, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98280, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "存款或贷款时，除本金外多收或多付的钱。", "primary_collocate": null, "pronunciation": "lì xī", "ipa": "li˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "向银行借钱要还本金和利息。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔贷款的利息很高。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月除了还本金，还要付利息。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "借了十万块，一年要付五千利息。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友借钱给我，没有要利息。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先算一下这笔钱的利息。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "利息太高了，他不想贷款买车。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子的人每月都要付利息。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚还钱，利息会越来越多。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行说，这笔钱的利息按月算。", "target_word": "利息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，借贷或存款中除本金以外多收或多付的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a02c85c-e546-43ae-aa26-2e30629ef750') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (98280, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "利息", "is_correct": true, "explanation": "正确：lì xī 是“利息”，指借贷或存款中除本金外多付或多收的钱。"}, {"text": "力气", "is_correct": false, "explanation": "声母混淆：lì qi 与 lì xī 第二个字声母不同（q／x），意思是身体的力量。"}, {"text": "离析", "is_correct": false, "explanation": "声调混淆：lí xī 与 lì xī 只有第一个字声调不同（第二声与第四声），意思是分解、分散。"}, {"text": "利基", "is_correct": false, "explanation": "声母混淆：lì jī 与 lì xī 只有第二个字声母不同（j／x），声调相同，意思是商业上的细分空白市场。"}], "explanations": {"利息": "正确：lì xī 是“利息”，指借贷或存款中除本金外多付或多收的钱。", "力气": "声母混淆：lì qi 与 lì xī 第二个字声母不同（q／x），意思是身体的力量。", "离析": "声调混淆：lí xī 与 lì xī 只有第一个字声调不同（第二声与第四声），意思是分解、分散。", "利基": "声母混淆：lì jī 与 lì xī 只有第二个字声母不同（j／x），声调相同，意思是商业上的细分空白市场。"}, "sentence_index": null, "correct_answer": "利息"}, "level_3": {"options": [{"text": "利率", "is_correct": false, "explanation": "搭配：“还”的对象是钱，利率是比率，不说“还利率”。"}, {"text": "利息", "is_correct": true, "explanation": "正确：借钱要还本金和利息，符合句意。"}, {"text": "存款", "is_correct": false, "explanation": "语义：存款是存进银行的钱，借钱时要还的是本金和利息，不还存款。"}, {"text": "利润", "is_correct": false, "explanation": "语义：利润是生意赚的钱，与借钱还款无关。"}], "explanations": {"利率": "搭配：“还”的对象是钱，利率是比率，不说“还利率”。", "利息": "正确：借钱要还本金和利息，符合句意。", "存款": "语义：存款是存进银行的钱，借钱时要还的是本金和利息，不还存款。", "利润": "语义：利润是生意赚的钱，与借钱还款无关。"}, "sentence_index": 0, "correct_answer": "利息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行的利息是三百块。", "explanation": "这里应该用〈费用〉。费用指花掉的钱，利息是借钱多付的钱，旅行花的钱不叫利息。"}, {"text": "这次合作对双方都有利息。", "explanation": "这里应该用〈利益〉。利益指好处，利息指存款或借贷多付的钱，合作的好处不能说利息。"}, {"text": "这家店卖一件衣服的利息是十块钱。", "explanation": "这里应该用〈利润〉。利润是卖东西赚的钱，利息是借钱多付的钱，卖一件衣服赚的钱不叫利息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de21d92-5d4b-497d-9701-8cc1dd403623') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
